def wild_rare_map_gate_zero_literal_swf_ids(profile: WildCaptureProfile) -> FrozenSet[int]:
    """
    Return map ids accepted as the temporary zero-gate after refresh/to scripts.

    Some rare routes enter an intermediate map before the final target map. Those
    intermediate ids are accepted so unexpected-map protection does not restart too early.
    """
    vals = (
        getattr(profile, "slug", None),
        getattr(profile, "route_hint", None),
        getattr(profile, "name", None),
        getattr(profile, "to_script", None),
    )
    if any('乌索' in str(v or "") for v in vals):
        return frozenset({325, 326})

    map_zero = getattr(profile, "map_zero_id", None)
    if map_zero is not None:
        try:
            z = int(map_zero)
            if z != int(profile.map_swf_id):
                return frozenset({z})
        except (TypeError, ValueError):
            pass
        return frozenset()

    name_lower = profile.name.lower()
    if "dugulu" in name_lower:
        return frozenset({320})
    if "双塔" in name_lower:
        return frozenset({315})
    if "闪光皮皮" in name_lower:
        return frozenset({11})
    if '眼球' in name_lower and int(getattr(profile, "map_swf_id", 0) or 0) == 60:
        return EYEBALL_GATE_MAP_ZERO_IDS
    return frozenset()


