    def _init_unified_framework(self):
        """初始化统一框架"""
        try:
            from core.unified_battle_framework import UnifiedBattleFramework
            from core.wild_mode_adapter import WildModeAdapter

            from config import TEMPLATES_PATH
            self._unified_framework = UnifiedBattleFramework(self.bot, self.regions, TEMPLATES_PATH)
            self._wild_adapter = WildModeAdapter(self._unified_framework)
            self._emit("✅ 统一框架已初始化（野外模式）", "DEBUG")
        except Exception as e:
            self._emit(f"⚠️ 统一框架初始化失败，使用旧逻辑: {e}", "WARN")
            self._unified_framework = None
            self._wild_adapter = None

    # =========================
    # kernel helpers
    # =========================
    def _fetch_kernel(self, cursor: int) -> Tuple[int, List[str]]:
        """
        统一 fetch_kernel_since 的返回形态：
        - (new_cursor, lines)
        - lines
        - rows[(seq, ts, line)]
        """
        try:
            res: Any = fetch_kernel_since(cursor)
        except Exception:
            return kernel_cursor(), []

        if isinstance(res, tuple) and len(res) == 2 and isinstance(res[0], int):
            new_cursor, lines = res
            return int(new_cursor), self._coerce_lines(lines)

        return kernel_cursor(), self._coerce_lines(res)

    @staticmethod
    def _coerce_lines(obj: Any) -> List[str]:
        if obj is None:
            return []
        if isinstance(obj, str):
            return [obj]
        if isinstance(obj, list):
            if not obj:
                return []
            if isinstance(obj[0], tuple) and len(obj[0]) >= 3:
                out: List[str] = []
                for t in obj:
                    try:
                        out.append(str(t[-1]))
                    except Exception:
                        pass
                return out
            return [str(x) for x in obj]
        try:
            return [str(x) for x in obj]
        except Exception:
            return []

    def _rotation_detection_log_tag(self, profile: Optional[WildCaptureProfile] = None) -> str:
        name = getattr(profile, "name", None)
        if name:
            return f"轮换检测-{name}"
        slot = (getattr(self, "_rotation_rare_slot", "shuangta") or "shuangta").strip().lower()
        labels = {
            "shuangta": "双塔",
            "flash_pipi": "闪光皮皮",
            "eyeball": '眼球',
            "dugulu": "嘟咕噜",
            "mantis": "螳螂",
            "xiaodouya": "小豆芽",
        }
        return f"轮换检测-{labels.get(slot, slot)}"

    def _handle_nieo_time_stop(self, nieo_stats: Dict[str, int]):
        """
        处理尼奥模式时间测量停止逻辑
        输出统计信息并停止切图
        """
        self._emit("[时间] 检测到异常间隔，停止切图", "SYSTEM")

        # 璁＄畻鎬昏繍琛屾椂闀?
        if self._nieo_mode_start_time is not None:
            total_duration = time.time() - self._nieo_mode_start_time
            total_duration_str = f"{total_duration:.1f}s"
        else:
            total_duration_str = "unknown"

        # 杈撳嚭缁熻淇℃伅
        self._emit("[时间] fightPetSwf 到 PetItem 间隔统计", "SYSTEM")
        if self._nieo_swf_to_petitem_min_time is not None:
            self._emit(f"   最短={self._nieo_swf_to_petitem_min_time:.3f}s", "INFO")
        else:
            self._emit("   最短=未知", "INFO")

        if self._nieo_swf_to_petitem_current_time is not None:
            self._emit(f"   当前={self._nieo_swf_to_petitem_current_time:.3f}s", "INFO")
        else:
            self._emit("   当前=未知", "INFO")

        self._emit(f"   尼奥模式运行时长={total_duration_str}", "INFO")

        # 杈撳嚭鎴樻枟缁熻
        self._emit("[尼奥模式] 战斗统计", "SYSTEM")
        self._emit(f"   统计={dict(nieo_stats)}", "INFO")

        # TODO: 鎵ц刷新鎿嶄綔锛堝湪TODO杩愯浆璧锋潵涔嬪墠閲囧彇鍋滄杩愯鑴氭湰琛屽姩锛?
        self._emit("⏸️ [TODO] 刷新操作未实现，当前停止运行脚本", "WARN")
        # 鍋滄杩愯鑴氭湰锛堥€氳繃设置stop_current鏍囧織锛?
        if hasattr(self.bot, "stop_current"):
            self.bot.stop_current = True

    def _settle_rotation_nieo_stats_once(
        self,
        nieo_stats: Optional[Dict[str, int]],
        *,
        reason: str = "尼奥模式结束",
    ) -> bool:
        """Settle one Nieo stats bucket into rotation totals once."""
        if not (self._is_rotation_mode and self._rotation_total_stats and nieo_stats):
            return False
        if nieo_stats.get("_rotation_settled"):
            return False
        nieo_total = self._rotation_total_stats["nieo"]
        for key in ("普通逃跑", "稀有捕捉", "尼尔家族", "108捕捉", "77捕捉", "310捕捉", "416捕捉"):
            nieo_total[key] += int(nieo_stats.get(key, 0) or 0)
        nieo_total["运行次数"] += 1
        nieo_stats["_rotation_settled"] = 1
        self._emit(
            f"[rotation-stats] settled Nieo stats reason={reason}: "
            f"escape={nieo_stats.get('普通逃跑', 0)}, "
            f"rare={nieo_stats.get('稀有捕捉', 0)}, "
            f"family={nieo_stats.get('尼尔家族', 0)}",
            "DEBUG",
        )
        return True

