    def _recover_bag_pet_slot_once(
        self,
        pos_cn: str,
        use_foreground: bool,
        stop_event: threading.Event,
        log_tag: str,
    ) -> None:
        self._emit(f"[{log_tag}] 恢复精灵{pos_cn}", "INFO")
        self._emit(f"[{log_tag}] 恢复前双击精灵{pos_cn}", "INFO")
        pet_key = f"精灵背包.精灵{pos_cn}"
        pet_btn_key = f"精灵背包.精灵{pos_cn}按钮"
        try:
            self._click_region_twice(pet_btn_key, use_foreground)
        except KeyError:
            self._click_region_twice(pet_key, use_foreground)
        self._sleep_abortable(stop_event, 0.5)

        self._recover_selected_bag_pet_once(
            pos_cn,
            use_foreground,
            stop_event,
            log_tag,
        )

    def _recover_selected_bag_pet_once(
        self,
        pos_cn: str,
        use_foreground: bool,
        stop_event: threading.Event,
        log_tag: str,
    ) -> None:
        """Recover a bag pet that is already selected without clicking its slot again."""
        self._emit(f"[{log_tag}] 点击精灵{pos_cn}恢复", "INFO")
        recover_key = "精灵背包.精灵恢复"
        recover_btn_key = "精灵背包.精灵恢复按钮"
        try:
            self._click_region(recover_btn_key, use_foreground)
        except KeyError:
            self._click_region(recover_key, use_foreground)
        self._sleep_abortable(stop_event, 1.0)

        self._emit(f"[{log_tag}] 精灵{pos_cn}恢复后等待1AND1确认", "INFO")
        if self._unified_framework:
            from core.unified_battle_framework import BattleConfig, BattleMode

            temp_config = BattleConfig(
                mode=BattleMode.WILD,
                use_foreground=use_foreground,
                abort_check=lambda: stop_event.is_set()
                or getattr(self.bot, "stop_current", False),
            )
            self._unified_framework._wait_for_confirm_probes(
                temp_config, timeout_s=2.0
            )
        self._sleep_abortable(stop_event, 0.5)

    def _recover_unique_bag_slots(
        self,
        slots: Sequence[Optional[str]],
        use_foreground: bool,
        stop_event: threading.Event,
        log_tag: str,
    ) -> None:
        seen = set()
        for raw_slot in slots:
            slot = str(raw_slot or "").strip()
            if not slot:
                continue
            if slot in seen:
                self._emit(
                    f"[{log_tag}] 精灵{slot}已在本轮恢复，跳过重复恢复",
                    "INFO",
                )
                continue
            seen.add(slot)
            self._recover_bag_pet_slot_once(
                slot,
                use_foreground,
                stop_event,
                log_tag,
            )

    def _scan_pickmode_bag_slot_skill4_once(
        self,
        pos_cn: str,
        use_foreground: bool,
        stop_event: threading.Event,
        log_tag: str,
    ) -> Optional[str]:
        self._emit(f"[{log_tag}] 扫描精灵{pos_cn}四技能探针", "INFO")
        self._click_bag_pet_slot_double(pos_cn, use_foreground)
        self._sleep_abortable(stop_event, 0.55)
        rgb = self._mean_rgb_for_region_key("精灵背包.技能四探针")
        if rgb is None:
            self._emit(f"[{log_tag}] 精灵{pos_cn}四技能探针 RGB=无", "WARN")
            return None
        r, g, b = rgb
        kind = self._pickmode_classify_skill4_rgb(r, g, b)
        self._emit(
            f"[{log_tag}] 精灵{pos_cn}四技能探针 RGB=({r},{g},{b})，R-B={r-b}，B-R={b-r}，结果={kind or '未知'}",
            "INFO",
        )
        return kind

    def _apply_pickmode_recover_scan_cache(
        self, slot_kinds: Dict[str, Optional[str]], log_tag: str
    ) -> None:
        primary_pos: Optional[str] = None
        support_pos: Optional[str] = None
        for pos_cn, kind in slot_kinds.items():
            if kind == "jita":
                primary_pos = pos_cn
            elif kind == "aifeidesi":
                support_pos = pos_cn

        primary_name = "亚梅丝" if getattr(self, "_pickmode_yameisi_branch", False) else "机塔"
        support_name = (
            "艾菲德斯/艾斯菲格"
            if getattr(self, "_pickmode_yameisi_branch", False)
            else "艾菲德斯"
        )

        if primary_pos:
            self._jita_pos = primary_pos
            if getattr(self, "_pickmode_yameisi_branch", False):
                self._yameisi_pos = primary_pos
        if support_pos:
            self._aisifeige_pos = support_pos

        if primary_pos and support_pos:
            self._emit(
                f"[{log_tag}] {primary_name}=精灵{primary_pos}，{support_name}=精灵{support_pos}",
                "SUCCESS",
            )
        elif primary_pos or support_pos:
            self._emit(
                f"[{log_tag}] 只识别到一部分：{primary_name}={primary_pos}，{support_name}={support_pos}",
                "WARN",
            )
        else:
            self._emit(
                f"[{log_tag}] 未能识别 {primary_name}/{support_name} 槽位",
                "WARN",
            )

    def _recover_and_identify_pickmode_bag_slots(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
        log_tag: str,
    ) -> bool:
        self._emit(
            f"🧩 [{log_tag}] 恢复精灵一并严格识别精灵一至六槽位",
            "SYSTEM",
        )
        return self._recover_pick_party_after_bag_ready(
            use_foreground,
            stop_event,
            log_tag,
            include_primary=False,
            set_follow_primary=False,
            require_scan_success=True,
        )

    def _classify_pick_bag_slot_rgb(
        self, rgb: Optional[Tuple[int, int, int]]
    ) -> Optional[str]:
        return classify_pet_bag_slot_rgb(rgb)

    @staticmethod
    def _pick_bag_color_label(color: Optional[str]) -> str:
        return pet_bag_slot_color_label(color)

    def _bag_party_slot_probe_key(self, pos_num: int) -> str:
        direct = f"精灵背包.{pos_num}"
        if self.regions.get(direct):
            return direct
        cn = {1: "一", 2: "二", 3: "三", 4: "四", 5: "五", 6: "六"}[int(pos_num)]
        fallback = f"精灵背包.精灵{cn}"
        if not getattr(self, "_bag_party_slot_probe_fallback_logged", False):
            self._emit(
                "[背包槽位扫描] 未找到1-6号专用探针，改用精灵槽位区域",
                "WARN",
            )
            self._bag_party_slot_probe_fallback_logged = True
        return fallback

    def _scan_pick_bag_party_slots_1_to_6(
        self,
        stop_event: threading.Event,
        log_tag: str,
        *,
        timeout_s: float = 8.0,
    ) -> Dict[str, Any]:
        self._aisifeige_pos = None
        self._jita_pos = None
        if getattr(self, "_pickmode_yameisi_branch", False):
            self._yameisi_pos = None
        self._emit(
            f"[{log_tag}] 扫描背包1-6号颜色；目标=4橙、1青、1紫；普通青色=197，尼奥青色=1459；超时={timeout_s:.0f}s",
            "INFO",
        )
        t0 = time.time()
        last: Dict[int, Dict[str, Any]] = {}
        last_counts = {"orange": 0, "cyan": 0, "purple": 0}
        attempt = 0
        while time.time() - t0 <= timeout_s:
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                break
            attempt += 1
            counts = {"orange": 0, "cyan": 0, "purple": 0}
            data: Dict[int, Dict[str, Any]] = {}
            for pos in range(1, 7):
                key = self._bag_party_slot_probe_key(pos)
                rgb = self._mean_rgb_for_region_key(key)
                color = self._classify_pick_bag_slot_rgb(rgb)
                if color in counts:
                    counts[color] += 1
                data[pos] = {"key": key, "rgb": rgb, "color": color}
            last = data
            last_counts = counts
            desc = "; ".join(
                f"{pos}号({item['key']})=RGB{item['rgb']}→{self._pick_bag_color_label(item['color'])}"
                for pos, item in data.items()
            )
            self._emit(
                f"[{log_tag}] 背包槽位扫描第{attempt}次：{desc}；统计 橙={counts['orange']} 青={counts['cyan']} 紫={counts['purple']}；目标=4/1/1",
                "DEBUG",
            )
            if counts == {"orange": 4, "cyan": 1, "purple": 1}:
                cyan_pos = next(pos for pos, item in data.items() if item["color"] == "cyan")
                purple_pos = next(pos for pos, item in data.items() if item["color"] == "purple")
                cn = {1: "一", 2: "二", 3: "三", 4: "四", 5: "五", 6: "六"}
                self._aisifeige_pos = cn[cyan_pos]
                self._jita_pos = cn[purple_pos]
                if getattr(self, "_pickmode_yameisi_branch", False):
                    self._yameisi_pos = cn[purple_pos]
                self._emit(
                    f"[{log_tag}] 背包槽位识别完成：青色=精灵{cn[cyan_pos]}({cyan_pos})，紫色=精灵{cn[purple_pos]}({purple_pos})",
                    "SUCCESS",
                )
                return {
                    "ok": True,
                    "cyan": cn[cyan_pos],
                    "purple": cn[purple_pos],
                    "data": data,
                }
            time.sleep(0.25)
        self._emit(
            f"[{log_tag}] 背包1-6号在 {timeout_s:.0f}s 内未达到4橙/1青/1紫；最后统计 橙={last_counts['orange']} 青={last_counts['cyan']} 紫={last_counts['purple']}；最后结果={last}",
            "WARN",
        )
        return {"ok": False, "data": last}

    def scan_pick_bag_party_color_slots_any(
        self,
        stop_event: threading.Event,
        log_tag: str,
        *,
        timeout_s: float = 8.0,
        min_cyan: int = 1,
        min_purple: int = 1,
    ) -> Dict[str, Any]:
        """Scan bag slots 1-6 and allow more than one cyan pet."""
        self._emit(
            f"[{log_tag}] 扫描背包1-6号颜色；允许多青色；至少青={min_cyan}、紫={min_purple}；超时={timeout_s:.0f}s",
            "INFO",
        )
        cn = {1: "一", 2: "二", 3: "三", 4: "四", 5: "五", 6: "六"}
        t0 = time.time()
        last: Dict[int, Dict[str, Any]] = {}
        last_counts = {"orange": 0, "cyan": 0, "purple": 0}
        attempt = 0
        while time.time() - t0 <= timeout_s:
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                break
            attempt += 1
            counts = {"orange": 0, "cyan": 0, "purple": 0}
            data: Dict[int, Dict[str, Any]] = {}
            for pos in range(1, 7):
                key = self._bag_party_slot_probe_key(pos)
                rgb = self._mean_rgb_for_region_key(key)
                color = self._classify_pick_bag_slot_rgb(rgb)
                if color in counts:
                    counts[color] += 1
                data[pos] = {"key": key, "rgb": rgb, "color": color}
            last = data
            last_counts = counts
            desc = "; ".join(
                f"{pos}号({item['key']})=RGB{item['rgb']}->{self._pick_bag_color_label(item['color'])}"
                for pos, item in data.items()
            )
            self._emit(
                f"[{log_tag}] 多青扫描第{attempt}次：{desc}；统计 橙={counts['orange']} 青={counts['cyan']} 紫={counts['purple']}",
                "DEBUG",
            )
            if counts["cyan"] >= int(min_cyan) and counts["purple"] >= int(min_purple):
                cyan_slots = [cn[pos] for pos, item in data.items() if item["color"] == "cyan"]
                purple_slots = [cn[pos] for pos, item in data.items() if item["color"] == "purple"]
                if cyan_slots:
                    self._aisifeige_pos = cyan_slots[0]
                if purple_slots:
                    self._jita_pos = purple_slots[0]
                self._emit(
                    f"[{log_tag}] 多青扫描完成：青色={cyan_slots}，紫色={purple_slots}",
                    "SUCCESS",
                )
                return {
                    "ok": True,
                    "cyan": cyan_slots[0] if cyan_slots else None,
                    "cyan_slots": cyan_slots,
                    "purple": purple_slots[0] if purple_slots else None,
                    "purple_slots": purple_slots,
                    "data": data,
                }
            time.sleep(0.25)
        self._emit(
            f"[{log_tag}] 多青扫描超时；最后统计 橙={last_counts['orange']} 青={last_counts['cyan']} 紫={last_counts['purple']}；最后结果={last}",
            "WARN",
        )
        return {"ok": False, "data": last, "cyan_slots": [], "purple_slots": []}

    def scan_full_pick_bag_party_color_slots(
        self,
        stop_event: threading.Event,
        log_tag: str,
        *,
        timeout_s: float = 8.0,
    ) -> Dict[str, Any]:
        """Wait until every bag slot from 1 to 6 is orange, cyan, or purple."""
        self._emit(
            f"🔎 [{log_tag}] 扫描背包全部六格；六格都必须是橙/青/紫之一；超时={timeout_s:.0f}s",
            "INFO",
        )
        cn = {1: "一", 2: "二", 3: "三", 4: "四", 5: "五", 6: "六"}
        t0 = time.time()
        last: Dict[int, Dict[str, Any]] = {}
        attempt = 0
        stable_signature: Optional[Tuple[Optional[str], ...]] = None
        stable_scans = 0
        while time.time() - t0 <= timeout_s:
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                break
            attempt += 1
            data: Dict[int, Dict[str, Any]] = {}
            for pos in range(1, 7):
                key = self._bag_party_slot_probe_key(pos)
                rgb = self._mean_rgb_for_region_key(key)
                data[pos] = {
                    "key": key,
                    "rgb": rgb,
                    "color": self._classify_pick_bag_slot_rgb(rgb),
                }
            last = data
            signature = tuple(data[pos]["color"] for pos in range(1, 7))
            all_tricolor = all(color in {"orange", "cyan", "purple"} for color in signature)
            if all_tricolor and signature == stable_signature:
                stable_scans += 1
            elif all_tricolor:
                stable_signature = signature
                stable_scans = 1
            else:
                stable_signature = None
                stable_scans = 0
            desc = "; ".join(
                f"精灵{cn[pos]}=RGB{item['rgb']}→{self._pick_bag_color_label(item['color'])}"
                for pos, item in data.items()
            )
            self._emit(
                f"🔎 [{log_tag}] 六格扫描第{attempt}次：{desc}；"
                f"有宠={sum(color in {'orange', 'cyan', 'purple'} for color in signature)}/6",
                "DEBUG",
            )
            if all_tricolor and stable_scans >= 2:
                cyan_slots = [cn[pos] for pos, item in data.items() if item["color"] == "cyan"]
                purple_slots = [cn[pos] for pos, item in data.items() if item["color"] == "purple"]
                orange_slots = [cn[pos] for pos, item in data.items() if item["color"] == "orange"]
                self._emit(
                    f"✅ [{log_tag}] 六格均已确认：橙={orange_slots}，青={cyan_slots}，紫={purple_slots}",
                    "SUCCESS",
                )
                return {
                    "ok": True,
                    "data": data,
                    "cyan_slots": cyan_slots,
                    "purple_slots": purple_slots,
                    "orange_slots": orange_slots,
                }
            self._sleep_abortable(stop_event, 0.2)
        self._emit(
            f"❌ [{log_tag}] 六格未能全部确认成橙/青/紫；最后结果={last}",
            "ERROR",
        )
        return {
            "ok": False,
            "data": last,
            "cyan_slots": [],
            "purple_slots": [],
            "orange_slots": [],
        }

    def _is_pick_bag_slot_deep_blue(
        self, rgb: Optional[Tuple[int, int, int]]
    ) -> bool:
        if rgb is None:
            return False
        r, g, b = rgb
        return self._hp_bar_color_distance(rgb, self.HP_BAR_STORAGE_BLUE) <= 55 or (
            r <= 70
            and 35 <= g <= 120
            and 100 <= b <= 195
            and (b - r) >= 55
            and (b - g) >= 25
        )

    def _wait_pick_bag_slot_deep_blue(
        self,
        pos_cn: str,
        stop_event: threading.Event,
        log_tag: str,
        *,
        timeout_s: Optional[float] = None,
    ) -> bool:
        """Confirm that one returned bag slot changed from a pet color to deep blue."""
        cn_to_num = {"一": 1, "二": 2, "三": 3, "四": 4, "五": 5, "六": 6}
        pos_num = cn_to_num.get(str(pos_cn))
        if pos_num is None:
            self._emit(f"❌ [{log_tag}] 未知背包位置：精灵{pos_cn}", "ERROR")
            return False
        key = self._bag_party_slot_probe_key(pos_num)
        wait_s = float(timeout_s or self.PUTBACK_SLOT_DEEP_BLUE_TIMEOUT_S)
        self._emit(
            f"⏳ [{log_tag}] 已点一次放回仓库，等待精灵{pos_cn}变深蓝后才能继续；超时={wait_s:.0f}s",
            "INFO",
        )
        t0 = time.time()
        last_log = 0.0
        stable_scans = 0
        while time.time() - t0 < wait_s:
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return False
            rgb = self._mean_rgb_for_region_key(key)
            if self._is_pick_bag_slot_deep_blue(rgb):
                stable_scans += 1
                if stable_scans >= 2:
                    self._emit(
                        f"✅ [{log_tag}] 精灵{pos_cn}已变深蓝，确认放回完成：{key} RGB={rgb}",
                        "SUCCESS",
                    )
                    return True
            else:
                stable_scans = 0
            now = time.time()
            if now - last_log >= 1.0:
                self._emit(
                    f"⏳ [{log_tag}] 等待精灵{pos_cn}变深蓝：{key} RGB={rgb}",
                    "DEBUG",
                )
                last_log = now
            self._sleep_abortable(stop_event, 0.1)
        self._emit(
            f"❌ [{log_tag}] 精灵{pos_cn}未在 {wait_s:.0f}s 内变深蓝，停止后续打开仓库",
            "ERROR",
        )
        return False

    def put_back_bag_slot_from_open_bag(
        self,
        pos_cn: str,
        use_foreground: bool,
        stop_event: threading.Event,
        log_tag: str,
        *,
        verify_hp: bool = True,
        verify_slot_deep_blue: bool = False,
        deep_blue_verify_pos: Optional[str] = None,
    ) -> bool:
        """Put one selected bag slot back to storage while the bag is already open."""
        try:
            self._emit(f"[{log_tag}] 放回精灵{pos_cn}", "INFO")
            self._click_bag_pet_slot_double(str(pos_cn), use_foreground)
            self._sleep_abortable(stop_event, 0.5)
            self._click_return_storage(use_foreground)
            self._sleep_abortable(stop_event, 0.8)
            if verify_slot_deep_blue:
                verify_pos = str(deep_blue_verify_pos or pos_cn)
                self._emit(
                    f"[{log_tag}] 精灵会自动向前补位：本次点击精灵{pos_cn}，改为验证精灵{verify_pos}",
                    "INFO",
                )
                return self.wait_bag_putback_slot_deep_blue(
                    verify_pos, stop_event, log_tag
                )
            if not verify_hp:
                self._emit(f"[{log_tag}] 已点击放回精灵{pos_cn}，跳过血条确认", "INFO")
                return True
            if not self.regions.get(f"精灵背包.血条{pos_cn}"):
                self._emit(f"[{log_tag}] 缺少精灵背包.血条{pos_cn}，放回后跳过血条确认", "INFO")
                return True
            return self._confirm_putback_hp_bar_cleared(str(pos_cn), use_foreground, stop_event)
        except Exception as exc:
            self._emit(f"[{log_tag}] 放回精灵{pos_cn}失败：{exc}", "ERROR")
            return False

    def wait_bag_putback_slot_deep_blue(
        self,
        pos_cn: str,
        stop_event: threading.Event,
        log_tag: str,
        *,
        timeout_s: Optional[float] = None,
    ) -> bool:
        """供测试模式和日常共用：只扫描指定精灵槽位，等待放回后的深蓝色。"""
        return self._wait_pick_bag_slot_deep_blue(
            str(pos_cn),
            stop_event,
            log_tag,
            timeout_s=timeout_s,
        )

    def put_back_cyan_slots_from_open_bag(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
        log_tag: str,
        *,
        require_cyan: bool = True,
        max_slots: Optional[int] = None,
        verify_hp: bool = True,
        require_all_six_tricolor: bool = False,
        verify_slot_deep_blue: bool = False,
    ) -> bool:
        """Put cyan bag slots back to storage while the bag is already open."""
        if require_all_six_tricolor:
            scan = self.scan_full_pick_bag_party_color_slots(
                stop_event,
                log_tag,
                timeout_s=8.0,
            )
        else:
            scan = self.scan_pick_bag_party_color_slots_any(
                stop_event,
                log_tag,
                timeout_s=8.0,
                min_cyan=1 if require_cyan else 0,
                min_purple=0,
            )
        if require_all_six_tricolor and not scan.get("ok"):
            return False
        all_cyan_slots = list(scan.get("cyan_slots") or [])
        if require_all_six_tricolor and max_slots == 1 and len(all_cyan_slots) != 1:
            self._emit(
                f"❌ [{log_tag}] 严格单青放回要求恰好1个青色，实际={all_cyan_slots}",
                "ERROR",
            )
            return False
        cyan_slots = list(all_cyan_slots)
        if max_slots is not None:
            cyan_slots = cyan_slots[: max(0, int(max_slots))]
            if len(all_cyan_slots) > len(cyan_slots):
                self._emit(
                    f"[{log_tag}] 识别到多个青色槽位 {all_cyan_slots}，本流程只放回 {cyan_slots}",
                    "INFO",
                )
        if not cyan_slots:
            if require_cyan:
                self._emit(f"[{log_tag}] 未识别到青色槽位，无法放回", "ERROR")
                return False
            self._emit(f"[{log_tag}] 未识别到青色槽位，跳过放回", "INFO")
            return True
        compacted_empty_slots = ("六", "五", "四", "三", "二", "一")
        for index, pos in enumerate(cyan_slots):
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                stop_event.set()
                return False
            if not self.put_back_bag_slot_from_open_bag(
                str(pos),
                use_foreground,
                stop_event,
                log_tag,
                verify_hp=verify_hp,
                verify_slot_deep_blue=verify_slot_deep_blue,
                deep_blue_verify_pos=(
                    compacted_empty_slots[index]
                    if verify_slot_deep_blue and index < len(compacted_empty_slots)
                    else None
                ),
            ):
                return False
        return True

    def _scan_bag_orange_slots_2_to_6(
        self,
        stop_event: threading.Event,
        log_tag: str,
        *,
        timeout_s: float = 8.0,
    ) -> Optional[List[int]]:
        """Return a stable snapshot of orange bag slots among positions 2-6."""
        required_stable = 2
        stable_count = 0
        last_signature: Optional[Tuple[Optional[str], ...]] = None
        last_desc = ""
        attempt = 0
        t0 = time.time()

        while time.time() - t0 <= timeout_s:
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return None

            attempt += 1
            colors: Dict[int, Optional[str]] = {}
            rgbs: Dict[int, Optional[Tuple[int, int, int]]] = {}
            for pos in range(2, 7):
                rgb = self._mean_rgb_for_region_key(self._bag_party_slot_probe_key(pos))
                rgbs[pos] = rgb
                colors[pos] = self._classify_pick_bag_slot_rgb(rgb)

            signature = tuple(colors[pos] for pos in range(2, 7))
            samples_ready = all(rgbs[pos] is not None for pos in range(2, 7))
            if samples_ready and signature == last_signature:
                stable_count += 1
            elif samples_ready:
                stable_count = 1
            else:
                stable_count = 0
            last_signature = signature

            last_desc = "; ".join(
                f"精灵{pos}=RGB{rgbs[pos]}/{self._pick_bag_color_label(colors[pos])}"
                for pos in range(2, 7)
            )
            if attempt <= 3 or attempt % 10 == 0 or stable_count >= required_stable:
                self._emit(
                    f"[{log_tag}] 扫描2-6号第{attempt}次：{last_desc}；"
                    f"稳定={stable_count}/{required_stable}",
                    "DEBUG" if stable_count < required_stable else "INFO",
                )

            if stable_count >= required_stable:
                orange_slots = [
                    pos for pos in range(2, 7) if colors[pos] == "orange"
                ]
                self._emit(
                    f"✅ [{log_tag}] 2-6号槽位颜色已稳定，橙色位置={orange_slots or '无'}",
                    "SUCCESS",
                )
                return orange_slots

            self._sleep_abortable(stop_event, 0.12)

        self._emit(
            f"❌ [{log_tag}] 扫描2-6号橙色位置超时，最后={last_desc}",
            "ERROR",
        )
        return None

    def _wait_bag_skill3_probe_stable(
        self,
        stop_event: threading.Event,
        log_tag: str,
    ) -> Optional[Tuple[int, int, int]]:
        """Wait for the skill-three probe to settle and return its stable RGB."""
        key = self.BAG_SKILL3_PROBE_KEY
        stable_values: List[Tuple[int, int, int]] = []
        last_rgb: Optional[Tuple[int, int, int]] = None
        attempt = 0
        t0 = time.time()

        while time.time() - t0 <= self.BAG_SKILL3_STABLE_TIMEOUT_SEC:
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return None

            attempt += 1
            rgb = self._mean_rgb_for_region_key(key)
            last_rgb = rgb
            if rgb is None:
                stable_values = []
            elif not stable_values:
                stable_values = [rgb]
            else:
                anchor = stable_values[0]
                channel_delta = max(
                    abs(int(rgb[index]) - int(anchor[index])) for index in range(3)
                )
                if channel_delta <= self.BAG_SKILL3_STABLE_CHANNEL_DELTA:
                    stable_values.append(rgb)
                else:
                    stable_values = [rgb]

            stable_count = len(stable_values)
            if attempt <= 3 or attempt % 10 == 0:
                self._emit(
                    f"[{log_tag}] 等待 {key} RGB稳定：当前={rgb}，"
                    f"稳定={stable_count}/{self.BAG_SKILL3_STABLE_SCANS}",
                    "DEBUG",
                )

            if stable_count >= self.BAG_SKILL3_STABLE_SCANS:
                samples = stable_values[-self.BAG_SKILL3_STABLE_SCANS :]
                stable_rgb = tuple(
                    int(round(sum(sample[index] for sample in samples) / len(samples)))
                    for index in range(3)
                )
                self._emit(
                    f"✅ [{log_tag}] {key} RGB已稳定：{stable_rgb}",
                    "SUCCESS",
                )
                return stable_rgb

            self._sleep_abortable(stop_event, self.BAG_SKILL3_STABLE_POLL_SEC)

        self._emit(
            f"❌ [{log_tag}] {key} 在 {self.BAG_SKILL3_STABLE_TIMEOUT_SEC:.0f}s 内未稳定，"
            f"最后RGB={last_rgb}",
            "ERROR",
        )
        return None

    def _bag_skill3_matches_pet166(
        self, rgb: Tuple[int, int, int]
    ) -> bool:
        return any(
            all(
                abs(int(rgb[index]) - int(target[index]))
                <= self.BAG_SKILL3_PET166_RGB_TOLERANCE
                for index in range(3)
            )
            for target in self.BAG_SKILL3_PET166_TARGET_RGBS
        )

    def _bag_skill3_matches_primary_target(
        self, rgb: Tuple[int, int, int]
    ) -> bool:
        """Compatibility wrapper: the skill-three target is specifically pet 166."""
        return self._bag_skill3_matches_pet166(rgb)

    def _bag_slot_one_is_pet166_from_open_bag(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
        *,
        log_tag: str,
    ) -> bool:
        """Verify that bag slot one is pet 166 using its stable skill-three RGB."""
        self._emit(
            f"🔎 [{log_tag}] SWFCheck已通过；开包后精灵一已选中，"
            "直接用技能三确认首发166",
            "SYSTEM",
        )
        stable_rgb = self._wait_bag_skill3_probe_stable(
            stop_event,
            f"{log_tag}·技能三",
        )
        if stable_rgb is None:
            self._emit(
                f"⚠️ [{log_tag}] 精灵一技能三探针未稳定，按首发166 mismatch处理",
                "WARN",
            )
            return False
        if not self._bag_skill3_matches_pet166(stable_rgb):
            self._emit(
                f"⚠️ [{log_tag}] 精灵一技能三RGB={stable_rgb}，"
                f"未命中166目标{self.BAG_SKILL3_PET166_TARGET_RGBS}，按mismatch处理",
                "WARN",
            )
            return False
        self._emit(
            f"✅ [{log_tag}] 精灵一技能三RGB={stable_rgb}命中166，首发正确",
            "SUCCESS",
        )
        return True

    def run_bag_putback_test(
        self,
        test_name: str,
        use_foreground: bool,
        stop_event: threading.Event,
    ) -> bool:
        """Run the standalone bag probe test selected by the dashboard."""
        test_name = str(test_name or "").strip()
        if test_name == "orange_skill3_primary":
            log_tag = "测试模式·橙色技能三探针"
            self._emit(
                f"🧪 [{log_tag}] 打开背包→稳定扫描2-6号橙色位置→"
                f"逐只等待技能三探针稳定；RGB接近166目标"
                f"{self.BAG_SKILL3_PET166_TARGET_RGBS}则设为首发",
                "SYSTEM",
            )
            if not self._pickmode_open_bag_ready_for_target(
                use_foreground,
                stop_event,
                log_tag=f"{log_tag}·开包",
            ):
                return False

            orange_slots = self._scan_bag_orange_slots_2_to_6(
                stop_event,
                f"{log_tag}·橙色位置",
                timeout_s=8.0,
            )
            if orange_slots is None:
                return False

            cn = {2: "二", 3: "三", 4: "四", 5: "五", 6: "六"}
            primary_count = 0
            for pos in orange_slots:
                if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                    return False
                pos_cn = cn[pos]
                slot_tag = f"{log_tag}·精灵{pos_cn}"
                self._emit(f"[{slot_tag}] 选中橙色槽位并读取技能三探针", "INFO")
                if not self._click_pet_with_selection_check(
                    pos_cn, use_foreground, stop_event
                ):
                    self._emit(f"❌ [{slot_tag}] 槽位未能选中，停止测试", "ERROR")
                    return False
                self._sleep_abortable(stop_event, 0.5)

                stable_rgb = self._wait_bag_skill3_probe_stable(
                    stop_event,
                    slot_tag,
                )
                if stable_rgb is None:
                    return False

                if self._bag_skill3_matches_pet166(stable_rgb):
                    self._emit(
                        f"[{slot_tag}] 稳定RGB={stable_rgb} 命中166目标 "
                        f"{self.BAG_SKILL3_PET166_TARGET_RGBS}，设该精灵为首发",
                        "SUCCESS",
                    )
                    self._click_region("精灵背包.设为首发", use_foreground)
                    self._sleep_abortable(stop_event, 0.8)
                    primary_count += 1
                else:
                    self._emit(
                        f"[{slot_tag}] 稳定RGB={stable_rgb} 未命中灰白目标，继续下一个橙色槽位",
                        "INFO",
                    )

            self._emit(
                f"✅ [{log_tag}] 已探索全部橙色位置 {orange_slots or '无'}，"
                f"设为首发次数={primary_count}",
                "SUCCESS",
            )
            return True

        self._emit(f"❌ [测试模式] 未知测试功能：{test_name}", "ERROR")
        return False

    def restore_pet166_primary_after_197_success_or_reseat(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
        *,
        log_tag: str = "197首发胜利后恢复166首发",
    ) -> bool:
        """首个橙色技能三命中166即恢复首发；全部未命中才放回并重新取197。"""
        if not self._pickmode_open_bag_ready_for_target(
            use_foreground,
            stop_event,
            log_tag=f"{log_tag}·开包",
        ):
            return False

        orange_slots = self._scan_bag_orange_slots_2_to_6(
            stop_event,
            f"{log_tag}·橙色位置",
            timeout_s=8.0,
        )
        if orange_slots is None:
            return False

        cn = {2: "二", 3: "三", 4: "四", 5: "五", 6: "六"}
        for pos in orange_slots:
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return False
            pos_cn = cn[pos]
            slot_tag = f"{log_tag}·精灵{pos_cn}"
            self._emit(f"[{slot_tag}] 选中橙色槽位并读取技能三探针", "INFO")
            if not self._click_pet_with_selection_check(
                pos_cn,
                use_foreground,
                stop_event,
            ):
                self._emit(f"⚠️ [{slot_tag}] 槽位未能选中，继续下一个橙色槽位", "WARN")
                continue
            self._sleep_abortable(stop_event, 0.5)
            stable_rgb = self._wait_bag_skill3_probe_stable(
                stop_event,
                slot_tag,
            )
            if stable_rgb is None:
                self._emit(f"⚠️ [{slot_tag}] 技能三探针未稳定，继续下一个橙色槽位", "WARN")
                continue
            if not self._bag_skill3_matches_pet166(stable_rgb):
                self._emit(
                    f"[{slot_tag}] 稳定RGB={stable_rgb} 未命中166，继续扫描",
                    "INFO",
                )
                continue

            self._emit(
                f"✅ [{slot_tag}] 稳定RGB={stable_rgb} 命中166，"
                "设166为首发并立即停止扫描",
                "SUCCESS",
            )
            self._click_region("精灵背包.设为首发", use_foreground)
            self._sleep_abortable(stop_event, 0.8)
            self._close_pet_bag_with_verify(
                use_foreground,
                stop_event,
                "精灵背包.打开精灵背包",
                "精灵背包.打开精灵背包按钮",
                log_tag=log_tag,
            )
            return not stop_event.is_set() and not getattr(self.bot, "stop_current", False)

        self._emit(
            f"⚠️ [{log_tag}] 橙色技能三未找到166，"
            "执行兜底：放回197后重新取197",
            "WARN",
        )
        if not self.put_back_cyan_slots_from_open_bag(
            use_foreground,
            stop_event,
            f"{log_tag}·兜底放回197",
            require_cyan=True,
            max_slots=1,
            require_all_six_tricolor=True,
            verify_slot_deep_blue=True,
        ):
            return False
        if not self._pickmode_open_warehouse_from_ready_bag(
            use_foreground,
            stop_event,
            log_tag=f"{log_tag}·兜底打开仓库",
        ):
            return False
        if not self.take_pickmode_pets_from_open_bag_warehouse(
            (PICKMODE_CYAN_BASE_PET_ID,),
            use_foreground,
            stop_event,
            log_tag=f"{log_tag}·兜底取197",
        ):
            return False
        self._click_pet_warehouse_close(use_foreground, log_tag=log_tag)
        self._sleep_abortable(stop_event, 0.5)
        self._close_pet_bag_with_verify(
            use_foreground,
            stop_event,
            "精灵背包.打开精灵背包",
            "精灵背包.打开精灵背包按钮",
            log_tag=log_tag,
        )
        return not stop_event.is_set() and not getattr(self.bot, "stop_current", False)

    def recover_cyan_and_follow_purple_from_open_bag(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
        log_tag: str,
        *,
        set_cyan_primary: bool = False,
        recover_pet_one: bool = True,
        recover_cyan: bool = True,
        set_follow_purple: bool = True,
        skip_cyan_recovery_when_primary: bool = False,
    ) -> bool:
        """Set cyan primary, recover selected pets, and follow purple while the bag is already open."""
        scan = self.scan_pick_bag_party_color_slots_any(
            stop_event,
            log_tag,
            timeout_s=10.0,
            min_cyan=1 if (set_cyan_primary or recover_cyan) else 0,
            min_purple=1 if set_follow_purple else 0,
        )
        if not scan.get("ok"):
            return False
        cyan = scan.get("cyan")
        purple = scan.get("purple")
        cyan_was_primary = str(cyan) == "一"
        if set_cyan_primary:
            if not cyan:
                self._emit(f"[{log_tag}] 未识别青色槽位，无法设为首发", "ERROR")
                return False
            if str(cyan) == "一":
                self._emit(
                    f"[{log_tag}] 前置SWF颜色确认青色已在精灵一，跳过重复设置首发",
                    "SUCCESS",
                )
            else:
                primary_ok = False
                for attempt in range(1, 4):
                    if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                        stop_event.set()
                        return False
                    self._emit(f"[{log_tag}] 设青色精灵{cyan}为首发（第{attempt}次）", "INFO")
                    if self.regions.get(f"精灵背包.选中{cyan}"):
                        if not self._click_pet_with_selection_check(str(cyan), use_foreground, stop_event):
                            self._emit(f"[{log_tag}] 青色精灵{cyan}选中失败，重试设首发", "WARN")
                            continue
                    else:
                        self._emit(f"[{log_tag}] 缺少精灵背包.选中{cyan}，无法确认青色首发选中", "ERROR")
                        return False
                    self._click_region("精灵背包.设为首发", use_foreground)
                    self._sleep_abortable(stop_event, 0.8)
                    verify = self.scan_pick_bag_party_color_slots_any(
                        stop_event,
                        f"{log_tag}·首发确认",
                        timeout_s=2.0,
                        min_cyan=1,
                        min_purple=0,
                    )
                    verify_cyan = verify.get("cyan")
                    if verify.get("ok") and verify_cyan == "一":
                        cyan = "一"
                        primary_ok = True
                        self._emit(f"[{log_tag}] 青色已确认在精灵一", "SUCCESS")
                        break
                    if verify_cyan:
                        cyan = verify_cyan
                    self._emit(
                        f"[{log_tag}] 青色首发未确认，当前青色={verify_cyan or '未知'}，继续重试",
                        "WARN",
                    )
                if not primary_ok:
                    self._emit(f"[{log_tag}] 青色未能设为首发", "ERROR")
                    return False
                if set_follow_purple:
                    # Setting the primary pet can reorder the party slots. The
                    # purple position from the pre-primary scan is no longer
                    # reliable, so rescan after the primary action succeeds.
                    self._emit(f"[{log_tag}] 首发已确认，重新扫描1-6号确定紫色位置", "INFO")
                    refreshed = self.scan_pick_bag_party_color_slots_any(
                        stop_event,
                        f"{log_tag}·首发后重扫紫色",
                        timeout_s=5.0,
                        min_cyan=0,
                        min_purple=1,
                    )
                    if not refreshed.get("ok") or not refreshed.get("purple"):
                        self._emit(f"[{log_tag}] 首发后未识别到紫色槽位，无法设置跟随", "ERROR")
                        return False
                    purple = refreshed.get("purple")
                    self._emit(f"[{log_tag}] 首发后紫色位置更新为精灵{purple}", "SUCCESS")
        recovery_slots: List[Optional[str]] = []
        if recover_pet_one:
            recovery_slots.append("一")
        if recover_cyan:
            if not cyan:
                self._emit(f"[{log_tag}] 未识别青色槽位，恢复失败", "ERROR")
                return False
            if skip_cyan_recovery_when_primary and cyan_was_primary:
                self._emit(
                    f"[{log_tag}] SWF目标组正确且青色已在精灵一，"
                    "跳过青色恢复，直接跟随紫色",
                    "SUCCESS",
                )
            else:
                recovery_slots.append(str(cyan))
        if recovery_slots:
            self._recover_unique_bag_slots(
                recovery_slots,
                use_foreground,
                stop_event,
                log_tag,
            )
        if set_follow_purple:
            if not purple:
                self._emit(f"[{log_tag}] 未识别紫色槽位，跟随失败", "ERROR")
                return False
            self._emit(f"[{log_tag}] 身边跟随紫色精灵{purple}", "INFO")
            if self.regions.get(f"精灵背包.选中{purple}"):
                if not self._click_pet_with_selection_check(str(purple), use_foreground, stop_event):
                    self._emit(f"[{log_tag}] 紫色精灵{purple}选中检测失败，无法设置跟随", "ERROR")
                    return False
            else:
                self._emit(f"[{log_tag}] 缺少精灵背包.选中{purple}，无法确认紫色跟随选中", "ERROR")
                return False
            self._sleep_abortable(stop_event, 0.5)
            self._click_region("精灵背包.身边跟随", use_foreground)
            self._sleep_abortable(stop_event, 0.5)
        self._reset_skill_recovery_counters(log_tag)
        return True

    def _reset_skill_recovery_counters(self, reason: str) -> None:
        self._post_recover_skill3_uses = 0
        self._post_recover_skill4_uses = 0
        self._emit(f"[skill-recover-counter] {reason}; skill3/skill4 counters reset", "INFO")

    def _configured_nieo_skill_recovery_thresholds(self) -> Tuple[int, int]:
        profile = getattr(self, "_configured_nieo_profile", None)
        skill3_threshold = max(
            1, int(getattr(profile, "skill3_recovery_uses", 10) or 10)
        )
        skill4_threshold = max(
            1,
            int(
                getattr(
                    profile,
                    "skill4_recovery_uses",
                    self.PEM_SKILL4_MAINTENANCE_EVERY_BATTLES,
                )
                or self.PEM_SKILL4_MAINTENANCE_EVERY_BATTLES
            ),
        )
        return skill3_threshold, skill4_threshold

    def _record_skill_defeat_and_maybe_recover(
        self,
        skill_action: str,
        use_foreground: bool,
        stop_event: threading.Event,
        *,
        log_tag: str,
        uses: int = 1,
    ) -> bool:
        if skill_action == "skill3":
            self._post_recover_skill3_uses = int(getattr(self, "_post_recover_skill3_uses", 0) or 0) + max(0, int(uses))
        elif skill_action == "skill4":
            self._post_recover_skill4_uses = int(getattr(self, "_post_recover_skill4_uses", 0) or 0) + max(0, int(uses))
        else:
            return False
        s3 = int(getattr(self, "_post_recover_skill3_uses", 0) or 0)
        s4 = int(getattr(self, "_post_recover_skill4_uses", 0) or 0)
        skill3_threshold, skill4_threshold = (
            self._configured_nieo_skill_recovery_thresholds()
        )
        self._emit(
            f"[{log_tag}] skill recover counters: skill3={s3}/{skill3_threshold}, "
            f"skill4={s4}/{skill4_threshold}",
            "INFO",
        )
        profile = getattr(self, "_configured_nieo_profile", None)
        sequential = bool(
            profile is not None
            and getattr(profile, "sequential_skill_recovery", False)
        )
        if sequential:
            if s4 < skill4_threshold or s3 < skill3_threshold:
                return False
            reason = (
                f"skill4 reached {skill4_threshold}, then skill3 reached "
                f"{skill3_threshold}"
            )
        else:
            if s3 < skill3_threshold and s4 < skill4_threshold:
                return False
            reason = (
                f"skill3 reached {skill3_threshold}"
                if s3 >= skill3_threshold
                else f"skill4 reached {skill4_threshold}"
            )
        if profile is not None and getattr(profile, "recovery_via_reconnect", False):
            self._emit(
                f"🔄 [{profile.name}] {reason}；不切 A/C，直接刷新重连恢复",
                "SYSTEM",
            )
            self._reset_skill_recovery_counters(f"reconnect-{reason}")
            self._check_configured_nieo_reconnect_condition(
                use_foreground,
                stop_event,
                force_reconnect=True,
                force_reason=f"{reason} 触发恢复",
            )
            return True
        if self._queue_configured_nieo_recovery(
            kind="skill",
            current_map_id=getattr(self, "_configured_nieo_active_map_id", None),
            reason=reason,
        ):
            self._reset_skill_recovery_counters(f"deferred-{reason}")
            return True
        self._emit(f"[{log_tag}] {reason}; recover primary/cyan/purple", "SYSTEM")
        return self._recover_pick_party_from_closed_bag(
            use_foreground,
            stop_event,
            f"{log_tag}-{reason}",
            include_primary=False,
            set_follow_primary=True,
        )

    def _recover_pick_party_from_closed_bag(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
        log_tag: str,
        *,
        include_primary: bool,
        set_follow_primary: bool,
    ) -> bool:
        bag_open_key = '精灵背包.打开精灵背包'
        bag_open_btn_key = "精灵背包.打开精灵背包按钮"
        try:
            self._emit(f"[{log_tag}] 打开精灵背包", "INFO")
            try:
                self._click_region(bag_open_btn_key, use_foreground)
            except KeyError:
                self._click_region(bag_open_key, use_foreground)
            if not self._ensure_pet_bag_ui_ready_after_open(
                stop_event, use_foreground, bag_open_key, bag_open_btn_key
            ):
                self._emit(f"[{log_tag}] 精灵背包UI未就绪，停止本次技能恢复", "ERROR")
                return False
            if not self._recover_pick_party_after_bag_ready(
                use_foreground,
                stop_event,
                log_tag,
                include_primary=include_primary,
                set_follow_primary=set_follow_primary,
            ):
                self._emit(f"[{log_tag}] 恢复或跟随未完成", "ERROR")
                return False
            if set_follow_primary:
                self._emit(
                    f"[{log_tag}] 身边跟随已自动关闭背包，不再点击背包按钮",
                    "SUCCESS",
                )
                return True
            self._close_pet_bag_with_verify(
                use_foreground,
                stop_event,
                bag_open_key,
                bag_open_btn_key,
                log_tag=log_tag,
            )
            return True
        except Exception as exc:
            self._emit(f"[{log_tag}] skill recovery error: {exc}", "ERROR")
            return False

    def recover_pick_party_color_slots_from_closed_bag(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
        log_tag: str,
        *,
        recover_cyan: bool = False,
        recover_purple: bool = False,
        set_follow_purple: bool = False,
        before_close_callback: Optional[Callable[[], bool]] = None,
        bag_already_open: bool = False,
    ) -> bool:
        """Recover selected bag pets by live color scan."""
        bag_open_key = '精灵背包.打开精灵背包'
        bag_open_btn_key = "精灵背包.打开精灵背包按钮"
        reuse_verified_primary = bool(
            bag_already_open
            and getattr(self, "_pick_party_verified_primary_selected", False)
        )
        self._pick_party_verified_primary_selected = False
        try:
            if bag_already_open:
                self._emit(
                    f"[{log_tag}] 沿用从精灵背包关闭仓库后保持打开的背包，不再点击背包按钮",
                    "INFO",
                )
            else:
                self._emit(f"[{log_tag}] 打开精灵背包进行颜色恢复", "INFO")
                try:
                    self._click_region(bag_open_btn_key, use_foreground)
                except KeyError:
                    self._click_region(bag_open_key, use_foreground)

            if not self._ensure_pet_bag_ui_ready_after_open(
                stop_event,
                use_foreground,
                bag_open_key,
                bag_open_btn_key,
                log_tag=log_tag,
            ):
                self._emit(f"[{log_tag}] 精灵背包UI未就绪，颜色恢复失败", "ERROR")
                self._close_pet_bag_with_verify(
                    use_foreground,
                    stop_event,
                    bag_open_key,
                    bag_open_btn_key,
                    log_tag=log_tag,
                )
                return False

            if reuse_verified_primary:
                self._emit(
                    f"[{log_tag}] 166技能三已通过且精灵一仍为选中状态，直接恢复精灵一",
                    "SUCCESS",
                )
                self._recover_selected_bag_pet_once(
                    "一",
                    use_foreground,
                    stop_event,
                    log_tag,
                )

            scan = self._scan_pick_bag_party_slots_1_to_6(
                stop_event,
                log_tag,
                timeout_s=10.0,
            )
            if not scan.get("ok"):
                self._emit(
                    f"[{log_tag}] 实时颜色扫描失败；不使用旧槽位缓存，停止颜色恢复",
                    "ERROR",
                )
                self._close_pet_bag_with_verify(
                    use_foreground,
                    stop_event,
                    bag_open_key,
                    bag_open_btn_key,
                    log_tag=log_tag,
                )
                return False
            cyan = scan.get("cyan")
            purple = scan.get("purple")
            self._emit(
                f"[{log_tag}] 实时颜色槽位：青色=精灵{cyan}，紫色=精灵{purple}",
                "INFO",
            )

            targets = []
            if recover_cyan:
                if not cyan:
                    self._emit(f"[{log_tag}] 未识别青色槽位，颜色恢复失败", "ERROR")
                    self._close_pet_bag_with_verify(
                        use_foreground,
                        stop_event,
                        bag_open_key,
                        bag_open_btn_key,
                        log_tag=log_tag,
                    )
                    return False
                targets.append(str(cyan))
            if recover_purple or set_follow_purple:
                if not purple:
                    self._emit(f"[{log_tag}] 未识别紫色槽位，颜色恢复失败", "ERROR")
                    self._close_pet_bag_with_verify(
                        use_foreground,
                        stop_event,
                        bag_open_key,
                        bag_open_btn_key,
                        log_tag=log_tag,
                    )
                    return False
                if recover_purple:
                    targets.append(str(purple))

            self._recover_unique_bag_slots(
                ([] if reuse_verified_primary else ["一"]) + targets,
                use_foreground,
                stop_event,
                log_tag,
            )

            if set_follow_purple and purple:
                self._emit(f"[{log_tag}] 身边跟随紫色精灵{purple}", "INFO")
                self._click_bag_pet_slot_double(str(purple), use_foreground)
                self._sleep_abortable(stop_event, 0.5)
                self._click_region("精灵背包.身边跟随", use_foreground)
                self._sleep_abortable(stop_event, 0.5)

            if set_follow_purple and not callable(before_close_callback):
                self._reset_skill_recovery_counters(log_tag)
                self._emit(f"[{log_tag}] 已设置身边跟随，背包应由跟随动作自动关闭", "SUCCESS")
                return True

            if callable(before_close_callback):
                self._emit(f"[{log_tag}] 执行关闭背包前回调", "INFO")
                if not bool(before_close_callback()):
                    self._emit(f"[{log_tag}] 关闭背包前回调失败", "ERROR")
                    self._close_pet_bag_with_verify(
                        use_foreground,
                        stop_event,
                        bag_open_key,
                        bag_open_btn_key,
                        log_tag=log_tag,
                    )
                    return False

            self._close_pet_bag_with_verify(
                use_foreground,
                stop_event,
                bag_open_key,
                bag_open_btn_key,
                log_tag=log_tag,
            )
            self._reset_skill_recovery_counters(log_tag)
            return True
        except Exception as exc:
            self._emit(f"[{log_tag}] 颜色恢复异常：{exc}", "ERROR")
            try:
                self._close_pet_bag_with_verify(
                    use_foreground,
                    stop_event,
                    bag_open_key,
                    bag_open_btn_key,
                    log_tag=log_tag,
                )
            except Exception:
                pass
            return False

    def set_follow_purple_jita_from_closed_bag(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
        log_tag: str = "紫色机塔跟随",
        *,
        bag_already_open: bool = False,
    ) -> bool:
        """Open the bag and follow a purple slot, including a partial party."""
        bag_open_key = '精灵背包.打开精灵背包'
        bag_open_btn_key = "精灵背包.打开精灵背包按钮"
        try:
            if bag_already_open:
                self._emit(
                    f"[{log_tag}] 仓库关闭后背包仍打开，直接扫描紫色机塔",
                    "INFO",
                )
            else:
                self._emit(f"[{log_tag}] 打开精灵背包", "INFO")
                try:
                    self._click_region(bag_open_btn_key, use_foreground)
                except KeyError:
                    self._click_region(bag_open_key, use_foreground)

            if not self._ensure_pet_bag_ui_ready_after_open(
                stop_event, use_foreground, bag_open_key, bag_open_btn_key, log_tag=log_tag
            ):
                self._emit(f"[{log_tag}] 精灵背包UI未就绪，无法设置跟随", "ERROR")
                self._close_pet_bag_with_verify(
                    use_foreground, stop_event, bag_open_key, bag_open_btn_key, log_tag=log_tag
                )
                return False

            scan = self.scan_pick_bag_party_color_slots_any(
                stop_event,
                log_tag,
                timeout_s=10.0,
                min_cyan=0,
                min_purple=1,
            )
            purple = scan.get("purple") if scan.get("ok") else None
            if not purple:
                self._emit(f"[{log_tag}] 未识别紫色槽位，停止跟随流程", "ERROR")
                self._close_pet_bag_with_verify(
                    use_foreground, stop_event, bag_open_key, bag_open_btn_key, log_tag=log_tag
                )
                return False

            self._emit(f"[{log_tag}] 身边跟随紫色精灵{purple}", "SYSTEM")
            self._click_bag_pet_slot_double(str(purple), use_foreground)
            self._sleep_abortable(stop_event, 0.5)
            self._click_region("精灵背包.身边跟随", use_foreground)
            self._sleep_abortable(stop_event, 0.5)
            self._emit(f"[{log_tag}] 紫色跟随已设置，背包应由跟随动作自动关闭", "SUCCESS")
            return True
        except Exception as exc:
            self._emit(f"[{log_tag}] 设置紫色跟随失败：{exc}", "ERROR")
            return False

    def _reset_current_battle_skill_use_counters(self) -> None:
        self._current_battle_skill3_uses = 0
        self._current_battle_skill4_uses = 0

    def _note_current_battle_skill_use(self, skill_action: str) -> None:
        if skill_action == "skill3":
            self._current_battle_skill3_uses = int(getattr(self, "_current_battle_skill3_uses", 0) or 0) + 1
        elif skill_action == "skill4":
            self._current_battle_skill4_uses = int(getattr(self, "_current_battle_skill4_uses", 0) or 0) + 1

    def _commit_current_battle_skill_uses_and_maybe_recover(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
        *,
        log_tag: str,
    ) -> bool:
        s3 = int(getattr(self, "_current_battle_skill3_uses", 0) or 0)
        s4 = int(getattr(self, "_current_battle_skill4_uses", 0) or 0)
        recovery_triggered = False
        if s3:
            recovery_triggered = self._record_skill_defeat_and_maybe_recover(
                "skill3", use_foreground, stop_event, log_tag=log_tag, uses=s3
            ) or recovery_triggered
        if s4:
            recovery_triggered = self._record_skill_defeat_and_maybe_recover(
                "skill4", use_foreground, stop_event, log_tag=log_tag, uses=s4
            ) or recovery_triggered
        self._reset_current_battle_skill_use_counters()
        return recovery_triggered

    def _recover_pick_party_after_bag_ready(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
        log_tag: str,
        *,
        include_primary: bool = True,
        set_follow_primary: bool = False,
        follow_primary_color: Optional[str] = None,
        require_scan_success: bool = False,
        primary_already_recovered: bool = False,
    ) -> bool:
        self._emit(
            f"[{log_tag}] 精灵背包就绪，扫描1-6号槽位",
            "INFO",
        )
        scan = self._scan_pick_bag_party_slots_1_to_6(stop_event, log_tag)
        if not scan.get("ok"):
            cyan = None
            purple = None
            if set_follow_primary or require_scan_success:
                follow_color = str(
                    follow_primary_color
                    or ("cyan" if getattr(self, "_nieo_follow_cyan", False) else "purple")
                ).strip().lower()
                follow_label = "青色" if follow_color == "cyan" else "紫色"
                if set_follow_primary:
                    self._emit(
                        f"❌ [{log_tag}] 背包槽位扫描失败，无法确认{follow_label}跟随",
                        "ERROR",
                    )
                else:
                    self._emit(
                        f"❌ [{log_tag}] 背包槽位扫描失败，严格识别未完成",
                        "ERROR",
                    )
                return False
            self._emit(
                f"[{log_tag}] 背包槽位扫描失败；不使用旧槽位缓存，仅恢复固定槽位精灵一",
                "WARN",
            )
        else:
            cyan = scan.get("cyan")
            purple = scan.get("purple")
            self._emit(
                f"[{log_tag}] 背包恢复槽位：青色=精灵{cyan}，紫色=精灵{purple}",
                "INFO",
            )

        if include_primary:
            target = None
            primary_type = self._last_battle_primary_pet_type
            if primary_type in ("aifeidesi", "aisifeige"):
                target = cyan
                self._emit(
                    f"[{log_tag}] 上次首发={primary_type}，恢复当前青色精灵{target or '?'}",
                    "INFO",
                )
            elif primary_type in ("jita", "yameisi"):
                target = purple
                self._emit(
                    f"[{log_tag}] 上次首发={primary_type}，恢复当前紫色精灵{target or '?'}",
                    "INFO",
                )
            elif purple:
                target = purple
                self._emit(
                    f"[{log_tag}] 上次首发未知，兜底恢复紫色精灵{target}",
                    "WARN",
                )
            self._recover_unique_bag_slots(
                ["一", str(target) if target else None],
                use_foreground,
                stop_event,
                log_tag,
            )
            self._last_battle_primary_pet_type = None
            self._last_battle_primary_slot_cn = None
        else:
            self._recover_unique_bag_slots(
                ([] if primary_already_recovered else ["一"]) + [cyan, purple],
                use_foreground,
                stop_event,
                log_tag,
            )
            if set_follow_primary:
                follow_color = str(
                    follow_primary_color
                    or ("cyan" if getattr(self, "_nieo_follow_cyan", False) else "purple")
                ).strip().lower()
                follow_slot = cyan if follow_color == "cyan" else purple
                follow_label = "青色" if follow_color == "cyan" else "紫色"
                if not follow_slot:
                    self._emit(
                        f"❌ [{log_tag}] 未识别{follow_label}槽位，无法设置身边跟随",
                        "ERROR",
                    )
                    return False
                self._emit(
                    f"[{log_tag}] 身边跟随{follow_label}精灵{follow_slot}",
                    "INFO",
                )
                if not self._click_pet_with_selection_check(
                    str(follow_slot),
                    use_foreground,
                    stop_event,
                ):
                    self._emit(
                        f"❌ [{log_tag}] {follow_label}精灵{follow_slot}未能稳定选中，取消跟随",
                        "ERROR",
                    )
                    return False
                self._sleep_abortable(stop_event, 0.5)
                self._click_region("精灵背包.身边跟随", use_foreground)
                self._sleep_abortable(stop_event, 0.5)
        self._reset_skill_recovery_counters(log_tag)
        return not (
            stop_event.is_set() or getattr(self.bot, "stop_current", False)
        )

    def _follow_cyan_from_closed_bag(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
        *,
        log_tag: str,
    ) -> bool:
        """Open the bag, identify the current cyan slot, and set it as companion."""
        bag_open_key = "精灵背包.打开精灵背包"
        bag_open_btn_key = "精灵背包.打开精灵背包按钮"
        bag_opened = False
        try:
            self._emit(f"[{log_tag}] 打开精灵背包，切换身边跟随为青色", "SYSTEM")
            try:
                self._click_region(bag_open_btn_key, use_foreground)
            except KeyError:
                self._click_region(bag_open_key, use_foreground)
            bag_opened = True
            if not self._ensure_pet_bag_ui_ready_after_open(
                stop_event,
                use_foreground,
                bag_open_key,
                bag_open_btn_key,
                log_tag=log_tag,
            ):
                return False

            scan = self._scan_pick_bag_party_slots_1_to_6(stop_event, log_tag)
            cyan_slot = scan.get("cyan") if scan.get("ok") else None
            if cyan_slot not in ("一", "二", "三", "四", "五", "六"):
                self._emit(
                    f"❌ [{log_tag}] 未识别青色槽位，不能进入下一张图",
                    "ERROR",
                )
                return False
            if not self._click_pet_with_selection_check(
                str(cyan_slot),
                use_foreground,
                stop_event,
            ):
                self._emit(
                    f"❌ [{log_tag}] 青色精灵{cyan_slot}未能稳定选中",
                    "ERROR",
                )
                return False

            self._sleep_abortable(stop_event, 0.5)
            self._click_region("精灵背包.身边跟随", use_foreground)
            self._sleep_abortable(stop_event, 0.5)
            bag_opened = False
            self._emit(
                f"✅ [{log_tag}] 已跟随青色精灵{cyan_slot}；背包由跟随动作自动关闭",
                "SUCCESS",
            )
            return not (
                stop_event.is_set() or getattr(self.bot, "stop_current", False)
            )
        except Exception as exc:
            self._emit(f"❌ [{log_tag}] 切换青色跟随异常：{exc}", "ERROR")
            return False
        finally:
            if (
                bag_opened
                and not stop_event.is_set()
                and not getattr(self.bot, "stop_current", False)
            ):
                self._close_pet_bag_with_verify(
                    use_foreground,
                    stop_event,
                    bag_open_key,
                    bag_open_btn_key,
                    log_tag=log_tag,
                )

    def _complete_deferred_cyan_follow_on_a(
        self,
        enabled: bool,
        recovery_was_skipped: bool,
        use_foreground: bool,
        stop_event: threading.Event,
        *,
        log_tag: str,
    ) -> bool:
        """Finish the deferred purple-to-cyan handoff on the first A-map visit."""
        if not enabled:
            return True
        if not recovery_was_skipped:
            self._emit(
                f"✅ [{log_tag}] A图恢复流程已完成青色跟随，准备进入B图",
                "SUCCESS",
            )
            return True
        self._emit(
            f"[{log_tag}] A图恢复因步骤4去重，单独打开背包切换青色后再进入B图",
            "INFO",
        )
        return self._follow_cyan_from_closed_bag(
            use_foreground,
            stop_event,
            log_tag=log_tag,
        )

    def _recover_pets(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
        skip_return_storage: bool = False,
        nie_family_id: Optional[int] = None,
        profile: Optional[WildCaptureProfile] = None,
    ) -> bool:
        """Recover pets after battle or setup."""
        try:
            if skip_return_storage and getattr(self, "_pickmode_base_recovery_done", False):
                self._emit(
                    "[首次恢复] 基础恢复已完成，跳过路线脚本后的重复恢复",
                    "INFO",
                )
                self._pickmode_base_recovery_done = False
                return True
            if not skip_return_storage:
                self._pickmode_base_recovery_done = False

            # 1. 打开精灵背包
            self._emit("打开精灵背包", "INFO")
            bag_open_key = '精灵背包.打开精灵背包'
            bag_open_btn_key = "精灵背包.打开精灵背包按钮"

            # 灏濊瘯点击鎸夐挳锛屽鏋滄病鏈夋寜閽垯点击鍖哄煙
            try:
                self._click_region(bag_open_btn_key, use_foreground)
            except KeyError:
                self._click_region(bag_open_key, use_foreground)

            # 打开精灵背包鍚庣瓑寰?UI 就绪锛堣秴鏃堕噸寮€涓€娆★級锛涙湭就绪鍒欒Е鍙戝埛鏂伴噸杩?
            if not self._ensure_pet_bag_ui_ready_after_open(
                stop_event, use_foreground, bag_open_key, bag_open_btn_key
            ):
                self._request_reconnect_after_recovery_failure(
                    profile,
                    use_foreground,
                    stop_event,
                    "精灵背包UI未就绪",
                )
                return False

            # 娉ㄦ剰锛氭帰閽堟壂鎻忓凡绉诲埌鎭㈠鍜?AND1涔嬪悗锛岄伩鍏嶈鍏朵粬UI元素污染

            # 2. 根据skip_return_storage鍐冲畾鏄惁鎵ц捕捉成功鍚庣殑鎭㈠娴佺▼
            if not skip_return_storage:
                self._emit(
                    "[战后恢复] 已捕捉，不回仓库，直接扫描背包并恢复",
                    "INFO",
                )
                if not self._recover_pick_party_after_bag_ready(
                    use_foreground,
                    stop_event,
                    "战后恢复",
                    include_primary=True,
                    set_follow_primary=False,
                    require_scan_success=True,
                ):
                    self._request_reconnect_after_recovery_failure(
                        profile,
                        use_foreground,
                        stop_event,
                        "战后背包恢复/识别未完成",
                    )
                    return False
                self._flash_aifeia_pos = None
                self._sleep_abortable(stop_event, 0.3)
                self._close_pet_bag_with_verify(
                    use_foreground,
                    stop_event,
                    bag_open_key,
                    bag_open_btn_key,
                    log_tag="战后恢复",
                )
                self._emit("捕捉后恢复流程完成", "SUCCESS")
                return True
            else:
                tag0 = "first-recover"
                if nie_family_id == 416:
                    tag0 = "nieo416-first-recover"
                elif nie_family_id in (77, 310):
                    tag0 = "nie-family-77-310-first-recover"
                if not self._recover_pick_party_after_bag_ready(
                    use_foreground,
                    stop_event,
                    tag0,
                    include_primary=False,
                    set_follow_primary=True,
                ):
                    self._request_reconnect_after_recovery_failure(
                        profile,
                        use_foreground,
                        stop_event,
                        f"{tag0}恢复/跟随未完成",
                    )
                    return False
                self._flash_aifeia_pos = None
                self._sleep_abortable(stop_event, 0.3)
                self._emit(
                    "[opening-recover] 身边跟随已自动关闭背包，不再点击背包按钮",
                    "SUCCESS",
                )
                self._emit("战前恢复流程完成", "SUCCESS")
                return True

            # 鉁?妫€鏌ユ瘡40娆℃垬鏂楁仮澶嶇簿鐏典竴鐨勬潯浠讹紙浠呭湪鎭㈠瀹屽搴旂簿鐏靛悗鎵ц锛?
            # 娉ㄦ剰锛氬彧鏈夊湪娌℃湁鍥犱负精灵鍥涙斁鍥炰粨搴撻棶棰橀噸杩炵殑鎯呭喌涓嬫墠鎵ц
            if not getattr(self, '_reconnect_reason_capture_verify_four', False):
                # 妫€鏌ワ細40娆℃垬鏂楁潯浠讹紙姣?0娆℃垬鏂楁仮澶嶄竴娆＄簿鐏典竴锛?
                battles_since_last_reconnect = self._battle_count - self._last_reconnect_battle_count
                if battles_since_last_reconnect >= 40:
                    self._emit(f"[每40战恢复] 距上次重连已战斗 {battles_since_last_reconnect} 场，恢复精灵一", "INFO")
                    # 鎭㈠精灵涓€锛堟墦寮€背包 -> 双击精灵涓€ -> 鎭㈠ -> 1AND1纭 -> 鍏抽棴背包锛?
                    try:
                        # 0. 打开精灵背包（确保背包是打开的）
                        self._emit("打开精灵背包进行每40战精灵一恢复", "INFO")
                        bag_open_key = '精灵背包.打开精灵背包'
                        bag_open_btn_key = "精灵背包.打开精灵背包按钮"
                        try:
                            self._click_region(bag_open_btn_key, use_foreground)
                        except KeyError:
                            self._click_region(bag_open_key, use_foreground)
                        # 打开精灵背包后扫描清空精灵一探针(#FF9901)就绪
                        if not self._wait_pet_bag_ui_ready_after_open(
                            stop_event, log_tag="每40战恢复"
                        ):
                            self._emit(
                                "[每40战恢复] 背包UI未就绪，取消本次恢复且不重置计数",
                                "ERROR",
                            )
                            return

                        # 1. 双击精灵涓€
                        self._emit("恢复前双击精灵一", "INFO")
                        pet_one_key = "精灵背包.精灵一"
                        pet_one_btn_key = "精灵背包.技能四探针"
                        try:
                            self._click_region_twice(pet_one_btn_key, use_foreground)
                        except KeyError:
                            self._click_region_twice(pet_one_key, use_foreground)

                        # 双击鍚庣瓑寰?.5s
                        self._sleep_abortable(stop_event, 0.5)

                        # 2. 点击"精灵鎭㈠"
                        self._emit("点击精灵一恢复", "INFO")
                        recover_key = "精灵背包.精灵恢复"
                        recover_btn_key = "精灵背包.精灵恢复按钮"
                        try:
                            self._click_region(recover_btn_key, use_foreground)
                        except KeyError:
                            self._click_region(recover_key, use_foreground)

                        # 精灵鎭㈠鍚庣瓑寰?.0s
                        self._sleep_abortable(stop_event, 1.0)

                        # 3. 使用1AND1纭娈嬬暀鐨勬仮澶嶅悗鐨勭‘璁?
                        self._emit("精灵一恢复后等待1AND1确认", "INFO")
                        if self._unified_framework:
                            from core.unified_battle_framework import BattleConfig, BattleMode
                            temp_config = BattleConfig(
                                mode=BattleMode.WILD,
                                use_foreground=use_foreground,
                                abort_check=lambda: stop_event.is_set() or getattr(self.bot, "stop_current", False),
                            )
                            self._unified_framework._wait_for_confirm_probes(temp_config, timeout_s=2.0)

                        # 鉁?鏂板锛?AND1纭鍚庯紙鏃犺鏄惁瓒呮椂），绛夊緟0.5s璁︰I绋冲畾
                        self._sleep_abortable(stop_event, 0.5)

                        self._close_pet_bag_with_verify(
                            use_foreground,
                            stop_event,
                            bag_open_key,
                            bag_open_btn_key,
                            log_tag="每40战恢复",
                        )

                        # 重置战斗计数（每40次战斗恢复一次）
                        self._last_reconnect_battle_count = self._battle_count
                        self._emit("[每40战恢复] 精灵一恢复完成，战斗计数已重置", "SUCCESS")
                    except Exception as e:
                        self._emit(f"[每40战恢复] 精灵一恢复异常：{e}；继续执行", "WARN")

            # 鉁?妫€鏌ラ噸杩炴潯浠讹細纭嚎 OR 鏈€灏忓€济桺ETSWF_TO_PETITEM_MIN_MULTIPLIER锛堜笉鍐嶆鏌?0次战斗条件）
            # 娉ㄦ剰锛氬彧鏈夊湪娌℃湁鍥犱负精灵鍥涙斁鍥炰粨搴撻棶棰橀噸杩炵殑鎯呭喌涓嬫墠鎵ц
            if not getattr(self, '_reconnect_reason_capture_verify_four', False):
                should_reconnect = False
                reconnect_reason = ""
                _pm = self.PETSWF_TO_PETITEM_MIN_MULTIPLIER

                # 妫€鏌?锛氱‖绾挎潯浠?
                if self._petswf_to_petitem_current_duration is not None:
                    if self._petswf_to_petitem_current_duration >= self.PETSWF_TO_PETITEM_HARD_LIMIT_SEC:
                        should_reconnect = True
                        reconnect_reason = (
                            f"petswf->PetItem duration {self._petswf_to_petitem_current_duration:.3f}s "
                            f"> hard limit {self.PETSWF_TO_PETITEM_HARD_LIMIT_SEC:.1f}s"
                        )

                # 妫€鏌?锛氭渶灏忓€煎€嶆暟鏃堕棿鏉′欢
                if not should_reconnect:
                    if (self._petswf_to_petitem_current_duration is not None and
                        self._petswf_to_petitem_min_duration is not None):
                        threshold = max(
                            self._petswf_to_petitem_min_duration * _pm,
                            self.PETSWF_TO_PETITEM_HARD_LIMIT_MIN_SEC,
                        )
                        # 鉁?淇锛氭坊鍔犺皟璇曟棩蹇楋紝纭繚閫昏緫姝ｇ‘锛屽苟鏀硅繘鏃ュ織杈撳嚭鏄剧ず鏈€灏忓€煎拰闃堝€?
                        self._emit(f"[重连检测] 当前={self._petswf_to_petitem_current_duration:.3f}s，最短={self._petswf_to_petitem_min_duration:.3f}s，阈值=max(最短*{_pm:g},{self.PETSWF_TO_PETITEM_HARD_LIMIT_MIN_SEC:.1f})={threshold:.3f}s", "DEBUG")
                        if self._petswf_to_petitem_current_duration >= threshold:
                            should_reconnect = True
                            reconnect_reason = f"petswf->PetItem duration {self._petswf_to_petitem_current_duration:.3f}s >= threshold {threshold:.3f}s (min={self._petswf_to_petitem_min_duration:.3f}s, x{_pm:g})"

                if should_reconnect:
                    self._emit(f"[重连检测] 条件满足：{reconnect_reason}，执行重连", "WARN")
                    # 鑾峰彇profile锛堝鏋滄湭浼犲叆锛屽皾璇曚粠_current_profile鑾峰彇锛?
                    if profile is None:
                        profile = getattr(self, '_current_profile', None)

                    if profile:
                        self._battle_count = 0
                        self._last_reconnect_battle_count = 0
                        self._last_reconnect_time = time.time()
                        self._petswf_to_petitem_min_duration = None
                        self._petswf_to_petitem_current_duration = None
                        if self._unified_framework and hasattr(self._unified_framework, '_petswf_to_petitem_durations'):
                            self._unified_framework._petswf_to_petitem_durations.clear()
                        self._emit("[运行时重启] 计时统计和战斗计数已清空", "INFO")
                        self._request_mode_restart(
                            stop_event,
                            f"运行时重连-{reconnect_reason}",
                        )
                        return False
                    else:
                        self._emit("[重连检测] 没有可用方案，跳过重连", "WARN")

            return True
        except KeyError as e:
            self._emit(f"恢复流程失败：缺少区域 {e}", "ERROR")
            self._request_reconnect_after_recovery_failure(
                profile,
                use_foreground,
                stop_event,
                f"缺少区域 {e}",
            )
            return False
        except Exception as e:
            self._emit(f"恢复流程异常：{e}", "ERROR")
            self._request_reconnect_after_recovery_failure(
                profile,
                use_foreground,
                stop_event,
                f"恢复流程异常：{e}",
            )
            return False

    # ---------------------------
    # map entry script
    # ---------------------------
    def _execute_map_entry_script(
        self,
        map_swf_id: int,
        use_foreground: bool,
        stop_event: threading.Event,
        profile: Optional[WildCaptureProfile] = None,
    ) -> bool:
        """Execute the map entry script for a map SWF id."""
        stem = _map_entry_script_stem(map_swf_id, profile=profile)
        return self._execute_map_entry_script_by_stem(stem, use_foreground, stop_event)

    def _execute_map_entry_script_by_stem(
        self, stem: str, use_foreground: bool, stop_event: threading.Event
    ) -> bool:
        """Execute a map entry script by stem."""
        try:
            import json
            from core.utils import window_manager

            from config import REGIONS_PATH
            script_path = os.path.join(REGIONS_PATH, '地图', f"{stem}.json")

            if not os.path.exists(script_path):
                self._emit(f"地图进入脚本缺失：{script_path}，跳过", "WARN")
                return False

            with open(script_path, "r", encoding="utf-8") as f:
                data = json.load(f)

            if "key" in data:
                region_key = data.get("key")
                self._emit(f"点击地图进入区域：{region_key}（{stem}）", "SYSTEM")
                try:
                    region = self.regions.get(region_key)
                    if region:
                        self._click_region(region, use_foreground)
                        self._emit(f"已点击地图进入区域：{region_key}", "SUCCESS")
                        return True
                    else:
                        self._emit(f"找不到区域：{region_key}，跳过", "WARN")
                        return False
                except Exception as e:
                    self._emit(f"点击地图进入区域失败：{e}，跳过", "WARN")
                    return False
            else:
                steps = data.get("steps", [])
                if not steps:
                    self._emit(f"地图进入脚本没有步骤：{os.path.basename(script_path)}", "WARN")
                    return False

                self._emit(f"执行地图进入脚本：{os.path.basename(script_path)}", "SYSTEM")

                for idx, step in enumerate(steps, start=1):
                    if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                        self._emit("地图进入脚本已停止", "WARN")
                        return False

                    action = step.get("action", "").lower()
                    if action == "click":
                        gx = step.get("x")
                        gy = step.get("y")
                        if gx is None or gy is None:
                            continue

                        delay = float(step.get("delay", 0.2))
                        if delay < 0:
                            delay = 0.0

                        time.sleep(delay)

                        if use_foreground:
                            window_manager.click(gx, gy)
                        else:
                            window_manager.click_background(gx, gy)
                    elif "pos" in step:
                        pos = step.get("pos")
                        if not isinstance(pos, (list, tuple)) or len(pos) < 2:
                            continue

                        gx, gy = float(pos[0]), float(pos[1])
                        delay = float(step.get("delay", 0.2))
                        if delay < 0:
                            delay = 0.0

                        step_bg = step.get("bg", True)
                        step_use_foreground = not step_bg if not use_foreground else use_foreground

                        time.sleep(delay)

                        if step_use_foreground:
                            window_manager.click(gx, gy)
                        else:
                            window_manager.click_background(gx, gy)

                self._emit(f"✅ 地图脚本执行完成: {os.path.basename(script_path)}", "SUCCESS")
                return True

        except Exception as e:
            self._emit(f"💥 执行地图脚本异常: {e}", "ERROR")
            import traceback
            self._emit(traceback.format_exc(), "ERROR")
        return False

    # ---------------------------
    # map / route resolve
