    def _get_last_map_id(self) -> Optional[int]:
        """Return the last map id from kernel history."""
        try:
            from core.logger import fetch_kernel_since

            # 浠巆ursor=0寮€濮嬭幏鍙栨墍鏈夊巻鍙叉棩蹇?
            all_lines = fetch_kernel_since(0)
            if not isinstance(all_lines, list):
                all_lines = []

            # 浠庢渶鏂扮殑鏃ュ織寮€濮嬶紝鍚戝墠鎼滅储鏈€鍚庝竴涓猰ap
            last_map_id = None
            for line in reversed(all_lines):  # 从最新到最旧
                line_str = str(line)
                mid = first_map_id_in_line(line_str)
                if mid is not None:
                    last_map_id = mid
                    break  # 鎵惧埌鏈€鏂扮殑map灏卞仠姝?

            if last_map_id is not None:
                self._emit(f"🔍 最近一次地图 ID: {last_map_id}", "DEBUG")

            return last_map_id
        except Exception as e:
            self._emit(f"⚠️ 获取最近一次地图 ID 失败: {e}", "DEBUG")
            return None

    def _dal_map11_already_ready_for_wild_capture(self, profile: WildCaptureProfile) -> bool:
        """Return whether map11 is already ready for wild capture."""
        try:
            if int(getattr(profile, "map_swf_id", 0) or 0) != 11:
                return False
            if str(getattr(profile, "route_hint", "") or "").strip() != '达尔':
                return False
            cm, has_npc = self._check_last_map_and_newnpc(11, initial_pause_s=0.6)
            return cm == 11 and has_npc
        except Exception:
            return False

    def _wait_for_map_ready(self, profile: WildCaptureProfile, stop_event: threading.Event) -> bool:
        """Wait until the target map is ready."""
        if stop_event.is_set() or getattr(self.bot, "stop_current", False):
            return False

        # 等待地图，但闇€瑕侀绻佹鏌ュ仠姝俊鍙?
        # 使用较短的超时时间，因为toXXX.json鑴氭湰鎵ц瀹屽悗閫氬父宸茬粡鍦ㄥ湴鍥句腑
        # _wait_kernel_contains_with_abort 浼氬厛妫€鏌ュ巻鍙叉棩蹇楋紝鎵€浠ラ€氬父鑳界珛鍗宠繑鍥?
        if not self._wait_kernel_contains_with_abort(
            re_map_swf_exact_id(profile.map_swf_id),
            timeout_s=10.0,  # 缩短超时时间锛屽洜涓鸿剼鏈墽琛屽悗閫氬父宸茬粡鍦ㄥ湴鍥句腑
            poll=0.05,
            stop_event=stop_event
        ):
            return False

        if stop_event.is_set() or getattr(self.bot, "stop_current", False):
            return False

        if profile.map_swf_id == 10:
            prefer_key = None
            if getattr(profile, "route_hint", None) == "闪光皮皮":
                prefer_key = "闪光皮皮.白色探针"
            if not self._wait_for_map10_white_probe_ready(
                stop_event,
                timeout_s=10.0,
                white_probe_key=prefer_key,
            ):
                return False
            return True

        # 绛夊緟newNpc信号锛屼篃使用杈冪煭鐨勮秴鏃舵椂闂?
        if not self._wait_kernel_contains_with_abort(
            RE_NEWNPC_MULTI,
            timeout_s=10.0,  # 缩短超时时间
            poll=0.05,
            stop_event=stop_event
        ):
            return False
        return True

    def _wait_for_map_id_and_newnpc(
        self,
        map_id: int,
        stop_event: threading.Event,
        *,
        timeout_s: float = 12.0,
        log_tag: str = "地图等待",
        start_cursor: Optional[int] = None,
        accepted_map_ids: Optional[AbstractSet[int]] = None,
    ) -> bool:
        """Wait for a new map plus newNpc after the cursor."""
        mid = int(map_id)
        accepted = {int(x) for x in accepted_map_ids} if accepted_map_ids else {mid}
        map_desc = "|".join(str(x) for x in sorted(accepted))
        self._emit(f"[{log_tag}] 等待新日志 map{map_desc}+newNpc，超时={timeout_s:.0f}s", "SYSTEM")
        from core.logger import fetch_kernel_since, kernel_cursor

        cursor = start_cursor if start_cursor is not None else kernel_cursor()
        deadline = time.time() + float(timeout_s)
        seen_map_id: Optional[int] = None
        seen_npc_after_target_map = False
        map_pats = {m: re_map_swf_exact_id(m) for m in accepted}
        while time.time() < deadline:
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return False
            try:
                lines = fetch_kernel_since(cursor)
                if isinstance(lines, list):
                    for line in lines:
                        line_str = str(line)
                        any_map_id = first_map_id_in_line(line_str)
                        map_seen_on_line = any_map_id is not None
                        if any_map_id is not None:
                            if int(any_map_id) in accepted:
                                seen_map_id = int(any_map_id)
                                seen_npc_after_target_map = False
                                self._emit(
                                    f"[{log_tag}] seen target map{seen_map_id}; wait for following newNpc",
                                    "DEBUG",
                                )
                            elif seen_map_id is not None:
                                self._emit(
                                    f"[{log_tag}] map{any_map_id} appeared after target map{seen_map_id}; reset newNpc wait",
                                    "DEBUG",
                                )
                                seen_map_id = None
                                seen_npc_after_target_map = False
                        if not map_seen_on_line:
                            for m, pat in map_pats.items():
                                if line_matches(pat, line_str):
                                    seen_map_id = m
                                    seen_npc_after_target_map = False
                                    self._emit(
                                        f"[{log_tag}] seen target map{seen_map_id}; wait for following newNpc",
                                        "DEBUG",
                                    )
                                    break
                        if line_matches(RE_NEWNPC_MULTI, line_str):
                            if seen_map_id is not None:
                                seen_npc_after_target_map = True
                            else:
                                self._emit(
                                    f"[{log_tag}] ignore newNpc before target map",
                                    "DEBUG",
                                )
                        if seen_map_id is not None and seen_npc_after_target_map:
                            self._emit(f"[{log_tag}] 新日志 map{seen_map_id}+newNpc 已就绪", "SUCCESS")
                            return True
                    cursor = kernel_cursor()
            except Exception as exc:
                self._emit(f"⚠️ [{log_tag}] 等待地图日志异常: {exc}", "DEBUG")
            time.sleep(0.05)
        self._emit(
            f"[{log_tag}] did not see new log map{map_desc}+newNpc within {timeout_s:.0f}s (map={seen_map_id}, newNpc_after_map={seen_npc_after_target_map})",
            "ERROR",
        )
        return False

    def _wait_after_to_then_check_last_map_and_newnpc(
        self,
        map_id: int,
        stop_event: threading.Event,
        *,
        timeout_s: float = 12.0,
        log_tag: str = "after-to-map-gate",
        start_cursor: Optional[int] = None,
        accepted_map_ids: Optional[AbstractSet[int]] = None,
        settle_s: float = 0.3,
        skip_reverse_check: bool = False,
    ) -> Tuple[Optional[int], bool]:
        """Gate map/newNpc after a to-script."""
        if stop_event.is_set() or getattr(self.bot, "stop_current", False):
            return (None, False)
        if not self._wait_for_map_id_and_newnpc(
            map_id,
            stop_event,
            timeout_s=timeout_s,
            log_tag=f"{log_tag}·等待",
            start_cursor=start_cursor,
            accepted_map_ids=accepted_map_ids,
        ):
            return (None, False)
        if skip_reverse_check:
            mid = int(map_id)
            self._emit(
                f"[{log_tag}] new log map{mid}+newNpc passed; skip reverse gate check",
                "SUCCESS",
            )
            return (mid, True)
        if settle_s > 0:
            self._sleep_abortable(stop_event, settle_s)
        if stop_event.is_set() or getattr(self.bot, "stop_current", False):
            return (None, False)
        return self._check_last_map_and_newnpc(
            map_id,
            timeout_s=0.0,
            initial_pause_s=0.0,
            accepted_map_ids=accepted_map_ids,
        )

    @staticmethod
    def _is_water_essence_to_script(script_name: Optional[str]) -> bool:
        return str(script_name or "").strip() == "to水之精华"

    @staticmethod
    def _is_shell_essence_to_script(script_name: Optional[str]) -> bool:
        return str(script_name or "").strip() == "to贝壳精华"

    @staticmethod
    def _is_crystal_bubble_to_script(script_name: Optional[str]) -> bool:
        return str(script_name or "").strip() == "to晶化气泡"

    @staticmethod
    def _is_water_grass_to_script(script_name: Optional[str]) -> bool:
        return str(script_name or "").strip() == "to水生海草1"

    def _wait_for_map_after_cursor(
        self,
        map_id: int,
        start_cursor: int,
        stop_event: threading.Event,
        *,
        timeout_s: float,
        log_tag: str,
    ) -> bool:
        """Wait for a target map in kernel rows at or after an existing cursor."""
        from core.logger import fetch_kernel_since, kernel_cursor

        target_map_id = int(map_id)
        cursor = int(start_cursor)
        deadline = time.time() + float(timeout_s)
        self._emit(
            f"⏳ [{log_tag}] 从脚本起点向下等待 map{target_map_id}",
            "SYSTEM",
        )
        while time.time() < deadline:
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return False
            try:
                lines = fetch_kernel_since(cursor)
                if isinstance(lines, list):
                    for line in lines:
                        if first_map_id_in_line(str(line)) == target_map_id:
                            self._emit(
                                f"✅ [{log_tag}] 向下检测到 map{target_map_id}",
                                "SUCCESS",
                            )
                            return True
                    cursor = kernel_cursor()
            except Exception as exc:
                self._emit(f"⚠️ [{log_tag}] 等待 map{target_map_id} 异常：{exc}", "DEBUG")
            time.sleep(0.05)
        self._emit(f"⚠️ [{log_tag}] 向下等待 map{target_map_id} 超时", "WARN")
        return False

    def _anchored_map_gate_after_to(
        self,
        start_cursor: int,
        stop_event: threading.Event,
        *,
        script_name: str,
        anchor_map_id: int,
        target_map_id: int,
        log_tag: str,
    ) -> bool:
        """Scan upward for an anchor map, then wait downward for target map + newNpc."""
        try:
            rows = fetch_kernel_since(start_cursor, return_rows=True)
        except Exception as exc:
            self._emit(
                f"⚠️ [{log_tag}] 扫描 map{anchor_map_id} 异常：{exc}",
                "WARN",
            )
            return False
        if not isinstance(rows, list):
            rows = []

        anchor_cursor: Optional[int] = None
        for seq, _ts, line in reversed(rows):
            if first_map_id_in_line(str(line)) == int(anchor_map_id):
                anchor_cursor = int(seq)
                self._emit(
                    f"✅ [{log_tag}] {script_name} 后向上扫描到 map{anchor_map_id}，seq={anchor_cursor}",
                    "SUCCESS",
                )
                break
        if anchor_cursor is None:
            self._emit(
                f"⚠️ [{log_tag}] {script_name} 后未扫描到 map{anchor_map_id}",
                "WARN",
            )
            return False

        found_map, has_newnpc = self._wait_after_to_then_check_last_map_and_newnpc(
            target_map_id,
            stop_event,
            timeout_s=20.0,
            log_tag=f"{log_tag}-map{target_map_id}",
            start_cursor=anchor_cursor,
            accepted_map_ids={target_map_id},
            settle_s=0.0,
            skip_reverse_check=True,
        )
        ok = int(found_map or -1) == int(target_map_id) and bool(has_newnpc)
        if not ok:
            self._emit(
                f"⚠️ [{log_tag}] 从 map{anchor_map_id} 向下等待 "
                f"map{target_map_id}+newNpc 失败：map={found_map}, newNpc={has_newnpc}",
                "WARN",
            )
        return ok

