    def _read_nieo_one_white_probe_nonwhite(self) -> Tuple[bool, Optional[Tuple[int, int, int]], Optional[float]]:
        """Return whether the Nieo-one white probe is no longer pure white."""
        reg = self.regions.get("尼奥一.白色探针")
        if reg is None:
            self._emit("[乌索门控] 缺少区域：尼奥一白色探针", "WARN")
            return False, None, None
        try:
            x1, y1, x2, y2 = reg.outer_bbox()
            img = window_manager.grab_game_bbox(x1, y1, x2, y2, min_size_px=2)
            if img is None:
                return False, None, None
            arr = np.asarray(img.convert("RGB"), dtype=np.uint8)
            if arr.size == 0:
                return False, None, None
            mean = arr.reshape(-1, 3).mean(axis=0)
            rgb = tuple(int(round(v)) for v in mean)
            white_mask = np.all(arr >= 250, axis=2)
            white_ratio = float(np.count_nonzero(white_mask)) / float(white_mask.size)
            return white_ratio < 0.80, rgb, white_ratio
        except Exception as exc:
            self._emit(f"[乌索to门控] 读取尼奥一白色探针失败：{exc}", "DEBUG")
            return False, None, None

    def _wait_wusuo_map325_and_probe_after_to(
        self,
        start_cursor,
        stop_event: threading.Event,
        *,
        timeout_s: float = 5.0,
    ) -> bool:
        """Gate Wusuo after to-script by map325 and white probe."""
        self._emit(
            f"[wusuo-to-gate] wait for new log map325 + nieo-one white probe nonwhite, timeout={timeout_s:.0f}s",
            "SYSTEM",
        )
        cursor = start_cursor if start_cursor is not None else kernel_cursor()
        deadline = time.time() + float(timeout_s)
        seen_map325 = False
        logged_map325 = False
        last_rgb: Optional[Tuple[int, int, int]] = None
        last_white_ratio: Optional[float] = None
        map_pat = re_map_swf_exact_id(325)

        while time.time() < deadline:
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return False
            try:
                lines = fetch_kernel_since(cursor)
                if isinstance(lines, list):
                    for line in lines:
                        if line_matches(map_pat, str(line)):
                            seen_map325 = True
                            if not logged_map325:
                                self._emit("[乌索to门控] 已看到新日志 map325", "INFO")
                                logged_map325 = True
                    cursor = kernel_cursor()
            except Exception as exc:
                self._emit(f"[乌索to门控] map325 日志扫描失败：{exc}", "DEBUG")

            probe_nonwhite, rgb, white_ratio = self._read_nieo_one_white_probe_nonwhite()
            if rgb is not None:
                last_rgb = rgb
            if white_ratio is not None:
                last_white_ratio = white_ratio
            if seen_map325 and probe_nonwhite:
                ratio_text = f"{last_white_ratio:.2f}" if last_white_ratio is not None else "?"
                self._emit(
                    f"[wusuo-to-gate] passed: map325 + white probe nonwhite RGB={last_rgb}, white_ratio={ratio_text}",
                    "SUCCESS",
                )
                return True
            time.sleep(0.05)

        ratio_text = f"{last_white_ratio:.2f}" if last_white_ratio is not None else "?"
        self._emit(
            f"[wusuo-to-gate] timeout: map325={seen_map325}, RGB={last_rgb}, white_ratio={ratio_text}",
            "ERROR",
        )
        return False

    def _is_wusuo_profile(self, profile: Optional[WildCaptureProfile]) -> bool:
        if profile is None:
            return False
        vals = (
            getattr(profile, "slug", None),
            getattr(profile, "route_hint", None),
            getattr(profile, "name", None),
            getattr(profile, "to_script", None),
        )
        return any('乌索' in str(v or "") for v in vals)

    def _is_wusuo_312_only_profile(self, profile: Optional[WildCaptureProfile]) -> bool:
        if profile is None:
            return False
        vals = (
            getattr(profile, "name", None),
            getattr(profile, "route_hint", None),
        )
        if not any('乌索' in str(v or "") for v in vals):
            return False
        try:
            mp3_ids = set(getattr(profile, "target_mp3_ids", None) or (getattr(profile, "target_mp3_id", None),))
            pet_ids = set(getattr(profile, "target_pet_ids", None) or (getattr(profile, "target_pet_id", None),))
        except TypeError:
            return False
        return mp3_ids == {312} and pet_ids == {312}

    def _current_battle_pet_ids(self) -> set:
        ids = getattr(self, "_immediate_collected_pet_ids", None)
        if not ids:
            return set()
        try:
            return set(ids)
        except TypeError:
            return set()

    def _is_wusuo_312_battle(self, profile: Optional[WildCaptureProfile]) -> bool:
        if not self._is_wusuo_profile(profile):
            return False
        ids = self._current_battle_pet_ids()
        if self._is_wusuo_312_only_profile(profile):
            return 312 in ids
        return 312 in ids and 528 not in ids

    def _is_wusuo_528_battle(self, profile: Optional[WildCaptureProfile]) -> bool:
        if not self._is_wusuo_profile(profile):
            return False
        if self._is_wusuo_312_only_profile(profile):
            return False
        return 528 in self._current_battle_pet_ids()

    def _record_wusuo_312_defeat_and_should_recover(
        self, profile: Optional[WildCaptureProfile]
    ) -> bool:
        if not self._is_wusuo_profile(profile):
            return False
        if not getattr(self, "_wusuo_current_battle_is_312", False):
            return False
        self._emit(
            "[wusuo312] 312 defeat recovery is now driven by skill3 counter, not consecutive 312 count",
            "INFO",
        )
        return False

    def _reset_wusuo_312_defeat_counter(self, reason: str) -> None:
        if getattr(self, "_wusuo_consecutive_312_defeats", 0):
            self._emit(f"[wusuo312] {reason}; consecutive 312 defeat counter reset", "INFO")
        self._wusuo_consecutive_312_defeats = 0

    def _run_wusuo_entry_chain_after_recover(
        self,
        profile: WildCaptureProfile,
        use_foreground: bool,
        stop_event: threading.Event,
    ) -> bool:
        """Execute the Wusuo route sequence."""
        stem = getattr(profile, "map_entry_stem", None) or "325to326"
        self._emit(f"[乌索] 点击地图进入脚本：map/{stem}.json", "SYSTEM")
        if not self._execute_map_entry_script_by_stem(str(stem), use_foreground, stop_event):
            self._emit(f"[乌索] map/{stem}.json 失败", "ERROR")
            return False
        if not self._wait_for_map_id_and_newnpc(
            326, stop_event, timeout_s=20.0, log_tag="wusuo326"
        ):
            return False
        if not hasattr(self.bot, "daily_runner"):
            self._emit("[乌索] 缺少 daily_runner，无法执行固定脚本", "ERROR")
            return False
        self._emit("[乌索] 执行固定脚本", "SYSTEM")
        if not self.bot.daily_runner.run_single_script('乌索', bg_mode=(not use_foreground)):
            self._emit("[乌索] 固定脚本执行失败", "ERROR")
            return False
        if not self._wait_for_map_id_and_newnpc(
            int(profile.map_swf_id), stop_event, timeout_s=20.0, log_tag="wusuo327"
        ):
            return False
        return True

    def _wait_kernel_contains_with_abort(self, needle, timeout_s: float, poll: float, stop_event: threading.Event) -> bool:
        """Wait for a kernel log match while honoring abort signals."""
        start_time = time.time()
        from core.logger import kernel_cursor

        # 记录当前cursor锛屽彧妫€鏌ユ柊鐨勬棩蹇楋紙涓嶆鏌ュ巻鍙叉棩蹇楋級
        cursor = kernel_cursor()

        while (time.time() - start_time) < timeout_s:
            # 棰戠箒妫€鏌ュ仠姝俊鍙?
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return False

            # 妫€鏌ユ柊鐨勫唴鏍告棩蹇楋紙浠庝笂娆ursor涔嬪悗鐨勬柊鏃ュ織锛?
            try:
                from core.logger import fetch_kernel_since
                lines = fetch_kernel_since(cursor)
                if isinstance(lines, list):
                    for line in lines:
                        if line_matches(needle, str(line)):
                            return True
                    # 鏇存柊cursor
                    cursor = kernel_cursor()
            except Exception:
                pass

            # 鐭殏浼戠湢鍚庣户缁鏌?
            time.sleep(poll)

        # 瓒呮椂
        return False

    def _wait_kernel_contains_compat(self, substr: str, timeout_s: float, poll: float) -> bool:
        try:
            return bool(wait_kernel_contains(substr, timeout_s=timeout_s, poll=poll, cursor=None))
        except TypeError:
            try:
                return bool(wait_kernel_contains(substr, timeout=timeout_s, poll=poll))
            except Exception:
                return False
        except Exception:
            return False

    @staticmethod
    def _prefix_variants(prefix: str) -> List[str]:
        prefix = (prefix or "").strip()
        if not prefix:
            return []
        variants = [prefix]
        if prefix.endswith('地图'):
            variants.append(prefix.replace('地图', ""))
        else:
            variants.append(prefix + '地图')
        out: List[str] = []
        for v in variants:
            if v and v not in out:
                out.append(v)
        return out

    def _resolve_route_regions(self, prefix: str, require_b: bool = True, use_z: bool = False) -> Tuple[List[Tuple[str, Region]], Region, Region]:
        """Resolve route regions."""
        candidates = self._prefix_variants(prefix)

        reg_a_or_z = reg_b = None
        used_ab = None
        point_key = "Z" if use_z else "A"

        for p in candidates:
            rz = self.regions.get(f"{p}.{point_key}")
            if not rz:
                continue

            if require_b:
                # 闇€瑕丅点：鍚屾椂鏌ユ壘A/Z鍜孊
                rb = self.regions.get(f"{p}.B")
                if rz and rb:
                    reg_a_or_z, reg_b = rz, rb
                used_ab = p
                break
            else:
                # 涓嶉渶瑕丅点：鍙煡鎵続/Z鐐?
                reg_a_or_z = rz
                used_ab = p
                break

        if not reg_a_or_z:
            raise KeyError(
                f"缺少 {point_key} 区域：prefix candidates={candidates} | suggest={self.regions.suggest(prefix, limit=30)}"
            )

        if require_b and not reg_b:
            raise KeyError(
                f"缺少 B 区域：prefix candidates={candidates} | suggest={self.regions.suggest(prefix, limit=30)}"
            )

        # 如果不需要B点但找到了B点，使用B点；如果没找到B点，使用A/Z鐐逛綔涓築鐐癸紙鍏煎鎬э級
        if not require_b and not reg_b:
            reg_b = reg_a_or_z  # 使用A/Z鐐逛綔涓築鐐癸紙铏界劧涓嶄細使用，但淇濇寔杩斿洖绫诲瀷涓€鑷达級

        def pick_key(p: str, i: int) -> Optional[str]:
            tries = [
                f"{p}.{i}",
                f"{p}.璺緞{i}",
                f"{p}.璺緞 {i}",
                f"{p}.path{i}",
                f"{p}.path {i}",
            ]
            for k in tries:
                if self.regions.get(k):
                    return k
            return None

        points: List[Tuple[str, Region]] = []
        used_pts = None
        for p in candidates:
            tmp: List[Tuple[str, Region]] = []
            ok = True
            for i in range(1, 10):
                kk = pick_key(p, i)
                if not kk:
                    ok = False
                    break
                rr = self.regions.get(kk)
                if not rr:
                    ok = False
                    break
                tmp.append((kk, rr))
            if ok:
                points = tmp
                used_pts = p
                break

        if not points:
            raise KeyError(
                f"未找到1~9刷新点：prefix candidates={candidates} | suggest={self.regions.suggest(prefix, limit=80)}"
            )

        used = used_pts or used_ab or prefix
        self._emit(f"🧩 刷新点 prefix={used} points={len(points)}", "INFO")
        return points, reg_a_or_z, reg_b

    def _kernel_map_matches_profile_expectation(
        self,
        profile: WildCaptureProfile,
        last_map_id: Optional[int],
        expected_map_id: int,
    ) -> bool:
        """Check whether the latest map is an allowed map-zero id."""
        if last_map_id is None:
            return False
        try:
            mid = int(last_map_id)
        except (TypeError, ValueError):
            return False
        gate_zero = wild_rare_map_gate_zero_literal_swf_ids(profile)
        if gate_zero:
            return mid in gate_zero
        return mid == int(expected_map_id)

    def _detect_unexpected_map(
        self,
        lines: Sequence[str],
        expected_map_id: int,
        profile: Optional[WildCaptureProfile] = None,
    ) -> Optional[int]:
        """Return the first unexpected map id from log lines."""
        exp = int(expected_map_id)
        gate_zero = wild_rare_map_gate_zero_literal_swf_ids(profile) if profile is not None else frozenset()
        for ln in lines or []:
            mid = first_map_id_in_line(str(ln))
            if mid is None:
                continue
            try:
                mid_i = int(mid)
            except (TypeError, ValueError):
                continue
            if gate_zero:
                if mid_i == exp:
                    continue
                return mid_i
            if mid_i != exp:
                return mid_i
        return None

    # ---------------------------
    # baseline / scan
    # ---------------------------
    def _recalibrate_all(self, points: Sequence[Tuple[str, Region]], stop_event: threading.Event, map_id: Optional[int] = None) -> None:
        """Recalibrate all route points."""
        # 鉂?DISABLED: 宸叉憭寮冧娇鐢ㄩ暱鏈熷熀绾跨殑鎯虫硶锛屾寔缁偣鍑荤█鏈夌簿鐏靛嵆鍙?

        for key, reg in points:
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return
            self._wait_if_paused(stop_event)

            # 使用姝ｅ父娴嬮噺锛堜笉使用闀挎湡鍩虹嚎鏁版嵁锛?
            mean_sig, jitter = self._measure_baseline(reg, samples=4, downsample=(8, 8))

            th = jitter * 5.0 + 12.0
            self._baseline[key] = mean_sig
            self._jitter[key] = jitter
            self._threshold[key] = th

    def _recalibrate_all_robust(self, points: Sequence[Tuple[str, Region]], stop_event: threading.Event, map_id: Optional[int] = None) -> None:
        """Recalibrate all route points with more samples."""
        for key, reg in points:
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return
            self._wait_if_paused(stop_event)

            # 鉁?绋冲仴鏍囧畾锛氫娇鐢?娆￠噰鏍凤紙姣旀甯告爣瀹氱殑4次更多，更稳健）
            mean_sig, jitter = self._measure_baseline(reg, samples=6, downsample=(8, 8))

            th = jitter * 5.0 + 12.0
            self._baseline[key] = mean_sig
            self._jitter[key] = jitter
            self._threshold[key] = th

    def _wait_for_ui_stable_before_recalibrate(
        self,
        points: Sequence[Tuple[str, Region]],
        stop_event: threading.Event,
        timeout_s: float = 3.0
    ) -> None:
        """Wait briefly for UI stability before recalibration."""
        start_time = time.time()
        check_interval = 0.2  # 姣?.2绉掓鏌ヤ竴娆?
        last_check_time = 0.0

        # 璁＄畻异常闃堝€硷細濡傛灉鏌愪釜鐐圭殑diff超过其阈值的3鍊嶏紝璁や负鏄紓甯革紙鍙兘鏄疷I骞叉壈锛?
        abnormal_count_threshold = 3  # 濡傛灉瓒呰繃3涓偣异常锛岃涓烘槸UI骞叉壈

        while (time.time() - start_time) < timeout_s:
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return

            now = time.time()
            if now - last_check_time < check_interval:
                time.sleep(0.05)
                continue

            last_check_time = now

            # 蹇€熸壂鎻忔墍鏈夌偣锛屾鏌ユ槸鍚︽湁异常澶х殑变化
            abnormal_count = 0
            for key, reg in points:
                base = self._baseline.get(key)
                if base is None:
                    continue

                sig = self._grab_sig(reg, downsample=(8, 8))
                diff = self._sig_diff(sig, base)
                th = self._threshold.get(key, 9999.0)

                # 濡傛灉diff瓒呰繃闃堝€肩殑3鍊嶏紝璁や负鏄紓甯革紙鍙兘鏄疷I骞叉壈锛?
                if diff > th * 3.0:
                    abnormal_count += 1

            # 如果异常点数量少于阈值，认为UI绋冲畾锛屽彲浠ョ户缁爣瀹?
            if abnormal_count < abnormal_count_threshold:
                if abnormal_count > 0:
                    self._emit(f"UI稳定检查通过：异常数={abnormal_count}，阈值={abnormal_count_threshold}；重新校准", "INFO")
                return

            # 濡傛灉妫€娴嬪埌UI骞叉壈锛岀户缁瓑寰?
            # 节流输出：每1绉掕緭鍑轰竴娆?
            elapsed = now - start_time
            if int(elapsed) != int(elapsed - check_interval):
                self._emit(
                    f"UI interference detected: abnormal={abnormal_count}; wait before recalibration, elapsed={elapsed:.1f}s",
                    "WARN"
                )

        # 瓒呮椂鍚庝粛鐒舵湁骞叉壈锛岃緭鍑鸿鍛婁絾缁х画鏍囧畾锛堝彲鑳芥槸鍏朵粬鍘熷洜瀵艰嚧鐨勫紓甯革級
        self._emit(f"UI稳定检查 {timeout_s}s 超时，继续重新校准", "WARN")

    def _quick_recalibrate_all(self, points: Sequence[Tuple[str, Region]], stop_event: threading.Event, samples: int = 4) -> None:
        """Quickly recalibrate all points."""
        for key, reg in points:
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return
            self._wait_if_paused(stop_event)

            # 閲嶆柊娴嬮噺鍩虹嚎锛堟竻闄ゅ彲鑳界殑鍣０鍜岃繃鏈熸壂鎻忓懡涓級
            mean_sig, jitter = self._measure_baseline(reg, samples=samples, downsample=(8, 8))

            th = jitter * 5.0 + 12.0
            self._baseline[key] = mean_sig
            self._jitter[key] = jitter
            self._threshold[key] = th

