    def _check_dark_blue_probe(self, use_foreground: bool) -> bool:
        """Return whether the round probe is dark blue."""
        try:
            probe_key = '对战.回合探针'
            r = self.regions.get(probe_key)
            if not r:
                return False

            # 鎴彇探针鍖哄煙
            x1, y1, x2, y2 = r.outer_bbox()
            img = window_manager.grab_game_bbox(x1, y1, x2, y2, min_size_px=2)
            if img is None:
                return False

            # 杞崲涓篟GB鏁扮粍
            arr = np.asarray(img.convert("RGB"), dtype=np.uint8)
            h, w = arr.shape[:2]

            # 妫€鏌ヤ腑蹇冨尯鍩熺殑骞冲潎棰滆壊
            cy, cx = h // 2, w // 2
            patch_size = min(3, h // 2, w // 2)
            y1_patch = max(0, cy - patch_size)
            y2_patch = min(h, cy + patch_size + 1)
            x1_patch = max(0, cx - patch_size)
            x2_patch = min(w, cx + patch_size + 1)
            patch = arr[y1_patch:y2_patch, x1_patch:x2_patch, :]

            # 璁＄畻骞冲潎RGB
            avg_rgb = patch.mean(axis=(0, 1)).astype(int)
            r_val, g_val, b_val = avg_rgb[0], avg_rgb[1], avg_rgb[2]

            # 娣辫摑鑹茶寖鍥达細#0E203F (14, 32, 63) 鍒?#003366 (0, 51, 102)
            # 鏀惧鑼冨洿浠ラ€傞厤鏇村鎯呭喌锛氬厑璁告洿澶х殑瀹瑰樊
            # 妫€鏌ユ槸鍚﹀湪鑼冨洿鍐咃紙使用鏇村鏉剧殑鑼冨洿锛?
            min_r, min_g, min_b = 0, 0, 40  # 放宽最小值
            max_r, max_g, max_b = 20, 60, 120  # 放宽最大值

            is_dark_blue = (
                min_r <= r_val <= max_r and
                min_g <= g_val <= max_g and
                min_b <= b_val <= max_b
            )

            # 濡傛灉涓嶅湪鑼冨洿鍐咃紝浣嗚摑鑹插€兼槑鏄鹃珮浜庣孩鑹插拰缁胯壊锛屼篃鍙兘鏄繁钃濊壊
            if not is_dark_blue and b_val > r_val + 20 and b_val > g_val + 20 and b_val >= 40:
                is_dark_blue = True

            if is_dark_blue:
                self._emit(f"🔵 检测到深蓝色切换探针(RGB=({r_val},{g_val},{b_val}), HEX=#{r_val:02X}{g_val:02X}{b_val:02X})", "DEBUG")

            return is_dark_blue

        except Exception as e:
            self._emit(f"⚠️ 检测深蓝色切换探针异常: {e}", "WARN")
            return False

    def _ocr_enemy_info_fast(self, use_foreground: bool) -> Tuple[Optional[int], Optional[int], Optional[Image.Image], Optional[Image.Image]]:
        """Fast OCR scan for enemy level and HP."""
        level = None
        hp = None
        level_img = None
        hp_img = None

        # OCR绛夌骇
        level_key = "对战信息.敌方精灵等级"
        try:
            r = self.regions.get(level_key)
            if r and pytesseract:
                x1, y1, x2, y2 = r.outer_bbox()
                img = window_manager.grab_game_bbox(x1, y1, x2, y2, min_size_px=2)
                if img:
                    level_img = img
                    from PIL import ImageOps
                    import re

                    # 棰勫鐞嗗浘鍍?
                    gray = img.convert("L")
                    gray = ImageOps.autocontrast(gray)
                    w, h = gray.size
                    gray = gray.resize((max(1, w * 4), max(1, h * 4)))

                    # 灏濊瘯澶氱棰勫鐞嗗拰PSM模式
                    variants = []
                    variants.append(gray.point(lambda p: 255 if p > 160 else 0))  # normal
                    inv = ImageOps.invert(gray)
                    variants.append(inv.point(lambda p: 255 if p > 160 else 0))   # inverted

                    configs = [
                        "--psm 7 -c tessedit_char_whitelist=0123456789",  # 鍗曡鏂囨湰
                        "--psm 8 -c tessedit_char_whitelist=0123456789",  # 鍗曚釜鍗曡瘝
                        "--psm 6 -c tessedit_char_whitelist=0123456789",  # 单块文本
                    ]

                    best_level = None
                    for i, variant in enumerate(variants):
                        for j, config in enumerate(configs):
                            try:
                                txt = pytesseract.image_to_string(variant, lang="eng", config=config)
                                # 浼樺厛鍖归厤涓や綅鏁?
                                nums = re.findall(r"\d{2}", txt or "")
                                if not nums:
                                    # 濡傛灉娌℃湁涓や綅鏁帮紝鍥為€€鍒板尮閰嶄换鎰忛暱搴︽暟瀛?
                                    nums = re.findall(r"\d{1,3}", txt or "")

                                if nums:
                                    candidate_level = int(nums[0])
                                    if 1 <= candidate_level <= 120:
                                        best_level = candidate_level
                                        break  # 鎵惧埌鏈夋晥缁撴灉灏遍€€鍑哄唴灞傚惊鐜?
                            except Exception as e:
                                self._emit(f"[OCR] 等级识别尝试失败（变体={i}，配置={j}）：{e}", "DEBUG")
                                continue
                        if best_level is not None:
                            break  # 鎵惧埌鏈夋晥缁撴灉灏遍€€鍑哄灞傚惊鐜?

                    if best_level is not None:
                        level = best_level
        except Exception as e:
            self._emit(f"OCR等级识别失败：{e}", "WARN")

        # OCR琛€閲?
        hp_key = "对战信息.敌方精灵血量"
        try:
            r = self.regions.get(hp_key)
            if r and pytesseract:
                x1, y1, x2, y2 = r.outer_bbox()
                img = window_manager.grab_game_bbox(x1, y1, x2, y2, min_size_px=2)
                if img:
                    hp_img = img
                    from PIL import ImageOps
                    import re

                    # 棰勫鐞嗗浘鍍?
                    gray = img.convert("L")
                    gray = ImageOps.autocontrast(gray)
                    w, h = gray.size
                    gray = gray.resize((max(1, w * 4), max(1, h * 4)))

                    # 灏濊瘯澶氱棰勫鐞嗗拰PSM模式
                    variants = []
                    variants.append(gray.point(lambda p: 255 if p > 160 else 0))  # normal
                    inv = ImageOps.invert(gray)
                    variants.append(inv.point(lambda p: 255 if p > 160 else 0))   # inverted

                    configs = [
                        "--psm 7 -c tessedit_char_whitelist=0123456789",  # 鍗曡鏂囨湰
                        "--psm 8 -c tessedit_char_whitelist=0123456789",  # 鍗曚釜鍗曡瘝
                        "--psm 6 -c tessedit_char_whitelist=0123456789",  # 单块文本
                    ]

                    best_hp = None
                    for i, variant in enumerate(variants):
                        for j, config in enumerate(configs):
                            try:
                                txt = pytesseract.image_to_string(variant, lang="eng", config=config)
                                # 鉁?寮哄埗鍙尮閰嶄袱浣嶆暟锛屼笉鎺ュ彈涓€浣嶆暟
                                nums = re.findall(r"\d{2}", txt or "")

                                if nums:
                                    candidate_hp = int(nums[0])
                                    if 1 <= candidate_hp <= 9999:
                                        best_hp = candidate_hp
                                        break  # 鎵惧埌鏈夋晥缁撴灉灏遍€€鍑哄唴灞傚惊鐜?
                                else:
                                    # 鉁?濡傛灉娌℃湁鍖归厤鍒颁袱浣嶆暟锛岃褰曡皟璇曚俊鎭?
                                    self._emit(f"[OCR] no two-digit HP matched, raw={txt!r} (variant={i}, config={j})", "DEBUG")
                            except Exception as e:
                                self._emit(f"[OCR] 血量识别尝试失败（变体={i}，配置={j}）：{e}", "DEBUG")
                                continue
                        if best_hp is not None:
                            break  # 鎵惧埌鏈夋晥缁撴灉灏遍€€鍑哄灞傚惊鐜?

                    if best_hp is not None:
                        hp = best_hp
                    else:
                        # 鉁?濡傛灉鎵€鏈夊皾璇曢兘澶辫触锛堟病鏈夊尮閰嶅埌涓や綅鏁帮級
                        self._emit("[OCR] no HP attempt matched a two-digit value", "WARN")
        except Exception as e:
            self._emit(f"OCR血量识别失败：{e}", "WARN")

        return level, hp, level_img, hp_img

    def _save_enemy_ocr_images(
        self,
        level: int,
        hp: int,
        level_img: Optional[Image.Image],
        hp_img: Optional[Image.Image],
        battle_num: int,
    ) -> None:
        """Save successful OCR source images for debugging."""
        if level_img is None or hp_img is None:
            return
        if not self.bot or not hasattr(self.bot, "project_root"):
            return
        try:
            save_dir = screenshots_subdir(self.bot.project_root, "ocr_enemy")
            ts = time.strftime("%Y%m%d_%H%M%S")
            ms = int((time.time() % 1) * 1000)
            ts_full = f"{ts}_{ms:03d}"
            hp_path = os.path.join(save_dir, f"ocr_enemy_hp{hp}_battle{battle_num}_{ts_full}.png")
            level_path = os.path.join(save_dir, f"ocr_enemy_level{level}_battle{battle_num}_{ts_full}.png")
            hp_img.save(hp_path)
            level_img.save(level_path)
            self._emit(f"[OCR] saved source images: {hp_path} / {level_path}", "DEBUG")
        except Exception as e:
            self._emit(f"[OCR] 保存源图失败：{e}", "WARN")

    def _ocr_enemy_info(self, use_foreground: bool) -> Tuple[Optional[int], Optional[int]]:
        """OCR scan for enemy level and HP."""
        level = None
        hp = None

        # OCR绛夌骇
        level_key = "对战信息.敌方精灵等级"
        try:
            r = self.regions.get(level_key)
            if not r:
                self._emit(f"[OCR] region not found: {level_key}", "WARN")
            else:
                self._emit(f"[OCR] scan level region: {level_key}", "DEBUG")
                x1, y1, x2, y2 = r.outer_bbox()
                self._emit(f"[OCR] level bbox: ({x1}, {y1}) -> ({x2}, {y2})", "DEBUG")
                img = window_manager.grab_game_bbox(x1, y1, x2, y2, min_size_px=2)
                if not img:
                    self._emit("[OCR] 截取等级图失败", "WARN")
                elif not pytesseract:
                    self._emit("[OCR] pytesseract unavailable", "WARN")
                else:
                    from PIL import ImageOps
                    import re

                    # 棰勫鐞嗗浘鍍?
                    gray = img.convert("L")
                    gray = ImageOps.autocontrast(gray)
                    w, h = gray.size
                    gray = gray.resize((max(1, w * 4), max(1, h * 4)))

                    # 灏濊瘯澶氱閰嶇疆
                    variants = [
                        gray.point(lambda p: 255 if p > 160 else 0),
                        ImageOps.invert(gray).point(lambda p: 255 if p > 160 else 0),
                    ]

                    configs = [
                        "--psm 7 -c tessedit_char_whitelist=0123456789",
                        "--psm 8 -c tessedit_char_whitelist=0123456789",
                        "--psm 6 -c tessedit_char_whitelist=0123456789",
                    ]

                    txt_result = ""
                    for v_idx, v in enumerate(variants):
                        for cfg_idx, cfg in enumerate(configs):
                            try:
                                txt = pytesseract.image_to_string(v, lang="eng", config=cfg)
                                nums = re.findall(r"\d{1,3}", txt or "")
                                if nums:
                                    level = int(nums[0])
                                    if 1 <= level <= 120:
                                        txt_result = txt
                                        self._emit(f"[OCR] level recognized: {level} (variant={v_idx}, config={cfg_idx}, raw_text={txt!r})", "INFO")
                                        break
                            except Exception as e:
                                self._emit(f"[OCR] 等级识别尝试失败（变体={v_idx}，配置={cfg_idx}）：{e}", "DEBUG")
                        if level:
                            break

                    if level:
                        self._emit(f"[OCR] enemy level: {level}", "INFO")
                    else:
                        self._emit(f"[OCR] 敌方等级识别失败，原始={txt_result if txt_result else 'N/A'}", "WARN")
        except Exception as e:
            self._emit(f"OCR等级识别失败：{e}", "WARN")
            import traceback
            self._emit(f"OCR level exception detail: {traceback.format_exc()}", "DEBUG")

        # OCR琛€閲?
        hp_key = "对战信息.敌方精灵血量"
        try:
            r = self.regions.get(hp_key)
            if not r:
                self._emit(f"[OCR] region not found: {hp_key}", "WARN")
            else:
                self._emit(f"[OCR] scan HP region: {hp_key}", "DEBUG")
                x1, y1, x2, y2 = r.outer_bbox()
                self._emit(f"[OCR] HP bbox: ({x1}, {y1}) -> ({x2}, {y2})", "DEBUG")
                img = window_manager.grab_game_bbox(x1, y1, x2, y2, min_size_px=2)
                if not img:
                    self._emit("[OCR] 截取血量图失败", "WARN")
                elif not pytesseract:
                    self._emit("[OCR] pytesseract unavailable", "WARN")
                else:
                    from PIL import ImageOps
                    import re

                    # 棰勫鐞嗗浘鍍?
                    gray = img.convert("L")
                    gray = ImageOps.autocontrast(gray)
                    w, h = gray.size
                    gray = gray.resize((max(1, w * 4), max(1, h * 4)))

                    # 灏濊瘯澶氱閰嶇疆
                    variants = [
                        gray.point(lambda p: 255 if p > 160 else 0),
                        ImageOps.invert(gray).point(lambda p: 255 if p > 160 else 0),
                    ]

                    configs = [
                        "--psm 7 -c tessedit_char_whitelist=0123456789",
                        "--psm 8 -c tessedit_char_whitelist=0123456789",
                        "--psm 6 -c tessedit_char_whitelist=0123456789",
                    ]

                    txt_result = ""
                    for v_idx, v in enumerate(variants):
                        for cfg_idx, cfg in enumerate(configs):
                            try:
                                txt = pytesseract.image_to_string(v, lang="eng", config=cfg)
                                nums = re.findall(r"\d+", txt or "")
                                if nums:
                                    hp = int(nums[0])
                                    if 1 <= hp <= 9999:
                                        txt_result = txt
                                        self._emit(f"[OCR] HP recognized: {hp} (variant={v_idx}, config={cfg_idx}, raw_text={txt!r})", "INFO")
                                        break
                            except Exception as e:
                                self._emit(f"[OCR] 血量识别尝试失败（变体={v_idx}，配置={cfg_idx}）：{e}", "DEBUG")
                        if hp:
                            break

                    if hp:
                        self._emit(f"[OCR] enemy HP: {hp}", "INFO")
                    else:
                        self._emit(f"[OCR] 敌方血量识别失败，原始={txt_result if txt_result else 'N/A'}", "WARN")
        except Exception as e:
            self._emit(f"OCR血量识别失败：{e}", "WARN")
            import traceback
            self._emit(f"OCR HP exception detail: {traceback.format_exc()}", "DEBUG")

        return level, hp

    def _monitor_enemy_info_after_skill(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
        timeout_s: float = 30.0,
        check_condition_callback: Optional[Callable[[Optional[int], Optional[int]], bool]] = None
    ) -> Tuple[Optional[int], Optional[int], str]:
        """Monitor enemy level and HP through the battle round."""
        from core.logger import fetch_kernel_since, kernel_cursor

        self._emit("🔎 [敌方监控] 启动监控流程", "INFO")

        # 1. 绛夊緟绗竴涓?fightResource/skill 鍑虹幇锛堜綔涓烘娴嬫繁钃濊壊探针鐨勫紑濮嬫爣蹇楋級
        start_cursor = kernel_cursor()
        skill_detected = False
        skill_detected_time = None

        t0 = time.time()

        # 鍏堟鏌ュ凡鏈夋棩蹇?
        try:
            lines = fetch_kernel_since(start_cursor)
            if isinstance(lines, list):
                for line in lines:
                    if line_matches(RE_FIGHT_SKILL_DIR, str(line)):
                        skill_detected = True
                        skill_detected_time = time.time()
                        self._emit("[敌方监控] 检测到 /resource/fightResource/skill/ 信号", "SUCCESS")
                        break
        except Exception:
            pass

        # 濡傛灉娌℃湁妫€娴嬪埌锛岀户缁洃鎺?
        if not skill_detected:
            self._emit("[敌方监控] 等待 /resource/fightResource/skill/ 信号", "INFO")
            while not skill_detected:
                if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                    return None, None, "stopped"

                if (time.time() - t0) > timeout_s:
                    self._emit(f"[敌方监控] 等待技能信号超时（{timeout_s}s）", "WARN")
                    return None, None, "timeout"

                try:
                    lines = fetch_kernel_since(start_cursor)
                    if isinstance(lines, list):
                        for line in lines:
                            if line_matches(RE_FIGHT_SKILL_DIR, str(line)):
                                skill_detected = True
                                skill_detected_time = time.time()
                                self._emit("[敌方监控] 检测到 /resource/fightResource/skill/ 信号", "SUCCESS")
                                break
                    start_cursor = kernel_cursor()
                except Exception:
                    pass

                time.sleep(0.1)

        # 2. skill信号鍑虹幇鍚庯紝寮€濮嬫娴嬪洖鍚堟帰閽堟槸鍚︿负娣辫摑鑹诧紙#0E203F 鍒?#003366 涔嬮棿锛?
        self._emit("[敌方监控] 技能信号已出现，等待深蓝回合探针", "INFO")
        dark_blue_detected = False
        dark_blue_time = None

        while not dark_blue_detected:
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return None, None, "stopped"

            if (time.time() - t0) > timeout_s:
                self._emit(f"[敌方监控] 等待深蓝探针超时（{timeout_s}s）", "WARN")
                return None, None, "timeout"

            if self._check_dark_blue_probe(use_foreground):
                dark_blue_detected = True
                dark_blue_time = time.time()
                self._emit("[敌方监控] 已检测到深蓝探针", "SUCCESS")
                break

            time.sleep(0.1)

        # 3. 绛夊緟探针鐢辨繁钃濆彉鐏帮紙鍙湁鍙樼伆鍚庢墠寮€濮婳CR锛?
        self._emit("[敌方监控] 等待回合探针变灰后开始OCR", "INFO")

        # 加载探针模型
        if not hasattr(self, '_unified_framework') or not self._unified_framework:
            from core.unified_battle_framework import UnifiedBattleFramework
            from config import TEMPLATES_PATH
            self._unified_framework = UnifiedBattleFramework(self.bot, self.regions, TEMPLATES_PATH)

        probe_model = self._unified_framework._load_probe_templates()
        probe_turned_gray = False
        probe_gray_time = None

        while not probe_turned_gray:
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return None, None, "stopped"

            if (time.time() - t0) > timeout_s:
                self._emit(f"[敌方监控] 等待探针变灰超时（{timeout_s}s）", "WARN")
                return None, None, "timeout"

            if probe_model:
                state, blue_score, gray_score = self._unified_framework._detect_round_probe(probe_model)
                if state == "GRAY":
                    probe_turned_gray = True
                    probe_gray_time = time.time()
                    self._emit(f"[敌方监控] 探针已变灰（蓝={blue_score:.3f}，灰={gray_score:.3f}）", "SUCCESS")
                    break

            time.sleep(0.1)

        # 4. 探针宸插彉鐏帮紝鐜板湪寮€濮嬫寔缁璒CR鎵弿直到PetItem锛堝鏋滄娴嬪埌绗﹀悎鏉′欢鍒欐彁鍓嶅仠姝級
        self._emit("[敌方监控] 探针已灰，开始OCR直到 PetItem 或条件满足", "INFO")

        # 鉁?妫€鏌CR渚濊禆
        if not pytesseract:
            self._emit("[敌方监控] pytesseract不可用，跳过OCR", "WARN")
            level = None
            hp = None
            last_level = None
            last_hp = None
        else:
            # 鉁?妫€鏌egion鏄惁瀛樺湪
            level_key = "对战信息.敌方精灵等级"
            hp_key = "对战信息.敌方精灵血量"
            level_region = self.regions.get(level_key)
            hp_region = self.regions.get(hp_key)

            if not level_region or not hp_region:
                self._emit(f"[敌方监控] OCR区域缺失：等级={level_region is not None}，体力={hp_region is not None}", "WARN")
                level = None
                hp = None
                last_level = None
                last_hp = None
            else:
                level = None
                hp = None
                last_level = None
                last_hp = None
                ocr_scan_count = 0
                condition_met = False  # 鏄惁妫€娴嬪埌绗﹀悎鏉′欢
                saved_ocr_images = False
                battle_num = self._battle_count + 1

                petitem_cursor = kernel_cursor()
                petitem_detected = False

                # 鎸佺画OCR鎵弿直到PetItem鎴栨娴嬪埌绗﹀悎鏉′欢
                while not petitem_detected and not condition_met:
                    if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                        self._last_enemy_level = last_level
                        self._last_enemy_hp = last_hp
                        return level, hp, "stopped"

                    if (time.time() - t0) > timeout_s:
                        self._last_enemy_level = last_level
                        self._last_enemy_hp = last_hp
                        if level is None and hp is None:
                            self._emit(f"[敌方监控] OCR超时且没有数据（{timeout_s}s）", "WARN")
                            return None, None, "timeout"
                        else:
                            self._emit("[敌方监控] OCR超时，但已有部分数据", "WARN")
                            return level, hp, "timeout"

                    # 妫€鏌etItem
                    try:
                        lines = fetch_kernel_since(petitem_cursor)
                        if isinstance(lines, list):
                            for line in lines:
                                if line_matches(RE_PETITEM, str(line)):
                                    petitem_detected = True
                                    self._emit("[敌方监控] 检测到 PetItem，停止OCR", "SUCCESS")
                                    break
                        petitem_cursor = kernel_cursor()
                    except Exception:
                        pass

                    # 濡傛灉杩樻病妫€娴嬪埌PetItem，继续OCR鎵弿
                    if not petitem_detected:
                        ocr_scan_count += 1
                        self._emit(f"[敌方监控] OCR扫描第 {ocr_scan_count} 次", "DEBUG")
                        scan_level, scan_hp, level_img, hp_img = self._ocr_enemy_info_fast(use_foreground)

                        if not saved_ocr_images and scan_level is not None and scan_hp is not None:
                            self._save_enemy_ocr_images(scan_level, scan_hp, level_img, hp_img, battle_num)
                            saved_ocr_images = True

                        # 鏇存柊鏈€鍚庝竴娆℃垚鍔熸祴寰楃殑鏁版嵁
                        if scan_level is not None:
                            level = scan_level
                            last_level = scan_level
                            # 鉁?绔嬪嵆淇濆瓨鍒板疄渚嬪彉閲忥紝閬垮厤绔炴€佹潯浠?
                            self._last_enemy_level = last_level
                            self._emit(f"[敌方监控] 等级OCR成功：{level}", "INFO")

                        if scan_hp is not None:
                            # 鉁?楠岃瘉琛€閲忔槸鍚︿负涓や綅鏁帮紙寮哄埗鍙帴鍙椾袱浣嶆暟锛?
                            if 10 <= scan_hp <= 99:
                                hp = scan_hp
                                last_hp = scan_hp
                                # 鉁?绔嬪嵆淇濆瓨鍒板疄渚嬪彉閲忥紝閬垮厤绔炴€佹潯浠?
                                self._last_enemy_hp = last_hp
                                self._emit(f"[敌方监控] 体力OCR成功：{hp}", "INFO")
                            else:
                                self._emit(f"[敌方监控] 体力OCR不是两位数：{scan_hp}，忽略", "WARN")
                                # 涓嶆洿鏂癶p鍜宭ast_hp锛屼繚鎸佷箣鍓嶇殑鍊?

                        # 濡傛灉妫€娴嬪埌绗﹀悎鏉′欢锛屾彁鍓嶅仠姝㈡壂鎻?
                        if check_condition_callback and last_level is not None and last_hp is not None:
                            if check_condition_callback(last_level, last_hp):
                                condition_met = True
                                self._emit(f"[敌方监控] 条件满足：等级={last_level}，体力={last_hp}，停止OCR", "SUCCESS")
                                # 鉁?纭繚鏁版嵁宸蹭繚瀛橈紙铏界劧涓婇潰宸茬粡淇濆瓨浜嗭紝浣嗚繖閲屽啀娆＄‘璁わ級
                                self._last_enemy_level = last_level
                                self._last_enemy_hp = last_hp
                                break

                        if last_level is not None or last_hp is not None:
                            self._emit(f"[敌方监控] 当前结果：等级={last_level}，体力={last_hp}，扫描={ocr_scan_count}", "INFO")

                        time.sleep(0.3)  # OCR鎵弿闂撮殧

        # 淇濆瓨鏈€缁堢粨鏋滐紙濡傛灉杩樻病淇濆瓨锛屼綔涓哄厹搴曪級
        if self._last_enemy_level is None:
            self._last_enemy_level = last_level if last_level is not None else level
        if self._last_enemy_hp is None:
            self._last_enemy_hp = last_hp if last_hp is not None else hp

        # 濡傛灉杩樻病妫€娴嬪埌PetItem锛岀户缁瓑寰?
        if not petitem_detected:
            self._emit("[敌方监控] OCR已结束，继续等待 PetItem", "INFO")
            while True:
                if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                    return self._last_enemy_level, self._last_enemy_hp, "stopped"

                if (time.time() - t0) > timeout_s:
                    self._emit(f"[敌方监控] 等待 PetItem 超时（{timeout_s}s）", "WARN")
                    return self._last_enemy_level, self._last_enemy_hp, "timeout"

                # 妫€鏌etItem
                try:
                    lines = fetch_kernel_since(petitem_cursor)
                    if isinstance(lines, list):
                        for line in lines:
                            if line_matches(RE_PETITEM, str(line)):
                                self._emit("[敌方监控] 检测到 PetItem", "SUCCESS")
                                if self._last_enemy_level is not None or self._last_enemy_hp is not None:
                                    self._emit(f"[敌方监控] 最终结果：等级={self._last_enemy_level}，体力={self._last_enemy_hp}", "INFO")
                                return self._last_enemy_level, self._last_enemy_hp, "success"
                    petitem_cursor = kernel_cursor()
                except Exception:
                    pass

                time.sleep(0.1)  # 妫€鏌ラ棿闅?
        else:
            # 宸茬粡妫€娴嬪埌PetItem
            if self._last_enemy_level is not None or self._last_enemy_hp is not None:
                self._emit(f"[敌方监控] 最终结果：等级={self._last_enemy_level}，体力={self._last_enemy_hp}", "INFO")
            return self._last_enemy_level, self._last_enemy_hp, "success"

    def _check_dugulu_escape_condition(
        self,
        use_foreground: bool,
        stop_event: threading.Event
    ) -> Tuple[bool, bool]:
        """Check whether Dugulu mode should escape based on OCR results."""
        # 鑾峰彇鏈€鍚庝竴娆℃祴寰楃殑绛夌骇鍜岃閲?
        level = self._last_enemy_level
        hp = self._last_enemy_hp

        if level is None or hp is None:
            self._emit(f"[嘟咕噜] 缺少等级或体力数据：等级={level}，体力={hp}，跳过", "WARN")
            return False, False

        # 鉁?棣栧厛妫€鏌ユ槸鍚﹀湪鍚堢悊鐨勮閲忕粍鍚堣寖鍥村唴
        is_valid_combination = False
        if (level == 15 and hp in [43, 44, 45, 46, 47]) or \
           (level == 16 and hp in [45, 46, 47, 48, 49, 50]):
            is_valid_combination = True
        else:
            # 涓嶅湪鍚堢悊鑼冨洿鍐咃紝璇存槑OCR鍑洪棶棰樹簡
            self._emit(f"[嘟咕噜] 等级/体力组合不合理：等级={level}，体力={hp}", "WARN")
            return False, True  # 继续捕捉但提醒失败

        # 鉁?鍦ㄥ悎鐞嗚寖鍥村唴锛屾鏌ユ槸鍚﹂渶瑕侀€冭窇
        # 鍙湁涓ょ鎯呭喌涓嶉€冭窇锛堢户缁崟鎹夛級锛?5绾?7琛€閲忥紝鎴?6绾?0琛€閲?
        if (level == 15 and hp == 47) or (level == 16 and hp == 50):
            self._emit(f"[嘟咕噜] 满足捕捉条件：等级={level}，体力={hp}", "SUCCESS")
            return False, False
        else:
            # 鍏朵粬鎯呭喌锛氶€冭窇
            self._emit(f"[嘟咕噜逃跑] 等级={level}，体力={hp}，执行逃跑", "SUCCESS")
            return True, False

    def _check_shuangta_escape_condition(
        self,
        pet_ids: Optional[set],
        use_foreground: bool,
        stop_event: threading.Event
    ) -> bool:
        """Check whether Shuangta mode should escape based on OCR results."""
        if not pet_ids:
            self._emit("[双塔逃跑] 没有精灵ID，跳过逃跑检查", "WARN")
            return False

        # 鑾峰彇鏈€鍚庝竴娆℃祴寰楃殑绛夌骇鍜岃閲?
        level = self._last_enemy_level
        hp = self._last_enemy_hp

        if level is None or hp is None:
            self._emit(f"[双塔逃跑] 缺少等级或体力数据：等级={level}，体力={hp}，跳过", "WARN")
            return False

        # 鉁?双塔模式鐗规畩澶勭悊锛歄CR璇嗗埆涓?0时，当作36澶勭悊锛堜絾淇濆瓨鎴浘鏃朵粛使用鍘熷鍊?0锛?
        hp_original = hp  # 保存原始值用于日志
        if hp == 30:
            hp = 36
            self._emit("[双塔逃跑] OCR体力30按36处理", "DEBUG")

        # 鉁?棣栧厛妫€鏌ユ槸鍚﹀湪鍚堢悊鐨勮閲忕粍鍚堣寖鍥村唴
        is_valid_combination = False
        if (level == 11 and hp in [32, 33, 34, 35, 36]) or \
           (level == 12 and hp in [34, 35, 36, 37, 38, 39]):
            is_valid_combination = True
        else:
            # 涓嶅湪鍚堢悊鑼冨洿鍐咃紝璇存槑OCR鍑洪棶棰樹簡
            self._emit(f"[双塔] 等级/体力组合不合理：等级={level}，体力={hp_original}->{hp}", "WARN")
            return False  # 继续捕捉但提醒失败（通过_dugulu_ocr_failed绫讳技鐨勬満鍒讹紝浣嗗弻濉旀ā寮忕洰鍓嶆病鏈夎繖涓爣蹇楋級

        # 鉁?鍦ㄥ悎鐞嗚寖鍥村唴锛屾鏌ユ槸鍚﹂渶瑕侀€冭窇
        # 143 卡塔锛氫竴寰嬩笉逃跑
        if 143 in pet_ids:
            self._emit(f"[双塔] 检测到143，等级={level}，体力={hp_original}->{hp}，继续捕捉", "SUCCESS")
            return False

        # 102 奇塔锛?1绾?2/33 鎴?12绾?4/35 逃跑
        if 102 in pet_ids:
            if (level == 11 and hp in [32, 33]) or (level == 12 and hp in [34, 35]):
                self._emit(f"[双塔逃跑] 102等级={level}，体力={hp_original}->{hp}，执行逃跑", "SUCCESS")
                return True
            else:
                self._emit(f"[双塔] 102等级={level}，体力={hp_original}->{hp}，继续捕捉", "SUCCESS")

        # 濡傛灉鏃笉鏄崱濉斾篃涓嶆槸奇塔，或鑰呬笉婊¤冻逃跑鏉′欢锛岀户缁崟鎹?
        return False

    def _read_hp_bar_mean_rgb(self, pos: str) -> Optional[Tuple[int, int, int]]:
        hp_bar_key = f"精灵背包.血条{pos}"
        try:
            if self._unified_framework:
                rgb = self._unified_framework._mean_rgb(hp_bar_key)
                if rgb is not None:
                    return (int(rgb[0]), int(rgb[1]), int(rgb[2]))
            hp_bar_reg = self.regions.require(hp_bar_key)
            from core.utils import window_manager
            x1, y1, x2, y2 = hp_bar_reg.outer_bbox()
            img = window_manager.grab_game_bbox(x1, y1, x2, y2)
            if img is None:
                return None
            import numpy as np
            arr = np.asarray(img.convert("RGB"), dtype=np.float32)
            if arr.size == 0:
                return None
            mean = np.round(arr.mean(axis=(0, 1))).astype(int)
            return (int(mean[0]), int(mean[1]), int(mean[2]))
        except KeyError:
            return None
        except Exception:
            return None

    @staticmethod
    def _hp_bar_color_distance(c1: Tuple[int, int, int], c2: Tuple[int, int, int]) -> float:
        return (
            (c1[0] - c2[0]) ** 2 + (c1[1] - c2[1]) ** 2 + (c1[2] - c2[2]) ** 2
        ) ** 0.5

    def _classify_storage_hp_bar_rgb(
        self, rgb: Tuple[int, int, int], *, log_prefix: str = "color-check", quiet: bool = False
    ) -> Optional[str]:
        """Classify an HP bar RGB sample."""
        r, g, b = rgb
        if (
            min(r, g, b) >= self.HP_BAR_NEUTRAL_MIN_CHANNEL
            or (max(r, g, b) - min(r, g, b) <= 20 and (r + g + b) / 3 >= 160)
        ):
            self._emit(
                f"⚪ [{log_prefix}] 血量探针RGB=({r},{g},{b}) 接近灰/白UI，跳过",
                "DEBUG" if quiet else "WARN",
            )
            return None
        dist_blue = self._hp_bar_color_distance(rgb, self.HP_BAR_STORAGE_BLUE)
        dist_red = self._hp_bar_color_distance(rgb, self.HP_BAR_KEEP_RED)
        tol = self.HP_BAR_COLOR_TOLERANCE
        if dist_blue <= tol:
            return "storage_blue"
        if dist_red <= tol:
            return "keep_red"
        # 严格蓝色：B 通道显著高于 R/G，避免白/娴呰壊璇垽
        if b > r + 30 and b > g + 15 and dist_blue < dist_red:
            return "storage_blue"
        if r > b + 30 and dist_red < dist_blue:
            return "keep_red"
        if dist_blue < dist_red and b > r + 15:
            return "storage_blue"
        if dist_red <= dist_blue:
            return "keep_red"
        return None

    def _click_return_storage(self, use_foreground: bool) -> None:
        return_storage_key = "精灵背包.放回仓库"
        return_storage_btn_key = "精灵背包.放回仓库按钮"
        try:
            self._click_region(return_storage_btn_key, use_foreground)
        except KeyError:
            self._click_region(return_storage_key, use_foreground)

    def _confirm_putback_hp_bar_cleared(
        self,
        pos: str,
        use_foreground: bool,
        stop_event: threading.Event,
    ) -> bool:
        """Wait until the HP bar no longer looks like a stored pet slot."""
        self._emit(
            f"[putback] wait for pet slot {pos} HP bar to clear ({self.PUTBACK_HP_VERIFY_TIMEOUT_S:.0f}s timeout)",
            "INFO",
        )
        t0 = time.time()
        last_retry = t0
        while (time.time() - t0) < self.PUTBACK_HP_VERIFY_TIMEOUT_S:
            if stop_event.is_set():
                return False
            elapsed = time.time() - t0
            rgb = self._read_hp_bar_mean_rgb(pos)
            if rgb is not None:
                kind = self._classify_storage_hp_bar_rgb(
                    rgb, log_prefix="鏀惧洖纭", quiet=True
                )
                if kind == "keep_red":
                    r, g, b = rgb
                    self._emit(f"[putback] pet{pos} HP bar is red RGB=({r},{g},{b}); done", "SUCCESS")
                    return True
                if kind is None and elapsed >= 1.0:
                    r, g, b = rgb
                    self._emit(f"[putback] pet{pos} slot empty/not blue RGB=({r},{g},{b}); done", "SUCCESS")
                    return True
            now = time.time()
            if (now - last_retry) >= self.PUTBACK_HP_RETRY_INTERVAL_S:
                self._emit(f"[putback] pet{pos} still blue; click putback again", "WARN")
                self._click_return_storage(use_foreground)
                last_retry = now
                self._sleep_abortable(stop_event, 0.8)
            else:
                self._sleep_abortable(stop_event, 0.25)
        self._emit(
            f"[putback] pet{pos} remained blue for {self.PUTBACK_HP_VERIFY_TIMEOUT_S:.0f}s; failed",
            "ERROR",
        )
        return False

    def _ensure_pet_bag_ui_ready_after_open(
        self,
        stop_event: threading.Event,
        use_foreground: bool,
        bag_open_key: str,
        bag_open_btn_key: str,
        log_tag: str = "背包",
    ) -> bool:
        """Wait for the bag UI after opening once; never retry opening the bag."""
        ok = self._wait_pet_bag_ui_ready_after_open(stop_event, log_tag=log_tag)
        if not ok:
            self._emit(f"[{log_tag}] 背包UI未就绪，不重试打开", "WARN")
        return ok

    def _close_pet_bag_with_verify(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
        bag_open_key: str,
        bag_open_btn_key: str,
        log_tag: str = "背包",
    ) -> None:
        """Click the bag button once to close it."""
        self._emit(f"[{log_tag}] 点击精灵背包按钮关闭", "INFO")
        try:
            self._click_region(bag_open_btn_key, use_foreground)
        except KeyError:
            self._click_region(bag_open_key, use_foreground)
        self._sleep_abortable(stop_event, 0.5)

    def _request_reconnect_after_recovery_failure(
        self,
        profile: Optional["WildCaptureProfile"],
        use_foreground: bool,
        stop_event: threading.Event,
        reason: str,
    ) -> None:
        """Request the current mode reconnect flow after recovery failure."""
        self._emit(f"[战后恢复] {reason}，请求刷新重连", "WARN")
        screenshot_path = self._save_client_screenshot(
            "post_battle_recovery_failed", category="recovery_failure"
        )
        if screenshot_path:
            self._emit(f"[战后恢复调试] 客户端截图已保存：{screenshot_path}", "INFO")

        event_profile = getattr(self, "_event_pet_active_profile", None)
        if event_profile is not None:
            self._event_pet_trigger_reconnect(
                event_profile,
                use_foreground,
                stop_event,
                reason=f"post_battle_recovery_failed-{reason}",
            )
            stop_event.set()
            self._emit(
                "[post-battle-recovery] event pet recovery failed; delegated reconnect",
                "INFO",
            )
            return

        current_mode = getattr(self, "_current_mode", None)
        if profile is DEFAULT_PROFILE_DUGULU and current_mode != "dugulu":
            profile = None
        configured_profile = getattr(self, "_configured_nieo_profile", None)
        if profile is None and configured_profile is not None:
            self._current_mode = f"nieo:{configured_profile.slug}"
            profile = WildCaptureProfile(
                name=configured_profile.name,
                route_hint=configured_profile.route_hint,
                map_swf_id=int(configured_profile.map_b_id),
                target_mp3_id=int(configured_profile.entry_pet_id),
                target_pet_id=int(configured_profile.entry_pet_id),
                excluded_pet_ids=(),
            )
        elif profile is None and current_mode == "pure_energy":
            profile = WildCaptureProfile(
                name="纯净能量(资源)",
                route_hint="纯净能量",
                map_swf_id=26,
                target_mp3_id=416,
                target_pet_id=416,
                excluded_pet_ids=(),
            )
        elif profile is None and current_mode == "nieo":
            profile = WildCaptureProfile(
                name="尼奥",
                route_hint="尼奥",
                map_swf_id=10,
                target_mp3_id=416,
                target_pet_id=416,
                excluded_pet_ids=(),
            )
        elif profile is None and current_mode == "rare":
            slot = getattr(self, "_rotation_rare_slot", "shuangta") or "shuangta"
            try:
                profile = self._resolve_rotation_rare_profile(slot)
            except Exception as exc:
                self._emit(f"[放回] 解析轮换稀有方案失败：{exc}", "WARN")

        if profile is None:
            profile = getattr(self, "_current_profile", None)
        if not profile:
            self._emit("[战后恢复] 方案不可用，仍请求当前模式重启", "WARN")
            self._request_mode_restart(stop_event, "战后恢复失败")
            return
        self._reconnect_reason_capture_verify_four = False
        self._request_mode_restart(stop_event, "战后恢复重连")

    def _identify_target_pet_by_color(self, use_foreground: bool) -> Optional[str]:
        """Identify which pet slot should be put back by HP-bar color."""
        _ = use_foreground
        self._emit("[color-check] scan pet slots for storage-blue HP bars", "INFO")
        for pos in ["四", "三", "二"]:
            rgb = self._read_hp_bar_mean_rgb(pos)
            if rgb is None:
                self._emit(f"[color-check] pet slot {pos} HP bar RGB unavailable", "WARN")
                continue
            r, g, b = rgb
            self._emit(f"[color-check] pet slot {pos} HP RGB=({r}, {g}, {b})", "DEBUG")
            kind = self._classify_storage_hp_bar_rgb(rgb, log_prefix="color-check")
            if kind == "storage_blue":
                self._emit(f"[color-check] pet slot {pos} is storage-blue", "SUCCESS")
                return pos
            if kind == "keep_red":
                self._emit(f"[color-check] pet slot {pos} is keep-red", "INFO")
                continue
        self._emit("[color-check] no storage-blue pet slot found", "WARN")
        return None

    def _scan_hp_bars_for_storage(self, use_foreground: bool) -> Optional[str]:
        """Scan HP bars and return a slot that should be put back."""
        _ = use_foreground
        self._emit("[hp-scan] scan HP bars for storage-blue pet slots", "INFO")
        for pos in ["二", "四", "三", "五"]:
            rgb = self._read_hp_bar_mean_rgb(pos)
            if rgb is None:
                self._emit(f"[hp-scan] pet slot {pos} HP bar RGB unavailable", "WARN")
                continue
            r, g, b = rgb
            self._emit(f"[hp-scan] pet slot {pos} HP RGB=({r}, {g}, {b})", "DEBUG")
            kind = self._classify_storage_hp_bar_rgb(rgb, log_prefix="hp-scan")
            if kind == "storage_blue":
                self._emit(f"[hp-scan] pet slot {pos} is storage-blue", "SUCCESS")
                return pos
            if kind == "keep_red":
                self._emit(f"[hp-scan] pet slot {pos} is keep-red", "INFO")
                continue
        self._emit("[hp-scan] no storage-blue pet slot found", "INFO")
        return None

    def _check_selected_four_color(self, use_foreground: bool) -> Optional[int]:
        """Check the selected-four bag region color."""
        try:
            selected_four_key = "精灵背包.选中四"
            selected_four_reg = self.regions.require(selected_four_key)

            # 获取选中四区域的图像
            from core.utils import window_manager
            x1, y1, x2, y2 = selected_four_reg.outer_bbox()
            img = window_manager.grab_game_bbox(x1, y1, x2, y2)
            if img is None:
                self._emit("[选四号] 截取选四号区域失败", "WARN")
                return None

            # 杞崲涓篟GB鏁扮粍
            import numpy as np
            arr = np.asarray(img.convert("RGB"), dtype=np.uint8)
            if arr.size == 0:
                self._emit("[选四号] 选四号区域截图为空", "WARN")
                return None

            # 璁＄畻骞冲潎RGB
            mean_rgb = np.round(arr.mean(axis=(0, 1))).astype(int)
            r, g, b = int(mean_rgb[0]), int(mean_rgb[1]), int(mean_rgb[2])
            self._emit(f"[选四号] 平均RGB=({r}, {g}, {b})", "DEBUG")

            # 瀹氫箟鍙傝€冮鑹诧紙鍩轰簬template鍥剧墖实际娴嬭瘯缁撴灉锛?
            # 榛勮壊娣峰悎鍙傝€僐GB（蓝色混合黄色或整体偏黄色）
            YELLOW_MIXED_REF = (230, 235, 26)  # 鍩轰簬01_123111_榛?png实际娴嬭瘯鍊?
            # 钃濊壊鍙傝€僐GB锛堢函钃濊壊鎴栨祬钃濊壊娣锋繁钃濊壊锛?
            BLUE_REF = (26, 115, 178)  # 鍩轰簬01_123737_钃?png实际娴嬭瘯鍊?

            # 璁＄畻娆ф皬璺濈
            def euclidean_distance(rgb1, rgb2):
                """Return Euclidean distance between two RGB colors."""
                return np.sqrt(sum((a - b) ** 2 for a, b in zip(rgb1, rgb2)))

            dist_to_yellow_mixed = euclidean_distance((r, g, b), YELLOW_MIXED_REF)
            dist_to_blue = euclidean_distance((r, g, b), BLUE_REF)

            self._emit(f"[选四号] 黄混距离={dist_to_yellow_mixed:.2f}，蓝色距离={dist_to_blue:.2f}", "DEBUG")

            # 使用RGB特征辅助判断
            # 黄色混合特征：R和G较高，B较低
            # 蓝色特征：B较高，R和G较低
            rgb_yellow_score = (r + g) / (b + 1)  # 黄色得分（越高越黄）
            rgb_blue_score = b / (r + g + 1)       # 蓝色得分（越高越蓝）

            self._emit(f"[选四号] 黄色分={rgb_yellow_score:.2f}，蓝色分={rgb_blue_score:.2f}", "DEBUG")

            # 缁煎悎判断锛氫紭鍏堜娇鐢ㄦ姘忚窛绂伙紝RGB特征作为辅助
            # 濡傛灉璺濈榛勮壊娣峰悎鏇磋繎锛屼笖RGB榛勮壊寰楀垎杈冮珮锛屽垽瀹氫负榛勮壊娣峰悎锛堣繑鍥?锛?
            # 濡傛灉璺濈钃濊壊鏇磋繎锛屼笖RGB钃濊壊寰楀垎杈冮珮锛屽垽瀹氫负钃濊壊锛堣繑鍥?锛?

            is_yellow_mixed = False
            is_blue = False

            # 判断1: 鍩轰簬娆ф皬璺濈锛堜富瑕佸垽鏂級
            if dist_to_yellow_mixed < dist_to_blue:
                # 璺濈榛勮壊娣峰悎鏇磋繎锛岃繘涓€姝ラ獙璇丷GB特征
                if rgb_yellow_score > 1.5:  # RGB特征也偏向黄色
                    is_yellow_mixed = True
                    self._emit(f"[选四号] 黄混更近（{dist_to_yellow_mixed:.2f} < {dist_to_blue:.2f}），黄色分支持该结果", "INFO")
                elif rgb_blue_score > 0.8:  # 濡傛灉RGB特征鏄庢樉鍋忓悜钃濊壊锛屽彲鑳芥槸璇垽
                    is_blue = True
                    self._emit("[选四号] 黄混更近但RGB支持蓝色", "INFO")
                else:
                    # RGB特征涓嶆槑纭紝榛樿鍒ゅ畾涓洪粍鑹叉贩鍚?
                    is_yellow_mixed = True
                    self._emit(f"[选四号] 黄混更近（{dist_to_yellow_mixed:.2f} < {dist_to_blue:.2f}），判定黄混", "INFO")
            else:
                # 璺濈钃濊壊鏇磋繎锛岃繘涓€姝ラ獙璇丷GB特征
                if rgb_blue_score > 0.6:  # RGB特征也偏向蓝色
                    is_blue = True
                    self._emit(f"[选四号] 蓝色更近（{dist_to_blue:.2f} < {dist_to_yellow_mixed:.2f}），蓝色分支持该结果", "INFO")
                elif rgb_yellow_score > 2.0:  # 濡傛灉RGB特征鏄庢樉鍋忓悜榛勮壊锛屽彲鑳芥槸璇垽
                    is_yellow_mixed = True
                    self._emit("[选四号] 蓝色更近但RGB支持黄混", "INFO")
                else:
                    # RGB特征涓嶆槑纭紝榛樿鍒ゅ畾涓鸿摑鑹?
                    is_blue = True
                    self._emit(f"[选四号] 蓝色更近（{dist_to_blue:.2f} < {dist_to_yellow_mixed:.2f}），判定蓝色", "INFO")

            # 杩斿洖缁撴灉
            if is_yellow_mixed:
                self._emit("[选四号] 最终判定：黄混", "SUCCESS")
                return 1
            elif is_blue:
                self._emit("[选四号] 最终判定：蓝色", "SUCCESS")
                return 0
            else:
                # 无法明确判断，默认返回None锛堢户缁墽琛屾斁鍥炵▼搴忥級
                self._emit("[选四号] 无法判定颜色，默认继续", "WARN")
                return None

        except KeyError:
            self._emit("[选四号] 找不到区域：精灵背包.选中四", "WARN")
            return None
        except Exception as e:
            self._emit(f"[选四号] 检测失败：{e}", "WARN")
            import traceback
            self._emit(f"exception detail: {traceback.format_exc()}", "DEBUG")
            return None

    def _check_capture_verify_four_color(self, use_foreground: bool) -> Optional[int]:
        """Check whether capture verify slot four contains a pet."""
        return self._check_selected_four_color(use_foreground)

    def _check_selected_pet_color(
        self, pet_position: str, use_foreground: bool, *, verbose: bool = False
    ) -> Optional[int]:
        """Check whether a selected-pet region is selected by color."""
        _ = use_foreground
        try:
            selected_key = f"精灵背包.选中{pet_position}"
            selected_reg = self.regions.require(selected_key)
            from core.utils import window_manager
            import numpy as np

            x1, y1, x2, y2 = selected_reg.outer_bbox()
            img = window_manager.grab_game_bbox(x1, y1, x2, y2)
            if img is None:
                self._emit(f"[选中-{pet_position}] 无法截取区域图像", "WARN")
                return None
            arr = np.asarray(img.convert("RGB"), dtype=np.uint8)
            if arr.size == 0:
                self._emit(f"[选中-{pet_position}] 区域图像为空", "WARN")
                return None
            mean_rgb = np.round(arr.mean(axis=(0, 1))).astype(int)
            r, g, b = int(mean_rgb[0]), int(mean_rgb[1]), int(mean_rgb[2])
            if verbose:
                self._emit(f"[选中-{pet_position}] RGB=({r},{g},{b})", "DEBUG")

            yellow_score = (r + g) / max(b + 1, 1)
            blue_score = b / max(r + g + 1, 1)

            # The selected border may be yellow or white and can vary with
            # capture scaling/compression; classify by color family, not an
            # exact RGB value.
            is_white_selected = (
                r >= 160
                and g >= 160
                and b >= 160
                and max(r, g, b) - min(r, g, b) <= 100
            )
            is_yellow_selected = (
                r >= 100
                and g >= 100
                and b <= min(r, g) * 0.95
            )
            if is_white_selected or is_yellow_selected:
                self._emit(f"[选中-{pet_position}] 已选中 RGB=({r},{g},{b})", "SUCCESS")
                return 1
            if blue_score > 0.45 or (b >= 120 and b > r and b > g):
                if verbose:
                    self._emit(f"[选中-{pet_position}] 未选中 RGB=({r},{g},{b})", "DEBUG")
                return 0
            self._emit(f"[选中-{pet_position}] RGB不明确=({r},{g},{b})", "WARN")
            return None
        except KeyError:
            self._emit(f"[精灵选择-{pet_position}] 缺少区域", "WARN")
            return None
        except Exception as e:
            self._emit(f"[选中-{pet_position}] 检查失败：{e}", "WARN")
            import traceback
            self._emit(f"traceback: {traceback.format_exc()}", "DEBUG")
            return None

    def _try_select_pet_four_with_timeout(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
        timeout_s: Optional[float] = None,
    ) -> bool:
        """Double-click pet slot four until selected or timeout."""
        timeout_s = float(timeout_s) if timeout_s is not None else self.SELECT_PET_FOUR_TIMEOUT_S
        check_delay = self.SELECT_PET_FOUR_CHECK_DELAY_S
        click_interval = self.SELECT_PET_FOUR_CLICK_INTERVAL_S
        self._emit(f"[选四号] 双击精灵四直到选中，超时={timeout_s:.0f}s", "INFO")
        pet_key = "精灵背包.精灵四"
        pet_btn_key = "精灵背包.精灵四按钮"
        start_time = time.time()
        attempt = 0
        last_progress_log = 0.0
        while (time.time() - start_time) < timeout_s:
            if stop_event.is_set():
                return False
            attempt += 1
            for i in range(2):
                try:
                    self._click_region(pet_btn_key, use_foreground)
                except KeyError:
                    self._click_region(pet_key, use_foreground)
                if i < 1:
                    self._sleep_abortable(stop_event, click_interval)
            self._sleep_abortable(stop_event, check_delay)
            result = self._check_selected_pet_color("四", use_foreground, verbose=False)
            if result == 1:
                self._emit(f"[选四号] 第 {attempt} 次后选中，耗时={time.time() - start_time:.1f}s", "SUCCESS")
                return True
            now = time.time()
            if result == 0 and (now - last_progress_log) >= 2.0:
                elapsed = now - start_time
                self._emit(f"[选四号] 仍未选中，尝试={attempt}，耗时={elapsed:.1f}/{timeout_s:.0f}s", "INFO")
                last_progress_log = now
        self._emit(f"[选四号] {attempt} 次尝试后超时，请求重连", "WARN")
        return False

    def _try_select_pet_five_until_selected(self, use_foreground: bool, stop_event: threading.Event, max_iterations: int = 15) -> bool:
        """Double-click pet slot five until selected."""
        self._emit("[选五号] 双击精灵五直到选中", "INFO")
        pet_key = "精灵背包.精灵五"
        pet_btn_key = "精灵背包.精灵五按钮"
        click_interval = 0.1
        check_delay = 0.2
        for i in range(max_iterations):
            if stop_event.is_set():
                return False
            for j in range(2):
                try:
                    self._click_region(pet_btn_key, use_foreground)
                except KeyError:
                    self._click_region(pet_key, use_foreground)
                if j < 1:
                    self._sleep_abortable(stop_event, click_interval)
            self._sleep_abortable(stop_event, check_delay)
            result = self._check_selected_pet_color("五", use_foreground)
            if result == 1:
                self._emit("[选五号] 已选中", "SUCCESS")
                return True
            if result == 0:
                self._emit(f"[选五号] 尚未选中，尝试={i + 1}", "INFO")
        self._emit("[select-five] max attempts reached without selection", "WARN")
        return False

    def _click_pet_with_selection_check(
        self,
        pet_position: str,
        use_foreground: bool,
        stop_event: threading.Event,
        *,
        timeout_s: Optional[float] = None,
    ) -> bool:
        """Click a pet slot until selected, allowing at least three seconds by default."""
        pet_key = f"精灵背包.精灵{pet_position}"
        pet_btn_key = f"精灵背包.精灵{pet_position}按钮"
        timeout_s = max(
            self.SELECT_PET_GENERIC_TIMEOUT_S,
            float(timeout_s)
            if timeout_s is not None
            else self.SELECT_PET_GENERIC_TIMEOUT_S,
        )
        click_interval = self.SELECT_PET_GENERIC_CLICK_INTERVAL_S
        check_delay = self.SELECT_PET_GENERIC_CHECK_DELAY_S
        clicks_per_scan = 2
        start_time = time.time()
        scan_count = 0
        self._emit(
            f"[选择精灵] 槽位 {pet_position} 持续点击并确认选中，"
            f"失败超时不少于 {timeout_s:g}s",
            "INFO",
        )
        while True:
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return False
            scan_count += 1
            for i in range(clicks_per_scan):
                try:
                    self._click_region(pet_btn_key, use_foreground)
                except KeyError:
                    self._click_region(pet_key, use_foreground)
                if i < clicks_per_scan - 1:
                    self._sleep_abortable(stop_event, click_interval)
            self._sleep_abortable(stop_event, check_delay)
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return False
            elapsed = time.time() - start_time
            self._emit(
                f"[选择精灵] 检查槽位 {pet_position} 的选中状态，"
                f"扫描={scan_count}，耗时={elapsed:.1f}/{timeout_s:g}s",
                "INFO",
            )
            selection_result = self._check_selected_pet_color(pet_position, use_foreground)
            if selection_result == 1:
                self._emit(
                    f"[选择精灵] 槽位 {pet_position} 已选中，"
                    f"扫描={scan_count}，耗时={elapsed:.1f}s",
                    "SUCCESS",
                )
                return True
            if elapsed >= timeout_s:
                break
            if selection_result == 0:
                self._emit(
                    f"[选择精灵] 槽位 {pet_position} 未选中，继续点击",
                    "INFO",
                )
            else:
                self._emit(
                    f"[选择精灵] 槽位 {pet_position} 选中状态不明确，继续点击",
                    "WARN",
                )
        self._emit(
            f"[选择精灵] 槽位 {pet_position} 在 {elapsed:.1f}s 内仍未选中，"
            f"扫描={scan_count}",
            "WARN",
        )
        return False

    def _ocr_identify_target_pet(self, use_foreground: bool, profile: WildCaptureProfile) -> Optional[str]:
        """Deprecated OCR target-pet identification entry."""
        _ = (use_foreground, profile)
        self._emit("[ocr-target] deprecated; use color detection instead", "WARN")
        return None
    def _collect_fight_pet_ids_immediate(self, stop_event: threading.Event, current_lines: Optional[List[str]] = None, start_index: int = 0) -> Optional[set]:
        """Collect fight pet IDs immediately from kernel log lines."""
        pet_ids = []

        self._emit("开始从已有内核日志收集 fightResource 精灵ID", "INFO")

        # 濡傛灉鎻愪緵浜哻urrent_lines，从这些行中搜索
        if current_lines is not None and isinstance(current_lines, list):
            # 浠巗tart_index寮€濮嬶紝鍚戜笅鎵弿鎵€鏈夎锛堢洿鍒板垪琛ㄦ湯灏炬垨閬囧埌skill信号锛?
            max_lines = len(current_lines)
            start_collecting_index = -1  # 鎵惧埌绗竴涓猵et/swf鐨勮绱㈠紩

            # 绗竴姝ワ細浠巗tart_index寮€濮嬶紝鎵惧埌绗竴涓寘鍚玴et/swf鐨勮锛堜笉瑕佹眰鏄?66锛?
            for i in range(start_index, max_lines):
                line_str = str(current_lines[i])
                matches = list(finditer_kernel_line(RE_FIGHT_PET_ID, line_str))
                if matches:
                    # 鎵惧埌绗竴涓猵et/swf，从杩欎竴琛屽紑濮嬫敹闆?
                    start_collecting_index = i
                    self._emit(f"📦 第一个 pet/swf 位于相对第 {i - start_index + 1} 行（index={i}），开始收集ID", "INFO")
                    break

            # 绗簩姝ワ細浠庣涓€涓猵et/swf鎵€鍦ㄧ殑琛屽紑濮嬶紝鏀堕泦鎵€鏈塸et IDs，直到遇到skill
            if start_collecting_index >= 0:
                for i in range(start_collecting_index, max_lines):
                    line_str = str(current_lines[i])

                    # 妫€鏌ユ槸鍚﹀嚭鐜皊kill（停止收集）
                    if line_matches(RE_FIGHT_SKILL_SWF, line_str):
                        self._emit("⚔️ 检测到技能资源信号，停止收集精灵ID", "INFO")
                        break

                    # 妫€鏌ヨ繖涓€琛屾槸鍚﹀寘鍚玴et/swf锛堜竴琛屽彲鑳藉寘鍚涓猵et ID锛?
                    matches = list(finditer_kernel_line(RE_FIGHT_PET_ID, line_str))
                    if matches:
                        for m in matches:
                            try:
                                pid_str = m.group(1)
                                pid = int(pid_str)
                                # 鏀堕泦鎵€鏈変笉鍚岀殑pet ID（去重）
                                if pid not in pet_ids:
                                    pet_ids.append(pid)  # 按顺序添加到列表
                                    self._emit(f"📦 检测到精灵ID：{pid}（原始={pid_str}，数量={len(pet_ids)}）", "INFO")
                            except Exception as e:
                                self._emit(f"解析精灵ID失败：{e}（原始={pid_str if 'pid_str' in locals() else 'N/A'}）", "WARN")
                                continue
            else:
                self._emit("未找到 pet/swf，无法收集精灵ID", "WARN")

        # 杞崲涓簊et骞跺幓閲嶏紙浣嗕繚鎸侀『搴忎俊鎭敤浜庢棩蹇楋級
        unique_pet_ids = list(dict.fromkeys(pet_ids))  # 保持顺序的去重
        pet_ids_set = set(unique_pet_ids)

        if pet_ids_set:
            self._emit(f"pet ID collection complete: {len(unique_pet_ids)} unique IDs: {unique_pet_ids}", "INFO")
            return pet_ids_set
        else:
            self._emit("no pet ID collected", "WARN")
            return None

    def _collect_fight_pet_ids(self, timeout: float, collect_window: float, stop_event: threading.Event) -> set:
        """Collect pet IDs from fightResource pet SWF kernel logs."""
        cursor = kernel_cursor()
        t0 = time.time()
        first_seen_at: Optional[float] = None
        pet_ids = set()
        found_trigger = False
        while time.time() - t0 < timeout:
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                break
            self._wait_if_paused(stop_event)
            cursor, lines = self._fetch_kernel(cursor)
            for ln in lines:
                line_str = str(ln)
                if "/resource/pet/swf/" in line_str or "/resource/pet/sound/" in line_str:
                    found_trigger = True
                if found_trigger:
                    for match in finditer_kernel_line(RE_FIGHT_PET_ID, line_str):
                        try:
                            pet_id = int(match.group(1))
                        except Exception:
                            continue
                        if pet_id not in pet_ids:
                            pet_ids.add(pet_id)
                            self._emit(f"[fight-pets] collected pet id {pet_id}", "DEBUG")
                            if first_seen_at is None:
                                first_seen_at = time.time()
                    if "fightResource/skill" in line_str or "/resource/fightResource/skill/" in line_str:
                        if pet_ids:
                            self._emit(f"[fight-pets] skill signal reached; ids={sorted(pet_ids)}", "INFO")
                            return pet_ids
            if first_seen_at is not None and (time.time() - first_seen_at) >= collect_window:
                break
            time.sleep(0.05)
        if pet_ids:
            self._emit(f"[fight-pets] collected ids={sorted(pet_ids)}", "INFO")
        else:
            self._emit("[fight-pets] no pet ids collected", "WARN")
        return pet_ids

    def _dismiss_1and1_until_disappear(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
        *,
        timeout_s: float = 20.0,
        log_tag: str = "1AND1",
        require_seen: bool = False,
        require_click: bool = False,
    ) -> bool:
        # 持续点击1AND1确认，直到探针消失。
        keys_1and1 = ("对话框.普通确认", "刷新.普通确认")
        t0 = time.time()
        saw_probes = False
        click_count = 0
        consecutive_gone = 0
        need_gone = 3
        try:
            if not self._check_1and1_probes() and not require_seen:
                self._emit(f"[{log_tag}] 未检测到1AND1，跳过清理", "DEBUG")
                return True
        except Exception:
            pass
        self._emit(f"[{log_tag}] 清理1AND1，超时={timeout_s:.0f}s", "INFO")
        while (time.time() - t0) < timeout_s:
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return False
            try:
                has_probes = self._check_1and1_probes()
            except Exception:
                has_probes = True
            if has_probes:
                saw_probes = True
                consecutive_gone = 0
                for key in keys_1and1:
                    try:
                        self._click_region(key, use_foreground)
                        click_count += 1
                        break
                    except KeyError:
                        continue
            elif saw_probes:
                consecutive_gone += 1
                if consecutive_gone >= need_gone:
                    if require_click and click_count <= 0:
                        self._emit(f"[{log_tag}] 检测到1AND1，但确认点击未成功", "ERROR")
                        return False
                    self._emit(f"[{log_tag}] 1AND1已清理", "SUCCESS")
                    return True
            self._sleep_abortable(stop_event, 0.08, tick=0.05)
        if saw_probes:
            self._emit(f"[{log_tag}] {timeout_s:.0f}s内1AND1未完全消失", "WARN")
            return False
        if require_seen:
            self._emit(f"[{log_tag}] {timeout_s:.0f}s内未检测到必需的1AND1", "WARN")
            return False
        return True

    @staticmethod
    def _dialog_confirm_region_is_white_rgb(rgb: Optional[Tuple[int, int, int]]) -> bool:
        if rgb is None:
            return False
        r, g, b = (int(rgb[0]), int(rgb[1]), int(rgb[2]))
        return r >= 240 and g >= 240 and b >= 240

    @staticmethod
    def _dialog_probe_blueish_rgb(rgb: Optional[Tuple[int, int, int]]) -> bool:
        if rgb is None:
            return False
        r, g, b = (int(rgb[0]), int(rgb[1]), int(rgb[2]))
        if r >= 240 and g >= 240 and b >= 240:
            return False
        return b >= 150 and g >= 80 and r <= 170 and (b - g) >= 30 and (g - r) >= 20

    def _check_release_base_1and1_probes(self) -> bool:
        if self._check_1and1_probes():
            return True
        white_rgb = self._mean_rgb_for_region_key(getattr(self, "KEY_PROBE_WHITE", "对话框.通用探针"))
        blue_rgb = self._mean_rgb_for_region_key(getattr(self, "KEY_PROBE_BLUE", "对话框.普通确认探针"))
        return self._dialog_confirm_region_is_white_rgb(white_rgb) and self._dialog_probe_blueish_rgb(blue_rgb)

    def _check_normal_1and1and1_probes(self) -> bool:
        # Check normal 1and1and1 probes.
        if not self._check_release_base_1and1_probes():
            return False
        rgb = self._mean_rgb_for_region_key("对话框.左边确认")
        return self._dialog_confirm_region_is_white_rgb(rgb)

    def _check_left_1and1and1_probes(self) -> bool:
        # Check left 1and1and1 probes.
        if not self._check_release_base_1and1_probes():
            return False
        rgb = self._mean_rgb_for_region_key("对话框.普通确认")
        return self._dialog_confirm_region_is_white_rgb(rgb)

    def _format_release_111_probe_state(self) -> str:
        def _fmt_rgb(rgb: Optional[Tuple[int, int, int]]) -> str:
            if rgb is None:
                return "None"
            return f"({int(rgb[0])},{int(rgb[1])},{int(rgb[2])})"

        def _safe_rgb(region_key: str) -> Optional[Tuple[int, int, int]]:
            try:
                return self._mean_rgb_for_region_key(region_key)
            except Exception:
                return None

        probe_white = _safe_rgb(getattr(self, "KEY_PROBE_WHITE", "对话框.通用探针"))
        probe_blue = _safe_rgb(getattr(self, "KEY_PROBE_BLUE", "对话框.普通确认探针"))
        normal_confirm = _safe_rgb("对话框.普通确认")
        left_confirm = _safe_rgb("对话框.左边确认")
        try:
            base_11 = bool(self._check_1and1_probes())
        except Exception as exc:
            base_11 = f"err:{exc}"
        normal_white = self._dialog_confirm_region_is_white_rgb(normal_confirm)
        left_white = self._dialog_confirm_region_is_white_rgb(left_confirm)
        return (
            f"base11={base_11}, "
            f"通用探针={_fmt_rgb(probe_white)}, 普通确认探针={_fmt_rgb(probe_blue)}, "
            f"普通确认={_fmt_rgb(normal_confirm)}/white={normal_white}, "
            f"左边确认={_fmt_rgb(left_confirm)}/white={left_white}"
        )

    def _dismiss_specific_111_until_disappear(
        self,
        *,
        checker,
        confirm_key: str,
        use_foreground: bool,
        stop_event: threading.Event,
        timeout_s: float = 20.0,
        log_tag: str,
        poll_s: float = 0.05,
        need_gone: int = 1,
        click_while_waiting: bool = False,
    ) -> bool:
        # Wait for a 1and1and1 probe, click confirm, and wait until it disappears.
        self._emit(f"[{log_tag}] 等待并关闭，超时={timeout_s:.0f}s", "INFO")
        t0 = time.time()
        saw = False
        consecutive_gone = 0
        last_probe_log = 0.0
        while (time.time() - t0) < timeout_s:
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                stop_event.set()
                if self.bot is not None:
                    self.bot.stop_current = True
                self._emit(f"[{log_tag}] 已请求停止，中止放生流程", "WARN")
                return False
            try:
                has_111 = bool(checker())
            except Exception as exc:
                self._emit(f"[{log_tag}] 探针检查失败：{exc}", "DEBUG")
                has_111 = False

            now = time.time()
            if now - last_probe_log >= 1.0:
                last_probe_log = now
                self._emit(
                    f"🔎 [{log_tag}] has111={has_111}, {self._format_release_111_probe_state()}",
                    "DEBUG",
                )

            if has_111:
                saw = True
                consecutive_gone = 0
                try:
                    self._click_region(confirm_key, use_foreground)
                except KeyError:
                    self._emit(f"[{log_tag}] 缺少确认区域：{confirm_key}", "ERROR")
                    return False
                self._sleep_abortable(stop_event, 0.05, tick=0.025)
            elif saw:
                consecutive_gone += 1
                if consecutive_gone >= need_gone:
                    self._emit(f"[{log_tag}] dismissed", "SUCCESS")
                    return True
            elif click_while_waiting:
                try:
                    self._click_region(confirm_key, use_foreground)
                except KeyError:
                    self._emit(f"[{log_tag}] 缺少确认区域：{confirm_key}", "ERROR")
                    return False
            self._sleep_abortable(stop_event, poll_s, tick=min(0.025, poll_s))

        if saw:
            self._emit(
                f"[{log_tag}] did not fully disappear within {timeout_s:.0f}s; {self._format_release_111_probe_state()}",
                "WARN",
            )
        else:
            self._emit(
                f"[{log_tag}] did not appear within {timeout_s:.0f}s; {self._format_release_111_probe_state()}",
                "WARN",
            )
        return False

    def _wait_release_111_until_disappear(
        self,
        checker,
        confirm_key: str,
        use_foreground: bool,
        stop_event: threading.Event,
        *,
        timeout_s: float = 20.0,
        log_tag: str,
        poll_s: float = 0.05,
        need_gone: int = 1,
        click_while_waiting: bool = False,
    ) -> bool:
        return self._dismiss_specific_111_until_disappear(
            checker=checker,
            confirm_key=confirm_key,
            use_foreground=use_foreground,
            stop_event=stop_event,
            timeout_s=timeout_s,
            log_tag=log_tag,
            poll_s=poll_s,
            need_gone=need_gone,
            click_while_waiting=click_while_waiting,
        )

    def run_release_cycles(
        self,
        repeat: int,
        use_foreground: bool,
        stop_event: threading.Event,
    ) -> bool:
        # Run pet release cycles and clear left/normal dialogs.
        total = max(1, int(repeat or 1))
        requested_left_flips = math.ceil(total / 9) + 5
        left_flips = min(requested_left_flips, WAREHOUSE_PAGE_TURN_MAX_COUNT)
        if requested_left_flips > WAREHOUSE_PAGE_TURN_MAX_COUNT:
            self._emit(
                f"[放生] 初始左翻请求 {requested_left_flips} 次，"
                f"按仓库翻页上限截断为 {WAREHOUSE_PAGE_TURN_MAX_COUNT} 次",
                "WARN",
            )
        self._emit(f"[放生] 启动：轮数={total}，初始左翻页={left_flips}", "SYSTEM")

        def _release_stopped(stage: str) -> bool:
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                stop_event.set()
                if self.bot is not None:
                    self.bot.stop_current = True
                self._emit(f"[放生] 在 {stage} 阶段停止", "WARN")
                return True
            return False

        for flip_idx in range(1, left_flips + 1):
            if _release_stopped(f"left flip {flip_idx}/{left_flips}"):
                return False
            try:
                self._click_region("精灵仓库.左", use_foreground)
            except KeyError:
                self._emit("[放生] 缺少区域：精灵仓库.左", "ERROR")
                return False
            self._sleep_abortable(stop_event, 0.08, tick=0.03)

        for idx in range(1, total + 1):
            if _release_stopped(f"cycle {idx}/{total}"):
                return False
            self._emit(f"[放生] 第 {idx}/{total} 轮：点击放生", "INFO")
            try:
                self._click_region("精灵仓库.放生", use_foreground)
            except KeyError:
                self._emit("[放生] 缺少区域：精灵仓库.放生", "ERROR")
                return False
            self._sleep_abortable(stop_event, 0.04, tick=0.02)
            if not self._wait_release_111_until_disappear(
                self._check_left_1and1and1_probes,
                "对话框.左边确认",
                use_foreground,
                stop_event,
                timeout_s=20.0,
                log_tag="release-left-111",
                poll_s=0.04,
                click_while_waiting=False,
            ):
                return False
            if not self._wait_release_111_until_disappear(
                self._check_normal_1and1and1_probes,
                "对话框.普通确认",
                use_foreground,
                stop_event,
                timeout_s=20.0,
                log_tag="release-normal-111",
                poll_s=0.04,
                click_while_waiting=False,
            ):
                return False
        self._emit(f"[放生] 完成轮数={total}", "SUCCESS")
        return True
    def _clear_dialogs_by_probes(
        self,
        use_foreground: bool,
        max_clicks: int = 20,
        stop_event: Optional[threading.Event] = None,
    ) -> None:
        _ = max_clicks  # 鍏煎鏃у弬鏁帮紱实际浠ユ帰閽堟秷澶变负鍑?
        se = stop_event or threading.Event()
        self._dismiss_1and1_until_disappear(
            use_foreground,
            se,
            timeout_s=20.0,
            log_tag="战后清理",
        )

    def _probe_match(self, reg: Region, target_rgb: Tuple[int, int, int], tol: int, min_ratio: float) -> bool:
        gx1, gy1, gx2, gy2 = reg.outer_bbox()
        img = window_manager.grab_game_bbox(gx1, gy1, gx2, gy2)
        pixels = list(img.getdata())
        if not pixels:
            return False

        tr, tg, tb = target_rgb
        ok = 0
        for r, g, b in pixels:
            if abs(r - tr) <= tol and abs(g - tg) <= tol and abs(b - tb) <= tol:
                ok += 1
        return (ok / len(pixels)) >= min_ratio

    def _check_1and1_probes(self) -> bool:
        # Check whether the 1AND1 white/blue probes are visible.
        try:
            reg_white = self.regions.require(self.KEY_PROBE_WHITE)

            w_ok = self._probe_match(reg_white, (255, 255, 255), tol=18, min_ratio=0.6)
            b_ok = self._dialog_probe_blueish_rgb(
                self._mean_rgb_for_region_key(self.KEY_PROBE_BLUE)
            )

            return w_ok and b_ok
        except Exception:
            return False

    def _get_beijing_time(self) -> datetime:
        # Return current Beijing time with timezone information.
        try:
            import pytz
            beijing_tz = pytz.timezone('Asia/Shanghai')
            return datetime.now(beijing_tz)
        except ImportError:
            # 濡傛灉娌℃湁pytz，使用UTC+8手动计算北京时间
            utc_now = datetime.now(timezone.utc)
            beijing_offset = timedelta(hours=8)
            # 创建固定偏移量的timezone
            beijing_tz = timezone(beijing_offset)
            return utc_now.astimezone(beijing_tz)

    def set_non_mantis_capsule_tier(self, tier: str) -> None:
        """Set non-mantis capsule strategy."""
        t = str(tier or "").lower().strip()
        if t in ("cycle", "default", "super_super_special"):
            self._non_mantis_capsule_tier = "cycle"
        elif t in ("super", "high", "special"):
            self._non_mantis_capsule_tier = t
        else:
            self._non_mantis_capsule_tier = "high"

    def set_non_mantis_use_super_capsule(self, value: bool) -> None:
        """Compatibility setter for non-mantis capsule tier."""
        self._non_mantis_capsule_tier = "super" if bool(value) else "high"

    def set_pick_pet_mode(self, value: bool) -> None:
        """Compatibility setter; pick mode is always enabled."""
        _ = value
        self._pick_pet_mode = True

    def set_enable_molecule_converter(self, value: bool) -> None:
        """Enable or disable molecule converter in reconnect flows."""
        self._enable_molecule_converter = bool(value)

    def set_resist_drain_logic(self, value: bool) -> None:
        """Enable or disable the resist-drain battle rhythm."""
        self._resist_drain_logic = bool(value)

    def configure_resource_yellow_rotation_handoff(
        self,
        enabled: bool,
        completion_action: str = "进入普通轮换重连模式",
    ) -> None:
        """Configure one resource-mode run to hand off after 60 yellow victories."""
        self._resource_yellow_rotation_handoff_enabled = bool(enabled)
        self._resource_yellow_rotation_handoff_count = 0
        self._resource_yellow_rotation_handoff_requested = False
        self._resource_yellow_completion_action = (
            str(completion_action).strip() or "进入普通轮换重连模式"
        )

    def consume_resource_yellow_rotation_handoff(self) -> bool:
        requested = bool(getattr(self, "_resource_yellow_rotation_handoff_requested", False))
        self._resource_yellow_rotation_handoff_requested = False
        return requested

    def _note_resource_yellow_victory(self) -> bool:
        if not bool(getattr(self, "_resource_yellow_rotation_handoff_enabled", False)):
            return False
        self._resource_yellow_rotation_handoff_count += 1
        count = int(self._resource_yellow_rotation_handoff_count)
        self._emit(f"🟨 [资源黄胜] 累计 {count}/60", "SUCCESS")
        if count < 60:
            return False
        self._resource_yellow_rotation_handoff_requested = True
        action = str(
            getattr(
                self,
                "_resource_yellow_completion_action",
                "进入普通轮换重连模式",
            )
        )
        self._emit(
            f"🔁 [资源黄胜] 已达 60 次，退出当前资源循环并{action}",
            "SYSTEM",
        )
        return True

    def _rotation_step1_force_molecule_converter(self) -> bool:
        """Return whether rotation step1 should force molecule converter."""
        if not getattr(self, "_enable_molecule_converter", False):
            return False
        return bool(getattr(self, "_unified_reconnect_pipeline_always", False))

    def _pickmode_skill1_cap(self) -> int:
        return 15

    def _capsule_cycle_tiers_for_current_battle(self) -> Optional[Tuple[str, ...]]:
        """Return the capsule cycle tiers for the current battle."""
        t = getattr(self, "_non_mantis_capsule_tier", "high")
        if t in ("super", "high", "special"):
            return (t,)
        return DEFAULT_CAPSULE_CYCLE_TIERS

    def _highest_capsule_tier_tuple(self, tiers: Optional[Tuple[str, ...]]) -> Optional[Tuple[str, ...]]:
        """Return the highest configured capsule tier as a single-tier override."""
        if not tiers:
            return tiers
        rank = {"high": 1, "super": 2, "special": 3}
        valid = [str(t).lower().strip() for t in tiers if str(t).lower().strip() in rank]
        if not valid:
            return tiers
        return (max(valid, key=lambda t: rank[t]),)

    def _capsule_cycle_log_fields(self) -> Tuple[str, str]:
        """Return capsule cycle fields for CSV logging."""
        ubf = getattr(self, "_unified_framework", None)
        tiers = None
        try:
            tiers = getattr(ubf, "_capsule_cycle_tiers_override", None) if ubf else None
        except Exception:
            tiers = None

        if not tiers:
            try:
                tiers = getattr(ubf, "_CAPSULE_CYCLE_TIERS", None) if ubf else None
            except Exception:
                tiers = None
        if not tiers:
            return ("default", "")

        try:
            t = tuple(tiers)
        except Exception:
            return ("custom", "")

        if t == LEGACY_CAPSULE_CYCLE_TIERS:
            return ("mantis_legacy", ",".join(t))
        if t == DEFAULT_CAPSULE_CYCLE_TIERS:
            return ("default_super_special", ",".join(t))
        if t == ("special",):
            return ("special_only", "special")
        if t == ("super",):
            return ("super_only", "super")
        if t == ("high",):
            return ("high_only", "high")
        return ("custom", ",".join(str(x) for x in t))

    def _normalize_rotation_schedule_mode(self, schedule_mode: str) -> str:
        """Normalize schedule mode names for execution."""
        if schedule_mode == "resource:pure_energy":
            return "pure_energy"
        if schedule_mode == "resource:nieo_resource":
            return "nieo_resource"
        return schedule_mode

    def _rotation_follow_cyan_for_mode(self, schedule_mode: str) -> bool:
        """Apply the rotation follow-color option to every Nieo-family segment."""
        if not bool(getattr(self, "_rotation_nieo_follow_cyan", False)):
            return False
        raw_mode = str(schedule_mode or "").strip()
        normalized = self._normalize_rotation_schedule_mode(raw_mode)
        return normalized in ("nieo", "nieo_resource", "pure_energy") or (
            raw_mode.startswith("resource:")
            and not raw_mode.startswith("resource:rare:")
        )

    def _rotation_defer_cyan_until_a_for_mode(self, schedule_mode: str) -> bool:
        """Return whether initial Pick must stay purple until the first A map."""
        raw_mode = str(schedule_mode or "").strip()
        normalized = self._normalize_rotation_schedule_mode(raw_mode)
        return normalized == "nieo" or raw_mode == "resource:水生海草"

    def _rotation_initial_follow_cyan_for_mode(self, schedule_mode: str) -> bool:
        """Resolve the companion color used before the mode reaches its A map."""
        return bool(
            self._rotation_follow_cyan_for_mode(schedule_mode)
            and not self._rotation_defer_cyan_until_a_for_mode(schedule_mode)
        )

    @staticmethod
    def _pre_nieo_should_defer_cyan_until_a(
        *,
        pem_route: bool,
        to_script: Optional[str],
    ) -> bool:
        """Keep standard Nieo and water-grass pre-entry reconnects on purple."""
        if pem_route:
            return False
        script_name = str(to_script or "to尼奥").strip()
        if script_name.endswith(".json"):
            script_name = script_name[:-5]
        return script_name in ("to尼奥", "to水生海草1")

    def _rotation_pick_mode_for(self, schedule_mode: str) -> str:
        from core.rotation_schedule import rotation_pick_compat_mode

        return rotation_pick_compat_mode(schedule_mode)

    def _rotation_running_bucket(self) -> Optional[str]:
        """Return the current rotation schedule bucket."""
        am = getattr(self, "_rotation_active_segment_mode", None)
        if am:
            if am == "pure_energy":
                return "resource:pure_energy"
            return am
        m = getattr(self, "_current_mode", None)
        if m == "nieo":
            return "nieo"
        if m == "pure_energy":
            return "resource:pure_energy"
        if m and str(m).startswith("nieo:"):
            return f"resource:{str(m).split(':', 1)[1]}"
        if m and str(m).startswith("rare:"):
            return str(m)
        if m and str(m).startswith("event_pet_"):
            return "eit"
        if m == "mantis":
            return "mantis"
        if m in ("shuangta", "dugulu", "flash_pipi", "eyeball", "xiaodouya"):
            return "rare"
        return None

    def _run_pending_rotation_hourly_full_chain_scan(self) -> bool:
        """Run a queued full-chain scan only after the active child mode exits."""
        request = getattr(
            self, "_pending_rotation_full_chain_maintenance", None
        )
        if not isinstance(request, dict):
            return False

        retry_limit = 20
        retry_gap_s = 180.0
        if self._hourly_daily_maintenance_retry_count >= retry_limit:
            self._emit(
                f"⚠️ [整点全链路检测-轮换外层] 已达到 {retry_limit} 次重试上限；"
                "结束本小时待办，下一轮从外层重新进入当前目标模式",
                "WARN",
            )
            self._pending_rotation_full_chain_maintenance = None
            return True
        if time.monotonic() < self._hourly_daily_maintenance_retry_not_before:
            return False

        hour_key = str(request.get("hour_key") or "")
        runner = getattr(self.bot, "run_rotation_startup_daily_precheck", None)
        if not callable(runner):
            self._emit(
                "❌ [整点全链路检测-轮换外层] BotThread 缺少完整日常检测入口；"
                "保留待办，禁止恢复旧子模式",
                "ERROR",
            )
            self._hourly_daily_maintenance_retry_count += 1
            self._hourly_daily_maintenance_retry_not_before = (
                time.monotonic() + retry_gap_s
            )
            return False

        self._emit(
            f"🕐 [整点全链路检测-轮换外层] 旧子模式已退出，开始执行 {hour_key} 完整日常链",
            "SYSTEM",
        )
        try:
            ok = bool(
                runner(
                    use_foreground=bool(
                        getattr(self, "_active_use_foreground", False)
                    ),
                    runtime_switch=True,
                )
            )
        except Exception as exc:
            self._emit(
                f"❌ [整点全链路检测-轮换外层] 执行异常：{exc}",
                "ERROR",
            )
            ok = False
            failed_labels = ["检测链异常"]
        else:
            failed_labels = list(
                getattr(
                    self.bot,
                    "_rotation_full_chain_scan_failed_labels",
                    [],
                )
                or []
            )

        self.invalidate_rotation_swf_sync_state("整点完整日常链")
        task_stop_event = getattr(self.bot, "_stop_event", None)
        restart_reason = None
        if isinstance(task_stop_event, threading.Event):
            restart_reason = self.consume_mode_restart_request(task_stop_event)
        if restart_reason is not None:
            ok = False
            failed_labels.append(f"请求重启：{restart_reason}")
            self._emit(
                f"↩️ [整点全链路检测-轮换外层] 已接收重启请求：{restart_reason}；"
                "停止信号已清理，保留待办并由轮换外层重试",
                "SYSTEM",
            )

        if (not ok) or failed_labels:
            self._hourly_daily_maintenance_retry_count += 1
            self._hourly_daily_maintenance_retry_not_before = (
                time.monotonic() + retry_gap_s
            )
            reason = "、".join(str(x) for x in failed_labels) or "检测链异常"
            self._emit(
                f"⚠️ [整点全链路检测-轮换外层] 未完成：{reason}；"
                f"{int(retry_gap_s // 60)} 分钟后仍由外层重试（第 "
                f"{self._hourly_daily_maintenance_retry_count}/{retry_limit} 次），"
                "不会恢复旧子模式",
                "WARN",
            )
            return False

        handled = bool(
            getattr(self.bot, "_rotation_full_chain_scan_handled", False)
        )
        self._pending_rotation_full_chain_maintenance = None
        self._rotation_time_check_window_active = False
        self._last_rotation_time_check = 0.0
        if handled:
            self._emit(
                "✅ [整点全链路检测-轮换外层] 待办动作已完成；"
                "下一轮重新判断并进入当前目标模式",
                "SUCCESS",
            )
        else:
            self._emit(
                "✅ [整点全链路检测-轮换外层] 无待办动作；"
                "下一轮从外层进入当前目标模式",
                "INFO",
            )
        return True

    def _maybe_run_rotation_hourly_full_chain_scan(
        self,
        *,
        defer_to_outer: bool = False,
    ) -> bool:
        """Queue in a child mode, or scan the full daily chain at the boundary."""
        if not bool(getattr(self, "_is_rotation_mode", False)) or not bool(
            getattr(self, "_rotation_full_daily_maintenance", False)
        ):
            return False

        pending = getattr(
            self, "_pending_rotation_full_chain_maintenance", None
        )
        if isinstance(pending, dict):
            if defer_to_outer:
                return True
            self._run_pending_rotation_hourly_full_chain_scan()
            return True

        now = self._get_beijing_time()
        hour = int(now.hour)
        if not (7 <= hour <= 19 or 1 <= hour <= 5):
            return False
        hour_key = now.strftime("%Y-%m-%d-%H")
        retry_limit = 20
        retry_gap_s = 180.0
        if self._hourly_daily_maintenance_key != hour_key:
            self._hourly_daily_maintenance_key = hour_key
            self._hourly_daily_maintenance_retry_count = 0
            self._hourly_daily_maintenance_retry_not_before = 0.0
        elif self._hourly_daily_maintenance_retry_count >= retry_limit:
            return False
        elif time.monotonic() < self._hourly_daily_maintenance_retry_not_before:
            return False

        self._emit(
            f"🕐 [整点全链路检测] {hour_key}：检测依卢、岚岚、光螳螂、孵化到一键日常完整链",
            "SYSTEM",
        )
        self._pending_rotation_full_chain_maintenance = {
            "hour_key": hour_key,
        }
        if defer_to_outer:
            self._emit(
                "↩️ [整点全链路检测] 已排队完整日常链；"
                "当前子模式先完整退出，再由轮换外层执行",
                "SYSTEM",
            )
            return True

        self._run_pending_rotation_hourly_full_chain_scan()
        return True

    def _run_pending_rotation_yilu_lanlan_maintenance(self) -> bool:
        """Run one queued Yilu/Lanlan maintenance request at the rotation boundary."""
        request = getattr(
            self, "_pending_rotation_yilu_lanlan_maintenance", None
        )
        if not isinstance(request, dict):
            return False

        if self._expire_pending_rotation_yilu_if_needed(request):
            request = getattr(
                self, "_pending_rotation_yilu_lanlan_maintenance", None
            )
            if not isinstance(request, dict):
                return True

        hour_key = str(request.get("hour_key") or "")
        run_yilu = bool(request.get("run_yilu"))
        run_lanlan = bool(request.get("run_lanlan"))
        run_weekend_release = bool(request.get("run_weekend_release"))
        task_label = str(request.get("task_label") or "依卢/岚岚")
        runner = getattr(self.bot, "run_hourly_yilu_lanlan_maintenance", None)
        if not callable(runner):
            self._emit(
                "❌ [整点补跑-轮换外层] BotThread 缺少执行器；保留待办，禁止恢复旧子模式",
                "ERROR",
            )
            return False

        self._emit(
            f"🔄 [整点补跑-轮换外层] 旧子模式已退出，开始独立执行：{task_label}",
            "SYSTEM",
        )
        try:
            ok = bool(
                runner(
                    use_foreground=bool(
                        getattr(self, "_active_use_foreground", False)
                    ),
                    run_yilu=run_yilu,
                    run_lanlan=run_lanlan,
                    run_weekend_release=run_weekend_release,
                    yilu_deadline=(
                        self._rotation_yilu_deadline(hour_key)
                        if run_yilu
                        else None
                    ),
                )
            )
        except Exception as exc:
            self._emit(
                f"❌ [整点补跑-轮换外层] 执行异常：{exc}；保留待办并由外层重连重试",
                "ERROR",
            )
            ok = False

        self.invalidate_rotation_swf_sync_state(
            f"整点补跑-{task_label}"
        )
        task_stop_event = getattr(self.bot, "_stop_event", None)
        restart_reason = None
        if isinstance(task_stop_event, threading.Event):
            restart_reason = self.consume_mode_restart_request(task_stop_event)
        if restart_reason is not None:
            ok = False
            self._emit(
                f"↩️ [整点补跑-轮换外层] 已接收重启请求：{restart_reason}；"
                "停止信号已清理，保留待办并由轮换外层重试",
                "SYSTEM",
            )

        if not ok:
            expired = self._expire_pending_rotation_yilu_if_needed(request)
            if expired and not isinstance(
                getattr(self, "_pending_rotation_yilu_lanlan_maintenance", None),
                dict,
            ):
                return True
            self._emit(
                "⚠️ [整点补跑-轮换外层] 本次未完成；"
                f"{'依卢窗口已结束，仅保留仍有效环节' if expired else '保留待办并由外层重连重试，不会返回旧子模式'}",
                "WARN",
            )
            return False

        self._rotation_yilu_lanlan_maintenance_key = hour_key or None
        self._pending_rotation_yilu_lanlan_maintenance = None
        self._rotation_time_check_window_active = False
        self._last_rotation_time_check = 0.0
        self._emit(
            f"✅ [整点补跑-轮换外层] 已完成{task_label}；下一轮重新判断并进入当前目标模式",
            "SUCCESS",
        )
        return True

    def _rotation_yilu_deadline(
        self,
        hour_key: str,
        *,
        now: Optional[datetime] = None,
    ) -> datetime:
        """Return the absolute Beijing-time :10 deadline for one queued hour."""
        current = now or self._get_beijing_time()
        try:
            hour_start = datetime.strptime(
                str(hour_key), "%Y-%m-%d-%H"
            ).replace(tzinfo=current.tzinfo)
        except (TypeError, ValueError):
            hour_start = current.replace(minute=0, second=0, microsecond=0)
        return hour_start + timedelta(minutes=10)

    def _expire_pending_rotation_yilu_if_needed(self, request: dict) -> bool:
        """Drop stale Yilu work at :10 while preserving a paired Lanlan request."""
        if not bool(request.get("run_yilu")):
            return False
        hour_key = str(request.get("hour_key") or "")
        now = self._get_beijing_time()
        deadline = self._rotation_yilu_deadline(hour_key, now=now)
        if now < deadline and now.strftime("%Y-%m-%d-%H") == hour_key:
            return False

        request["run_yilu"] = False
        if bool(request.get("run_lanlan")):
            request["task_label"] = "岚岚"
            self._emit(
                f"⏭️ [整点补跑-轮换外层] 依卢窗口已于 {deadline.strftime('%H:%M:%S')} 结束；"
                "取消依卢且不写完成记录，继续仍有效的岚岚待办",
                "WARN",
            )
            return True

        self._pending_rotation_yilu_lanlan_maintenance = None
        self._rotation_yilu_lanlan_maintenance_key = hour_key or None
        self._rotation_time_check_window_active = False
        self._last_rotation_time_check = 0.0
        self._emit(
            f"⏭️ [整点补跑-轮换外层] 依卢窗口已于 {deadline.strftime('%H:%M:%S')} 结束；"
            "清除过期待办、不写完成记录并恢复轮换，禁止继续重连依卢",
            "WARN",
        )
        return True

    def _maybe_run_hourly_yilu_lanlan_maintenance(
        self,
        *,
        defer_to_outer: bool = False,
    ) -> bool:
        """Queue in a child mode, or execute at the outer rotation boundary."""
        if not bool(getattr(self, "_is_rotation_mode", False)) or bool(
            getattr(self, "_rotation_full_daily_maintenance", False)
        ):
            return False

        pending = getattr(
            self, "_pending_rotation_yilu_lanlan_maintenance", None
        )
        if isinstance(pending, dict):
            if defer_to_outer:
                return True
            self._run_pending_rotation_yilu_lanlan_maintenance()
            return True

        now = self._get_beijing_time()
        hour_key = now.strftime("%Y-%m-%d-%H")
        if self._rotation_yilu_lanlan_maintenance_key == hour_key:
            return False

        daily_runner = getattr(self.bot, "daily_runner", None)
        if daily_runner is None:
            self._rotation_yilu_lanlan_maintenance_key = hour_key
            self._emit("⚠️ [整点补跑] 缺少 daily_runner，跳过本小时检查", "WARN")
            return False
        has_yilu = getattr(daily_runner, "has_yilu_daily_record_today", None)
        has_lanlan = getattr(daily_runner, "has_lanlan_daily_record_today", None)
        if not callable(has_yilu) or not callable(has_lanlan):
            self._rotation_yilu_lanlan_maintenance_key = hour_key
            self._emit("⚠️ [整点补跑] 缺少依卢/岚岚当日记录接口，跳过本小时检查", "WARN")
            return False

        try:
            yilu_done = bool(has_yilu(now))
            lanlan_done = bool(has_lanlan(now))
            lanlan_target = self.bot._lanlan_cyan_pet_for_current_time(now)
            has_weekend_release = getattr(
                daily_runner, "has_one_click_release_weekly_record", None
            )
            run_weekend_release = bool(
                int(now.weekday()) in (5, 6)
                and callable(has_weekend_release)
                and not bool(has_weekend_release(now))
            )
        except Exception as e:
            self._rotation_yilu_lanlan_maintenance_key = hour_key
            self._emit(f"⚠️ [整点补跑] 查询当日状态失败，跳过：{e}", "WARN")
            return False

        yilu_window_open = 0 <= int(now.minute) < 10
        run_yilu = (not yilu_done) and yilu_window_open
        run_lanlan = (not lanlan_done) and lanlan_target is not None
        if not run_yilu and not run_lanlan and not run_weekend_release:
            self._rotation_yilu_lanlan_maintenance_key = hour_key
            self._emit(
                f"⏰ [整点补跑] {hour_key} 无需补跑：依卢={'已执行' if yilu_done else '等待下个整点前10分钟'}，"
                f"岚岚={'已执行' if lanlan_done else '不在预定时间'}，"
                f"周末放生={'本周已执行' if int(now.weekday()) in (5, 6) else '非周末跳过'}",
                "INFO",
            )
            return False

        task_label = "+".join(
            label
            for enabled, label in (
                (run_yilu, "依卢"),
                (run_lanlan, "岚岚"),
                (run_weekend_release, "周末放生"),
            )
            if enabled
        )
        self._emit(
            f"⏰ [整点补跑] {hour_key} 状态：依卢={'已执行' if yilu_done else ('待执行' if yilu_window_open else '等待下个整点前10分钟')}，"
            f"岚岚={'已执行' if lanlan_done else ('待执行' if lanlan_target is not None else '不在预定时间')}；"
            f"本次={task_label}",
            "SYSTEM",
        )
        request = {
            "hour_key": hour_key,
            "run_yilu": run_yilu,
            "run_lanlan": run_lanlan,
            "task_label": task_label,
        }
        if run_weekend_release:
            request["run_weekend_release"] = True
        self._pending_rotation_yilu_lanlan_maintenance = request
        if defer_to_outer:
            self._emit(
                f"↩️ [整点补跑] 已排队{task_label}；当前子模式先完整退出，"
                "再由轮换外层重连执行",
                "SYSTEM",
            )
            return True

        self._run_pending_rotation_yilu_lanlan_maintenance()
        return True

    def _maybe_run_rotation_fusion_hatch_maintenance(self) -> bool:
        """Run due fusion/hatch maintenance during every rotation time check."""
        if not bool(getattr(self, "_is_rotation_mode", False)):
            return False
        if not bool(
            getattr(self.bot, "_rotation_nono_fusion_enabled", False)
        ):
            return False
        runner = getattr(self.bot, "run_rotation_time_due_maintenance", None)
        if not callable(runner):
            return False
        try:
            handled = bool(runner(use_foreground=bool(getattr(self, "_active_use_foreground", False))))
        except Exception as e:
            self.invalidate_rotation_swf_sync_state("轮换融合维护异常")
            self._emit(f"❌ [轮换时间检查] 融合/孵化维护异常，继续轮换：{e}", "ERROR")
            return False
        self.invalidate_rotation_swf_sync_state("轮换融合维护")
        if not handled:
            return False
        target_mode, next_switch = self._detect_rotation_mode(quiet=True)
        self._target_mode_after_switch = target_mode
        self._pending_rotation_switch = True
        self._next_rotation_switch_time = next_switch
        self._rotation_time_check_window_active = False
        self._last_rotation_time_check = 0.0
        self._emit(
            f"🔁 [轮换时间检查] 融合/孵化维护已执行，准备重接入 {target_mode}",
            "SYSTEM",
        )
        return True

    def _check_rotation_switch_time(self) -> bool:
        if self._maybe_run_rotation_hourly_full_chain_scan(
            defer_to_outer=True
        ):
            return True
        if self._maybe_run_hourly_yilu_lanlan_maintenance(
            defer_to_outer=True
        ):
            return True
        if self._maybe_run_rotation_fusion_hatch_maintenance():
            return True
        # Check whether rotation switch time has been reached.
        if not self._is_rotation_mode:
            self._emit("[轮换检查] 当前不在轮换模式，跳过", "DEBUG")
            return False

        # 鉁?测试模式锛氫娇鐢ㄥ浐瀹氭椂闂撮棿闅旀娴嬶紙浠ｆ浛鏃堕棿鐐规娴嬶級
        is_test_mode = self.ROTATION_TEST_MODE  # 鉁?使用缁熶竴寮€鍏?
        if is_test_mode:
            current_mode_for_interval = self._test_mode_current_mode or "nieo"
            interval_minutes = (
                self.ROTATION_RECONNECT_INTERVAL_MINUTES_NIEO
                if current_mode_for_interval == "nieo"
                else self.ROTATION_RECONNECT_INTERVAL_MINUTES_SHUANGTA
            )
            # 鉁?测试模式：优先使用_next_rotation_switch_time（与鏃ュ織涓殑涓嬫切换鏃堕棿涓€鑷达級
            if self._next_rotation_switch_time:
                current_time = self._get_beijing_time()
                switch_time = self._next_rotation_switch_time
                if switch_time.tzinfo is None:
                    try:
                        import pytz
                        beijing_tz = pytz.timezone('Asia/Shanghai')
                        switch_time = beijing_tz.localize(switch_time)
                    except ImportError:
                        beijing_offset = timedelta(hours=8)
                        beijing_tz = timezone(beijing_offset)
                        switch_time = switch_time.replace(tzinfo=beijing_tz)
                    self._next_rotation_switch_time = switch_time

                if current_time >= switch_time:
                    if self._test_mode_current_mode is None:
                        self._test_mode_current_mode = "nieo"  # 鉁?测试模式：默认从nieo寮€濮?

                    current_mode = self._test_mode_current_mode
                    next_mode = "nieo" if current_mode == "shuangta" else "shuangta"
                    self._test_mode_current_mode = next_mode

                    self._target_mode_after_switch = next_mode
                    self._pending_rotation_switch = True
                    self._emit(
                        f"[轮换测试] 已到计划时间（{current_time.strftime('%Y-%m-%d %H:%M:%S')} >= {switch_time.strftime('%Y-%m-%d %H:%M:%S')}）；{current_mode} -> {next_mode}",
                        "SYSTEM",
                    )
                    self._test_mode_start_time = 0.0
                    self._rotation_time_check_window_active = False
                    self._last_rotation_time_check = 0.0
                    return True

            # 测试模式锛氭鏌ヤ粠模式寮€濮嬪埌鐜板湪鏄惁宸茬粡杩囦簡2.5分钟
            if self._test_mode_start_time == 0.0:
                # 濡傛灉寮€濮嬫椂闂存湭记录锛岃鏄庢ā寮忓垰鍚姩锛岃褰曞紑濮嬫椂闂?
                self._test_mode_start_time = time.time()
                self._emit(f"[轮换测试] 首次检查，将在 {interval_minutes} 分钟后切换", "INFO")
                return False

            elapsed_seconds = time.time() - self._test_mode_start_time
            elapsed_minutes = elapsed_seconds / 60.0

            # 姣?0绉掕緭鍑轰竴娆¤繘搴︽棩蹇楋紙鐢ㄤ簬璋冭瘯锛?
            if int(elapsed_seconds) % 30 == 0 and elapsed_seconds > 0:
                self._emit(f"[轮换测试] 已经过 {elapsed_minutes:.1f} 分钟，目标={interval_minutes}", "DEBUG")

            if elapsed_minutes >= interval_minutes:
                # 鉁?到达鍥哄畾鏃堕棿闂撮殧锛岃Е鍙戝垏鎹?
                # 鑾峰彇褰撳墠模式锛堢敤浜庤绠椾笅涓€涓ā寮忥級
                if self._test_mode_current_mode is None:
                    self._test_mode_current_mode = "nieo"  # 鉁?测试模式：默认从nieo寮€濮?

                current_mode = self._test_mode_current_mode
                # 鉁?鐩存帴璁＄畻涓嬩竴涓ā寮忥紙浜ゆ浛切换锛?
                next_mode = "nieo" if current_mode == "shuangta" else "shuangta"

                # 鉁?鏇存柊褰撳墠模式涓轰笅涓€涓ā寮忥紙杩欐牱涓嬫调用_detect_rotation_mode时会使用新模式）
                self._test_mode_current_mode = next_mode

                self._target_mode_after_switch = next_mode
                self._pending_rotation_switch = True
                self._emit(
                    f"[轮换测试] 已到间隔（{elapsed_minutes:.1f} >= {interval_minutes}）；{current_mode} -> {next_mode}",
                    "SYSTEM",
                )
                # 重置寮€濮嬫椂闂达紙涓嬫模式寮€濮嬫椂閲嶆柊璁℃椂锛?
                self._test_mode_start_time = 0.0
                # 鉁?重置鏃堕棿妫€娴嬬浉鍏崇姸鎬?
                self._rotation_time_check_window_active = False
                self._last_rotation_time_check = 0.0
                return True

            return False

        # 鉁?正常模式锛氫娇鐢ㄦ椂闂寸偣妫€娴嬶紙姘歌繙浠ュ寳浜椂闂村仛鍩哄噯锛?
        current_time = self._get_beijing_time()

        # 鉁?鏃堕棿琛ㄤ笌褰撳墠杩愯模式鏄惁涓€鑷达紙涓嶈兘鍙湅 _next_rotation_switch_time锛屽惁鍒欏崍澶滃悗浠嶈窇尼奥鏃?
        #    鑻?next 琚悓姝ユ垚銆屽綋鏃?20:00銆嶄細涓€鐩寸瓑鍒版櫄涓婃墠鍒囷級
        running_bucket = self._rotation_running_bucket()
        if running_bucket is not None:
            expected_mode, canonical_next = self._detect_rotation_mode(quiet=True)
            if running_bucket != expected_mode:
                self._target_mode_after_switch = expected_mode
                self._pending_rotation_switch = True
                self._next_rotation_switch_time = canonical_next
                self._rotation_time_check_window_active = False
                self._last_rotation_time_check = 0.0
                self._emit(
                    f"[轮换检查] 当前时段 {running_bucket} 与期望 {expected_mode} 不一致；"
                    f"立即切换，下一次={canonical_next.strftime('%Y-%m-%d %H:%M:%S')}",
                    "SYSTEM",
                )
                return True

        if not self._next_rotation_switch_time:
            self._emit("[轮换检查] 正常模式下 _next_rotation_switch_time 为空", "WARN")
            return False

        # 鉁?纭繚_next_rotation_switch_time涔熸槸鍖椾含鏃堕棿锛堝甫鏃跺尯锛?
        # 濡傛灉_next_rotation_switch_time鏄痭aive datetime锛岄渶瑕佽浆鎹负鍖椾含鏃堕棿
        switch_time = self._next_rotation_switch_time
        if switch_time.tzinfo is None:
            # naive datetime锛屽亣璁炬槸鍖椾含鏃堕棿锛屾坊鍔犳椂鍖轰俊鎭?
            try:
                import pytz
                beijing_tz = pytz.timezone('Asia/Shanghai')
                switch_time = beijing_tz.localize(switch_time)
            except ImportError:
                beijing_offset = timedelta(hours=8)
                beijing_tz = timezone(beijing_offset)
                switch_time = switch_time.replace(tzinfo=beijing_tz)
            # 鏇存柊淇濆瓨鐨勫垏鎹㈡椂闂?
            self._next_rotation_switch_time = switch_time

        # 鉁?添加调试日志（每30绉掕緭鍑轰竴娆★紝閬垮厤鏃ュ織杩囧锛?
        now_timestamp = time.time()
        if not hasattr(self, '_last_rotation_check_log_time'):
            self._last_rotation_check_log_time = 0.0
        if now_timestamp - self._last_rotation_check_log_time >= 30.0:
            self._last_rotation_check_log_time = now_timestamp
            self._emit(
                f"[轮换检查] 当前={current_time.strftime('%Y-%m-%d %H:%M:%S')}，切换={switch_time.strftime('%Y-%m-%d %H:%M:%S')}",
                "DEBUG",
            )

        # 妫€鏌ユ槸鍚﹀埌杈惧垏鎹㈡椂闂达紙涓や釜datetime都带时区，可以直接比较）
        if current_time >= switch_time:
            # 鉁?妫€娴嬩笅涓€涓ā寮忥紙到达棰勫畾切换点）
            next_mode, next_switch = self._detect_rotation_mode(quiet=False)
            self._target_mode_after_switch = next_mode
            self._pending_rotation_switch = True
            self._emit(
                f"[轮换检查] 已到切换时间 {current_time.strftime('%Y-%m-%d %H:%M:%S')}；下一模式={next_mode}",
                "SYSTEM",
            )
            # 鉁?重置鏃堕棿妫€娴嬬浉鍏崇姸鎬?
            self._rotation_time_check_window_active = False
            self._last_rotation_time_check = 0.0
            return True

        return False

    def _should_abort_main_loop_for_reconnect(self, stop_event: threading.Event) -> bool:
        """Return whether reconnect/restart should abort the main loop."""
        if stop_event.is_set():
            return True
        if getattr(self, "_should_restart_after_reconnect", False):
            return True
        return False

    def _is_user_stop_requested(self, stop_event: threading.Event) -> bool:
        """Return whether the user explicitly requested stop."""
        if getattr(self, "bot", None) is None:
            return False
        if hasattr(self.bot, "user_stop_requested"):
            return bool(getattr(self.bot, "user_stop_requested", False))
        return bool(getattr(self.bot, "stop_current", False))

    def _should_abort_user_task(self, stop_event: threading.Event) -> bool:
        """Return whether the user task should abort."""
        return stop_event.is_set() or self._is_user_stop_requested(stop_event)

    def _clear_stop_event_for_reconnect_restart(self, stop_event: threading.Event) -> None:
        """Clear stop_event before a reconnect-driven restart."""
        if self._is_user_stop_requested(stop_event):
            return
        stop_event.clear()

    def _request_mode_restart(
        self,
        stop_event: threading.Event,
        reason: str,
    ) -> bool:
        """Request a fresh outer mode run without recursively entering ``run*``."""
        if self._is_user_stop_requested(stop_event):
            self._should_restart_after_reconnect = False
            self._mode_restart_reason = None
            return False
        self._should_restart_after_reconnect = True
        self._mode_restart_reason = str(reason or "刷新重连")
        stop_event.set()
        self._emit(
            f"[{self._mode_restart_reason}] 结束当前旧执行栈；外层将重连并重新启动同一模式",
            "SYSTEM",
        )
        return True

    def consume_mode_restart_request(
        self,
        stop_event: threading.Event,
    ) -> Optional[str]:
        """Consume one reconnect-driven restart request at the outer controller."""
        if not getattr(self, "_should_restart_after_reconnect", False):
            return None
        if self._is_user_stop_requested(stop_event):
            self._should_restart_after_reconnect = False
            self._mode_restart_reason = None
            return None

        reason = str(getattr(self, "_mode_restart_reason", None) or "刷新重连")
        self._should_restart_after_reconnect = False
        self._mode_restart_reason = None
        self._is_scanning_steady_state = False
        self._is_in_battle = False
        self._is_recovering = False
        self._stop_1and1_monitoring = False
        self._last_nie_family_id = None
        if getattr(self, "bot", None) is not None:
            self.bot.stop_current = False
        self._clear_stop_event_for_reconnect_restart(stop_event)
        return reason

    def _handoff_after_configured_nieo_reconnect(
        self, stop_event: threading.Event, profile_name: str
    ) -> None:
        """Mark configured Nieo mode for restart after reconnect."""
        if self._is_user_stop_requested(stop_event):
            self._should_restart_after_reconnect = False
            self._emit(f"[自定义尼奥:{profile_name}] 用户已停止，跳过重连重启", "WARN")
            return
        self._petswf_to_petitem_min_duration = None
        self._petswf_to_petitem_current_duration = None
        self._petswf_to_petitem_consecutive_over_threshold = 0
        self._nieo_consecutive_entry_failures = 0
        self._last_reconnect_battle_count = self._battle_count
        self._last_reconnect_time = time.time()
        if self._unified_framework and hasattr(self._unified_framework, "_petswf_to_petitem_durations"):
            self._unified_framework._petswf_to_petitem_durations.clear()
        self._request_mode_restart(stop_event, f"自定义尼奥-{profile_name}-重连")

    def _check_configured_nieo_reconnect_condition(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
        force_reconnect: bool = False,
        force_reason: str = "",
    ) -> bool:
        """Check reconnect condition for configured Nieo-like modes."""
        prof = getattr(self, "_configured_nieo_profile", None)
        if prof is None:
            return False

        if force_reconnect:
            if self._is_user_stop_requested(stop_event):
                return False
            battles_since_last_reconnect = self._battle_count - self._last_reconnect_battle_count
            reason_text = str(force_reason or "连续入战失败").strip()
            self._emit(f"[重连检测:{prof.name}] {reason_text}，请求重启当前模式", "WARN")
            self._emit(f"[重连统计:{prof.name}] 距上次重连已战斗={battles_since_last_reconnect}", "INFO")
            self._current_mode = f"nieo:{prof.slug}"
            if self._is_user_stop_requested(stop_event):
                self._should_restart_after_reconnect = False
                return False
            self._handoff_after_configured_nieo_reconnect(stop_event, prof.name)
            return True

        should_reconnect = False
        reconnect_reason = ""
        _pm = self.PETSWF_TO_PETITEM_MIN_MULTIPLIER
        _hard_min = self.NIEO_PETSWF_HARD_LIMIT_MIN_SEC
        _hard_max = self.NIEO_PETSWF_HARD_LIMIT_MAX_SEC

        if self._petswf_to_petitem_current_duration is not None:
            if self._petswf_to_petitem_current_duration >= _hard_max:
                should_reconnect = True
                reconnect_reason = (
                    f"petswf-to-PetItem duration {self._petswf_to_petitem_current_duration:.3f}s "
                    f"exceeded hard max {_hard_max:.1f}s"
                )

        if not should_reconnect:
            if (
                self._petswf_to_petitem_current_duration is not None
                and self._petswf_to_petitem_min_duration is not None
            ):
                threshold = max(self._petswf_to_petitem_min_duration * _pm, _hard_min)
                if self._petswf_to_petitem_current_duration >= threshold:
                    self._petswf_to_petitem_consecutive_over_threshold += 1
                    if (
                        self._petswf_to_petitem_consecutive_over_threshold
                        >= self.PETSWF_TO_PETITEM_CONSECUTIVE_LIMIT
                    ):
                        should_reconnect = True
                        reconnect_reason = (
                            f"petswf-to-PetItem duration exceeded {_pm:g}x min "
                            f"(current={self._petswf_to_petitem_current_duration:.3f}s, threshold={threshold:.3f}s)"
                        )
                elif self._petswf_to_petitem_consecutive_over_threshold > 0:
                    self._petswf_to_petitem_consecutive_over_threshold = 0

        if should_reconnect:
            battles_since_last_reconnect = self._battle_count - self._last_reconnect_battle_count
            self._emit(f"[重连检测:{prof.name}] 重启条件满足：{reconnect_reason}", "WARN")
            self._emit(f"[重连统计:{prof.name}] 距上次重连已战斗={battles_since_last_reconnect}", "INFO")
            self._current_mode = f"nieo:{prof.slug}"
            if self._is_user_stop_requested(stop_event):
                self._should_restart_after_reconnect = False
                return False
            self._handoff_after_configured_nieo_reconnect(stop_event, prof.name)
            return True
        return False

    def _pem_post_battle_reconnect_check(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
        *,
        force_reconnect: bool = False,
    ) -> None:
        if getattr(self, "_configured_nieo_profile", None) is not None:
            self._check_configured_nieo_reconnect_condition(
                use_foreground, stop_event, force_reconnect=force_reconnect
            )
        else:
            self._check_pure_energy_reconnect_condition(
                use_foreground, stop_event, force_reconnect=force_reconnect
            )

    def _handoff_after_nieo_reconnect(
        self, stop_event: threading.Event, log_tag: str = "尼奥模式"
    ) -> None:
        """Mark Nieo mode for restart after reconnect."""
        if self._is_user_stop_requested(stop_event):
            self._should_restart_after_reconnect = False
            self._emit(f"[{log_tag}] 用户已停止，跳过重连重启", "WARN")
            return
        self._petswf_to_petitem_min_duration = None
        self._petswf_to_petitem_current_duration = None
        self._petswf_to_petitem_consecutive_over_threshold = 0
        self._nieo_consecutive_entry_failures = 0
        self._last_reconnect_battle_count = self._battle_count
        self._last_reconnect_time = time.time()
        if self._unified_framework and hasattr(self._unified_framework, "_petswf_to_petitem_durations"):
            self._unified_framework._petswf_to_petitem_durations.clear()
        self._request_mode_restart(stop_event, f"{log_tag}-重连")

    def _check_nieo_reconnect_condition(
        self, use_foreground: bool, stop_event: threading.Event, force_reconnect: bool = False
    ) -> bool:
        """Check Nieo reconnect condition."""
        if getattr(self, "_configured_nieo_profile", None) is not None:
            return self._check_configured_nieo_reconnect_condition(
                use_foreground, stop_event, force_reconnect=force_reconnect
            )
        # 鉁?淇敼锛氬鏋滃己鍒堕噸杩烇紙杩炵画入战澶辫触），鐩存帴鎵ц閲嶈繛
        if force_reconnect:
            if self._is_user_stop_requested(stop_event):
                return False
            # 鉁?璁＄畻浠庝笂娆￠噸杩烇紙鎴栨ā寮忓紑濮嬶級鍒版湰娆￠噸杩炰箣闂寸殑鎴樻枟鏁?
            battles_since_last_reconnect = self._battle_count - self._last_reconnect_battle_count
            self._emit("[重连检测:尼奥] 连续入战失败，请求重启当前模式", "WARN")
            self._emit(f"[重连统计:尼奥] 距上次重连已战斗={battles_since_last_reconnect}", "INFO")
            self._current_mode = "nieo"
            if self._is_user_stop_requested(stop_event):
                self._should_restart_after_reconnect = False
                return False
            self._handoff_after_nieo_reconnect(stop_event)
            return True

        # 鉁?妫€鏌ラ噸杩炴潯浠讹細浠呮椂闂存娴嬶紙尼奥模式涓嶉渶瑕?0娆℃垬鏂楄鏁帮級
        # 纭嚎涓婇檺 NIEO_PETSWF_HARD_LIMIT_MAX_SEC锛涘€嶆暟闃堝€间笉浣庝簬 NIEO_PETSWF_HARD_LIMIT_MIN_SEC
        should_reconnect = False
        reconnect_reason = ""
        _pm = self.PETSWF_TO_PETITEM_MIN_MULTIPLIER
        _hard_min = self.NIEO_PETSWF_HARD_LIMIT_MIN_SEC
        _hard_max = self.NIEO_PETSWF_HARD_LIMIT_MAX_SEC

        # 妫€鏌?：硬线上限（超过即重连）
        if self._petswf_to_petitem_current_duration is not None:
            if self._petswf_to_petitem_current_duration >= _hard_max:
                should_reconnect = True
                reconnect_reason = (
                    f"petswf-to-PetItem duration {self._petswf_to_petitem_current_duration:.3f}s "
                    f"exceeded hard max {_hard_max:.1f}s"
                )

        # 妫€鏌?锛氭椂闂存潯浠讹紙鏈€灏忓€煎€嶆暟锛岄槇鍊间笉浣庝簬纭嚎涓嬮檺锛?
        if not should_reconnect:
            if (self._petswf_to_petitem_current_duration is not None and
                self._petswf_to_petitem_min_duration is not None):
                threshold = max(self._petswf_to_petitem_min_duration * _pm, _hard_min)
                self._emit(
                    f"[reconnect-check:nieo] current={self._petswf_to_petitem_current_duration:.3f}s, "
                    f"min={self._petswf_to_petitem_min_duration:.3f}s, threshold={threshold:.3f}s, "
                    f"hard_max={_hard_max:.1f}s, consecutive={self._petswf_to_petitem_consecutive_over_threshold}",
                    "DEBUG",
                )

                if self._petswf_to_petitem_current_duration >= threshold:
                    # 褰撳墠鏃堕棿瓒呰繃闃堝€硷紝澧炲姞杩炵画瓒呰繃璁℃暟
                    self._petswf_to_petitem_consecutive_over_threshold += 1
                    self._emit(
                        f"[reconnect-check:nieo] current exceeds threshold; consecutive={self._petswf_to_petitem_consecutive_over_threshold}/{self.PETSWF_TO_PETITEM_CONSECUTIVE_LIMIT}",
                        "INFO",
                    )

                    if (
                        self._petswf_to_petitem_consecutive_over_threshold
                        >= self.PETSWF_TO_PETITEM_CONSECUTIVE_LIMIT
                    ):
                        should_reconnect = True
                        reconnect_reason = (
                            f"petswf-to-PetItem duration exceeded {_pm:g}x min "
                            f"(current={self._petswf_to_petitem_current_duration:.3f}s, "
                            f"min={self._petswf_to_petitem_min_duration:.3f}s, threshold={threshold:.3f}s)"
                        )
                else:
                    # 褰撳墠鏃堕棿鏈秴杩囬槇鍊硷紝重置杩炵画瓒呰繃璁℃暟
                    if self._petswf_to_petitem_consecutive_over_threshold > 0:
                        self._emit(f"[重连检测:尼奥] 当前值低于阈值，重置连续计数：{self._petswf_to_petitem_consecutive_over_threshold}", "INFO")
                    self._petswf_to_petitem_consecutive_over_threshold = 0

        if should_reconnect:
            # 鉁?璁＄畻浠庝笂娆￠噸杩烇紙鎴栨ā寮忓紑濮嬶級鍒版湰娆￠噸杩炰箣闂寸殑鎴樻枟鏁?
            battles_since_last_reconnect = self._battle_count - self._last_reconnect_battle_count
            self._emit(f"[重连检测:尼奥] 条件满足：{reconnect_reason}，请求重启当前模式", "WARN")
            self._emit(f"[重连统计:尼奥] 距上次重连已战斗={battles_since_last_reconnect}", "INFO")
            self._current_mode = "nieo"
            self._handoff_after_nieo_reconnect(stop_event)
            return True
        return False

    def _mark_nieo_entry_success(self) -> None:
        """入战成功不代表耗时恢复正常；慢场计数由战后耗时检查独占维护。"""
        self._nieo_consecutive_entry_failures = 0

    def _check_pure_energy_reconnect_condition(self, use_foreground: bool, stop_event: threading.Event, force_reconnect: bool = False) -> None:
        """Check pure-energy reconnect condition."""
        if getattr(self, "_configured_nieo_profile", None) is not None:
            self._check_configured_nieo_reconnect_condition(
                use_foreground, stop_event, force_reconnect=force_reconnect
            )
            return
        pem_pre = getattr(self, "_pem_pre_rotation_first", False)

        if force_reconnect:
            battles_since_last_reconnect = self._battle_count - self._last_reconnect_battle_count
            self._emit("[重连检测:纯净能量] 连续入战失败，请求重启当前模式", "WARN")
            self._emit(f"[重连统计:纯净能量] 距上次重连已战斗={battles_since_last_reconnect}", "INFO")
            self._current_mode = "pure_energy"
            self._petswf_to_petitem_min_duration = None
            self._petswf_to_petitem_current_duration = None
            self._petswf_to_petitem_consecutive_over_threshold = 0
            self._nieo_consecutive_entry_failures = 0
            self._last_reconnect_battle_count = self._battle_count
            self._last_reconnect_time = time.time()
            if self._unified_framework and hasattr(self._unified_framework, "_petswf_to_petitem_durations"):
                self._unified_framework._petswf_to_petitem_durations.clear()
            self._request_mode_restart(stop_event, "纯净能量-强制重连")
            return

        should_reconnect = False
        reconnect_reason = ""
        _pm = self.PETSWF_TO_PETITEM_MIN_MULTIPLIER
        if self._petswf_to_petitem_current_duration is not None:
            if self._petswf_to_petitem_current_duration >= self.PETSWF_TO_PETITEM_HARD_LIMIT_SEC:
                should_reconnect = True
                reconnect_reason = (
                    f"petswf-to-PetItem {self._petswf_to_petitem_current_duration:.3f}s "
                    f"exceeded hard limit {self.PETSWF_TO_PETITEM_HARD_LIMIT_SEC:.1f}s"
                )
        if not should_reconnect:
            if self._petswf_to_petitem_current_duration is not None and self._petswf_to_petitem_min_duration is not None:
                threshold = max(
                    self._petswf_to_petitem_min_duration * _pm,
                    self.PETSWF_TO_PETITEM_HARD_LIMIT_MIN_SEC,
                )
                self._emit(
                    f"[reconnect-check:pure-energy] current={self._petswf_to_petitem_current_duration:.3f}s, "
                    f"min={self._petswf_to_petitem_min_duration:.3f}s, threshold={threshold:.3f}s",
                    "DEBUG",
                )
                if self._petswf_to_petitem_current_duration >= threshold:
                    self._petswf_to_petitem_consecutive_over_threshold += 1
                    if (
                        self._petswf_to_petitem_consecutive_over_threshold
                        >= self.PETSWF_TO_PETITEM_CONSECUTIVE_LIMIT
                    ):
                        should_reconnect = True
                        reconnect_reason = (
                            f"petswf-to-PetItem exceeded {_pm:g}x min "
                            f"(current={self._petswf_to_petitem_current_duration:.3f}s)"
                        )
                else:
                    self._petswf_to_petitem_consecutive_over_threshold = 0

        if should_reconnect:
            battles_since_last_reconnect = self._battle_count - self._last_reconnect_battle_count
            self._emit(f"[重连检测:纯净能量] {reconnect_reason}，请求重启当前模式", "WARN")
            self._emit(f"[重连统计:纯净能量] 距上次重连已战斗={battles_since_last_reconnect}", "INFO")
            self._current_mode = "pure_energy"
            self._petswf_to_petitem_min_duration = None
            self._petswf_to_petitem_current_duration = None
            self._petswf_to_petitem_consecutive_over_threshold = 0
            self._nieo_consecutive_entry_failures = 0
            self._last_reconnect_battle_count = self._battle_count
            self._last_reconnect_time = time.time()
            if self._unified_framework and hasattr(self._unified_framework, "_petswf_to_petitem_durations"):
                self._unified_framework._petswf_to_petitem_durations.clear()
            self._request_mode_restart(
                stop_event,
                f"纯净能量-{reconnect_reason}",
            )

    def _get_rotation_place_pets_mode(self, profile: Optional[WildCaptureProfile]) -> str:
        """
        轮换 Step3 传入 ``_rotation_step3_place_pets(current_mode, ...)`` 的兼容参数。

        历史上有 ``"nieo"``（旧文案：亨姆/波克尔/尼奥超能）与 ``"shuangta"``（旧文案：双塔四宠）两套标签；
        现已统一：**无论返回 nieo 还是 shuangta，``_rotation_step3_place_pets`` 内部都走同一套 Pick**——
        波克尔（飞行倒数）→ 艾菲德斯（超能倒数第 20）→ 机塔（双属性→机械龙系），见 ``_pickmode_rotation_step3_place_pets``。

        仍保留按 profile 区分的返回值，仅便于日志与旧调用点阅读；**与仓库实际点击序列无关**。
        """
        if profile is None:
            return "nieo"
        name_lower = profile.name.lower()
        if '尼奥' in name_lower:
            return "nieo"
        # 鍘嗗彶鍚嶃€屽弻濉斻€嶏細鍚箟宸插彉涓恒€岄潪尼奥 profile銆嶅垎鏀爣绛撅紝鍙栧疇涓庝笂鐩稿悓
        return "shuangta"

    def _get_rare_pet_reconnect_config(self, profile: WildCaptureProfile) -> Optional[Tuple[str, int, str]]:
        """
        获取稀有精灵模式重连配置（闪光皮皮、眼球）

        Returns:
            (to_script_name, expected_map_id, mode_key) 或 None
        """
        name_lower = profile.name.lower()
        if "闪光皮皮" in name_lower:
            return ("to闪光皮皮", 11, "flash_pipi")
        if '眼球' in name_lower:
            return ("to眼球", 60, "eyeball")
        return None

    def _wild_rare_expected_map_zero_after_to(self, profile: WildCaptureProfile) -> Optional[int]:
        """
        ``to*`` 后与重连 Step3 配对：字面「地图零」见 ``wild_rare_map_gate_zero_literal_swf_ids(profile)``；
        本函数仍返回与历史调用兼容的锚点整数（嘟咕噜 320、双塔 315、豆芽 11、眼球仍 60）。
        `_kernel_map_matches_profile_expectation` / `_check_last_map_and_newnpc(..., accepted_map_ids=)`
        以 **字面集合** 为准。**稳态只允许地图一** 由 `_detect_unexpected_map`（同一集合）对齐。
        """
        map_zero = getattr(profile, "map_zero_id", None)
        if map_zero is not None:
            try:
                return int(map_zero)
            except (TypeError, ValueError):
                pass

        name_lower = profile.name.lower()
        if "双塔" in name_lower:
            return 315
        if "嘟咕噜" in name_lower:
            return 320
        if "小豆芽" in name_lower:
            return 11
        if '眼球' in name_lower:
            return 60
        return None

    def _execute_unified_wild_rare_pre_reconnect(
        self,
        profile: WildCaptureProfile,
        use_foreground: bool,
        stop_event: threading.Event,
    ) -> bool:
        """Run the common pre-rotation reconnect pipeline for rare modes."""
        if self._rotation_reconnect_executing:
            self._handoff_after_active_rotation_reconnect("稀有前置重连", stop_event)
            return False

        reason_tag = "稀有统一前置重连"
        expected_zero = self._wild_rare_expected_map_zero_after_to(profile)
        if expected_zero is None:
            self._emit(f"[{reason_tag}] 方案={profile.name} 不支持统一前置流程", "WARN")
            return False

        to_script = self._get_to_script_name(profile)
        if not to_script:
            self._emit(f"[{reason_tag}] 无法解析 {profile.name} 的to脚本", "WARN")
            return False

        self._mark_rotation_reconnect_active(reason_tag)
        try:
            gate_z_literal = wild_rare_map_gate_zero_literal_swf_ids(profile)
            zero_banner = (
                "|".join(str(x) for x in sorted(gate_z_literal)) + "（字面地图零）"
                if gate_z_literal
                else str(expected_zero)
            )
            self._emit(f"[{reason_tag}] 启动：{profile.name} → 清包取宠 → {to_script} → 地图零={zero_banner}", "SYSTEM")

            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return False

            if not self._rotation_step1_login(
                use_foreground,
                stop_event,
                force_molecule_converter=True,
            ):
                self._emit(f"[{reason_tag}] 步骤1+2失败", "ERROR")
                return False

            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return False

            place_mode = self._get_rotation_place_pets_mode(profile)
            if not self._rotation_clear_backpack_and_pick_or_skip(
                place_mode,
                use_foreground,
                stop_event,
                log_tag=reason_tag,
                expected_party_ids=self._pickmode_expected_party_ids(),
            ):
                self._emit(f"[{reason_tag}] 清背包/取宠未完成", "WARN")
                return False

            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return False

            if not self._rotation_step4_set_companion(use_foreground, stop_event):
                self._emit(f"[{reason_tag}] 设置跟随失败", "WARN")
                return False

            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return False

            bg_mode = not use_foreground
            self._emit(f"[{reason_tag}] run {to_script}.json", "SYSTEM")
            if not hasattr(self.bot, "daily_runner"):
                self._emit(f"[{reason_tag}] 缺少 daily_runner", "WARN")
                return False
            if not self._to_script_has_steps(to_script):
                self._emit(f"[{reason_tag}] {to_script}.json has no steps", "ERROR")
                return False
            to_start_cursor = kernel_cursor()
            if not self.bot.daily_runner.run_single_script(to_script, bg_mode=bg_mode):
                self._emit(f"[{reason_tag}] {to_script}.json 失败", "WARN")
                return False

            if self._is_wusuo_profile(profile):
                if not self._wait_wusuo_map325_and_probe_after_to(
                    to_start_cursor,
                    stop_event,
                    timeout_s=5.0,
                ):
                    self._emit(f"[{reason_tag}] 乌索 to 脚本后门控失败", "ERROR")
                    return False
                self._emit(f"[{reason_tag}] 乌索零位地图门控通过，可以开始 run()", "SUCCESS")
                self._on_map_zero_gate_passed()
                return True

            last_map_id, has_newNPC = self._wait_after_to_then_check_last_map_and_newnpc(
                expected_zero,
                timeout_s=12.0,
                stop_event=stop_event,
                log_tag=f"{reason_tag}-map-zero",
                start_cursor=to_start_cursor,
                accepted_map_ids=gate_z_literal if gate_z_literal else None,
                skip_reverse_check=(
                    int(expected_zero) == 414
                    and (
                        str(getattr(profile, "route_hint", "")) == "埃尔特"
                        or "埃尔特" in str(getattr(profile, "name", ""))
                        or str(to_script) == "to埃尔特"
                    )
                ),
            )
            if (
                self._kernel_map_matches_profile_expectation(
                    profile, last_map_id, expected_zero
                )
                and has_newNPC
            ):
                self._emit(f"[{reason_tag}] 零位地图门控通过：map={last_map_id}+newNpc；运行 {profile.name}", "SUCCESS")
                self._on_map_zero_gate_passed()
                return True

            self._emit(f"[{reason_tag}] 零位地图门控失败：期望={expected_zero}, 实际={last_map_id}, newNpc={has_newNPC}", "ERROR")
            return False
        finally:
            self._clear_rotation_reconnect_active(reason_tag)

    def _get_to_script_name(self, profile: WildCaptureProfile) -> Optional[str]:
        """Return the to-script name for a profile."""
        custom = getattr(profile, "to_script", None)
        if custom:
            return str(custom).strip()

        # 根据profile.name鎴杛oute_hint判断
        name_lower = profile.name.lower()
        route_hint = profile.route_hint

        if "螳螂" in name_lower or route_hint == "达尔":
            return "to螳螂"
        elif "嘟咕噜" in name_lower or route_hint == "嘟咕噜":
            return "to嘟咕噜"
        elif "双塔" in name_lower or route_hint == "双塔":
            return "to双塔"
        elif "乌索" in name_lower or route_hint == "乌索":
            return "to乌索"
        elif "小豆芽" in name_lower:
            return "to小豆芽"
        elif "尼奥" in name_lower:
            return "to尼奥"
        elif "闪光皮皮" in name_lower or route_hint == "闪光皮皮":
            return "to闪光皮皮"
        elif "眼球" in name_lower or route_hint == "眼球":
            return "to眼球"
        else:
            return None

    def _to_script_has_steps(self, to_script: str) -> bool:
        """Return whether fix_script/{to_script}.json exists with non-empty steps."""
        import json as _json

        try:
            root = getattr(self.bot, "project_root", None) or os.path.dirname(
                os.path.dirname(os.path.abspath(__file__))
            )
            path = os.path.join(root, "fix_script", f"{to_script}.json")
            if not os.path.isfile(path):
                return False
            with open(path, "r", encoding="utf-8") as f:
                data = _json.load(f)
            steps = data.get("steps")
            return isinstance(steps, list) and len(steps) > 0
        except Exception:
            return False

    def _check_login_swf_non_blocking(self, start_cursor, start_time: float, timeout_s: float = 5.0) -> Tuple[bool, Optional[int]]:
        # Check for Login.swf without blocking.
        from core.logger import fetch_kernel_since, kernel_cursor

        # 妫€鏌ユ槸鍚﹁秴鏃?
        if (time.time() - start_time) >= timeout_s:
            return False, None

        try:
            new_cursor, lines = self._fetch_kernel(start_cursor)
            if isinstance(lines, list):
                for line in lines:
                    line_str = str(line)
                    if self._kernel_line_indicates_login_swf(line_str):
                        self._emit("检测到 Login.swf 内核信号，需要重连", "WARN")
                        return True, new_cursor
            return False, new_cursor
        except Exception as e:
            self._emit(f"[登录检查] 失败：{e}", "WARN")
            return False, start_cursor

    def _stop_normal_1and1_monitoring(self) -> None:
        # Stop normal 1and1 monitoring thread.
        if self._1and1_monitoring_thread is not None:
            monitor_thread = self._1and1_monitoring_thread
            current_is_monitor = threading.current_thread() is monitor_thread
            if monitor_thread.is_alive():
                self._emit("[普通1AND1] 停止上一个监控线程", "INFO")
                # 设置鍋滄鏍囧織
                self._stop_1and1_monitoring = True
                # 浠呭敜閱?缁撴潫鐩戞帶绾跨▼锛堝嬁使用涓?run 鐨?stop_event锛岃 _start_normal_1and1_monitoring锛?
                if self._1and1_monitoring_stop_event is not None:
                    self._1and1_monitoring_stop_event.set()
                # 不能在当前线程内对自身join，否则会 RuntimeError: cannot join current thread
                if not current_is_monitor:
                    monitor_thread.join(timeout=2.0)
                    if monitor_thread.is_alive():
                        self._emit("[普通1AND1] 监控线程2秒内未退出，保留引用并禁止重复启动", "WARN")
                        return
                    else:
                        self._emit("[普通1AND1] 监控线程已停止", "SUCCESS")
                else:
                    self._emit("[普通1AND1] 重连由监控线程触发，跳过join", "INFO")
                    return
            else:
                self._emit("[普通1AND1] 监控线程已退出，清理引用", "INFO")
            if self._1and1_monitoring_thread is monitor_thread:
                self._1and1_monitoring_thread = None
                self._1and1_monitoring_stop_event = None

    def _start_normal_1and1_monitoring(
        self,
        profile: WildCaptureProfile,
        use_foreground: bool,
        stop_event: threading.Event
    ) -> None:
        # Start normal dialog monitoring in a background thread.
        # 鉁?鍏堝仠姝笂涓€涓ā寮忕殑鐩戞帶锛堝鏋滃瓨鍦級
        self._stop_normal_1and1_monitoring()
        if self._1and1_monitoring_thread is not None and self._1and1_monitoring_thread.is_alive():
            self._emit("[普通1AND1] 上一个监控线程仍在退出中，本次不重复启动", "WARN")
            return

        # 鉁?浠呯敤浜庣粨鏉熺洃鎺х嚎绋嬶紱鍕夸笌涓?run 鐨?stop_event 鍏辩敤锛屽惁鍒?_stop_normal_1and1_monitoring()
        #    在刷新重连里 set 鏃朵細璇激涓诲惊鐜紝瀵艰嚧銆?0 绉掓湭 login 閫掑綊閲嶈瘯銆嶅湪绗簩娆″叆鍙ｈ璇垽涓哄凡鍋滄鑰屽崱姝汇€?
        monitor_thread_stop = threading.Event()

        def monitor_loop():
            self._emit("[普通1AND1] 监控线程已启动", "INFO")
            last_check_time = 0.0
            check_interval = 0.5  # 每0.5秒检查一次（不高频，可能半小时到两小时触发一次）
            paused_logged = False
            last_debug_skip_log = 0.0

            # 鐢ㄤ簬闈為樆濉炴鏌?login/Login.swf鐨勭姸鎬?
            login_swf_check_active = False
            login_swf_check_start_cursor = None
            login_swf_check_start_time = None

            while (
                not stop_event.is_set()
                and not getattr(self.bot, "stop_current", False)
                and not monitor_thread_stop.is_set()
            ):
                # 鉁?关键锛氬鏋滃仠姝㈢洃鎺ф爣蹇楄设置锛屾鏌ユ槸鍚﹂渶瑕侀€€鍑?
                if getattr(self, "_stop_1and1_monitoring", False):
                    # 鉁?濡傛灉stop_event涔熻设置浜嗭紝璇存槑鏄ā寮忓垏鎹紝闇€瑕侀€€鍑虹嚎绋?
                    if stop_event.is_set():
                        self._emit("[普通1AND1] 模式切换，退出监控线程", "INFO")
                        return  # 閫€鍑虹洃鎺х嚎绋?
                    # 鍚﹀垯鍙槸鏆傚仠锛堢瓑寰呮仮澶嶏級
                    if not paused_logged:
                        self._emit("[普通1AND1] 监控已暂停", "INFO")
                        paused_logged = True
                    time.sleep(1.0)
                    continue
                elif paused_logged:
                    self._emit("[普通1AND1] 监控已恢复", "INFO")
                    paused_logged = False

                # 鉁?关键锛氬鏋滀笉鍦ㄧǔ鎬佹壂鎻忛樁娈碉紙鍦ㄦ垬鏂椾腑），鏆傚仠鐩戞帶
                if not self._is_scanning_steady_state:
                    if time.time() - last_debug_skip_log >= 10.0:
                        self._emit("[普通1AND1] 跳过：当前不在稳态扫描阶段", "DEBUG")
                        last_debug_skip_log = time.time()
                    time.sleep(1.0)
                    continue

                # 鉁?关键锛氬鏋滄鍦ㄦ仮澶嶄腑锛屽畬鍏ㄨ烦杩囨娴嬶紙涓嶈繘琛屼换浣?AND1妫€鏌ワ級
                if getattr(self, "_is_recovering", False):
                    if time.time() - last_debug_skip_log >= 10.0:
                        self._emit("[普通1AND1] 跳过：正在恢复中", "DEBUG")
                        last_debug_skip_log = time.time()
                    time.sleep(0.5)
                    continue

                now = time.time()

                # 濡傛灉姝ｅ湪杩涜/login/Login.swf妫€鏌ワ紝闈為樆濉炲湴妫€鏌ヤ竴娆?
                if login_swf_check_active and login_swf_check_start_cursor is not None and login_swf_check_start_time is not None:
                    detected, new_cursor = self._check_login_swf_non_blocking(
                        login_swf_check_start_cursor,
                        login_swf_check_start_time,
                        timeout_s=5.0
                    )

                    if detected:
                        self._emit(
                            "[普通1AND1] 检测到 /login/Login.swf，请求重启当前模式",
                            "WARN",
                        )
                        self._request_mode_restart(
                            stop_event,
                            "normal-1and1-Login.swf",
                        )
                        return
                    elif new_cursor is None:
                        self._emit("[普通1AND1] 5秒内未检测到 Login.swf，继续监控", "INFO")
                        login_swf_check_active = False
                        login_swf_check_start_cursor = None
                        login_swf_check_start_time = None
                    else:
                        login_swf_check_start_cursor = new_cursor

                # 鍙湪娌℃湁杩涜/login/Login.swf妫€鏌ユ椂鎵嶆鏌?AND1
                if not login_swf_check_active and (now - last_check_time >= check_interval):
                    last_check_time = now

                    if self._check_1and1_probes():
                        self._emit("[普通1AND1] 检测到1AND1探针，点击普通确认", "INFO")

                        try:
                            # 点击涓€娆℃櫘閫氱‘璁わ紙使用鍚庡彴点击锛屼笉骞叉壈鍓嶅彴鎿嶄綔锛?
                            self._click_region(self.KEY_NORMAL_CONFIRM, use_foreground=False)
                            time.sleep(0.2)  # 等待点击生效


                            # 鉁?绛夊緟涓€灏忔鏃堕棿锛岀‘淇漧ogin信号锛堝鏋滀細鍑虹幇锛夊凡缁忓嚭鐜?
                            time.sleep(0.5)

                            # 寮€濮嬮潪闃诲妫€鏌?login/Login.swf锛堜笉闃诲锛屽湪涓嬩竴娆″惊鐜腑妫€鏌ワ級
                            # 娉ㄦ剰：在点击纭鍚庣瓑寰?.5s再获取cursor锛岀‘淇濊兘妫€娴嬪埌涔嬪悗鍑虹幇鐨刲ogin信号
                            from core.logger import kernel_cursor
                            login_swf_check_start_cursor = kernel_cursor()
                            login_swf_check_start_time = time.time()
                            login_swf_check_active = True
                            self._emit("[普通1AND1] 开始检测 Login.swf", "INFO")

                        except Exception as e:
                            self._emit(f"[普通1AND1] 处理失败：{e}", "WARN")
                            import traceback
                            self._emit(f"异常详情：{traceback.format_exc()}", "ERROR")

                time.sleep(0.5)  # 涓诲惊鐜紤鐪?

        # 鍚姩鍚庡彴绾跨▼
        monitor_thread = threading.Thread(target=monitor_loop, daemon=True)
        monitor_thread.start()
        # 鉁?淇濆瓨绾跨▼寮曠敤涓庛€屼粎鐩戞帶绾跨▼銆嶅仠姝簨浠讹紙涓庝富 run 鐨?stop_event 鍒嗙锛?
        self._1and1_monitoring_thread = monitor_thread
        self._1and1_monitoring_stop_event = monitor_thread_stop
        self._emit("[普通1AND1] 监控线程已启动", "INFO")

    def _on_map_zero_gate_passed(self) -> None:
        """Mark map-zero gate passed so run recovery can delay once."""
        self._map_zero_gate_passed_pending_run_recover = True

    def _sleep_after_map_zero_before_run_recover(self, stop_event: threading.Event) -> None:
        if not getattr(self, "_map_zero_gate_passed_pending_run_recover", False):
            return
        self._map_zero_gate_passed_pending_run_recover = False
        delay = MAP_ZERO_TO_RUN_RECOVER_DELAY_SEC
        self._emit(f"零位地图门控已通过；run 恢复前等待 {delay:.1f}s", "INFO")
        self._sleep_abortable(stop_event, delay)

    def _check_last_map_and_newnpc(
        self,
        map_id: int,
        timeout_s: float = 10.0,
        initial_pause_s: float = 2.0,
        *,
        accepted_map_ids: Optional[AbstractSet[int]] = None,
    ) -> Tuple[Optional[int], bool]:
        """Check recent kernel logs for a map id above a newNPC signal."""
        try:
            from core.logger import fetch_kernel_since, kernel_cursor

            gate_desc = (
                f"accepted={sorted(accepted_map_ids)}"
                if accepted_map_ids is not None
                else f"target_map={map_id}"
            )
            self._emit(f"[map-check] scan existing logs for first NewNPC then preceding map ({gate_desc})", "INFO")

            # 绛夊緟涓€娈垫椂闂达紝纭繚to鑴氭湰鎵ц鍚庣殑鏃ュ織閮借鏀堕泦
            time.sleep(initial_pause_s)

            # 鑾峰彇鎵€鏈夊巻鍙叉棩蹇楋紙浠巆ursor=0寮€濮嬶級
            all_lines = fetch_kernel_since(0)
            if not isinstance(all_lines, list):
                all_lines = []

            if not all_lines:
                self._emit("[map-check] no kernel logs available", "WARN")
                return (None, False)

            # 浠庢渶鏂扮殑鏃ュ織寮€濮嬶紝鍚戝墠锛堝悜涓婏級鎵弿锛屾壘鍒扮涓€涓狽ewNPC
            newnpc_line_idx = -1
            for i in range(len(all_lines) - 1, -1, -1):  # 从最新到最旧
                line_str = str(all_lines[i])
                if line_matches(RE_NEWNPC_MULTI, line_str):
                    newnpc_line_idx = i
                    self._emit(f"[map-check] first NewNPC signal found at index {i}", "SUCCESS")
                    break

            if newnpc_line_idx == -1:
                self._emit("[map-check] NewNPC signal not found", "WARN")
                return (None, False)

            # 浠嶯ewNPC琛屽紑濮嬶紝缁х画鍚戝墠锛堝悜涓婏級鎵弿锛屾壘鍒扮涓€涓猰ap信号
            found_map_id = None
            for i in range(newnpc_line_idx - 1, -1, -1):  # 浠嶯ewNPC鐨勪笂涓€琛屽紑濮嬶紝鍚戝墠鎵弿
                line_str = str(all_lines[i])
                mid = first_map_id_in_line(line_str)
                if mid is not None:
                    found_map_id = mid
                    self._emit(f"[map-check] map ID above NewNPC: {found_map_id} (index {i})", "SUCCESS")
                    break

            if found_map_id is None:
                self._emit("[map-check] no map signal found above NewNPC", "WARN")
                return (None, True)  # 找到了newNPC，但没找到map

            acc = accepted_map_ids
            if acc is not None:
                match = int(found_map_id) in acc
                if match:
                    self._emit(
                        f"[map-check] ok: map={found_map_id} in accepted set {sorted(acc)}",
                        "SUCCESS",
                    )
                    return (int(found_map_id), True)
                self._emit(
                    f"[map-check] map={found_map_id} not in accepted set {sorted(acc)}",
                    "WARN",
                )
                return (int(found_map_id), True)
            if found_map_id == map_id:
                self._emit(f"[map-check] ok: map above NewNPC is target map {map_id}", "SUCCESS")
                return (map_id, True)
            else:
                self._emit(f"[map-check] map above NewNPC is {found_map_id}, not target {map_id}", "WARN")
                return (found_map_id, True)  # 找到了newNPC鍜宮ap，但map涓嶆槸鐩爣

        except Exception as e:
            self._emit(f"[地图检查] 失败：{e}", "ERROR")
            import traceback
            self._emit(f"exception detail: {traceback.format_exc()}", "ERROR")
            return (None, False)

    # ---------- 刷新 UI 鐧诲綍绠＄嚎锛堟浛浠?fix_script/鐧诲綍.json锛?----------
    #
    # 閲庡精灵閲嶈繛缁熶竴 Step123锛堝疄鐜颁笌鏃ュ織涓€涓€对应）：
    #   Step1 鈥?_step1_trinity_clicks_and_wait_login_swf锛氳缃獥 + 刷新锛堟棤淇濆瓨锛? 绛?Login.swf
    #   Step2 鈥?_run_full_refresh_login_pipeline：至基地 / map500001 门控；成功则 _mark_refresh_pipeline_map500001_gate_done
    #   Step3 鈥?_execute_reconnect_scripts_*锛氳交閲?500001 闂ㄦ帶锛堝彲鍥?Step2 璺宠繃涓€娆″叏缂撳啿）→ 杞崲背包/精灵/璺熼殢 鈫?to 鑴氭湰 鈫?鐩爣 map
    # 杞崲 Step2 鎴愬姛鍚庡悓鏍?_mark（与閲庡涓€鑷达級锛涗笅涓€鑻ヨ繘閲嶈繛鏍稿績鍒?_consume 璺宠繃澶嶉獙銆傝疆鎹㈠瓙姝ラ 2鈥? 浠嶄笉缁忚繃 _execute_refresh_reconnect 澶栧３銆?
    #

    def _mark_refresh_pipeline_start(self) -> None:
        self._refresh_pipeline_start_perf = time.perf_counter()
        self._refresh_pipeline_step2_kernel_cursor = None
        self._refresh_pipeline_first_map_kernel_cursor = None
        self._refresh_pipeline_shield_cursor = None

    def _mark_refresh_pipeline_step2_kernel_cursor(self) -> None:
        from core.logger import kernel_cursor

        self._refresh_pipeline_step2_kernel_cursor = kernel_cursor()

    def _mark_refresh_pipeline_first_map_kernel_cursor(self, cursor: int) -> None:
        """Record cursor when the first map is detected."""
        if getattr(self, "_refresh_pipeline_first_map_kernel_cursor", None) is not None:
            return
        self._refresh_pipeline_first_map_kernel_cursor = int(cursor)

    def _mark_refresh_pipeline_map500001_gate_done(self) -> None:
        """Mark the global Step2 map500001 gate as completed."""
        self._reconnect_core_skip_map500001_fullcheck_once = True

    def _consume_reconnect_core_map500001_skip_if_set(self) -> bool:
        """Consume the one-shot map500001 skip flag."""
        if getattr(self, "_reconnect_core_skip_map500001_fullcheck_once", False):
            self._reconnect_core_skip_map500001_fullcheck_once = False
            return True
        return False

    def _step1_trinity_clicks_and_wait_login_swf(
        self,
        use_foreground: bool,
        log_prefix: str,
        stop_event: Optional[threading.Event] = None,
        max_wait_s: Optional[float] = None,
    ) -> str:
        """执行第一步刷新UI点击，并等待 Login.swf。"""
        if max_wait_s is None:
            max_wait_s = float(self.REFRESH_LOGIN_WAIT_SEC)
        self._mark_refresh_pipeline_start()
        self._emit(f"[第一步:{log_prefix}] 刷新UI并等待 Login.swf", "INFO")
        if not self._refresh_trinity_clicks(use_foreground, log_prefix=log_prefix, stop_event=stop_event):
            if (stop_event is not None and stop_event.is_set()) or getattr(self.bot, "stop_current", False):
                return "stopped"
            return "trinity_fail"
        if stop_event is not None:
            self._sleep_abortable(stop_event, 0.45, tick=0.05)
        else:
            time.sleep(0.45)
        if (stop_event is not None and stop_event.is_set()) or getattr(self.bot, "stop_current", False):
            self._emit(f"[第一步:{log_prefix}] 刷新UI后检测到停止", "WARN")
            return "stopped"
        self._emit(f"[第一步:{log_prefix}] 等待 Login.swf（{max_wait_s:.0f}s）", "INFO")
        from core.logger import fetch_kernel_since, kernel_cursor

        start_cursor = kernel_cursor()
        t0 = time.time()
        while (time.time() - t0) < max_wait_s:
            if stop_event is not None and stop_event.is_set():
                self._emit(f"[第一步:{log_prefix}] 等待 Login 时收到停止事件", "WARN")
                return "stopped"
            if getattr(self.bot, "stop_current", False):
                self._emit(f"[第一步:{log_prefix}] 等待 Login 时任务已停止", "WARN")
                return "stopped"
            lines = fetch_kernel_since(start_cursor)
            if isinstance(lines, list):
                for line in lines:
                    if self._kernel_line_indicates_login_swf(line):
                        self._emit(f"[第一步:{log_prefix}] 检测到 Login.swf", "SUCCESS")
                        return "login"
            start_cursor = kernel_cursor()
            time.sleep(0.5)
        self._emit(f"[第一步:{log_prefix}] {max_wait_s:.0f}s 内未检测到 Login.swf", "WARN")
        return "no_login"

    def _click_refresh_on_settings_hwnd(self, dlg: int, log_prefix: str = "") -> bool:
        """在已打开的设置窗口里点击刷新。"""
        lp = f"{log_prefix} " if log_prefix else ""
        key = "刷新.刷新"
        name = key.split(".", 1)[1] if "." in key else key
        child_keys = (f"设置窗口.{name}", f"设置子窗口.{name}")
        for ck in child_keys:
            try:
                reg_child = self.regions.get(ck)
                if reg_child:
                    px, py = reg_child.sample_click_point()
                    coord_space = (reg_child.meta or {}).get("coord_space", "")
                    if coord_space == "settings_dialog_logic":
                        ok = window_manager.click_background_settings_dialog_logic_xy_on_hwnd(
                            dlg, px, py
                        )
                    else:
                        ok = window_manager.click_background_on_dialog_client_xy(
                            dlg, px, py
                        )
                    if ok:
                        self._emit(
                            f"[{lp}刷新UI] 已在设置窗口点击 {ck}（{'逻辑1440x1000' if coord_space == 'settings_dialog_logic' else '客户端像素'}）",
                            "INFO",
                        )
                        return True
            except Exception:
                pass

        try:
            reg = self.regions.get(key)
            if not reg:
                raise KeyError(key)
            gx, gy = reg.sample_click_point()
        except KeyError:
            self._emit(f"[{lp}刷新UI] 缺少区域：{key}", "ERROR")
            return False
        if window_manager.click_background_on_dialog_hwnd(dlg, gx, gy):
            self._emit(f"[{lp}刷新UI] 已通过设置窗口句柄点击 {key}", "INFO")
            return True
        self._emit(f"[{lp}刷新UI] 后台点击失败：{key}", "ERROR")
        return False

    def _click_refresh_setting_attach_client(
        self, use_foreground: bool, log_prefix: str = ""
    ) -> bool:
        """点击主客户端上的刷新设置按钮。"""
        lp = f"{log_prefix} " if log_prefix else ""
        try:
            reg = self.regions.require("刷新.设置")
        except KeyError:
            self._emit(f"[{lp}刷新UI] 缺少区域：刷新.设置", "ERROR")
            return False
        x1, _y1, x2, _y2 = reg.outer_bbox()
        client_x = int(round((float(x1) + float(x2)) / 2.0))
        client_y = 45
        ok = window_manager.click_client(client_x, client_y, foreground=use_foreground)
        if ok:
            self._emit(f"[{lp}刷新UI] 已点击客户端刷新.设置 ({client_x},{client_y})", "INFO")
        else:
            self._emit(f"[{lp}刷新UI] 点击客户端刷新.设置失败", "ERROR")
        return ok

    def _refresh_trinity_clicks(
        self,
        use_foreground: bool,
        log_prefix: str = "",
        stop_event: Optional[threading.Event] = None,
    ) -> bool:
        """按需打开刷新设置并点击刷新。"""
        lp = f"{log_prefix} " if log_prefix else ""
        def _stopped() -> bool:
            return (stop_event is not None and stop_event.is_set()) or getattr(self.bot, "stop_current", False)

        if _stopped():
            self._emit(f"[{lp}刷新UI] 开始前已停止", "WARN")
            return False
        dlg = window_manager.find_settings_dialog_hwnd()
        if dlg:
            if _stopped():
                self._emit(f"[{lp}刷新UI] 后台刷新前已停止", "WARN")
                return False
            self._emit(f"[{lp}刷新UI] 设置窗口已打开 HWND={dlg}，点击刷新", "INFO")
            return self._click_refresh_on_settings_hwnd(dlg, log_prefix=log_prefix)

        OPEN_TIMEOUT_S = 25.0
        t_open = time.time()
        self._emit(
            f"[{lp}刷新UI] 未发现设置窗口，持续点击 刷新.设置 直到出现",
            "INFO",
        )
        dlg = 0
        while time.time() - t_open < OPEN_TIMEOUT_S:
            if _stopped():
                self._emit(f"[{lp}刷新UI] 打开设置窗口时已停止", "WARN")
                return False
            if not self._click_refresh_setting_attach_client(
                use_foreground, log_prefix=log_prefix
            ):
                return False
            self._sleep_abortable(stop_event, 0.35, tick=0.05)
            if _stopped():
                self._emit(f"[{lp}刷新UI] 点击设置后已停止", "WARN")
                return False
            wait_deadline = time.time() + 1.5
            while time.time() < wait_deadline:
                if _stopped():
                    self._emit(f"[{lp}刷新UI] 等待设置窗口时已停止", "WARN")
                    return False
                dlg = window_manager.find_settings_dialog_hwnd()
                if dlg:
                    break
                time.sleep(0.05)
            if dlg:
                break
        if not dlg:
            self._emit(
                f"[{lp}刷新UI] {OPEN_TIMEOUT_S:.0f}s 内设置窗口未出现",
                "ERROR",
            )
            return False
        self._emit(f"[{lp}刷新UI] 检测到设置窗口 HWND={dlg}", "INFO")
        self._sleep_abortable(stop_event, 2.0, tick=0.05)
        if _stopped():
            self._emit(f"[{lp}刷新UI] 点击刷新前已停止", "WARN")
            return False
        return self._click_refresh_on_settings_hwnd(dlg, log_prefix=log_prefix)

    def _click_shield_preferred(self, use_foreground: bool, log_tag: str = "") -> None:
        from core.logger import kernel_cursor

        for key in ("刷新.屏蔽", "系统.屏蔽"):
            try:
                self._click_region(key, use_foreground)
                self._emit(f"[{log_tag}] 已点击 {key}", "INFO")
                try:
                    self._refresh_pipeline_shield_cursor = kernel_cursor()
                except Exception:
                    self._refresh_pipeline_shield_cursor = None
                return
            except KeyError:
                continue
        self._emit(f"[{log_tag}] 缺少区域：刷新.屏蔽 / 系统.屏蔽", "WARN")

    def _beijing_is_day_shield_window(self) -> bool:
        """判断北京时间是否处于白天屏蔽窗口。"""
        t = self._get_beijing_time()
        minutes = t.hour * 60 + t.minute + t.second / 60.0
        return 360.0 <= minutes <= (17 * 60 + 55)

    def _shield_schedule_after_map_signal(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
        log_tag: str,
    ) -> bool:
        """
        出现 map 后：
        - 白天 06:00–17:55：等 1s → 单击屏蔽（刷新.屏蔽 优先）
        - 夜间：1.5s 内若出现 1AND1 则点确认至消失 → 再单击屏蔽
        测量起点为 _refresh_pipeline_start_perf / _pinnacle_round_refresh_start（非首次 map 时刻）。
        """
        if stop_event.is_set() or getattr(self.bot, "stop_current", False):
            return False
        if "巅峰" in log_tag:
            t0_meas = getattr(self, "_pinnacle_round_refresh_start", None)
        else:
            t0_meas = getattr(self, "_refresh_pipeline_start_perf", None)
        if self._beijing_is_day_shield_window():
            self._emit(f"☀️ [{log_tag}] 白天窗口：等待 1s 后单击屏蔽", "INFO")
            self._sleep_abortable(stop_event, 1.0)
            self._click_shield_preferred(use_foreground, log_tag)
        else:
            self._emit(f"🌙 [{log_tag}] 夜间窗口：1.5s 内探测 1AND1，处理后单击屏蔽", "INFO")
            deadline = time.time() + 1.5
            seen = False
            while time.time() < deadline:
                if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                    return False
                if self._check_1and1_probes():
                    seen = True
                    break
                self._sleep_abortable(stop_event, 0.05, tick=0.05)
            if seen:
                elapsed = (
                    (time.perf_counter() - t0_meas) if t0_meas is not None else None
                )
                if elapsed is not None:
                    self._emit(
                        f"📊 [{log_tag}] 刷新起点 -> 1AND1 首次: {elapsed:.3f}s",
                        "INFO",
                    )
                while not stop_event.is_set() and not getattr(
                    self.bot, "stop_current", False
                ):
                    if not self._check_1and1_probes():
                        self._emit(f"✅ [{log_tag}] 1AND1 已消失", "INFO")
                        break
                    clicked = False
                    for key in (
                        "对话框.普通确认按钮",
                        "对话框.普通确认",
                        "刷新.普通确认",
                    ):
                        try:
                            self._click_region(key, use_foreground)
                            clicked = True
                            break
                        except KeyError:
                            continue
                    if not clicked:
                        break
                    self._sleep_abortable(stop_event, 0.05, tick=0.05)
            self._click_shield_preferred(use_foreground, log_tag)
        settle_s = max(
            0.0,
            float(getattr(self, "REFRESH_POST_SHIELD_SETTLE_SEC", 0.2)),
        )
        if settle_s > 0:
            self._emit(
                f"⏳ [{log_tag}] 已点击屏蔽，等待 {settle_s:.1f}s 后再继续扫描",
                "INFO",
            )
            self._sleep_abortable(stop_event, settle_s, tick=0.05)
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return False
        return True

    def _click_three_keys_until_map_refresh(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
        log_tag: str,
    ) -> bool:
        """持续点击登录/确认直到出现地图信号。"""
        from core.logger import fetch_kernel_since, kernel_cursor

        def _region_exists(key: str) -> bool:
            try:
                return bool(self.regions.get(key))
            except Exception:
                return False

        def _login_probe_is_pure_white() -> bool:
            probe_key = None
            for k in ("巅峰对战.登录探针", "登录.登录探针"):
                if _region_exists(k):
                    probe_key = k
                    break
            if not probe_key:
                return False
            reg = self.regions.get(probe_key)
            if not reg:
                return False
            try:
                return self._check_white_probe_pure_white(reg)
            except Exception:
                return False

        def _ocr_digit_123_from_region_key(region_key: str) -> Optional[int]:
            if not pytesseract:
                return None
            reg = self.regions.get(region_key)
            if not reg:
                return None
            try:
                gx1, gy1, gx2, gy2 = reg.outer_bbox()
                img = window_manager.grab_game_bbox(gx1, gy1, gx2, gy2, min_size_px=2)
                if img is None:
                    return None
                if img.mode != "RGB":
                    img = img.convert("RGB")
                g = img.convert("L")
                g = g.resize((max(1, g.size[0] * 6), max(1, g.size[1] * 6)))
                g = g.point(lambda p: 255 if p > 160 else 0)
                cfg = "--psm 10 -c tessedit_char_whitelist=123"
                try:
                    txt = pytesseract.image_to_string(g, lang="eng", config=cfg)
                except Exception:
                    try:
                        txt = pytesseract.image_to_string(g, config=cfg)
                    except Exception:
                        return None
                s = (txt or "").strip()
                for ch in s:
                    if ch in ("1", "2", "3"):
                        return int(ch)
                return None
            except Exception:
                return None

        # Phase A: click confirm/login until the login probe becomes white.
        click_sequence = [
            ("刷新.普通确认", "对话框.普通确认"),
            ("刷新.登录",),
        ]
        seq_idx = 0
        cursor = kernel_cursor()
        last_click = 0.0
        interval = getattr(self, "PINNACLE_LOOP_CLICK_INTERVAL_SEC", 0.25)
        poll = getattr(self, "PINNACLE_LOOP_SLEEP_SEC", 0.05)
        max_wait_s = float(getattr(self, "REFRESH_LOGIN_MAP_WAIT_SEC", 25.0))
        t0 = time.time()

        while True:
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return False
            if time.time() - t0 > max_wait_s:
                self._emit(
                    f"[{log_tag}] 刷新登录循环超时（{max_wait_s:.0f}s）",
                    "WARN",
                )
                return False

            # In a few cases map appears directly; finish early.
            loop_cursor = cursor
            lines = fetch_kernel_since(cursor)
            if isinstance(lines, list):
                for line in lines:
                    if first_map_id_in_line(str(line)) is not None:
                        self._mark_refresh_pipeline_first_map_kernel_cursor(loop_cursor)
                        self._emit(f"[{log_tag}] 检测到地图信号", "SUCCESS")
                        return True
            cursor = kernel_cursor()

            if _login_probe_is_pure_white():
                break

            now = time.time()
            if now - last_click >= interval:
                current_keys = click_sequence[seq_idx]
                clicked = False
                for key in current_keys:
                    try:
                        self._click_region(key, use_foreground)
                        clicked = True
                        break
                    except KeyError:
                        continue
                if not clicked and current_keys and current_keys[0].startswith("刷新."):
                    self._emit(f"[{log_tag}] 缺少区域：{current_keys[0]}", "ERROR")
                    return False
                seq_idx = (seq_idx + 1) % len(click_sequence)
                last_click = now
            time.sleep(poll)

        # 登录探针变白后，OCR服务器探针并点击目标服务器直到地图出现。
        self._emit(f"[{log_tag}] 登录探针已变白，开始OCR选择服务器", "SUCCESS")

        probe_to_server_click = [
            ("巅峰对战.服务器一探针", ("巅峰对战.服务器一",)),
            ("巅峰对战.服务器二探针", ("巅峰对战.服务器二",)),
            ("巅峰对战.服务器三探针", ("巅峰对战.服务器三",)),
        ]

        chosen_click_key: Optional[str] = None
        if not pytesseract:
            self._emit(f"[{log_tag}] pytesseract不可用，默认选择服务器三", "WARN")
            for probe_key, click_keys in probe_to_server_click:
                if "服务器三探针" in probe_key:
                    for ck in click_keys:
                        if _region_exists(ck):
                            chosen_click_key = ck
                            break
        else:
            ocr_results: List[Tuple[str, Optional[int]]] = []
            for probe_key, _click_keys in probe_to_server_click:
                ocr_results.append((probe_key, _ocr_digit_123_from_region_key(probe_key)))
            self._emit(
                f"[{log_tag}] 服务器探针OCR："
                + ", ".join(
                    [
                        f"{pk.split('.')[-1]}={v if v is not None else '?'}"
                        for pk, v in ocr_results
                    ]
                ),
                "INFO",
            )
            probe_key_3: Optional[str] = None
            for pk, val in ocr_results:
                if val == 3:
                    probe_key_3 = pk
                    break
            if probe_key_3:
                for pk, click_keys in probe_to_server_click:
                    if pk == probe_key_3:
                        for ck in click_keys:
                            if _region_exists(ck):
                                chosen_click_key = ck
                                break
                        break
            else:
                self._emit(f"[{log_tag}] 未识别到数字3，默认选择服务器三", "WARN")
                for pk, click_keys in probe_to_server_click:
                    if "服务器三探针" in pk:
                        for ck in click_keys:
                            if _region_exists(ck):
                                chosen_click_key = ck
                                break

        if not chosen_click_key:
            self._emit(f"[{log_tag}] 缺少可点击的服务器区域", "ERROR")
            return False

        self._emit(f"[{log_tag}] 选择服务器：持续点击 {chosen_click_key} 直到地图出现", "INFO")
        cursor = kernel_cursor()
        last_click = 0.0
        while True:
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return False
            if time.time() - t0 > max_wait_s:
                self._emit(f"[{log_tag}] 选择服务器后等待地图超时（{max_wait_s:.0f}s）", "WARN")
                return False
            now = time.time()
            if now - last_click >= interval:
                try:
                    self._click_region(chosen_click_key, use_foreground)
                except KeyError:
                    self._emit(f"[{log_tag}] 缺少区域：{chosen_click_key}", "ERROR")
                    return False
                last_click = now
            loop_cursor = cursor
            lines = fetch_kernel_since(cursor)
            if isinstance(lines, list):
                for line in lines:
                    if first_map_id_in_line(str(line)) is not None:
                        self._mark_refresh_pipeline_first_map_kernel_cursor(loop_cursor)
                        self._emit(f"[{log_tag}] 检测到地图信号", "SUCCESS")
                        return True
            cursor = kernel_cursor()
            time.sleep(poll)

    def _post_login_swf_programmatic_clicks(
        self, use_foreground: bool, stop_event: threading.Event, log_tag: str
    ) -> bool:
        """点击开始四次、双击登录，然后等待地图。"""
        self._emit(f"[{log_tag}] 点击刷新开始四次", "INFO")
        for _ in range(4):
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return False
            try:
                self._click_region("刷新.开始", use_foreground)
            except KeyError:
                self._emit(f"[{log_tag}] 缺少区域：刷新.开始", "ERROR")
                return False
            self._sleep_abortable(stop_event, 0.05, tick=0.05)
        self._emit(f"[{log_tag}] 双击刷新登录", "INFO")
        try:
            self._click_region_twice("刷新.登录", use_foreground, gap=0.08)
        except KeyError:
            self._emit(f"[{log_tag}] 缺少区域：刷新.登录", "ERROR")
            return False
        return self._click_three_keys_until_map_refresh(
            use_foreground, stop_event, log_tag
        )

    def _gate_map500001_after_refresh_base(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
        log_tag: str,
        *,
        force_molecule_converter: bool = False,
        skip_molecule_converter: bool = False,
    ) -> bool:
        """Gate after clicking refresh base: wait for map/newNPC and optional converter flow."""
        from core.logger import fetch_kernel_since, kernel_cursor

        # The caller already clicked base; only inspect fresh kernel lines.
        gate_start_cursor = kernel_cursor()
        time.sleep(0.35)

        def _segment_last_map_and_npc() -> Tuple[Optional[int], bool, int]:
            seg = fetch_kernel_since(gate_start_cursor)
            if not isinstance(seg, list):
                return None, False, 0
            last_map: Optional[int] = None
            for line in reversed(seg):
                mid = first_map_id_in_line(str(line))
                if mid is not None:
                    last_map = mid
                    break
            has_npc = any(line_matches(RE_NEWNPC_MULTI, str(ln)) for ln in seg)
            return last_map, has_npc, len(seg)

        def _double_confirm() -> bool:
            self._emit(f"[{log_tag}] 基地门控通过后双击普通确认", "INFO")
            for _ in range(2):
                clicked = False
                for key in (
                    "对话框.普通确认",
                    "刷新.普通确认",
                ):
                    try:
                        self._click_region(key, use_foreground)
                        clicked = True
                        break
                    except KeyError:
                        continue
                if not clicked:
                    self._emit(f"[{log_tag}] 缺少普通确认区域", "WARN")
                    return False
                time.sleep(0.12)
            return True

        def _maybe_run_molecule_converter_flow() -> bool:
            """Run molecule converter flow if throttle allows it."""
            if not force_molecule_converter:
                try:
                    last_ts = getattr(self, "_molecule_flow_last_ts", None)
                    now_ts = time.time()
                    if last_ts is not None and (now_ts - float(last_ts)) <= (30 * 60 + 30):
                        return True
                except Exception:
                    pass

            ok = self._run_molecule_converter_flow_after_gate(
                use_foreground=use_foreground,
                stop_event=stop_event,
                log_tag=log_tag,
                gate_start_cursor=gate_start_cursor,
            )
            if ok:
                try:
                    self._molecule_flow_last_ts = time.time()
                except Exception:
                    pass
            return ok

        self._emit(
            f"[{log_tag}] 等待基地后 map={self.MAP_ID_AFTER_LOGIN} + newNpc",
            "INFO",
        )
        t0 = time.time()
        while time.time() - t0 < 32.0:
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return False
            last_map, has_npc, nlines = _segment_last_map_and_npc()
            if last_map is not None and last_map != self.MAP_ID_AFTER_LOGIN:
                self._emit(
                    f"[{log_tag}] 基地后最新地图={last_map}，期望={self.MAP_ID_AFTER_LOGIN}，重新刷新",
                    "WARN",
                )
                return False
            if last_map == self.MAP_ID_AFTER_LOGIN and has_npc:
                self._emit(
                    f"[{log_tag}] 基地门控通过：map={last_map} + newNpc（新增日志 {nlines} 行）",
                    "SUCCESS",
                )
                if not _double_confirm():
                    return False
                time.sleep(0.25)
                if skip_molecule_converter:
                    self._emit(
                        f"[{log_tag}] 跳过分子转化仪流程",
                        "INFO",
                    )
                elif not getattr(self, "_enable_molecule_converter", False):
                    self._emit(
                        f"[{log_tag}] 分子转化仪选项未启用，跳过",
                        "INFO",
                    )
                elif not _maybe_run_molecule_converter_flow():
                    self._emit(f"[{log_tag}] 分子转化仪流程失败，继续后续", "WARN")
                self._emit(
                    f"[{log_tag}] 门控完成，继续后续步骤",
                    "INFO",
                )
                return True
            self._sleep_abortable(stop_event, 0.12, tick=0.12)
        self._emit(
            f"[{log_tag}] 基地后等待 map={self.MAP_ID_AFTER_LOGIN} / newNpc 超时（32s）",
            "WARN",
        )
        return False

    def _run_molecule_converter_flow_after_gate(
        self,
        *,
        use_foreground: bool,
        stop_event: threading.Event,
        log_tag: str,
        gate_start_cursor,
    ) -> bool:
        # Run the molecule converter flow after the map gate.
        tag = f"{log_tag}-分子转化仪"
        molecule_1and1_timeout_s = 3.0
        if stop_event.is_set() or getattr(self.bot, "stop_current", False):
            return False

        def _click_once_any(keys: Sequence[str]) -> bool:
            for k in keys:
                try:
                    self._click_region(k, use_foreground)
                    return True
                except KeyError:
                    continue
                except Exception:
                    continue
            return False

        def _double_click_any(keys: Sequence[str], gap: float = 0.10) -> bool:
            # Keep double click behavior aligned with the existing click path.
            for _ in range(2):
                if not _click_once_any(keys):
                    return False
                time.sleep(gap)
            return True

        def _confirm_1and1_until_disappear(timeout_s: float = 3.0) -> bool:
            # Keep clicking confirm until probes disappear or timeout.
            time.sleep(0.22)
            t0d = time.time()
            seen_probes = False
            consecutive_gone = 0
            need_gone = 3
            keys_1and1 = (
                "对话框.普通确认",
                "刷新.普通确认",
            )
            while time.time() - t0d < timeout_s:
                if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                    return False
                try:
                    has_probes = self._check_1and1_probes()
                except Exception:
                    has_probes = True
                if has_probes:
                    seen_probes = True
                    consecutive_gone = 0
                elif seen_probes:
                    consecutive_gone += 1
                    if consecutive_gone >= need_gone:
                        return True
                _click_once_any(keys_1and1)
                time.sleep(0.08)
            return True

        def _click_close_molecule_panel() -> bool:
            self._emit(f"[{tag}] click 刷新.关闭分子转化仪", "INFO")
            if not _click_once_any(("刷新.关闭分子转化仪",)):
                self._emit(f"[{tag}] 缺少区域或点击失败：刷新.关闭分子转化仪", "ERROR")
                return False
            self._sleep_abortable(stop_event, 0.2, tick=0.05)
            return True

        def _click_jingyuan_confirm_and_1and1_once() -> bool:
            self._emit(f"[{tag}] click 刷新.精元确认", "INFO")
            if not _click_once_any(("刷新.精元确认",)):
                self._emit(f"[{tag}] 缺少区域或点击失败：刷新.精元确认", "ERROR")
                return False
            self._emit(f"[{tag}] 确认1AND1直到消失（超时 {molecule_1and1_timeout_s}s）", "INFO")
            if not _confirm_1and1_until_disappear(timeout_s=molecule_1and1_timeout_s):
                return False
            return _click_close_molecule_panel()

        def _kernel_segment_has_molecule_and_doodle_icon() -> bool:
            """Scan fresh kernel lines for MoleculePanel plus doodle icon."""
            try:
                seg = fetch_kernel_since(gate_start_cursor)
            except Exception:
                return False
            if not isinstance(seg, list) or not seg:
                return False
            has_molecule = False
            has_doodle = False
            re_doodle = re.compile(
                r"(?:resource[\\/]+item[\\/]+doodle[\\/]+icon[\\/]+)(\d+)\.swf",
                re.IGNORECASE,
            )
            # Only inspect the fresh section after the latest newNPC marker.
            seen_newnpc = False
            for line in reversed(seg):
                s = str(line)
                if not seen_newnpc:
                    if line_matches(RE_NEWNPC_MULTI, s):
                        seen_newnpc = True
                    continue
                if "MoleculePanel.swf" in s or "moleculepanel.swf" in s.lower():
                    has_molecule = True
                if re_doodle.search(s):
                    has_doodle = True
                if has_molecule and has_doodle:
                    return True
            return False

        self._emit(f"[{tag}] 等待 1.0s", "INFO")
        self._sleep_abortable(stop_event, 1.0, tick=0.1)

        self._emit(f"[{tag}] 双击 刷新.基地右侧", "INFO")
        if not _double_click_any(("刷新.基地右侧",)):
            self._emit(f"[{tag}] 缺少区域或点击失败：刷新.基地右侧", "ERROR")
            return False

        self._emit(f"[{tag}] 分子转化仪前等待 0.3s", "INFO")
        self._sleep_abortable(stop_event, 0.3, tick=0.1)

        self._emit(f"[{tag}] 双击 刷新.分子转化仪", "INFO")
        if not _double_click_any(("刷新.分子转化仪",)):
            self._emit(f"[{tag}] 缺少区域或点击失败：刷新.分子转化仪", "ERROR")
            return False

        self._emit(f"[{tag}] 第一次 1AND1，直到探针消失（超时 {molecule_1and1_timeout_s}s）", "INFO")
        if not _confirm_1and1_until_disappear(timeout_s=molecule_1and1_timeout_s):
            return False

        self._emit(f"[{tag}] 第二次点击分子转化仪前等待 1.5s", "INFO")
        self._sleep_abortable(stop_event, 1.5, tick=0.1)

        self._emit(f"[{tag}] 再次双击 刷新.分子转化仪", "INFO")
        if not _double_click_any(("刷新.分子转化仪",)):
            return False

        self._emit(f"[{tag}] 第二次双击后等待 0.5s", "INFO")
        self._sleep_abortable(stop_event, 0.5, tick=0.1)

        did = 0
        for i in range(3):
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return False
            if _kernel_segment_has_molecule_and_doodle_icon():
                self._emit(
                    f"[{tag}] detected MoleculePanel + doodle/icon ({i+1}/3); run 精元确认 + 1AND1",
                    "SUCCESS",
                )
                if not _click_jingyuan_confirm_and_1and1_once():
                    return False
                did += 1
                continue
            break

        if did == 0:
            self._emit(
                f"[{tag}] 未检测到 MoleculePanel+doodle/icon，执行一次兜底 精元确认 + 1AND1",
                "WARN",
            )
            if not _click_jingyuan_confirm_and_1and1_once():
                return False

        return True

    def _run_full_refresh_login_pipeline(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
        log_prefix: str,
        *,
        include_base_and_map_gate: bool = True,
        force_molecule_converter: bool = False,
        skip_molecule_converter: bool = False,
    ) -> bool:
        """Run the refresh login pipeline after Login.swf appears."""
        tag = log_prefix or "刷新登录"
        self._mark_refresh_pipeline_step2_kernel_cursor()
        if not self._post_login_swf_programmatic_clicks(
            use_foreground, stop_event, tag
        ):
            return False
        if not self._shield_schedule_after_map_signal(use_foreground, stop_event, tag):
            return False
        if not include_base_and_map_gate:
            return True
        self._emit(f"[{tag}] 点击 刷新.基地", "INFO")
        try:
            self._click_region("刷新.基地", use_foreground)
        except KeyError:
            self._emit(f"[{tag}] 缺少区域：刷新.基地", "ERROR")
            return False
        return self._gate_map500001_after_refresh_base(
            use_foreground,
            stop_event,
            tag,
            force_molecule_converter=force_molecule_converter,
            skip_molecule_converter=skip_molecule_converter,
        )

    def _mode_requires_nono_fusion_reconnect_check(self) -> bool:
        """Whether the current reconnect belongs to a rare/Nieo/resource flow."""
        current_mode = str(getattr(self, "_current_mode", "") or "").strip().lower()
        if bool(getattr(self, "_is_rotation_mode", False)):
            # Temporary policy: rotation must not interrupt itself for Nono fusion.
            return False
        if current_mode.startswith(("rare:", "nieo:", "resource:")):
            return True
        return current_mode in {
            "rare",
            "mantis",
            "flash_pipi",
            "eyeball",
            "dugulu",
            "shuangta",
            "xiaodouya",
            "nieo",
            "nieo_resource",
            "pure_energy",
        }

    def _run_nono_fusion_after_mode_reconnect(
        self,
        use_foreground: bool,
        *,
        reconnect_reason: str,
    ) -> bool:
        """Insert a due Nono fusion before this mode reconnect restores its party."""
        if not self._mode_requires_nono_fusion_reconnect_check():
            return True
        daily_runner = getattr(self.bot, "daily_runner", None)
        if daily_runner is None:
            self._emit(f"❌ [{reconnect_reason}] 缺少 daily_runner，无法执行融合重连检查", "ERROR")
            return False
        mode_name = str(getattr(self, "_current_mode", "") or "稀有/尼奥资源")
        ok, handled = daily_runner.run_nono_soul_fusion_after_reconnect_check(
            use_foreground=use_foreground,
            mode_name=f"{mode_name}-{reconnect_reason}",
        )
        if handled:
            self._emit(f"✅ [{reconnect_reason}] 已在本次重连插入融合，继续清包取宠和 to 脚本", "SUCCESS")
        return bool(ok)

    def mark_nono_fusion_connection_ready(self) -> None:
        """Allow the immediately following mode setup to reuse the fusion connection once."""
        self._nono_fusion_connection_ready = True

    def _consume_nono_fusion_connection_ready(self) -> bool:
        """Consume the one-shot connection marker set after a successful Nono fusion."""
        if not bool(getattr(self, "_nono_fusion_connection_ready", False)):
            return False
        self._nono_fusion_connection_ready = False
        return True

    def run_refresh_login_test_cycle(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
        *,
        max_retries: int = 3,
    ) -> bool:
        """Test refresh login through map, then run one extra trinity refresh."""
        retries = 0
        while retries <= max_retries:
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return False
            step1 = self._step1_trinity_clicks_and_wait_login_swf(
                use_foreground=use_foreground,
                log_prefix="刷新登录测试",
                stop_event=stop_event,
            )
            if step1 == "stopped":
                return False
            if step1 != "login":
                retries += 1
                self._emit(
                    f"[刷新登录测试] 步骤1未进入 Login.swf（结果={step1}），重试 {retries}/{max_retries}",
                    "WARN",
                )
                continue
            ok2 = self._run_full_refresh_login_pipeline(
                use_foreground=use_foreground,
                stop_event=stop_event,
                log_prefix="刷新登录测试",
                include_base_and_map_gate=False,
            )
            if not ok2:
                if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                    return False
                retries += 1
                self._emit(
                    f"[刷新登录测试] 步骤2失败，重试 {retries}/{max_retries}",
                    "WARN",
                )
                continue

            self._emit("[刷新登录测试] map detected; run one more trinity refresh", "SUCCESS")
            ok3 = self._refresh_trinity_clicks(
                use_foreground=use_foreground,
                log_prefix="刷新登录测试-再次刷新",
                stop_event=stop_event,
            )
            return bool(ok3)
        return False

    def run_pure_refresh(self, use_foreground: bool) -> bool:
        """只执行刷新UI路径。"""
        if not window_manager.find_window():
            self._emit("[仅刷新] game window not found", "ERROR")
            return False
        self._emit(
            "[仅刷新] run settings if needed, then background refresh only",
            "INFO",
        )
        ok = self._refresh_trinity_clicks(use_foreground, log_prefix="仅刷新")
        if ok:
            self._emit("[仅刷新] 执行完成", "SUCCESS")
        else:
            self._emit("[仅刷新] 刷新UI失败", "ERROR")
        return bool(ok)

    def _pre_daily_run_script_if_present(
        self,
        script_name: str,
        use_foreground: bool,
        *,
        required: bool,
        log_tag: str,
    ) -> bool:
        daily_runner = getattr(self.bot, "daily_runner", None)
        if daily_runner is None:
            self._emit(f"❌ [{log_tag}] 缺少 DailyRunner，无法执行脚本 {script_name}", "ERROR")
            return False
        resolve = getattr(daily_runner, "_resolve_script_path", None)
        if callable(resolve) and not resolve(script_name):
            level = "ERROR" if required else "WARN"
            self._emit(f"{'❌' if required else '⚠️'} [{log_tag}] 找不到脚本：{script_name}", level)
            return not required
        ok = bool(daily_runner.run_single_script(script_name, bg_mode=(not use_foreground)))
        if ok:
            self._emit(f"✅ [{log_tag}] 脚本 {script_name} 已执行", "SUCCESS")
            return True
        level = "ERROR" if required else "WARN"
        self._emit(f"{'❌' if required else '⚠️'} [{log_tag}] 脚本 {script_name} 未完全成功", level)
        return not required

    def _pre_daily_place_daily_six_pets(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
        *,
        log_tag: str,
    ) -> bool:
        import config as _rot_cfg

        def _r(name: str, default: int) -> int:
            try:
                return int(getattr(_rot_cfg, name, default))
            except Exception:
                return default

        required = [
            "精灵仓库.打开",
            "精灵仓库.关闭",
            "精灵仓库.ALL",
            "精灵仓库.放入背包",
            "精灵仓库.右",
            "精灵仓库.左",
            "精灵仓库.地面系",
            "精灵仓库.冰系",
            "精灵仓库.水系",
            "精灵仓库.草系",
            "精灵仓库.火系",
            "精灵仓库.双属性",
            "精灵仓库.机械龙系",
            "对话框.普通确认",
        ]
        required.extend(f"精灵仓库.{i}" for i in range(1, 10))
        for key in required:
            if not self.regions.get(key):
                self._emit(f"❌ [{log_tag}] 缺少区域：{key}", "ERROR")
                return False

        try:
            self._emit(f"📦 [{log_tag}] 打开精灵仓库，开始取日常六宠", "SYSTEM")
            self._click_pet_warehouse_open(use_foreground, log_tag=log_tag)
            self._sleep_abortable(stop_event, 0.8)
            if not self._warehouse_click_all_until_right_available(
                use_foreground,
                stop_event,
                log_tag=f"{log_tag}·仓库ALL",
            ):
                return False
            if self.regions.get("精灵仓库.单属性"):
                self._click_region("精灵仓库.单属性", use_foreground)
                self._sleep_abortable(stop_event, 0.4)

            plan = [
                ("水系", 19, _r("ROTATION_NIEO_RIGHT_CLICKS_WATER", 20)),
                ("地面系", 1, _r("ROTATION_NIEO_RIGHT_CLICKS_GROUND", 15)),
                ("草系", 4, _r("ROTATION_NIEO_RIGHT_CLICKS_GRASS", 40)),
                ("冰系", 3, _r("ROTATION_NIEO_RIGHT_CLICKS_ICE", 80)),
                ("火系", 4, 40),
            ]
            for category, reverse_pos, right_clicks in plan:
                if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                    return False
                if self.regions.get("精灵仓库.单属性"):
                    self._click_region("精灵仓库.单属性", use_foreground)
                    self._sleep_abortable(stop_event, 0.2)
                self._emit(
                    f"🐾 [{log_tag}] 取 {category} 倒数第 {reverse_pos} 只",
                    "INFO",
                )
                if not self._rotation_place_pets_same_category_by_reverse(
                    category,
                    (reverse_pos,),
                    right_clicks,
                    use_foreground,
                    stop_event,
                    log_tag=log_tag,
                ):
                    return False

            self._emit(f"🐾 [{log_tag}] 取机塔（双属性→机械龙系）", "INFO")
            if not self._pickmode_place_jita_dual_mechanical(
                use_foreground,
                stop_event,
                log_tag=log_tag,
            ):
                return False
            self._emit(f"✅ [{log_tag}] 日常六宠已放入背包", "SUCCESS")
            return True
        except Exception as exc:
            self._emit(f"❌ [{log_tag}] 取日常六宠异常：{exc}", "ERROR")
            return False
        finally:
            try:
                self._emit(f"📦 [{log_tag}] 关闭精灵仓库", "INFO")
                self._click_pet_warehouse_close(use_foreground, log_tag=log_tag)
                self._sleep_abortable(stop_event, 0.5)
            except Exception as exc:
                self._emit(f"⚠️ [{log_tag}] 关闭精灵仓库异常：{exc}", "WARN")

    def _pre_daily_find_purple_jita_slot(
        self,
        stop_event: threading.Event,
        *,
        log_tag: str,
        timeout_s: float = 5.0,
    ) -> Optional[str]:
        """扫描日常六宠背包里的紫色机塔槽位，不要求同时存在青色精灵。"""
        cn = {2: "二", 3: "三", 4: "四", 5: "五", 6: "六"}
        deadline = time.time() + float(timeout_s)
        attempt = 0
        last_desc = ""
        while time.time() < deadline:
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return None
            attempt += 1
            data: Dict[int, Dict[str, Any]] = {}
            counts = {"orange": 0, "cyan": 0, "purple": 0}
            for pos in range(2, 7):
                key = self._bag_party_slot_probe_key(pos)
                rgb = self._mean_rgb_for_region_key(key)
                color = self._classify_pick_bag_slot_rgb(rgb)
                if color in counts:
                    counts[color] += 1
                data[pos] = {"key": key, "rgb": rgb, "color": color}

            last_desc = "; ".join(
                f"{pos}号({item['key']})=RGB{item['rgb']}→{self._pick_bag_color_label(item['color'])}"
                for pos, item in data.items()
            )
            purple_pos = next(
                (pos for pos, item in data.items() if item["color"] == "purple"),
                None,
            )
            self._emit(
                f"[{log_tag}] 日常六宠槽位扫描第{attempt}次：{last_desc}；统计 橙={counts['orange']} 青={counts['cyan']} 紫={counts['purple']}；只要求找到紫色机塔",
                "DEBUG",
            )
            if purple_pos is not None:
                slot = cn[int(purple_pos)]
                self._jita_pos = slot
                self._emit(f"[{log_tag}] 识别到紫色机塔：精灵{slot}", "SUCCESS")
                return slot
            self._sleep_abortable(stop_event, 0.25)
        self._emit(
            f"[{log_tag}] {timeout_s:.0f}s 内未识别紫色机塔；最后扫描={last_desc}",
            "WARN",
        )
        return None

    def _pre_daily_follow_pet_one_after_daily_six_pets(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
        *,
        log_tag: str,
    ) -> bool:
        """打开或复用精灵背包，跟随日常六宠里的精灵一；跟随动作负责自动关包。"""
        bag_open_key = "精灵背包.打开精灵背包"
        bag_open_btn_key = "精灵背包.打开精灵背包按钮"
        bag_ready = False
        try:
            if self._wait_pet_bag_ui_ready_after_open(
                stop_event,
                log_tag=log_tag,
                timeout_s=0.6,
            ):
                bag_ready = True
                self._emit(f"[{log_tag}] 精灵背包已打开，直接设置身边跟随", "INFO")
            else:
                self._emit(f"[{log_tag}] 打开精灵背包设置身边跟随", "INFO")
                try:
                    self._click_region(bag_open_btn_key, use_foreground)
                except KeyError:
                    self._click_region(bag_open_key, use_foreground)
                if not self._ensure_pet_bag_ui_ready_after_open(
                    stop_event,
                    use_foreground,
                    bag_open_key,
                    bag_open_btn_key,
                    log_tag=log_tag,
                ):
                    self._emit(f"[{log_tag}] 精灵背包UI未就绪，无法跟随精灵一", "ERROR")
                    return False
                bag_ready = True

            self._emit(
                f"[{log_tag}] 开包后精灵一已选中，直接点击身边跟随",
                "SYSTEM",
            )
            self._click_region("精灵背包.身边跟随", use_foreground)
            self._sleep_abortable(stop_event, 0.5)
            self._emit(f"[{log_tag}] 已设置身边跟随，背包应由跟随动作自动关闭", "SUCCESS")
            return True
        except Exception as exc:
            self._emit(f"❌ [{log_tag}] 设置日常精灵一跟随失败：{exc}", "ERROR")
            if bag_ready:
                try:
                    self._close_pet_bag_with_verify(
                        use_foreground,
                        stop_event,
                        bag_open_key,
                        bag_open_btn_key,
                        log_tag=log_tag,
                    )
                except Exception:
                    pass
            return False

    def prepare_happy_valley_daily_pets(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
        *,
        log_tag: str = "欢乐谷日常",
        clear_backpack: bool = True,
    ) -> bool:
        """清空背包后按欢乐谷顺序取六宠，首次连接专用。"""
        if clear_backpack:
            if not self._rotation_step2_clear_backpack(
                use_foreground,
                stop_event,
                log_tag=f"{log_tag}·清包",
            ):
                return False
        else:
            self._emit(f"⏭️ [{log_tag}] 未执行加经验流程，跳过第二次清空精灵背包", "INFO")
        return self._pre_daily_place_daily_six_pets(
            use_foreground,
            stop_event,
            log_tag=f"{log_tag}·取宠",
        )

    def set_follow_color_from_closed_bag(
        self,
        color: str,
        use_foreground: bool,
        stop_event: threading.Event,
        *,
        log_tag: str = "颜色跟随",
    ) -> bool:
        """打开背包扫描槽位，选中并跟随指定颜色精灵。"""
        target = str(color or "").strip().lower()
        if target not in {"cyan", "purple"}:
            self._emit(f"❌ [{log_tag}] 不支持的跟随颜色：{color}", "ERROR")
            return False
        bag_open_key = "精灵背包.打开精灵背包"
        bag_open_btn_key = "精灵背包.打开精灵背包按钮"
        try:
            try:
                self._click_region(bag_open_btn_key, use_foreground)
            except KeyError:
                self._click_region(bag_open_key, use_foreground)
            if not self._ensure_pet_bag_ui_ready_after_open(
                stop_event,
                use_foreground,
                bag_open_key,
                bag_open_btn_key,
                log_tag=log_tag,
            ):
                return False
            scan = self.scan_pick_bag_party_color_slots_any(
                stop_event,
                log_tag,
                timeout_s=10.0,
                min_cyan=1,
                min_purple=1,
            )
            slot = scan.get(target) if scan.get("ok") else None
            if not slot:
                self._emit(f"❌ [{log_tag}] 未找到{target}色精灵", "ERROR")
                self._close_pet_bag_with_verify(
                    use_foreground,
                    stop_event,
                    bag_open_key,
                    bag_open_btn_key,
                    log_tag=log_tag,
                )
                return False
            if not self._click_pet_with_selection_check(slot, use_foreground, stop_event):
                self._emit(f"❌ [{log_tag}] 槽位{slot}选中检测失败", "ERROR")
                return False
            self._click_region("精灵背包.身边跟随", use_foreground)
            self._sleep_abortable(stop_event, 0.5)
            self._emit(f"✅ [{log_tag}] 已跟随{target}色精灵{slot}", "SUCCESS")
            return True
        except Exception as exc:
            self._emit(f"❌ [{log_tag}] 设置{target}色跟随失败：{exc}", "ERROR")
            return False

    def run_pre_daily_mode(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
    ) -> bool:
        """预选重连：刷新登录、清包、签到/小蜜蜂、取日常六宠、跟随精灵一、接受任务。"""
        log_tag = "预选前置"
        if not window_manager.find_window():
            self._emit(f"❌ [{log_tag}] 未检测到游戏窗口", "ERROR")
            return False
        self._emit(
            f"📋 [{log_tag}] 开始：重连→清包→签到/小蜜蜂→跳过尼尔冲经验及其二次清包→日常六宠→跟随精灵一→接受任务",
            "SYSTEM",
        )
        if not self.run_refresh_login_until_map(
            use_foreground,
            stop_event,
            include_base_and_map_gate=True,
        ):
            self._emit(f"❌ [{log_tag}] 刷新登录失败", "ERROR")
            return False
        if stop_event.is_set() or getattr(self.bot, "stop_current", False):
            return False

        if not self._rotation_step2_clear_backpack(
            use_foreground,
            stop_event,
            log_tag=f"{log_tag}·首次清包",
        ):
            self._emit(f"❌ [{log_tag}] 首次清空背包失败", "ERROR")
            return False

        self._pre_daily_run_script_if_present(
            "每日签到",
            use_foreground,
            required=False,
            log_tag=f"{log_tag}·签到",
        )
        if stop_event.is_set() or getattr(self.bot, "stop_current", False):
            return False
        if not self._dismiss_1and1_until_disappear(
            use_foreground,
            stop_event,
            timeout_s=10.0,
            log_tag=f"{log_tag}·签到后1AND1",
            require_seen=False,
            require_click=False,
        ):
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return False
            self._emit(f"⚠️ [{log_tag}] 签到后1AND1未完全清理，继续后续日常", "WARN")

        self._emit(f"ℹ️ [{log_tag}] 判断日暂无独立脚本，继续执行", "INFO")
        signin_record = append_signin_record("pre_daily")
        if signin_record.get("ok"):
            counted_text = "计入次数" if signin_record.get("counted") else "同业务日重复，不重复计数"
            self._emit(
                f"🧾 [{log_tag}] 签到记录：业务日={signin_record.get('business_date')}，本月第{signin_record.get('signin_count')}次（{counted_text}）",
                "INFO",
            )
        else:
            self._emit(
                f"⚠️ [{log_tag}] 签到记录写入失败，按业务日号兜底：{signin_record.get('error')}",
                "WARN",
            )
        today_day = int(signin_record.get("signin_count") or self._business_day_6am())
        bee_awarded = has_monthly_bee_award()
        should_run_bee = (28 <= today_day <= 31) and not bee_awarded
        if should_run_bee and self.regions.get("日常.小蜜蜂"):
            try:
                self._emit(f"🐝 [{log_tag}] 本月第{today_day}次签到：点击小蜜蜂", "INFO")
                self._click_region("日常.小蜜蜂", use_foreground)
                bee_record = append_monthly_bee_award("pre_daily")
                if bee_record.get("ok"):
                    record_text = "已写入领取记录" if bee_record.get("recorded") else "本月已有领取记录"
                    self._emit(f"🧾 [{log_tag}] 小蜜蜂本月奖励：{record_text}", "INFO")
                else:
                    self._emit(f"⚠️ [{log_tag}] 小蜜蜂领取记录写入失败：{bee_record.get('error')}", "WARN")
                self._sleep_abortable(stop_event, 1.0)
                if not self._dismiss_1and1_until_disappear(
                    use_foreground,
                    stop_event,
                    timeout_s=10.0,
                    log_tag=f"{log_tag}·小蜜蜂后1AND1",
                    require_seen=False,
                    require_click=False,
                ):
                    if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                        return False
                    self._emit(f"⚠️ [{log_tag}] 小蜜蜂后1AND1未完全清理，继续后续日常", "WARN")
            except Exception as exc:
                self._emit(f"⚠️ [{log_tag}] 小蜜蜂点击异常：{exc}", "WARN")
        elif bee_awarded:
            self._emit(f"⏭️ [{log_tag}] 本月已领取过小蜜蜂奖励，跳过小蜜蜂", "INFO")
        elif should_run_bee:
            self._emit(f"⚠️ [{log_tag}] 本月第{today_day}次签到需要小蜜蜂，但缺少日常.小蜜蜂区域，跳过", "WARN")
        else:
            self._emit(f"⏭️ [{log_tag}] 本月第{today_day}次签到不在28-31次，跳过小蜜蜂", "INFO")

        if self.regions.get("日常.关闭签到"):
            try:
                self._click_region("日常.关闭签到", use_foreground)
                self._sleep_abortable(stop_event, 0.3)
            except Exception:
                pass

        self._emit(f"⏭️ [{log_tag}] 暂时跳过尼尔冲经验；同步跳过尼尔流程里的第二次清包", "INFO")
        if not self._pre_daily_place_daily_six_pets(
            use_foreground,
            stop_event,
            log_tag=f"{log_tag}·日常六宠",
        ):
            return False
        if not self._pre_daily_follow_pet_one_after_daily_six_pets(
            use_foreground,
            stop_event,
            log_tag=f"{log_tag}·日常跟随",
        ):
            return False
        if not self._pre_daily_run_script_if_present(
            "接受任务",
            use_foreground,
            required=True,
            log_tag=f"{log_tag}·接受任务",
        ):
            return False
        self._emit(f"✅ [{log_tag}] 完成", "SUCCESS")
        return True

    def run_pre_daily_ocean_energy_handoff(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
    ) -> bool:
        """预选前置后进入一键日常方案1起点。"""
        log_tag = "预选前置·去日常"
        if stop_event.is_set() or getattr(self.bot, "stop_current", False):
            return False
        expected_map_id = 20
        to_start_cursor = kernel_cursor()
        ok = self._pre_daily_run_script_if_present(
            "to日常2",
            use_foreground,
            required=True,
            log_tag=log_tag,
        )
        if not ok:
            return False
        last_map_id, has_newNPC = self._wait_after_to_then_check_last_map_and_newnpc(
            expected_map_id,
            stop_event,
            timeout_s=45.0,
            log_tag=log_tag,
            start_cursor=to_start_cursor,
        )
        if last_map_id != expected_map_id or not has_newNPC:
            self._emit(
                f"❌ [{log_tag}] 地图门控失败：map={last_map_id}，期望={expected_map_id}，newNpc={has_newNPC}",
                "ERROR",
            )
            return False
        self._emit(f"✅ [{log_tag}] 已到方案1起点：map{expected_map_id}+NewNPC", "SUCCESS")
        return True

    def run_refresh_login_until_map(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
        *,
        max_retries: int = 3,
        include_base_and_map_gate: bool = False,
    ) -> bool:
        """Run refresh login until a map signal is detected."""
        retries = 0
        while retries <= max_retries:
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return False
            step1 = self._step1_trinity_clicks_and_wait_login_swf(
                use_foreground=use_foreground,
                log_prefix="刷新登录",
                stop_event=stop_event,
            )
            if step1 == "stopped":
                return False
            if step1 != "login":
                retries += 1
                self._emit(
                    f"[刷新登录] 步骤1未进入 Login.swf（结果={step1}），重试 {retries}/{max_retries}",
                    "WARN",
                )
                continue
            ok2 = self._run_full_refresh_login_pipeline(
                use_foreground=use_foreground,
                stop_event=stop_event,
                log_prefix="刷新登录",
                include_base_and_map_gate=include_base_and_map_gate,
            )
            if ok2:
                return True
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return False
            retries += 1
            self._emit(
                f"[刷新登录] 步骤2失败，重试 {retries}/{max_retries}",
                "WARN",
            )
        return False

    def _execute_refresh_flow_and_wait_login(self, profile: WildCaptureProfile, use_foreground: bool, stop_event: threading.Event, retry_count: int = 0, max_retries: Optional[int] = None) -> bool:
        """Run one top-level refresh reconnect request (dashboard compatibility)."""
        return self._execute_refresh_reconnect(
            profile=profile,
            use_foreground=use_foreground,
            stop_event=stop_event,
            is_capture_verify_four=False,
            reason="刷新流程",
            retry_count=0,
            max_retries=max_retries,
            is_retry=False,
        )

    def _handle_stage3_round_timeout_reconnect(
        self,
        profile: WildCaptureProfile,
        use_foreground: bool,
        stop_event: threading.Event,
        is_nieo: bool = False,
    ) -> bool:
        """Handle reconnect after a Stage3 round timeout."""
        if getattr(self._unified_framework, "_stage3_exit_reason", None) != "round_timeout":
            return False
        reason = "回合超时60s重连"
        try:
            pre_path = self._save_client_screenshot(f"{reason}前", category="round_timeout")
            if pre_path:
                self._emit(f"[{reason}] 重连前截图已保存：{pre_path}", "INFO")
        except Exception as e:
            self._emit(f"[{reason}] 重连前截图失败：{e}，继续流程", "WARN")
        self._emit(f"战斗触发 {reason}，请求重启当前模式", "WARN")
        self._is_scanning_steady_state = False
        self._is_in_battle = False
        self._is_recovering = False
        if self.bot:
            self.bot.stop_current = False
            self._emit(f"[{reason}] 重连前已清除 stop_current", "INFO")

        # Record the timeout battle before reconnecting.
        try:
            ubf = self._unified_framework
            cycle_mode, cycle_tiers = self._capsule_cycle_log_fields()
            enemy_ids = self._enemy_pet_ids_for_battle_csv(profile)
            pend = getattr(self, "_pending_battle_csv_id", None)
            if pend and getattr(self, "_battle_logger", None):
                ok = self._battle_logger.log_battle_end(
                    pend,
                    enemy_pet_ids=enemy_ids,
                    total_rounds=ubf._round_idx if ubf else 0,
                    result="round_timeout",
                    battle_duration_s=ubf._battle_duration if ubf else 0.0,
                    reconnect_reason=reason,
                    capsule_counts=ubf._battle_capsule_counts if ubf else {},
                    capsule_cycle_mode=cycle_mode,
                    capsule_cycle_tiers=cycle_tiers,
                )
                if not ok:
                    self._battle_logger.log_battle(
                        enemy_pet_ids=enemy_ids,
                        total_rounds=ubf._round_idx if ubf else 0,
                        result="round_timeout",
                        battle_duration_s=ubf._battle_duration if ubf else 0.0,
                        reconnect_reason=reason,
                        capsule_counts=ubf._battle_capsule_counts if ubf else {},
                        capsule_cycle_mode=cycle_mode,
                        capsule_cycle_tiers=cycle_tiers,
                    )
                self._pending_battle_csv_id = None
            elif getattr(self, "_battle_logger", None):
                self._battle_logger.log_battle(
                    enemy_pet_ids=enemy_ids,
                    total_rounds=ubf._round_idx if ubf else 0,
                    result="round_timeout",
                    battle_duration_s=ubf._battle_duration if ubf else 0.0,
                    reconnect_reason=reason,
                    capsule_counts=ubf._battle_capsule_counts if ubf else {},
                    capsule_cycle_mode=cycle_mode,
                    capsule_cycle_tiers=cycle_tiers,
                )
            self._emit(f"[{reason}] 已记录回合超时战斗日志", "INFO")
        except Exception:
            pass

        return self._request_mode_restart(stop_event, reason)

    def _execute_refresh_reconnect(
        self,
        profile: WildCaptureProfile,
        use_foreground: bool,
        stop_event: threading.Event,
        is_capture_verify_four: bool = False,
        reason: str = "刷新重连",
        retry_count: int = 0,
        max_retries: Optional[int] = None,
        is_retry: bool = False
    ) -> bool:
        """Run one bounded reconnect chain and report whether restart was prepared."""
        retry_limit = int(
            self.REFRESH_RECONNECT_MAX_RETRIES
            if max_retries is None
            else max(1, int(max_retries))
        )
        if retry_count >= retry_limit:
            self._emit(
                f"⚠️ [{reason}] 本轮重连达到上限 {retry_limit} 次，退出本轮并交给外层重启",
                "WARN",
            )
            self._reconnect_scripts_executing = False
            self._request_mode_restart(stop_event, reason)
            return False
        if is_capture_verify_four:
            self._emit(
                "[刷新重连] capture recovery failure only triggers reconnect; skip legacy verify-four",
                "INFO",
            )
            is_capture_verify_four = False

        current_mode_for_default = getattr(self, "_current_mode", None)
        if profile is DEFAULT_PROFILE_DUGULU:
            event_profile = getattr(self, "_event_pet_active_profile", None)
            if event_profile is not None:
                self._event_pet_trigger_reconnect(
                    event_profile,
                    use_foreground,
                    stop_event,
                    reason=f"刷新重连拦截-{reason}",
                )
                stop_event.set()
                self._emit(
                    "[刷新重连] current target is event pet; hand reconnect back to event flow",
                    "WARN",
                )
                return False

            if current_mode_for_default and current_mode_for_default.startswith("afk_"):
                self._emit(
                    f"[刷新重连] current mode={current_mode_for_default} has no wild profile; block DEFAULT_PROFILE_DUGULU",
                    "WARN",
                )
                stop_event.set()
                return False

            configured_profile = getattr(self, "_configured_nieo_profile", None)
            if configured_profile is not None:
                self._current_mode = f"nieo:{configured_profile.slug}"
            elif (
                current_mode_for_default in (
                    "shuangta",
                    "flash_pipi",
                    "eyeball",
                    "mantis",
                    "dugulu",
                    "xiaodouya",
                    "rare",
                )
                or (
                    isinstance(current_mode_for_default, str)
                    and current_mode_for_default.startswith("rare:")
                )
            ):
                try:
                    if isinstance(current_mode_for_default, str) and current_mode_for_default.startswith("rare:"):
                        slot = current_mode_for_default.split(":", 1)[1]
                    elif current_mode_for_default == "rare":
                        slot = getattr(self, "_rotation_rare_slot", "shuangta") or "shuangta"
                    else:
                        slot = current_mode_for_default
                    profile = self._resolve_rotation_rare_profile(slot)
                    self._emit(
                        f"[刷新重连] resolve default profile by current mode {current_mode_for_default} -> {profile.name}",
                        "WARN",
                    )
                except Exception as exc:
                    self._emit(
                        f"[刷新重连] 解析默认配置失败：{exc}；保留原配置",
                        "WARN",
                    )
            elif current_mode_for_default and current_mode_for_default.startswith("event_pet_"):
                self._emit(
                    f"[刷新重连] 当前模式={current_mode_for_default} 收到 DEFAULT_PROFILE_DUGULU，拒绝执行步骤3",
                    "WARN",
                )
                stop_event.set()
                return False

        # 鉁?闃查噸鍏ワ細浠呴樆姝㈡柊鐨勯娆¤皟鐢紙閫掑綊閲嶈瘯浠嶅厑璁革級
        if not is_retry:
            with self._refresh_reconnect_lock:
                if self._refresh_reconnect_executing:
                    self._emit(
                        f"⚠️ [{reason}] 已有标准刷新重连在执行；退出本次旧流程，不重复启动",
                        "WARN",
                    )
                    self._request_mode_restart(stop_event, f"{reason}-重连互斥冲突")
                    return False
                self._refresh_reconnect_executing = True

        try:
            is_map_entry_failure = "进入地图失败" in reason
            is_1and1_login_refresh = "normal-1and1" in reason or "1AND1" in reason

            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                if self._is_user_stop_requested(stop_event):
                    self._emit(f"[{reason}] 用户请求停止，取消刷新重连和自动重启", "WARN")
                    self._should_restart_after_reconnect = False
                    self._reconnect_scripts_executing = False
                    stop_event.set()
                    return False
                if is_map_entry_failure or is_1and1_login_refresh:
                    tag = "地图进入失败" if is_map_entry_failure else "1AND1登录"
                    self._emit(f"[{reason}] 检测到停止标记，但由{tag}触发重连，清除标记并继续", "INFO")
                    stop_event.clear()
                    if self.bot:
                        self.bot.stop_current = False
                else:
                    self._emit(f"[{reason}] 刷新重连前已请求停止", "WARN")
                    self._reconnect_scripts_executing = False
                    self._request_mode_restart(stop_event, f"{reason}-内部停止标记")
                    return False

            self._emit(f"[{reason}] 启动标准刷新重连流程", "WARN")

            # 鉁?閲嶈：在刷新娴佺▼鍓嶅叧闂?AND1监控（避免重连过程中1AND1鐩戞帶骞叉壈锛?
            self._stop_normal_1and1_monitoring()

            # 鉁?记录“本 run 鍥犻噸杩炵粨鏉熲€濈殑鍘熷洜锛堝啓鍏?battle_log 鏈€鍚庯紱鍚?run 鍙涓€娆★級
            try:
                if getattr(self, "_battle_logger", None):
                    bid = getattr(self, "_pending_battle_csv_id", None)
                    self._battle_logger.log_reconnect_marker_once(
                        reason=reason, flush_pending_battle_id=bid
                    )
                    self._pending_battle_csv_id = None
            except Exception:
                pass

            try:
                self._emit(f"[{reason}] 刷新重连：尝试删除游戏tmp", "INFO")
                self._try_delete_game_tmp_dir(log_tag=reason)
            except Exception:
                pass

            # 鉁?鍓嶅彴鍖栨父鎴忕獥鍙ｏ紙涓嶈嚜鍔ㄦ渶澶у寲锛?
            import win32gui
            if window_manager.find_window() and window_manager.hwnd:
                try:
                    win32gui.SetForegroundWindow(window_manager.hwnd)
                except Exception:
                    pass

            # Step1锛氳缃獥 + 鍚庡彴刷新锛堟棤淇濆瓨锛? 绛?Login（与「Step2 绋嬪簭鍖栥€嶅垎绂伙紝閬垮厤涓庨噸杩?to 闃舵娣锋穯锛?
            step1_res = self._step1_trinity_clicks_and_wait_login_swf(
                use_foreground, reason, stop_event=None
            )
            if step1_res == "trinity_fail":
                self._emit(f"[{reason}] 刷新UI点击失败，退出本轮重连", "WARN")
                self._request_mode_restart(stop_event, reason)
                return False
            if step1_res == "stopped":
                self._reconnect_scripts_executing = False
                self._request_mode_restart(stop_event, f"{reason}-刷新步骤停止")
                return False
            if step1_res == "no_login":
                self._emit(
                    f"[{reason}] {self.REFRESH_LOGIN_WAIT_SEC:.0f}s 内未检测到登录信号，退出本轮重连",
                    "WARN",
                )
                self._request_mode_restart(stop_event, reason)
                return False
            self._emit(
                f"[步骤2-{reason}] 开始程序化登录至基地/map{self.MAP_ID_AFTER_LOGIN}门控",
                "INFO",
            )
            import threading
            reconnect_stop_event = threading.Event()
            actual_retry_count = retry_count
            actual_max_retries = retry_limit

            if not self._run_full_refresh_login_pipeline(
                use_foreground,
                reconnect_stop_event,
                reason,
                include_base_and_map_gate=True,
                force_molecule_converter=self._rotation_step1_force_molecule_converter(),
            ):
                self._emit(f"[{reason}] 步骤2程序化登录/基地门控失败，退出本轮重连", "WARN")
                self._request_mode_restart(stop_event, reason)
                return False

            self._mark_refresh_pipeline_map500001_gate_done()
            if not self._run_nono_fusion_after_mode_reconnect(
                use_foreground,
                reconnect_reason=reason,
            ):
                self._emit(f"[{reason}] 融合重连检查失败，重新刷新", "WARN")
                return self._execute_refresh_reconnect(
                    profile,
                    use_foreground,
                    stop_event,
                    is_capture_verify_four=is_capture_verify_four,
                    reason=reason,
                    retry_count=retry_count + 1,
                    max_retries=max_retries,
                    is_retry=True,
                )
            self._emit(
                f"[步骤3-{reason}] 步骤2完成，开始当前模式的to脚本/背包阶段",
                "INFO",
            )
            if getattr(self, "_is_rotation_mode", False):
                seg = self._rotation_calendar_segment_for_swf_sync()
                self._sync_swf_for_rotation_segment(
                    seg, log_tag=f"{reason}-轮换-刷新重连Step3前",
                )
            current_mode = getattr(self, "_current_mode", None)
            profile_name_lower = profile.name.lower()
            configured_prof = getattr(self, "_configured_nieo_profile", None)
            if configured_prof is not None or (
                isinstance(current_mode, str)
                and current_mode.startswith("nieo:")
                and current_mode != "nieo"
            ):
                self._execute_reconnect_scripts_for_configured_nieo(
                    use_foreground,
                    reconnect_stop_event,
                    retry_count=actual_retry_count,
                    max_retries=actual_max_retries,
                    is_capture_verify_four=is_capture_verify_four,
                )
            elif current_mode == "nieo":
                self._execute_reconnect_scripts_for_nieo(
                    use_foreground,
                    reconnect_stop_event,
                    retry_count=actual_retry_count,
                    max_retries=actual_max_retries,
                    is_capture_verify_four=is_capture_verify_four,
                )
            elif current_mode == "pure_energy":
                self._execute_reconnect_scripts_for_pure_energy(
                    use_foreground,
                    reconnect_stop_event,
                    retry_count=actual_retry_count,
                    max_retries=actual_max_retries,
                    is_capture_verify_four=is_capture_verify_four,
                )
            elif current_mode == "shuangta" or (current_mode is None and "双塔" in profile_name_lower):
                self._execute_reconnect_scripts_for_shuangta(
                    profile,
                    use_foreground,
                    reconnect_stop_event,
                    retry_count=actual_retry_count,
                    max_retries=actual_max_retries,
                    is_capture_verify_four=is_capture_verify_four,
                )
            elif current_mode == "dugulu" or (current_mode is None and "嘟咕噜" in profile_name_lower):
                self._execute_reconnect_scripts_for_dugulu(
                    profile,
                    use_foreground,
                    reconnect_stop_event,
                    retry_count=actual_retry_count,
                    max_retries=actual_max_retries,
                    is_capture_verify_four=is_capture_verify_four,
                )
            elif current_mode in ("flash_pipi", "eyeball") or (
                current_mode is None
                and ("闪光皮皮" in profile_name_lower or '眼球' in profile_name_lower)
            ):
                self._execute_reconnect_scripts_for_rare_pet(
                    profile,
                    use_foreground,
                    reconnect_stop_event,
                    retry_count=actual_retry_count,
                    max_retries=actual_max_retries,
                )
            else:
                self._execute_reconnect_scripts(
                    profile, use_foreground, reconnect_stop_event, is_capture_verify_four=is_capture_verify_four
                )

            if not getattr(self, "_should_restart_after_reconnect", False):
                self._emit(
                    f"[{reason}] 重连步骤未生成重启请求，补交给外层控制器",
                    "WARN",
                )
                return self._request_mode_restart(stop_event, f"{reason}-步骤3未完成")
            stop_event.set()
            self._emit(f"🐞 [{reason}] 重连脚本已触发，当前 run 设置 stop_event 并退出", "DEBUG")
            return True

        except Exception as e:
            self._emit(f"❌ [{reason}] 执行异常: {e}", "ERROR")
            import traceback
            self._emit(f"📋 异常详情: {traceback.format_exc()}", "ERROR")
            self._reconnect_scripts_executing = False
            self._request_mode_restart(stop_event, f"{reason}-重连异常")
            return False
        finally:
            if not is_retry:
                with self._refresh_reconnect_lock:
                    self._refresh_reconnect_executing = False
                # The reconnect chain is synchronous.  Once the owner call returns,
                # no caller should keep waiting on a stale script-running flag.
                self._reconnect_scripts_executing = False

    def _reconnect_pre_hengmu_actions(self, use_foreground: bool, log_prefix: str) -> None:
        """Run common actions before the Hengmu script starts."""
        time.sleep(0.8)

        try:
            warehouse_open_key = "精灵仓库.打开"
            warehouse_open_region = self.regions.get(warehouse_open_key)
            if warehouse_open_region:
                self._emit(f"[{log_prefix}] click 精灵仓库.打开", "INFO")
                self._hide_newnpc_multi_4_for_warehouse(log_prefix)
                self._click_region(warehouse_open_region, use_foreground)
                time.sleep(1.0)
            else:
                self._emit(f"[{log_prefix}] 缺少 精灵仓库.打开，跳过", "WARN")
        except Exception as e:
            self._emit(f"[{log_prefix}] 点击 精灵仓库.打开 失败：{e}，继续", "WARN")

        try:
            ground_category_key = "精灵仓库.地面系"
            ground_category_region = self.regions.get(ground_category_key)
            if ground_category_region:
                self._emit(f"[{log_prefix}] click 精灵仓库.地面系", "INFO")
                self._click_region(ground_category_region, use_foreground)
                time.sleep(0.8)
            else:
                self._emit(f"[{log_prefix}] 缺少 精灵仓库.地面系，跳过", "WARN")
        except Exception as e:
            self._emit(f"[{log_prefix}] 点击 精灵仓库.地面系 失败：{e}，继续", "WARN")

        try:
            hengmu_region = self.regions.get("登录.亨姆")
            if hengmu_region:
                self._emit(f"[{log_prefix}] click 登录.亨姆", "INFO")
                self._click_region(hengmu_region, use_foreground)
                time.sleep(0.5)
            else:
                self._emit(f"[{log_prefix}] 缺少 登录.亨姆，跳过", "WARN")
        except Exception as e:
            self._emit(f"[{log_prefix}] 点击 登录.亨姆 失败：{e}", "WARN")

        self._keep_newnpc_multi_4_hidden(log_prefix)

    def _set_nieo_family_reconnect_companion(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
    ) -> bool:
        """Set the reconnect companion, honoring modes that defer cyan until A."""
        cyan_requested = bool(
            getattr(self, "_nieo_follow_cyan", False)
            or getattr(self, "_rotation_nieo_follow_cyan", False)
        )
        defer_cyan = bool(
            getattr(self, "_nieo_defer_cyan_until_a_active", False)
        )
        follow_cyan = bool(cyan_requested and not defer_cyan)
        self._emit(
            "[重连脚本-跟随] "
            + ("当前模式到A图前保持紫色：" if defer_cyan else "继承当前设置：")
            + ("跟随青色" if follow_cyan else "跟随紫色"),
            "INFO",
        )
        return self._rotation_step4_set_companion(
            use_foreground,
            stop_event,
            follow_cyan=follow_cyan,
        )

    def _execute_reconnect_scripts_for_nieo(self, use_foreground: bool, stop_event: Optional[threading.Event] = None, retry_count: int = 0, max_retries: Optional[int] = None, is_capture_verify_four: bool = False) -> None:
        """Run Step3 reconnect scripts for Nieo."""
        if stop_event and stop_event.is_set():
            self._emit("[重连脚本-尼奥] 已停止", "WARN")
            return

        if getattr(self.bot, "stop_current", False):
            self._emit("[重连脚本-尼奥] stop_current 已设置，停止重试", "WARN")
            return

        self._reconnect_scripts_executing = True

        try:
            self._emit(
                "[Step3-重连脚本-尼奥] 开始步骤3（登录和基地门控后）",
                "SYSTEM",
            )

            # 妫€鏌ユ槸鍚︽湁daily_runner
            if not hasattr(self.bot, "daily_runner"):
                self._emit("[重连脚本-尼奥] 缺少 daily_runner，无法执行脚本", "WARN")
                return

            daily_runner = self.bot.daily_runner
            bg_mode = not use_foreground

            if not self._consume_reconnect_core_map500001_skip_if_set():
                login_map_id, login_has_newNPC = self._check_last_map_and_newnpc(self.MAP_ID_AFTER_LOGIN, timeout_s=10.0)
                if login_map_id != self.MAP_ID_AFTER_LOGIN or not login_has_newNPC:
                    max_retries_str = f"/{max_retries}" if max_retries is not None else ""
                    if login_map_id is not None and login_map_id != self.MAP_ID_AFTER_LOGIN:
                        self._emit(f"[重连脚本-尼奥] 登录后地图={login_map_id}，期望={self.MAP_ID_AFTER_LOGIN}；重试 {retry_count + 1}{max_retries_str}", "WARN")
                    else:
                        self._emit(f"[重连脚本-尼奥] 登录后基地门控缺失（map={login_map_id}, newNpc={login_has_newNPC}）；重试 {retry_count + 1}{max_retries_str}", "WARN")
                    actual_stop_event = stop_event if stop_event is not None else threading.Event()
                    self._request_mode_restart(actual_stop_event, "重连脚本-尼奥-基地地图门控失败")
                    return
            else:
                self._emit("[重连脚本-尼奥] 已跳过完整 map500001 复查", "INFO")

            temp_stop_event = threading.Event()
            self._emit("[Step3-重连脚本-尼奥] 准备清包取宠并设置跟随", "INFO")
            if not self._rotation_clear_backpack_and_pick_or_skip(
                "nieo",
                use_foreground,
                temp_stop_event,
                log_tag="重连脚本-尼奥",
                expected_party_ids=self._pickmode_expected_party_ids(),
            ):
                self._emit("[重连脚本-尼奥] 清包取宠失败，重新刷新", "WARN")
                actual_stop_event = stop_event if stop_event is not None else threading.Event()
                self._request_mode_restart(actual_stop_event, "重连脚本-尼奥-清包取宠失败")
                return
            if not self._set_nieo_family_reconnect_companion(
                use_foreground, temp_stop_event
            ):
                self._emit("[重连脚本-尼奥] 设置跟随失败，重新刷新", "WARN")
                actual_stop_event = stop_event if stop_event is not None else threading.Event()
                self._request_mode_restart(actual_stop_event, "重连脚本-尼奥-设置跟随失败")
                return

            if daily_runner.run_single_script("to尼奥", bg_mode=bg_mode):
                self._emit("[重连脚本-尼奥] to尼奥.json 执行完成", "SUCCESS")
            else:
                self._emit("[重连脚本-尼奥] to尼奥.json 执行失败", "WARN")

            self._emit("[重连脚本-尼奥] 重连脚本完成", "SUCCESS")

            time.sleep(2.0)

            if self.bot:
                self.bot.stop_current = False
                self._emit("[重连脚本-尼奥] 已清除 stop_current", "SUCCESS")

            # map 11 + newNPC
            last_map_id, has_newNPC = self._check_last_map_and_newnpc(11, timeout_s=10.0)

            if last_map_id == 11 and has_newNPC:
                self._emit("[重连脚本-尼奥] 已检测到 map 11 + newNpc", "SUCCESS")

                self._reconnect_scripts_executing = False

                self._petswf_to_petitem_min_duration = None
                self._petswf_to_petitem_current_duration = None
                if self._unified_framework and hasattr(self._unified_framework, '_petswf_to_petitem_durations'):
                    self._unified_framework._petswf_to_petitem_durations.clear()
                self._emit("[重连脚本-尼奥] 已重置时长计数", "INFO")

                self._should_restart_after_reconnect = True
                self._emit("[重连脚本-尼奥] 已设置重启标记", "INFO")
                return
            else:
                max_retries_str = f"/{max_retries}" if max_retries is not None else ""
                if last_map_id is not None and last_map_id != 11:
                    self._emit(f"[重连脚本-尼奥] 地图错误：当前 {last_map_id}，期望 11；重试 {retry_count + 1}{max_retries_str}", "WARN")
                else:
                    self._emit(f"[重连脚本-尼奥] 未检测到 map 11 + newNpc（map={last_map_id}, newNpc={has_newNPC}）；重试 {retry_count + 1}{max_retries_str}", "WARN")

                actual_stop_event = stop_event if stop_event is not None else threading.Event()
                self._request_mode_restart(actual_stop_event, "重连脚本-尼奥-map11门控失败")
                return

        except Exception as e:
            self._emit(f"[重连脚本-尼奥] 异常：{e}", "ERROR")
            import traceback
            self._emit(traceback.format_exc(), "ERROR")
        finally:
            self._reconnect_scripts_executing = False

    def _execute_reconnect_scripts_for_configured_nieo(
        self,
        use_foreground: bool,
        stop_event: Optional[threading.Event] = None,
        retry_count: int = 0,
        max_retries: Optional[int] = None,
        is_capture_verify_four: bool = False,
    ) -> None:
        """Run Step3 reconnect scripts for configured Nieo profiles."""
        prof = getattr(self, "_configured_nieo_profile", None)
        if prof is None:
            self._emit("[重连脚本-自定义尼奥] no profile; fallback to default Nieo", "WARN")
            self._execute_reconnect_scripts_for_nieo(
                use_foreground, stop_event, retry_count, max_retries, is_capture_verify_four
            )
            return

        if stop_event and stop_event.is_set():
            self._emit(f"[重连脚本-自定义尼奥/{prof.name}] 已停止", "WARN")
            return
        if getattr(self.bot, "stop_current", False):
            self._emit(f"[重连脚本-自定义尼奥/{prof.name}] stop_current 已设置，停止重试", "WARN")
            return

        to_script = (prof.to_script or f"to{prof.route_hint}").strip()
        expected_map = int(prof.map_a_id)
        tag = prof.name
        self._reconnect_scripts_executing = True
        try:
            self._emit(
                f"[Step3-重连脚本-自定义尼奥/{tag}] 开始：清包取宠 / {to_script} / map{expected_map} 校验",
                "SYSTEM",
            )
            if not hasattr(self.bot, "daily_runner"):
                self._emit(f"[重连脚本-自定义尼奥/{tag}] 缺少 daily_runner", "WARN")
                return
            daily_runner = self.bot.daily_runner
            bg_mode = not use_foreground
            if not self._consume_reconnect_core_map500001_skip_if_set():
                login_map_id, login_has_newNPC = self._check_last_map_and_newnpc(
                    self.MAP_ID_AFTER_LOGIN, timeout_s=10.0
                )
                if login_map_id != self.MAP_ID_AFTER_LOGIN or not login_has_newNPC:
                    actual_stop_event = stop_event if stop_event is not None else threading.Event()
                    self._request_mode_restart(
                        actual_stop_event,
                        f"重连脚本-自定义尼奥-{tag}-基地地图门控失败",
                    )
                    return
            temp_stop_event = threading.Event()
            if not self._rotation_clear_backpack_and_pick_or_skip(
                "nieo",
                use_foreground,
                temp_stop_event,
                log_tag=f"重连脚本-自定义尼奥/{tag}",
                expected_party_ids=self._pickmode_expected_party_ids(),
            ):
                actual_stop_event = stop_event if stop_event is not None else threading.Event()
                self._request_mode_restart(
                    actual_stop_event,
                    f"重连脚本-自定义尼奥-{tag}-清包取宠失败",
                )
                return
            if not self._set_nieo_family_reconnect_companion(
                use_foreground, temp_stop_event
            ):
                actual_stop_event = stop_event if stop_event is not None else threading.Event()
                self._request_mode_restart(
                    actual_stop_event,
                    f"重连脚本-自定义尼奥-{tag}-设置跟随失败",
                )
                return
            to_start_cursor = kernel_cursor()
            if daily_runner.run_single_script(to_script, bg_mode=bg_mode):
                self._emit(f"[重连脚本-自定义尼奥/{tag}] {to_script}.json 执行完成", "SUCCESS")
            else:
                self._emit(f"[重连脚本-自定义尼奥/{tag}] {to_script}.json 执行失败", "WARN")
            time.sleep(2.0)
            if self.bot:
                self.bot.stop_current = False
            special_gate = self._special_essence_gate_after_to(
                to_script,
                to_start_cursor,
                stop_event or threading.Event(),
                log_tag=f"重连脚本-自定义尼奥/{tag}",
            )
            if special_gate is False:
                self._request_mode_restart(
                    stop_event or threading.Event(),
                    f"重连脚本-自定义尼奥-{tag}-专用地图门控失败",
                )
                return

            if special_gate is True:
                last_map_id, map_ready = expected_map, True
                ready_signal = "专用地图门控"
            else:
                last_map_id, has_newNPC = self._check_last_map_and_newnpc(
                    expected_map, timeout_s=10.0
                )
                map_ready = bool(last_map_id == expected_map and has_newNPC)
                ready_signal = "newNpc"
            if map_ready:
                self._emit(
                    f"[重连脚本-自定义尼奥/{tag}] 已检测到 map {expected_map} + {ready_signal}",
                    "SUCCESS",
                )
                self._reconnect_scripts_executing = False
                self._petswf_to_petitem_min_duration = None
                self._petswf_to_petitem_current_duration = None
                if self._unified_framework and hasattr(
                    self._unified_framework, "_petswf_to_petitem_durations"
                ):
                    self._unified_framework._petswf_to_petitem_durations.clear()
                self._should_restart_after_reconnect = True
                self._emit(f"[重连脚本-自定义尼奥/{tag}] 已设置重启标记", "INFO")
                return
            max_retries_str = f"/{max_retries}" if max_retries is not None else ""
            self._emit(
                f"[重连脚本-自定义尼奥/{tag}] 地图门控失败（map={last_map_id}, npc={has_newNPC}）；"
                f"刷新重试 {retry_count + 1}{max_retries_str}",
                "WARN",
            )
            actual_stop_event = stop_event if stop_event is not None else threading.Event()
            self._request_mode_restart(
                actual_stop_event,
                f"重连脚本-自定义尼奥-{tag}-目标地图门控失败",
            )
        except Exception as e:
            self._emit(f"[重连脚本-自定义尼奥/{tag}] 异常：{e}", "ERROR")
            import traceback
            self._emit(traceback.format_exc(), "ERROR")
        finally:
            self._reconnect_scripts_executing = False

    def _execute_reconnect_scripts_for_pure_energy(
        self,
        use_foreground: bool,
        stop_event: Optional[threading.Event] = None,
        retry_count: int = 0,
        max_retries: Optional[int] = None,
        is_capture_verify_four: bool = False,
    ) -> None:
        """Run Step3 reconnect scripts for pure energy."""
        if stop_event and stop_event.is_set():
            self._emit("[重连脚本-纯净能量] 已停止", "WARN")
            return
        if getattr(self.bot, "stop_current", False):
            self._emit("[重连脚本-纯净能量] stop_current 已设置，停止重试", "WARN")
            return
        self._reconnect_scripts_executing = True
        try:
            self._emit(
                "[Step3-重连脚本-纯净能量] 开始：map500001 / 清包取宠 / to纯净能量 / map26 校验",
                "SYSTEM",
            )
            if not hasattr(self.bot, "daily_runner"):
                self._emit("[重连脚本-纯净能量] 缺少 daily_runner", "WARN")
                return
            daily_runner = self.bot.daily_runner
            bg_mode = not use_foreground
            if not self._consume_reconnect_core_map500001_skip_if_set():
                login_map_id, login_has_newNPC = self._check_last_map_and_newnpc(self.MAP_ID_AFTER_LOGIN, timeout_s=10.0)
                if login_map_id != self.MAP_ID_AFTER_LOGIN or not login_has_newNPC:
                    actual_stop_event = stop_event if stop_event is not None else threading.Event()
                    self._request_mode_restart(
                        actual_stop_event,
                        "重连脚本-纯净能量-基地地图门控失败",
                    )
                    return
            temp_stop_event = threading.Event()
            self._emit("[Step3-纯净能量] 准备清包取宠并设置跟随", "INFO")
            if not self._rotation_clear_backpack_and_pick_or_skip(
                "nieo",
                use_foreground,
                temp_stop_event,
                log_tag="重连脚本-纯净能量",
                expected_party_ids=self._pickmode_expected_party_ids(),
            ):
                actual_stop_event = stop_event if stop_event is not None else threading.Event()
                self._request_mode_restart(
                    actual_stop_event,
                    "重连脚本-纯净能量-清包取宠失败",
                )
                return
            if not self._set_nieo_family_reconnect_companion(
                use_foreground, temp_stop_event
            ):
                actual_stop_event = stop_event if stop_event is not None else threading.Event()
                self._request_mode_restart(
                    actual_stop_event,
                    "重连脚本-纯净能量-设置跟随失败",
                )
                return
            if daily_runner.run_single_script("to纯净能量", bg_mode=bg_mode):
                self._emit("[重连脚本-纯净能量] to纯净能量 执行完成", "SUCCESS")
            else:
                self._emit("[重连脚本-纯净能量] to纯净能量 执行失败", "WARN")
            time.sleep(2.0)
            if self.bot:
                self.bot.stop_current = False
            last_map_id, has_newNPC = self._check_last_map_and_newnpc(26, timeout_s=10.0)
            if last_map_id == 26 and has_newNPC:
                self._emit("[重连脚本-纯净能量] 已检测到 map 26 + newNpc", "SUCCESS")
                self._reconnect_scripts_executing = False
                self._petswf_to_petitem_min_duration = None
                self._petswf_to_petitem_current_duration = None
                if self._unified_framework and hasattr(self._unified_framework, "_petswf_to_petitem_durations"):
                    self._unified_framework._petswf_to_petitem_durations.clear()
                self._should_restart_after_reconnect = True
                self._emit("[重连脚本-纯净能量] 已设置重启标记", "INFO")
                return
            max_retries_str = f"/{max_retries}" if max_retries is not None else ""
            self._emit(
                f"[重连脚本-纯净能量] 地图门控失败（map={last_map_id}, npc={has_newNPC}）；"
                f"刷新重试 {retry_count + 1}{max_retries_str}",
                "WARN",
            )
            actual_stop_event = stop_event if stop_event is not None else threading.Event()
            self._request_mode_restart(
                actual_stop_event,
                "重连脚本-纯净能量-map26门控失败",
            )
        except Exception as e:
            self._emit(f"[重连脚本-纯净能量] 异常：{e}", "ERROR")
            import traceback
            self._emit(traceback.format_exc(), "ERROR")
        finally:
            self._reconnect_scripts_executing = False

    def _execute_reconnect_scripts_for_shuangta(self, profile: WildCaptureProfile, use_foreground: bool, stop_event: Optional[threading.Event] = None, retry_count: int = 0, max_retries: Optional[int] = None, is_capture_verify_four: bool = False) -> None:
        """Run Step3 reconnect scripts for Shuangta."""
        if stop_event and stop_event.is_set():
            self._emit("[重连脚本] 已停止", "WARN")
            return

        if getattr(self.bot, "stop_current", False):
            self._emit("[重连脚本] stop_current 已设置，停止重试", "WARN")
            return

        self._execute_reconnect_scripts_core(profile, use_foreground, stop_event, retry_count, max_retries, is_capture_verify_four=is_capture_verify_four)

    def _execute_reconnect_scripts_for_dugulu(self, profile: WildCaptureProfile, use_foreground: bool, stop_event: Optional[threading.Event] = None, retry_count: int = 0, max_retries: Optional[int] = None, is_capture_verify_four: bool = False) -> None:
        """Run Step3 reconnect scripts for Dugulu."""
        if stop_event and stop_event.is_set():
            self._emit("[重连脚本] 已停止", "WARN")
            return

        if getattr(self.bot, "stop_current", False):
            self._emit("[重连脚本] stop_current 已设置，停止重试", "WARN")
            return

        self._execute_reconnect_scripts_core(profile, use_foreground, stop_event, retry_count, max_retries, is_capture_verify_four=is_capture_verify_four)

    def _execute_reconnect_scripts_for_rare_pet(
        self,
        profile: WildCaptureProfile,
        use_foreground: bool,
        stop_event: Optional[threading.Event] = None,
        retry_count: int = 0,
        max_retries: Optional[int] = None,
    ) -> None:
        """Run Step3 reconnect scripts for rare pets."""
        config = self._get_rare_pet_reconnect_config(profile)
        if not config:
            self._emit(f"[重连脚本-稀有精灵] 无法识别方案={profile.name}，跳过", "WARN")
            return

        to_script_name, expected_map_id, mode_key = config
        mode_name = "闪光皮皮" if mode_key == "flash_pipi" else "眼球"

        if stop_event and stop_event.is_set():
            self._emit(f"[重连脚本-{mode_name}] 已停止", "WARN")
            return

        if getattr(self.bot, "stop_current", False):
            self._emit(f"[重连脚本-{mode_name}] stop_current 已设置，停止重试", "WARN")
            return

        self._reconnect_scripts_executing = True

        try:
            self._emit(
                f"[Step3-重连脚本-{mode_name}] 开始步骤3：门控 / 清包取宠 / {to_script_name}.json / 地图校验",
                "SYSTEM",
            )

            if not hasattr(self.bot, "daily_runner"):
                self._emit(f"[重连脚本-{mode_name}] 缺少 daily_runner，无法执行脚本", "WARN")
                return

            daily_runner = self.bot.daily_runner
            bg_mode = not use_foreground

            if not self._consume_reconnect_core_map500001_skip_if_set():
                login_map_id, login_has_newNPC = self._check_last_map_and_newnpc(self.MAP_ID_AFTER_LOGIN, timeout_s=10.0)
                if login_map_id != self.MAP_ID_AFTER_LOGIN or not login_has_newNPC:
                    if login_map_id is not None and login_map_id != self.MAP_ID_AFTER_LOGIN:
                        self._emit(f"[重连脚本-{mode_name}] 登录后地图={login_map_id}，期望={self.MAP_ID_AFTER_LOGIN}；重新刷新", "WARN")
                    else:
                        self._emit(f"[重连脚本-{mode_name}] 登录后地图门控缺失（map={login_map_id}, newNpc={login_has_newNPC}）；重新刷新", "WARN")
                    actual_stop_event = stop_event if stop_event is not None else threading.Event()
                    self._request_mode_restart(
                        actual_stop_event,
                        f"重连脚本-{mode_name}-基地地图门控失败",
                    )
                    return
            else:
                self._emit(
                    f"[重连脚本-{mode_name}] 已跳过完整 map500001 复查",
                    "INFO",
                )

            temp_stop_event = threading.Event()
            self._emit(f"[Step3-重连脚本-{mode_name}] 准备清包取宠并设置跟随", "INFO")
            if not self._rotation_clear_backpack_and_pick_or_skip(
                "shuangta",
                use_foreground,
                temp_stop_event,
                log_tag=f"重连脚本-{mode_name}",
                expected_party_ids=self._pickmode_expected_party_ids(),
            ):
                self._emit(f"[重连脚本-{mode_name}] 清包取宠失败，重新刷新", "WARN")
                actual_stop_event = stop_event if stop_event is not None else threading.Event()
                self._request_mode_restart(
                    actual_stop_event,
                    f"重连脚本-{mode_name}-清包取宠失败",
                )
                return
            if not self._rotation_step4_set_companion(use_foreground, temp_stop_event):
                self._emit(f"[重连脚本-{mode_name}] 设置跟随失败，重新刷新", "WARN")
                actual_stop_event = stop_event if stop_event is not None else threading.Event()
                self._request_mode_restart(
                    actual_stop_event,
                    f"重连脚本-{mode_name}-设置跟随失败",
                )
                return

            if daily_runner.run_single_script(to_script_name, bg_mode=bg_mode):
                self._emit(f"[重连脚本-{mode_name}] {to_script_name}.json 执行完成", "SUCCESS")
            else:
                self._emit(f"[重连脚本-{mode_name}] {to_script_name}.json 执行失败", "WARN")

            self._emit(f"[重连脚本-{mode_name}] 重连脚本完成", "SUCCESS")

            time.sleep(2.0)
            if self.bot:
                self.bot.stop_current = False
                self._emit(f"[重连脚本-{mode_name}] 已清除 stop_current", "SUCCESS")

            gate_z_literal = wild_rare_map_gate_zero_literal_swf_ids(profile)
            last_map_id, has_newNPC = self._check_last_map_and_newnpc(
                expected_map_id,
                timeout_s=10.0,
                accepted_map_ids=gate_z_literal if gate_z_literal else None,
            )

            if (
                self._kernel_map_matches_profile_expectation(
                    profile, last_map_id, expected_map_id
                )
                and has_newNPC
            ):
                self._emit(f"[重连脚本-{mode_name}] 地图门控通过：map={last_map_id}+newNpc", "SUCCESS")
                self._on_map_zero_gate_passed()
                self._reconnect_scripts_executing = False
                self._petswf_to_petitem_min_duration = None
                self._petswf_to_petitem_current_duration = None
                if self._unified_framework and hasattr(self._unified_framework, '_petswf_to_petitem_durations'):
                    self._unified_framework._petswf_to_petitem_durations.clear()
                self._emit(f"[重连脚本-{mode_name}] 已重置时长计数", "INFO")
                self._should_restart_after_reconnect = True
                self._emit(f"[重连脚本-{mode_name}] 已设置重启标记", "INFO")
                if stop_event is not None:
                    stop_event.set()
                    self._emit(f"[重连脚本-{mode_name}] current stop_event set", "DEBUG")
                main_ev = getattr(self, '_main_run_stop_event_for_reconnect', None)
                if main_ev is not None:
                    main_ev.set()
                    self._emit(f"[重连脚本-{mode_name}] main run stop_event set", "DEBUG")
                    setattr(self, '_main_run_stop_event_for_reconnect', None)
                return
            else:
                max_retries_str = f"/{max_retries}" if max_retries is not None else ""
                literal_desc = (
                    "|".join(str(x) for x in sorted(gate_z_literal))
                    if gate_z_literal
                    else str(expected_map_id)
                )
                if last_map_id is not None and not self._kernel_map_matches_profile_expectation(
                    profile, last_map_id, expected_map_id
                ):
                    self._emit(f"[重连脚本-{mode_name}] 检测到 map={last_map_id}，期望零位={literal_desc}；重试 {retry_count + 1}{max_retries_str}", "WARN")
                else:
                    self._emit(f"[重连脚本-{mode_name}] 零位地图门控未完成（零位={literal_desc}, map={last_map_id}, newNpc={has_newNPC}）；重试 {retry_count + 1}{max_retries_str}", "WARN")
                actual_stop_event = stop_event if stop_event is not None else threading.Event()
                self._request_mode_restart(
                    actual_stop_event,
                    f"重连脚本-{mode_name}-目标地图门控失败",
                )
                return

        except Exception as e:
            self._emit(f"[重连脚本-{mode_name}] 异常：{e}", "ERROR")
            import traceback
            self._emit(traceback.format_exc(), "ERROR")
        finally:
            self._reconnect_scripts_executing = False

    def _execute_reconnect_scripts_core(self, profile: WildCaptureProfile, use_foreground: bool, stop_event: Optional[threading.Event] = None, retry_count: int = 0, max_retries: Optional[int] = None, is_capture_verify_four: bool = False) -> None:
        """Run generic Step3 reconnect scripts for profiles with to-script map checks."""
        self._reconnect_scripts_executing = True

        try:
            to_script_name = self._get_to_script_name(profile)
            if not to_script_name:
                self._emit(f"[重连脚本] 无法确定 to 脚本（profile={profile.name}），跳过", "WARN")
                return

            self._emit(
                f"[Step3-重连脚本-{profile.name}] 开始步骤3：map{self.MAP_ID_AFTER_LOGIN} 门控 / 清包取宠 / {to_script_name}.json / 地图校验",
                "SYSTEM",
            )

            if not hasattr(self.bot, "daily_runner"):
                self._emit("[重连脚本] 缺少 daily_runner，无法执行脚本", "WARN")
                return

            daily_runner = self.bot.daily_runner
            bg_mode = not use_foreground

            if not self._consume_reconnect_core_map500001_skip_if_set():
                login_map_id, login_has_newNPC = self._check_last_map_and_newnpc(self.MAP_ID_AFTER_LOGIN, timeout_s=10.0)
                if login_map_id != self.MAP_ID_AFTER_LOGIN or not login_has_newNPC:
                    max_retries_str = f"/{max_retries}" if max_retries is not None else ""
                    if login_map_id is not None and login_map_id != self.MAP_ID_AFTER_LOGIN:
                        self._emit(f"[重连脚本] 登录后地图={login_map_id}，期望={self.MAP_ID_AFTER_LOGIN}；重试 {retry_count + 1}{max_retries_str}", "WARN")
                    else:
                        self._emit(f"[重连脚本] 登录后门控缺失（map={login_map_id}, newNpc={login_has_newNPC}）；重试 {retry_count + 1}{max_retries_str}", "WARN")
                    actual_stop_event = stop_event if stop_event is not None else threading.Event()
                    self._request_mode_restart(
                        actual_stop_event,
                        f"重连脚本-{profile.name}-基地地图门控失败",
                    )
                    return
            else:
                self._emit("[重连脚本] 已跳过完整 map500001 复查", "INFO")

            rotation_mode = self._get_rotation_place_pets_mode(profile)
            temp_stop_event = threading.Event()
            self._emit(f"[Step3-重连脚本] 准备清包取宠并设置跟随（模式={rotation_mode}）", "INFO")
            if not self._rotation_clear_backpack_and_pick_or_skip(
                rotation_mode,
                use_foreground,
                temp_stop_event,
                log_tag="重连脚本",
                expected_party_ids=self._pickmode_expected_party_ids(),
            ):
                self._emit("[重连脚本] 清包取宠失败，重新刷新", "WARN")
                actual_stop_event = stop_event if stop_event is not None else threading.Event()
                self._request_mode_restart(
                    actual_stop_event,
                    f"重连脚本-{profile.name}-清包取宠失败",
                )
                return
            if not self._rotation_step4_set_companion(use_foreground, temp_stop_event):
                self._emit("[重连脚本] 设置跟随失败，重新刷新", "WARN")
                actual_stop_event = stop_event if stop_event is not None else threading.Event()
                self._request_mode_restart(
                    actual_stop_event,
                    f"重连脚本-{profile.name}-设置跟随失败",
                )
                return

            to_start_cursor = kernel_cursor()
            if daily_runner.run_single_script(to_script_name, bg_mode=bg_mode):
                self._emit(f"[重连脚本] {to_script_name}.json 执行完成", "SUCCESS")
            else:
                self._emit(f"[重连脚本] {to_script_name}.json 执行失败", "WARN")

            self._emit("[重连脚本] 重连脚本完成", "SUCCESS")

            profile_name_lower = profile.name.lower()
            if self._is_wusuo_profile(profile):
                if self._wait_wusuo_map325_and_probe_after_to(
                    to_start_cursor,
                    stop_event or threading.Event(),
                    timeout_s=5.0,
                ):
                    self._emit("[重连脚本] 乌索零位地图门控通过：map325 + 白探针变非白", "SUCCESS")
                    self._on_map_zero_gate_passed()
                    self._reconnect_scripts_executing = False
                    self._petswf_to_petitem_min_duration = None
                    self._petswf_to_petitem_current_duration = None
                    if self._unified_framework and hasattr(self._unified_framework, '_petswf_to_petitem_durations'):
                        self._unified_framework._petswf_to_petitem_durations.clear()
                    self._emit("[重连脚本] 已重置时长计数", "INFO")
                    self._should_restart_after_reconnect = True
                    self._emit("[重连脚本] 已为乌索模式设置重启标记", "INFO")
                    if stop_event is not None:
                        stop_event.set()
                    main_ev = getattr(self, '_main_run_stop_event_for_reconnect', None)
                    if main_ev is not None:
                        main_ev.set()
                        setattr(self, '_main_run_stop_event_for_reconnect', None)
                    return
                self._emit("[重连脚本] 乌索 to 脚本后的门控失败，重新刷新", "WARN")
                actual_stop_event = stop_event if stop_event is not None else threading.Event()
                self._request_mode_restart(
                    actual_stop_event,
                    "重连脚本-乌索-map325门控失败",
                )
                return
            if "双塔" in profile_name_lower:
                if self.bot:
                    self.bot.stop_current = False
                    self._emit("[重连脚本] 已清除 stop_current", "SUCCESS")

                gz = wild_rare_map_gate_zero_literal_swf_ids(profile)
                ez = self._wild_rare_expected_map_zero_after_to(profile)
                anchor = int(ez) if ez is not None else profile.map_swf_id
                last_map_id, has_newNPC = self._wait_after_to_then_check_last_map_and_newnpc(
                    anchor,
                    timeout_s=10.0,
                    stop_event=stop_event or threading.Event(),
                    log_tag="重连脚本-双塔地图零",
                    start_cursor=to_start_cursor,
                    accepted_map_ids=(gz if gz else None),
                )

                if has_newNPC and self._kernel_map_matches_profile_expectation(
                    profile, last_map_id, anchor
                ):
                    self._emit(
                        "[重连脚本] 双塔零位地图门控通过：map=%s + newNpc"
                        % (last_map_id,),
                        "SUCCESS",
                    )
                    self._on_map_zero_gate_passed()
                    self._reconnect_scripts_executing = False

                    self._petswf_to_petitem_min_duration = None
                    self._petswf_to_petitem_current_duration = None
                    if self._unified_framework and hasattr(self._unified_framework, '_petswf_to_petitem_durations'):
                        self._unified_framework._petswf_to_petitem_durations.clear()
                    self._emit("[重连脚本] 已重置时长计数", "INFO")

                    self._should_restart_after_reconnect = True
                    self._emit("[重连脚本] 已为双塔模式设置重启标记", "INFO")

                    if stop_event is not None:
                        stop_event.set()
                    main_ev = getattr(self, '_main_run_stop_event_for_reconnect', None)
                    if main_ev is not None:
                        main_ev.set()
                        setattr(self, '_main_run_stop_event_for_reconnect', None)
                    return
                else:
                    gdesc = "|".join(str(x) for x in sorted(gz)) if gz else str(anchor)
                    self._emit(
                        "[重连脚本] 零位地图门控失败（零位=%s anchor=%s map=%s, newNpc=%s）；重新刷新"
                        % (gdesc, anchor, last_map_id, has_newNPC),
                        "WARN",
                    )

                    actual_stop_event = stop_event if stop_event is not None else threading.Event()
                    self._request_mode_restart(
                        actual_stop_event,
                        "重连脚本-双塔-目标地图门控失败",
                    )
                    return
            elif "嘟咕噜" in profile_name_lower:
                if self.bot:
                    self.bot.stop_current = False
                    self._emit("[重连脚本] 已清除 stop_current", "SUCCESS")

                gz = wild_rare_map_gate_zero_literal_swf_ids(profile)
                ez = self._wild_rare_expected_map_zero_after_to(profile)
                anchor = int(ez) if ez is not None else profile.map_swf_id
                last_map_id, has_newNPC = self._wait_after_to_then_check_last_map_and_newnpc(
                    anchor,
                    timeout_s=10.0,
                    stop_event=stop_event or threading.Event(),
                    log_tag="重连脚本-嘟咕噜地图零",
                    start_cursor=to_start_cursor,
                    accepted_map_ids=(gz if gz else None),
                )

                if has_newNPC and self._kernel_map_matches_profile_expectation(
                    profile, last_map_id, anchor
                ):
                    self._emit(
                        "[重连脚本] 嘟咕噜零位地图门控通过：map=%s + newNpc"
                        % (last_map_id,),
                        "SUCCESS",
                    )
                    self._on_map_zero_gate_passed()
                    self._reconnect_scripts_executing = False

                    self._petswf_to_petitem_min_duration = None
                    self._petswf_to_petitem_current_duration = None
                    if self._unified_framework and hasattr(self._unified_framework, '_petswf_to_petitem_durations'):
                        self._unified_framework._petswf_to_petitem_durations.clear()
                    self._emit("[重连脚本] 已重置时长计数", "INFO")

                    self._should_restart_after_reconnect = True
                    self._emit("[重连脚本] 已为嘟咕噜模式设置重启标记", "INFO")
                    if stop_event is not None:
                        stop_event.set()
                    main_ev = getattr(self, '_main_run_stop_event_for_reconnect', None)
                    if main_ev is not None:
                        main_ev.set()
                        setattr(self, '_main_run_stop_event_for_reconnect', None)
                    return
                else:
                    max_retries_str = f"/{max_retries}" if max_retries is not None else ""
                    gdesc = "|".join(str(x) for x in sorted(gz)) if gz else str(anchor)
                    self._emit(
                        f"[重连脚本] 嘟咕噜零位地图门控失败（零位={gdesc} anchor={anchor} "
                        f"map={last_map_id}, npc={has_newNPC}）；刷新重试 {retry_count + 1}{max_retries_str}",
                        "WARN",
                    )

                    actual_stop_event = stop_event if stop_event is not None else threading.Event()
                    self._request_mode_restart(
                        actual_stop_event,
                        "重连脚本-嘟咕噜-目标地图门控失败",
                    )
                    return
            elif "螳螂" in profile_name_lower or "小豆芽" in profile_name_lower:
                self._emit("[重连脚本] 等待 2s，清除 stop_current 并设置重启标记", "INFO")
                time.sleep(2.0)
                if self.bot:
                    self.bot.stop_current = False
                    self._emit("[重连脚本] 已清除 stop_current", "SUCCESS")

                self._reconnect_scripts_executing = False

                self._petswf_to_petitem_min_duration = None
                self._petswf_to_petitem_current_duration = None
                if self._unified_framework and hasattr(self._unified_framework, '_petswf_to_petitem_durations'):
                    self._unified_framework._petswf_to_petitem_durations.clear()
                self._emit("[重连脚本] 已重置时长计数", "INFO")

                self._should_restart_after_reconnect = True
                self._emit("[重连脚本] 已设置重启标记", "INFO")
                if stop_event is not None:
                    stop_event.set()
                main_ev = getattr(self, '_main_run_stop_event_for_reconnect', None)
                if main_ev is not None:
                    main_ev.set()
                    setattr(self, '_main_run_stop_event_for_reconnect', None)
            else:
                if self.bot:
                    self.bot.stop_current = False
                    self._emit("[重连脚本] 已清除 stop_current", "SUCCESS")

                gz = wild_rare_map_gate_zero_literal_swf_ids(profile)
                ez = self._wild_rare_expected_map_zero_after_to(profile)
                anchor = int(ez) if ez is not None else int(profile.map_swf_id)
                gdesc = "|".join(str(x) for x in sorted(gz)) if gz else str(anchor)
                last_map_id, has_newNPC = self._wait_after_to_then_check_last_map_and_newnpc(
                    anchor,
                    stop_event=stop_event or threading.Event(),
                    timeout_s=12.0,
                    log_tag=f"重连脚本-{profile.name}地图零",
                    start_cursor=to_start_cursor,
                    accepted_map_ids=(gz if gz else None),
                    skip_reverse_check=(
                        int(anchor) == 414
                        and (
                            str(getattr(profile, "route_hint", "")) == "埃尔特"
                            or "埃尔特" in str(getattr(profile, "name", ""))
                            or str(to_script_name) == "to埃尔特"
                        )
                    ),
                )
                if not (
                    has_newNPC
                    and self._kernel_map_matches_profile_expectation(profile, last_map_id, anchor)
                ):
                    max_retries_str = f"/{max_retries}" if max_retries is not None else ""
                    self._emit(
                        f"[重连脚本] {profile.name} 零位地图门控失败（零位={gdesc} anchor={anchor} "
                        f"map={last_map_id}, npc={has_newNPC}）；刷新重试 {retry_count + 1}{max_retries_str}",
                        "WARN",
                    )
                    actual_stop_event = stop_event if stop_event is not None else threading.Event()
                    self._request_mode_restart(
                        actual_stop_event,
                        f"重连脚本-{profile.name}-目标地图门控失败",
                    )
                    return

                self._emit(
                    f"[重连脚本] {profile.name} 零位地图门控通过：map={last_map_id}+newNpc；设置重启标记",
                    "SUCCESS",
                )
                self._on_map_zero_gate_passed()
                self._reconnect_scripts_executing = False
                self._petswf_to_petitem_min_duration = None
                self._petswf_to_petitem_current_duration = None
                if self._unified_framework and hasattr(self._unified_framework, '_petswf_to_petitem_durations'):
                    self._unified_framework._petswf_to_petitem_durations.clear()
                self._emit("[重连脚本] 已重置时长计数", "INFO")
                self._should_restart_after_reconnect = True
                self._emit("[重连脚本] 已设置重启标记", "INFO")
                if stop_event is not None:
                    stop_event.set()
                main_ev = getattr(self, '_main_run_stop_event_for_reconnect', None)
                if main_ev is not None:
                    main_ev.set()
                    setattr(self, '_main_run_stop_event_for_reconnect', None)

            self._reconnect_scripts_executing = False

        except Exception as e:
            self._reconnect_scripts_executing = False
            self._emit(f"[重连脚本] 异常：{e}", "ERROR")
            import traceback
            self._emit(traceback.format_exc(), "ERROR")
        finally:
            self._reconnect_scripts_executing = False

    def _execute_reconnect_scripts(self, profile: WildCaptureProfile, use_foreground: bool, stop_event: Optional[threading.Event] = None, is_capture_verify_four: bool = False) -> None:
        """Run generic Step3 reconnect scripts."""
        self._execute_reconnect_scripts_core(profile, use_foreground, stop_event, retry_count=0, max_retries=1, is_capture_verify_four=is_capture_verify_four)

    # ---------------------------
    # click helpers
    # ---------------------------
    def _click_region(self, reg_or_key, use_foreground: bool) -> Tuple[float, float]:
        """Click a Region object or region key."""
        if isinstance(reg_or_key, str):
            reg = self.regions.get(reg_or_key)
            if not reg:
                raise KeyError(f"Region not found: {reg_or_key}")
        else:
            reg = reg_or_key

        x, y = reg.sample_click_point()
        if use_foreground:
            window_manager.click(x, y)
        else:
            window_manager.click_background(x, y)
        return float(x), float(y)

    @staticmethod
    def _region_center(reg: Region) -> Tuple[float, float]:
        x1, y1, x2, y2 = reg.outer_bbox()
        return (x1 + x2) / 2.0, (y1 + y2) / 2.0

    @staticmethod
    def _dist2(a: Tuple[float, float], b: Tuple[float, float]) -> float:
        return (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2

    def _route_distance_for_scan(
        self,
        key: str,
        reg: Region,
        reference_center: Tuple[float, float],
    ) -> float:
        """Return active terrain-chain distance, falling back to straight-line distance."""
        chain_distances = getattr(self, "_active_route_chain_distances", {})
        if key in chain_distances:
            return float(chain_distances[key])
        return self._dist2(self._region_center(reg), reference_center)

    def _route_chain_distances(
        self,
        route_points: Sequence[Tuple[str, Region]],
        prefix: str,
        reg_z: Region,
        chain: Sequence[str],
    ) -> Optional[Dict[str, float]]:
        """Accumulate adjacent segment lengths along a configured terrain chain from Z."""
        labels = tuple(str(item).strip() for item in chain if str(item).strip())
        if not labels or labels.count("Z") != 1 or len(set(labels)) != len(labels):
            self._emit(f"⚠️ [{prefix}] 距离链配置无效（必须包含唯一 Z，且节点不能重复）：{labels}", "WARN")
            return None

        point_labels = {key.rsplit(".", 1)[-1] for key, _ in route_points}
        missing_labels = sorted(point_labels.difference(labels))
        if missing_labels:
            self._emit(
                f"⚠️ [{prefix}] 距离链缺少刷新点 {missing_labels}，回退直线判距",
                "WARN",
            )
            return None

        chain_regions: Dict[str, Region] = {}
        for label in labels:
            reg = reg_z if label == "Z" else self.regions.get(f"{prefix}.{label}")
            if reg is None:
                self._emit(
                    f"⚠️ [{prefix}] 距离链节点 {label} 没有区域，回退直线判距",
                    "WARN",
                )
                return None
            chain_regions[label] = reg

        cumulative: Dict[str, float] = {labels[0]: 0.0}
        total = 0.0
        for previous, current in zip(labels, labels[1:]):
            px, py = self._region_center(chain_regions[previous])
            cx, cy = self._region_center(chain_regions[current])
            total += math.hypot(cx - px, cy - py)
            cumulative[current] = total

        z_offset = cumulative["Z"]
        distances: Dict[str, float] = {}
        for key, _reg in route_points:
            label = key.rsplit(".", 1)[-1]
            distances[key] = abs(cumulative[label] - z_offset)
        return distances

    def _sort_route_points_by_distance(
        self,
        route_points: List[Tuple[str, Region]],
        prefix: str,
        map_id: int,
        reg_z: Region,
        *,
        farthest_exclude_count: int = 2,
        profile: Any = None,
        previous_map_id: Optional[int] = None,
    ) -> List[Tuple[str, Region]]:
        """Sort route points by distance to a reference point and drop farthest points."""
        self._active_route_chain_distances = {}
        k_drop = max(0, int(farthest_exclude_count))
        def trim_farthest(seq: List, k: int):
            if k <= 0:
                return seq
            return seq[:-k] if len(seq) > k else seq

        route_chain: Sequence[str] = ()
        if profile is not None and int(map_id) == int(profile.map_b_id):
            route_chain = getattr(profile, "route_distance_chain_b", ())
        if route_chain:
            chain_distances = self._route_chain_distances(
                route_points, prefix, reg_z, route_chain
            )
            if chain_distances is not None:
                self._active_route_chain_distances = chain_distances
                point_distances = [
                    (chain_distances[key], key, reg) for key, reg in route_points
                ]
                point_distances.sort(key=lambda item: item[0])
                filtered_points = trim_farthest(point_distances, k_drop)
                sorted_points = [(key, reg) for _, key, reg in filtered_points]
                excluded_keys = (
                    [key for _, key, _ in point_distances[-k_drop:]] if k_drop else []
                )
                self._emit(
                    f"🧭 [map{map_id}] 按地形链累计判距：{'→'.join(route_chain)}（基准 Z）；"
                    f"由近到远={', '.join(key for key, _ in sorted_points)}"
                    + (f" | 排除最远={', '.join(excluded_keys)}" if excluded_keys else ""),
                    "INFO",
                )
                return sorted_points

        reference_key = ""
        reference_reg: Optional[Region] = None

        if profile is not None:
            if getattr(profile, "stay_on_b_map", False):
                reference_reg = reg_z
                reference_key = f"{prefix}.Z"
            else:
                from core.nieo_mode_registry import nieo_scan_reference_keys

                cur = int(map_id)
                abc_ids = {
                    int(profile.map_a_id),
                    int(profile.map_b_id),
                    int(profile.map_c_id),
                }
                if cur in abc_ids:
                    ref_key, legacy = nieo_scan_reference_keys(
                        profile, cur, previous_map_id
                    )
                    reference_reg = self.regions.get(ref_key) or self.regions.get(legacy)
                    reference_key = ref_key if self.regions.get(ref_key) else legacy

        if reference_reg is not None:
            reference_center = self._region_center(reference_reg)
        elif map_id == 10:
            reference_key = f"{prefix}.to二"
            reference_reg = self.regions.get(reference_key)
            if not reference_reg:
                self._emit(f"reference point not found: {reference_key}; use default order", "WARN")
                return trim_farthest(route_points, k_drop)
            reference_center = self._region_center(reference_reg)
        elif map_id == 11:
            reference_key = f"{prefix}.to一"
            reference_reg = self.regions.get(reference_key)
            if not reference_reg:
                self._emit(f"reference point not found: {reference_key}; use default order", "WARN")
                return trim_farthest(route_points, k_drop)
            reference_center = self._region_center(reference_reg)
        elif map_id == 26:
            reference_key = "纯净能量二.to一"
            reference_reg = self.regions.get(reference_key)
            if not reference_reg:
                self._emit(f"reference point not found: {reference_key}; use default order", "WARN")
                return trim_farthest(route_points, k_drop)
            reference_center = self._region_center(reference_reg)
        elif map_id == 27:
            reference_key = "纯净能量一.to二"
            reference_reg = self.regions.get(reference_key)
            if not reference_reg:
                self._emit(f"reference point not found: {reference_key}; use default order", "WARN")
                return trim_farthest(route_points, k_drop)
            reference_center = self._region_center(reference_reg)
        else:
            self._emit(f"unknown route sort map_id={map_id}; use default order", "WARN")
            return trim_farthest(route_points, k_drop)

        def calc_distance(key_reg: Tuple[str, Region]) -> Tuple[float, str, Region]:
            key, reg = key_reg
            point_center = self._region_center(reg)
            dist = self._dist2(point_center, reference_center)
            return (dist, key, reg)

        point_distances = [calc_distance(p) for p in route_points]

        point_distances.sort(key=lambda x: x[0])

        filtered_points = trim_farthest(point_distances, k_drop)

        sorted_points = [(key, reg) for _, key, reg in filtered_points]

        if reference_key:
            excluded_keys = [k for _, k, _ in point_distances[-k_drop:]] if k_drop else []
            from core.nieo_mode_registry import nieo_btoc_ctob_only_reference

            prev_note = (
                "fixed BtoC/CtoB"
                if profile is not None and nieo_btoc_ctob_only_reference(profile)
                else f"previous map={previous_map_id}"
            )
            self._emit(
                f"[map{map_id}] reference={reference_key} ({prev_note}); "
                f"near-to-far={', '.join(k for k, _ in sorted_points)}"
                + (f" | excluded farthest={', '.join(excluded_keys)}" if excluded_keys else ""),
                "INFO",
            )

        return sorted_points

    def _nieo_white_probe_key(self, map_id: int) -> Optional[str]:
        if map_id == 10:
            return "尼奥一.白色探针"
        prof = getattr(self, "_configured_nieo_profile", None)
        configured_key = str(getattr(prof, "white_probe_key", "") or "").strip()
        configured_map_ids = {
            int(item) for item in (getattr(prof, "white_probe_map_ids", ()) or ())
        }
        if configured_key and int(map_id) in configured_map_ids:
            return configured_key
        if (
            prof is not None
            and getattr(prof, "b_entry_white_probe_key", "")
            and int(map_id) == int(prof.map_b_id)
        ):
            return prof.b_entry_white_probe_key
        return None

    def _nieo_verify_map_landed(
        self,
        expected_map_id: int,
        stop_event: threading.Event,
    ) -> bool:
        """Verify the latest kernel map and white probe state."""
        actual = self._get_last_map_id()
        if actual != expected_map_id:
            self._emit(
                f"[地图校验] expected map{expected_map_id}, latest kernel map={actual}",
                "WARN",
            )
            return False
        probe_key = self._nieo_white_probe_key(expected_map_id)
        if probe_key:
            reg = self.regions.get(probe_key)
            if reg is not None and self._check_white_probe_pure_white(reg):
                self._emit(
                    f"[地图校验] map{expected_map_id} white probe is still pure white; not landed",
                    "WARN",
                )
                return False
        elif expected_map_id == 11:
            cm, has_npc = self._check_last_map_and_newnpc(11, initial_pause_s=0.3)
            if cm != 11 or not has_npc:
                self._emit(
                    f"[地图校验] map11 newNpc check failed (map={cm}, npc={has_npc})",
                    "WARN",
                )
                return False
        return True

    def _nieo_guard_unexpected_map(
        self,
        valid_map_ids: FrozenSet[int],
        use_foreground: bool,
        stop_event: threading.Event,
        mode_name: str = "尼奥",
        force_reconnect_fn: Optional[Callable] = None,
    ) -> bool:
        """Trigger reconnect if the latest kernel map is outside valid_map_ids."""
        if stop_event.is_set() or getattr(self.bot, "stop_current", False):
            return False
        actual = self._get_last_map_id()
        if actual is None:
            return False
        actual_i = int(actual)
        if actual_i in valid_map_ids:
            return False
        self._emit(
            f"[{mode_name}-地图保护] kernel map={actual_i}, allowed={set(valid_map_ids)}; trigger reconnect",
            "WARN",
        )
        if force_reconnect_fn is not None:
            force_reconnect_fn()
        return True

    def _nieo_kernel_has_recent_wild_battle(self) -> bool:
        """Return whether recent kernel lines indicate a wild battle."""
        try:
            from core.logger import fetch_kernel_since, kernel_cursor
            lines = fetch_kernel_since(max(0, kernel_cursor() - 200))
            if not isinstance(lines, list):
                return False
            for line in reversed(lines[-80:]):
                s = str(line)
                if line_matches(RE_PETITEM, s) or line_matches(RE_FIGHT_PET, s):
                    return True
        except Exception:
            pass
        return False

    def _nieo_try_escape_once(self, use_foreground: bool, stop_event: threading.Event) -> None:
        """Fallback: if a wild battle is detected, run one escape flow."""
        if not (
            getattr(self, "_is_in_battle", False)
            or self._nieo_kernel_has_recent_wild_battle()
        ):
            self._emit("[补救] 未检测到野外战斗，跳过逃跑", "DEBUG")
            return
        from core.unified_battle_framework import BattleConfig, BattleMode
        from core.logger import kernel_cursor

        self._emit("[补救] run one escape flow", "SYSTEM")
        self._is_in_battle = True

        def escape_cb(round_idx: int) -> str:
            return "escape"

        cfg = BattleConfig(
            mode=BattleMode.WILD,
            use_foreground=use_foreground,
            skill_key="对战.使用技能一",
            action_callback=escape_cb,
            abort_check=lambda: stop_event.is_set() or getattr(self.bot, "stop_current", False),
            round_timeout_sec=30.0,
        )
        stage2_cursor = kernel_cursor()
        ok, _ = self._unified_framework.stage2_calibration_and_petitem(
            trigger_callback=None,
            use_foreground=use_foreground,
            timeout_s=8.0,
            skip_stage1=True,
            config=cfg,
            initial_cursor=stage2_cursor,
        )
        if ok:
            self._unified_framework.stage3_battle_loop(cfg)
            self._unified_framework.stage4_post_battle(cfg, is_training_room=False)
        # Escape cleanup: dismiss 1AND1 until it disappears.
        post_timeout = 20.0
        if self._unified_framework is not None:
            post_timeout = float(
                getattr(
                    self._unified_framework,
                    "POST_BATTLE_CONFIRM_DIALOG_TIMEOUT_SEC",
                    2.0,
                )
            )
        self._dismiss_1and1_until_disappear(
            use_foreground,
            stop_event,
            timeout_s=post_timeout,
            log_tag="补救·逃跑",
        )
        self._is_in_battle = False
        self._is_scanning_steady_state = True

    def _nieo_dismiss_1and1_optional(
        self, use_foreground: bool, stop_event: threading.Event, timeout_s: float = 2.0
    ) -> None:
        """Dismiss 1AND1 briefly; skip if it does not appear."""
        self._dismiss_1and1_until_disappear(
            use_foreground,
            stop_event,
            timeout_s=timeout_s,
            log_tag="补救·1AND1",
        )

    def _switch_neighbor_map_verified(
        self,
        *,
        current_map_id: int,
        target_map_id: int,
        click_entrance: Callable[[], bool],
        use_foreground: bool,
        stop_event: threading.Event,
        wait_timeout_s: Optional[float] = None,
        log_tag: str = "地图切换",
        on_final_failure: Optional[Callable[[], None]] = None,
    ) -> Optional[int]:
        """Switch to a neighbor map and verify kernel/probe state."""
        if self._should_abort_main_loop_for_reconnect(stop_event):
            return None
        if wait_timeout_s is None:
            if target_map_id == 10:
                wait_timeout_s = 30.0
            elif target_map_id == 11:
                wait_timeout_s = 15.0
            else:
                wait_timeout_s = 45.0

        if not click_entrance():
            self._emit(f"[{log_tag}] 点击 map{target_map_id} 入口失败", "ERROR")
            if not (stop_event.is_set() or getattr(self.bot, "stop_current", False)):
                if on_final_failure is not None:
                    on_final_failure()
            return None

        if stop_event.is_set() or getattr(self.bot, "stop_current", False):
            return None

        if not self._wait_for_map_id(
            target_map_id,
            stop_event,
            timeout_s=wait_timeout_s,
            white_probe_key=self._nieo_white_probe_key(target_map_id),
        ):
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return None
            self._emit(
                f"[{log_tag}] waiting for map{target_map_id} timed out; trigger reconnect",
                "WARN",
            )
            if on_final_failure is not None:
                on_final_failure()
            return None

        if self._nieo_verify_map_landed(target_map_id, stop_event):
            self._emit(f"[{log_tag}] confirmed map{target_map_id}", "SUCCESS")
            return target_map_id

        self._emit(
            f"[{log_tag}-地图错位] entered map{target_map_id}, but verification failed; trigger reconnect",
            "WARN",
        )
        if on_final_failure is not None:
            on_final_failure()
        return None

    def _nieo_click_map_entrance(
        self,
        *,
        from_map_id: int,
        current_prefix: str,
        use_foreground: bool,
    ) -> bool:
        """Click the Nieo neighbor-map entrance."""
        try:
            if from_map_id == 11:
                to_key = f"{current_prefix}.to一"
                self._emit(f"click {to_key} to return to map10", "SYSTEM")
                reg = self.regions.get(to_key)
            else:
                to_key = f"{current_prefix}.to二"
                self._emit(f"click {to_key} to enter map11", "SYSTEM")
                reg = self.regions.get(to_key)
            if not reg:
                self._emit(f"[补救] 缺少区域：{to_key}", "WARN")
                return False
            self._click_region(reg, use_foreground)
            return True
        except Exception as e:
            self._emit(f"点击地图入口失败：{e}", "WARN")
            return False

    def _nieo_switch_neighbor_map_verified(
        self,
        *,
        current_map_id: int,
        current_prefix: str,
        use_foreground: bool,
        stop_event: threading.Event,
    ) -> Optional[int]:
        """Switch between Nieo map10/map11 and verify."""
        target_map_id = 10 if current_map_id == 11 else 11
        return self._switch_neighbor_map_verified(
            current_map_id=current_map_id,
            target_map_id=target_map_id,
            click_entrance=lambda: self._nieo_click_map_entrance(
                from_map_id=current_map_id,
                current_prefix=current_prefix,
                use_foreground=use_foreground,
            ),
            use_foreground=use_foreground,
            stop_event=stop_event,
            log_tag="尼奥10/11",
            on_final_failure=lambda: self._check_nieo_reconnect_condition(
                use_foreground, stop_event, force_reconnect=True
            ),
        )

    def _pem_click_neighbor_entrance(
        self, current_map_id: int, use_foreground: bool
    ) -> bool:
        try:
            if current_map_id == 26:
                reg = self.regions.get("纯净能量二.to一")
                if not reg:
                    self._emit("[纯净能量] 缺少 纯净能量二.to一", "WARN")
                    return False
                self._emit("[纯净能量] click 纯净能量二.to一 to enter map27", "SYSTEM")
                self._click_region(reg, use_foreground)
                return True
            if current_map_id == 27:
                reg = self.regions.get("纯净能量一.to二")
                if not reg:
                    self._emit("[纯净能量] 缺少 纯净能量一.to二", "WARN")
                    return False
                self._emit("[纯净能量] click 纯净能量一.to二 to return to map26", "SYSTEM")
                self._click_region(reg, use_foreground)
                return True
        except Exception as e:
            self._emit(f"[纯净能量] 点击地图入口失败：{e}", "WARN")
        return False

    def _pem_switch_neighbor_map_verified(
        self,
        *,
        current_map_id: int,
        use_foreground: bool,
        stop_event: threading.Event,
    ) -> Optional[int]:
        target_map_id = 27 if current_map_id == 26 else 26
        return self._switch_neighbor_map_verified(
            current_map_id=current_map_id,
            target_map_id=target_map_id,
            click_entrance=lambda: self._pem_click_neighbor_entrance(
                current_map_id, use_foreground
            ),
            use_foreground=use_foreground,
            stop_event=stop_event,
            log_tag="纯净能量26/27",
            on_final_failure=lambda: self._check_pure_energy_reconnect_condition(
                use_foreground, stop_event, force_reconnect=True
            ),
        )

    def _configured_nieo_click_entrance(
        self,
        profile: "NieoModeProfile",
        current_map_id: int,
        target_map_id: int,
        use_foreground: bool,
        stop_event: threading.Event,
    ) -> bool:
        from core.nieo_mode_registry import (
            nieo_neighbor_transition_keys,
            nieo_transition_to_target,
        )

        region_key, stem = nieo_transition_to_target(
            profile, current_map_id, target_map_id
        )
        reg = self.regions.get(region_key) if region_key else None
        label = region_key
        if reg is None and int(current_map_id) in (
            int(profile.map_b_id),
            int(profile.map_c_id),
        ):
            primary_key, legacy_key = nieo_neighbor_transition_keys(profile, current_map_id)
            reg = self.regions.get(primary_key) or self.regions.get(legacy_key)
            label = primary_key if self.regions.get(primary_key) else legacy_key

        if reg:
            self._emit(
                f"[自定义尼奥] click {label} -> map {target_map_id}",
                "SYSTEM",
            )
            self._click_region(reg, use_foreground)
            return True
        if stem:
            self._emit(
                f"[自定义尼奥] click map/{stem}.json -> map {target_map_id}",
                "SYSTEM",
            )
            return self._execute_map_entry_script_by_stem(stem, use_foreground, stop_event)
        self._emit(
            f"[自定义尼奥] no transition config {current_map_id}->{target_map_id}",
            "WARN",
        )
        return False

    def _neighbor_switch_twomap_after_fail(
        self,
        *,
        pem: bool,
        current_map_id: int,
        current_prefix: str,
        use_foreground: bool,
        stop_event: threading.Event,
    ) -> Optional[int]:
        """Switch Nieo 10/11, pure energy 26/27, or configured B/C maps."""
        if self._should_abort_main_loop_for_reconnect(stop_event):
            return None
        prof = getattr(self, "_configured_nieo_profile", None)
        if prof is not None:
            pending = getattr(self, "_configured_nieo_pending_recovery", None)
            if pending:
                target_map_id = int(pending.get("target_map_id", current_map_id))
                if target_map_id != int(current_map_id):
                    self._emit(
                        f"🩹 [自定义尼奥恢复] 战后恢复优先：map{current_map_id} -> map{target_map_id}",
                        "SYSTEM",
                    )
                    return self._configured_nieo_switch_to_map(
                        prof,
                        int(current_map_id),
                        target_map_id,
                        use_foreground,
                        stop_event,
                    )
            if getattr(prof, "stay_on_b_map", False):
                self._emit(
                    f"🔄 [{prof.name}] 单 B 图模式不切 A/C，直接刷新重连",
                    "SYSTEM",
                )
                self._check_configured_nieo_reconnect_condition(
                    use_foreground,
                    stop_event,
                    force_reconnect=True,
                    force_reason="单 B 图需要重新入场",
                )
                return None
            if (
                int(current_map_id) == int(prof.map_b_id)
                and self._configured_nieo_has_a_fork(prof)
            ):
                last = getattr(self, "_configured_nieo_last_battle_xy", None)
                if last is not None:
                    bx, by = last
                    return self._configured_nieo_switch_after_battle_on_b(
                        prof, bx, by, use_foreground, stop_event
                    )
            return self._configured_nieo_switch_map(
                prof, current_map_id, use_foreground, stop_event
            )
        if pem:
            if current_map_id in (26, 27):
                return self._pem_switch_neighbor_map_verified(
                    current_map_id=current_map_id,
                    use_foreground=use_foreground,
                    stop_event=stop_event,
                )
            return None

        if current_map_id in (10, 11):
            return self._nieo_switch_neighbor_map_verified(
                current_map_id=current_map_id,
                current_prefix=current_prefix,
                use_foreground=use_foreground,
                stop_event=stop_event,
            )
        return None

    def _pem_handle_external_maintenance_entry(
        self,
        current_map_id: int,
        use_foreground: bool,
        stop_event: threading.Event,
    ) -> bool:
        """Handle pure energy external maintenance after neighbor-map recovery."""
        if not getattr(self, "_pem_maintenance_pending", False):
            return False
        self._pem_maintenance_pending = False
        n = self.PEM_SKILL4_MAINTENANCE_EVERY_BATTLES
        self._emit(
            f"[纯净能量] recovered pet one on map {current_map_id} after {n} battles; skip this map battle",
            "SYSTEM",
        )
        if not self._pem_recover_pet_one_maintenance(
            use_foreground, stop_event
        ):
            self._emit("[纯净能量] 周期恢复未完成，不标记维护成功", "ERROR")
            return False
        return True

    def _configured_nieo_recovery_map(
        self, profile: "NieoModeProfile", current_map_id: int
    ) -> Optional[int]:
        """Return the configured skip map used for recovery, if one exists."""
        candidates = (
            (profile.map_c_id, profile.action_c),
            (profile.map_a_id, profile.action_a),
        )
        for map_id, action in candidates:
            if int(map_id) != int(current_map_id) and action == "skip":
                return int(map_id)
        return None

    def _queue_configured_nieo_recovery(
        self,
        *,
        kind: str,
        current_map_id: Optional[int],
        reason: str,
        nie_family_id: Optional[int] = None,
    ) -> bool:
        """Defer configured-Nieo recovery to its designated skip map."""
        profile = getattr(self, "_configured_nieo_profile", None)
        if profile is None or current_map_id is None:
            return False
        target_map_id = self._configured_nieo_recovery_map(profile, int(current_map_id))
        if target_map_id is None:
            return False
        if getattr(self, "_configured_nieo_pending_recovery", None):
            return True
        self._configured_nieo_pending_recovery = {
            "kind": kind,
            "origin_map_id": int(current_map_id),
            "target_map_id": target_map_id,
            "reason": reason,
            "nie_family_id": nie_family_id,
        }
        self._emit(
            f"🧭 [自定义尼奥恢复] {reason}：切到跳过图 map{target_map_id} 后恢复，再回 map{current_map_id}",
            "SYSTEM",
        )
        return True

    def _run_configured_nieo_pending_recovery(
        self,
        profile: "NieoModeProfile",
        current_map_id: int,
        use_foreground: bool,
        stop_event: threading.Event,
    ) -> Optional[int]:
        """Recover on a configured skip map, then return to the originating battle map."""
        pending = getattr(self, "_configured_nieo_pending_recovery", None)
        if not pending or int(pending.get("target_map_id", -1)) != int(current_map_id):
            return None
        kind = str(pending.get("kind") or "")
        reason = str(pending.get("reason") or "战后恢复")
        origin_map_id = int(pending.get("origin_map_id"))
        recovery_ok = True
        self._emit(f"🛠️ [自定义尼奥恢复] 在跳过图 map{current_map_id} 执行：{reason}", "SYSTEM")
        try:
            if kind == "capture":
                self._sleep_abortable(stop_event, 3.0)
                self._stop_1and1_monitoring = True
                self._is_recovering = True
                recovery_ok = self._recover_pets(
                    use_foreground,
                    stop_event,
                    skip_return_storage=False,
                    nie_family_id=pending.get("nie_family_id"),
                    profile=None,
                )
            elif kind == "skill":
                recovery_ok = self._recover_pick_party_from_closed_bag(
                    use_foreground,
                    stop_event,
                    f"自定义尼奥-{reason}",
                    include_primary=False,
                    set_follow_primary=True,
                )
                if recovery_ok:
                    self._reset_skill_recovery_counters(f"自定义尼奥-{reason}")
            else:
                recovery_ok = self._pem_recover_pet_one_maintenance(
                    use_foreground, stop_event
                )
        finally:
            self._is_recovering = False
            self._stop_1and1_monitoring = False
            self._configured_nieo_pending_recovery = None
        if not recovery_ok:
            self._emit(
                f"❌ [自定义尼奥恢复] {reason}未完成，不标记恢复成功",
                "ERROR",
            )
            return None

        back = self._configured_nieo_switch_to_map(
            profile,
            int(current_map_id),
            origin_map_id,
            use_foreground,
            stop_event,
        )
        if back == origin_map_id:
            self._emit(f"✅ [自定义尼奥恢复] 完成，重进战斗图 map{origin_map_id}", "SUCCESS")
        return back

    def _configured_nieo_external_maintenance(
        self,
        profile: "NieoModeProfile",
        use_foreground: bool,
        stop_event: threading.Event,
    ) -> Optional[int]:
        """Configured Nieo: recover pet one on map A after N battles, then return to B."""
        n = self.PEM_SKILL4_MAINTENANCE_EVERY_BATTLES
        self._emit(
            f"[自定义尼奥] reached {n} battles; switch to map A({profile.map_a_id}) to recover pet one",
            "SYSTEM",
        )
        on_a = self._configured_nieo_switch_to_map(
            profile,
            profile.map_b_id,
            profile.map_a_id,
            use_foreground,
            stop_event,
        )
        if on_a != profile.map_a_id:
            self._emit("[自定义尼奥] 切回A点失败，跳过外部恢复", "WARN")
            return profile.map_b_id
        if not self._pem_recover_pet_one_maintenance(
            use_foreground, stop_event
        ):
            self._emit("[自定义尼奥] 外部恢复失败，停止返回地图B", "ERROR")
            return None
        back = self._configured_nieo_switch_to_map(
            profile,
            profile.map_a_id,
            profile.map_b_id,
            use_foreground,
            stop_event,
        )
        if back == profile.map_b_id:
            self._emit("[自定义尼奥] 外部恢复完成，继续地图B", "SUCCESS")
        return back if back is not None else profile.map_b_id

    def _pem_recover_pet_one_maintenance(
        self, use_foreground: bool, stop_event: threading.Event
    ) -> bool:
        """Recover pet one during periodic pure energy maintenance."""
        bag_open_key = "精灵背包.打开精灵背包"
        bag_open_btn_key = "精灵背包.打开精灵背包按钮"
        try:
            self._emit("[纯净能量(资源)] 打开精灵背包进行周期性精灵一恢复", "INFO")
            try:
                self._click_region(bag_open_btn_key, use_foreground)
            except KeyError:
                self._click_region(bag_open_key, use_foreground)
            if not self._wait_pet_bag_ui_ready_after_open(
                stop_event, log_tag="纯净能量定期恢复"
            ):
                self._emit(
                    "[纯净能量(资源)] 背包UI未就绪，请求重连并重启当前模式",
                    "ERROR",
                )
                self._request_mode_restart(
                    stop_event,
                    "纯净能量定期恢复-背包UI未就绪",
                )
                return False
            pet_one_key = "精灵背包.精灵一"
            pet_one_btn_key = "精灵背包.精灵一按钮"
            self._emit("双击精灵一准备恢复", "INFO")
            try:
                self._click_region_twice(pet_one_btn_key, use_foreground)
            except KeyError:
                self._click_region_twice(pet_one_key, use_foreground)
            self._sleep_abortable(stop_event, 0.5)
            recover_key = "精灵背包.精灵恢复"
            recover_btn_key = "精灵背包.精灵恢复按钮"
            try:
                self._click_region(recover_btn_key, use_foreground)
            except KeyError:
                self._click_region(recover_key, use_foreground)
            self._sleep_abortable(stop_event, 1.0)
            if self._unified_framework:
                from core.unified_battle_framework import BattleConfig, BattleMode

                temp_config = BattleConfig(
                    mode=BattleMode.WILD,
                    use_foreground=use_foreground,
                    abort_check=lambda: stop_event.is_set() or getattr(self.bot, "stop_current", False),
                )
                self._unified_framework._wait_for_confirm_probes(temp_config, timeout_s=2.0)
            self._sleep_abortable(stop_event, 0.5)
            self._close_pet_bag_with_verify(
                use_foreground,
                stop_event,
                bag_open_key,
                bag_open_btn_key,
                log_tag="纯净能量定期恢复",
            )
            self._emit("[纯净能量(资源)] 定期恢复精灵一完成", "SUCCESS")
            return True
        except Exception as e:
            self._emit(f"[纯净能量(资源)] 恢复精灵一异常：{e}", "ERROR")
            return False

    def _pem_pure_energy_neighbor_switch_finish(
        self,
        *,
        current_map_id: int,
        current_prefix: str,
        use_foreground: bool,
        stop_event: threading.Event,
    ) -> int:
        self._is_in_battle = False
        self._is_scanning_steady_state = True
        nxt = self._neighbor_switch_twomap_after_fail(
            pem=True,
            current_map_id=current_map_id,
            current_prefix=current_prefix,
            use_foreground=use_foreground,
            stop_event=stop_event,
        )
        return nxt if nxt is not None else current_map_id

    def _should_use_skill3_for_resource_defeat(self, unique_ids: set) -> bool:
        prof = getattr(self, "_configured_nieo_profile", None)
        names = []
        if prof is not None:
            if getattr(prof, "sequential_skill_recovery", False):
                _skill3_threshold, skill4_threshold = (
                    self._configured_nieo_skill_recovery_thresholds()
                )
                committed = int(
                    getattr(self, "_post_recover_skill4_uses", 0) or 0
                )
                current = int(
                    getattr(self, "_current_battle_skill4_uses", 0) or 0
                )
                return committed + current >= skill4_threshold
            names = [
                str(getattr(prof, "slug", "") or ""),
                str(getattr(prof, "route_hint", "") or ""),
                str(getattr(prof, "name", "") or ""),
            ]
        if 251 in unique_ids and prof is None:
            return True
        joined = "|".join(names)
        if 37 in unique_ids and "熔岩晶体" in joined:
            return True
        if 107 in unique_ids and "大地之核" in joined:
            return True
        if 121 in unique_ids and "贝壳精华" in joined:
            return True
        return False

    def _resource_defeat_skill_action(self, unique_ids: set) -> str:
        """Choose skill 4 first, then skill 3 after the configured skill-4 threshold."""
        return (
            "skill3"
            if self._should_use_skill3_for_resource_defeat(unique_ids)
            else "skill4"
        )

    def _pem_pure_energy_calibration_reconnect_restart(
        self, use_foreground: bool, stop_event: threading.Event, reason_tag: str
    ) -> None:
        self._emit(f"[纯净能量] 校准检测到非目标地图（{reason_tag}），请求重启当前模式", "WARN")
        prof = getattr(self, "_configured_nieo_profile", None)
        if prof is not None:
            self._current_mode = f"nieo:{prof.slug}"
        else:
            self._current_mode = "pure_energy"
        self._request_mode_restart(
            stop_event,
            f"纯净能量-校准后地图不匹配-{reason_tag}",
        )

    def _pem_pure_energy_petitem_logging_cb(self) -> None:
        if self._unified_framework and hasattr(self._unified_framework, "_petswf_to_petitem_durations"):
            durs = self._unified_framework._petswf_to_petitem_durations
            if durs:
                cur = durs[-1]
                self._petswf_to_petitem_current_duration = cur
                if (
                    self._petswf_to_petitem_min_duration is None
                    or cur < self._petswf_to_petitem_min_duration
                ):
                    self._petswf_to_petitem_min_duration = cur

    def _pem_pure_energy_maybe_rotation_then_exit(self, stop_event: threading.Event, tag: str) -> bool:
        if not self._check_rotation_switch_time():
            return False
        self._emit(
            f"[轮换检测-纯净能量/{tag}] 已到轮换时间，返回轮换层",
            "SUCCESS",
        )
        stop_event.set()
        return True

    def _post_battle_external_maintenance_handoff(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
    ) -> Optional[int]:
        """External maintenance handoff placeholder."""
        _ = (use_foreground, stop_event)
        return None

    def _pem_pure_energy_after_battle_counters(
        self, use_foreground: bool, stop_event: threading.Event
    ) -> Optional[int]:
        maint = self._post_battle_external_maintenance_handoff(use_foreground, stop_event)
        self._pem_post_battle_reconnect_check(use_foreground, stop_event)
        return maint

    def _pem_pure_energy_escape77_like_nieo(
        self,
        *,
        current_map_id: int,
        current_prefix: str,
        use_foreground: bool,
        stop_event: threading.Event,
    ) -> Optional[int]:
        """If skip-capture 77 is enabled, escape and switch the pure energy map."""
        from core.unified_battle_framework import BattleConfig, BattleMode
        from core.logger import kernel_cursor
        from core.dar_route_runner import DEFAULT_PROFILE_DUGULU

        self._emit("[纯净能量] 跳过捕捉77，执行第一回合逃跑", "SYSTEM")
        self._is_in_battle = True
        self._is_scanning_steady_state = False
        self._last_nie_family_id = 77

        cfg = BattleConfig(
            mode=BattleMode.WILD,
            use_foreground=use_foreground,
            skill_key="对战.使用技能一",
            action_callback=lambda _r: "escape",
            abort_check=lambda: stop_event.is_set() or getattr(self.bot, "stop_current", False),
            on_petitem_detected=self._pem_pure_energy_petitem_logging_cb,
            round_timeout_sec=60.0,
        )
        stage2_cursor = kernel_cursor()
        ok, calib_result = self._unified_framework.stage2_calibration_and_petitem(
            trigger_callback=None,
            use_foreground=use_foreground,
            timeout_s=15.0,
            skip_stage1=True,
            config=cfg,
            initial_cursor=stage2_cursor,
        )
        if calib_result == "reconnect_needed":
            self._pem_pure_energy_calibration_reconnect_restart(use_foreground, stop_event, "逃跑")
            return None
        if not ok:
            return self._pem_pure_energy_neighbor_switch_finish(
                current_map_id=current_map_id,
                current_prefix=current_prefix,
                use_foreground=use_foreground,
                stop_event=stop_event,
            )
        bs = self._unified_framework.stage3_battle_loop(cfg)
        if not bs:
            if self._handle_stage3_round_timeout_reconnect(DEFAULT_PROFILE_DUGULU, use_foreground, stop_event, is_nieo=False):
                return None
            return self._pem_pure_energy_neighbor_switch_finish(
                current_map_id=current_map_id,
                current_prefix=current_prefix,
                use_foreground=use_foreground,
                stop_event=stop_event,
            )
        self._unified_framework.stage4_post_battle(cfg, is_training_room=False)
        self._battle_count += 1
        self._csv_log_battle("escape", [])
        self._emit("[纯净能量] 77逃跑完成", "SUCCESS")
        self._last_nie_family_id = None
        if self._pem_pure_energy_maybe_rotation_then_exit(stop_event, "逃跑"):
            return None
        if self._is_rotation_mode and getattr(self, "_pending_rotation_switch", False):
            return None
        if getattr(self, "_unexpected_pet_reconnect_pending", False):
            self._unexpected_pet_reconnect_pending = False
            self._emit(
                "[纯净能量-异常] 检测到异常精灵ID，本场结束后重连",
                "WARN",
            )
            self._pem_post_battle_reconnect_check(
                use_foreground, stop_event, force_reconnect=True
            )
            return None
        maint_map = self._pem_pure_energy_after_battle_counters(use_foreground, stop_event)
        if maint_map is not None:
            return maint_map
        return self._pem_pure_energy_neighbor_switch_finish(
            current_map_id=current_map_id,
            current_prefix=current_prefix,
            use_foreground=use_foreground,
            stop_event=stop_event,
        )

    def _pem_pure_energy_nie_family_like_nieo(
        self,
        *,
        nie_id: int,
        current_map_id: int,
        current_prefix: str,
        use_foreground: bool,
        stop_event: threading.Event,
    ) -> Optional[int]:
        """Handle Nie-family encounters in pure energy/configured Nieo flows."""
        from core.unified_battle_framework import BattleConfig, BattleMode, LastActionType
        from core.logger import kernel_cursor
        from core.dar_route_runner import DEFAULT_PROFILE_DUGULU

        self._emit(
            f"[{'自定义尼奥' if getattr(self, '_configured_nieo_profile', None) else '纯净能量'}] "
            f"Nie-family nie_id={nie_id}: skill1 -> switch -> capsule -> round 7+ first non-red fear escape",
            "SYSTEM",
        )
        self._is_in_battle = True
        self._is_scanning_steady_state = False
        self._last_nie_family_id = nie_id

        def nie_action_cb(round_idx: int) -> str:
            limit_action = self._nie_family_round_limit_action(
                round_idx,
                use_foreground,
                allow_escape=True,
            )
            if limit_action is not None:
                return limit_action
            if round_idx == 1:
                return "skill"
            if round_idx == 2:
                switched = self._switch_pet_for_nie_family(
                    nie_id, use_foreground, stop_event, test_mode=False
                )
                if not switched:
                    self._emit("[纯净能量/自定义尼奥] 尼尔家族切换失败，跳过切换并使用胶囊", "WARN")
                    return "capsule"
                return "switch"
            if round_idx == 3:
                return "capsule"
            return "capsule"

        cycle_ov = self._capsule_cycle_tiers_for_current_battle()
        cfg = BattleConfig(
            mode=BattleMode.WILD,
            use_foreground=use_foreground,
            skill_key="对战.使用技能一",
            action_callback=nie_action_cb,
            abort_check=lambda: stop_event.is_set() or getattr(self.bot, "stop_current", False),
            on_petitem_detected=self._pem_pure_energy_petitem_logging_cb,
            round_timeout_sec=60.0,
            capsule_cycle_tiers_override=cycle_ov,
        )

        stage2_cursor = kernel_cursor()
        ok, calib_result = self._unified_framework.stage2_calibration_and_petitem(
            trigger_callback=None,
            use_foreground=use_foreground,
            timeout_s=15.0,
            skip_stage1=True,
            config=cfg,
            initial_cursor=stage2_cursor,
        )
        if calib_result == "reconnect_needed":
            self._pem_pure_energy_calibration_reconnect_restart(use_foreground, stop_event, "尼尔家族")
            return None
        if not ok:
            return self._pem_pure_energy_neighbor_switch_finish(
                current_map_id=current_map_id,
                current_prefix=current_prefix,
                use_foreground=use_foreground,
                stop_event=stop_event,
            )
        bs = self._unified_framework.stage3_battle_loop(cfg)
        if not bs:
            if self._handle_stage3_round_timeout_reconnect(DEFAULT_PROFILE_DUGULU, use_foreground, stop_event, is_nieo=False):
                return None
            return self._pem_pure_energy_neighbor_switch_finish(
                current_map_id=current_map_id,
                current_prefix=current_prefix,
                use_foreground=use_foreground,
                stop_event=stop_event,
            )

        self._unified_framework.stage4_post_battle(cfg, is_training_room=False)
        self._battle_count += 1
        captured = self._unified_framework._last_action == LastActionType.CAPSULE
        if captured:
            self._csv_log_battle("captured", [nie_id] if nie_id else [])
            deferred_recovery = self._queue_configured_nieo_recovery(
                kind="capture",
                current_map_id=current_map_id,
                reason=f"尼尔家族 {nie_id} 捕捉成功",
                nie_family_id=nie_id,
            )
            if not deferred_recovery:
                self._emit(f"[纯净能量] 尼尔家族 {nie_id} 捕捉动作完成，恢复并入库", "SUCCESS")
                self._sleep_abortable(stop_event, 3.0)
                self._stop_1and1_monitoring = True
                self._is_recovering = True
                recovery_ok = self._recover_pets(
                    use_foreground,
                    stop_event,
                    skip_return_storage=False,
                    nie_family_id=nie_id,
                    profile=None,
                )
                self._is_recovering = False
                self._stop_1and1_monitoring = False
                if not recovery_ok:
                    self._last_nie_family_id = None
                    return None
            self._last_nie_family_id = None
            if deferred_recovery:
                return self._pem_pure_energy_neighbor_switch_finish(
                    current_map_id=current_map_id,
                    current_prefix=current_prefix,
                    use_foreground=use_foreground,
                    stop_event=stop_event,
                )
        else:
            self._emit("[纯净能量] 尼尔家族战斗胜利但不是胶囊结尾，继续战后处理", "INFO")
            self._last_nie_family_id = None

        if self._pem_pure_energy_maybe_rotation_then_exit(stop_event, "尼尔家族"):
            return None
        if self._is_rotation_mode and getattr(self, "_pending_rotation_switch", False):
            return None
        if getattr(self, "_unexpected_pet_reconnect_pending", False):
            self._unexpected_pet_reconnect_pending = False
            self._emit(
                "[纯净能量-异常] 检测到异常精灵ID，本场结束后重连",
                "WARN",
            )
            self._pem_post_battle_reconnect_check(
                use_foreground, stop_event, force_reconnect=True
            )
            return None
        maint_map = self._pem_pure_energy_after_battle_counters(use_foreground, stop_event)
        if maint_map is not None:
            return maint_map
        if self._nieo_single_map_escape and not captured:
            self._emit(
                f"🧭 [尼奥单图] 尼尔家族未捕捉成功，保留 map{current_map_id} 继续扫描",
                "DEBUG",
            )
            return current_map_id
        return self._pem_pure_energy_neighbor_switch_finish(
            current_map_id=current_map_id,
            current_prefix=current_prefix,
            use_foreground=use_foreground,
            stop_event=stop_event,
        )

    def _pem_after_change_skill4_defeat(
        self,
        *,
        current_map_id: int,
        current_prefix: str,
        use_foreground: bool,
        stop_event: threading.Event,
        selected_key: str,
        tx: float,
        ty: float,
        collected_pet_ids: Optional[set],
        skip_nie_family_check: bool = False,
    ) -> Optional[int]:
        """After entering battle: defeat resources or delegate Nie-family/rare handling."""
        from core.unified_battle_framework import BattleConfig, BattleMode
        from core.logger import kernel_cursor
        from core.dar_route_runner import DEFAULT_PROFILE_DUGULU

        pet_ids: List[int]
        if collected_pet_ids:
            pet_ids = sorted(collected_pet_ids)
            self._emit(f"[纯净能量] 已收集对战精灵ID：{pet_ids}", "SUCCESS")
        else:
            ids_set = self._collect_fight_pet_ids(timeout=4.5, collect_window=0.55, stop_event=stop_event)
            if not ids_set:
                self._emit("[纯净能量] 未收集到对战精灵ID，切图后重试", "WARN")
                return self._neighbor_switch_twomap_after_fail(
                    pem=True,
                    current_map_id=current_map_id,
                    current_prefix=current_prefix,
                    use_foreground=use_foreground,
                    stop_event=stop_event,
                ) or current_map_id
            pet_ids = sorted(ids_set)

        unique_ids = set(pet_ids)
        self._immediate_collected_pet_ids = set(unique_ids)

        configured = getattr(self, "_configured_nieo_profile", None)
        if configured is None:
            self._warn_if_no_nieo_like_my_pet_in_battle(unique_ids, tag="纯净能量")
            self._check_pet_id_allowlist_anomaly(
                unique_ids,
                "pem",
                current_map_id=current_map_id,
                pem_resource_path=True,
            )

        nf_keys = unique_ids & {77, 310, 416}
        if nf_keys and not skip_nie_family_check:
            self._nieo_run_seen_nie_family = True
            nie_pick = list(nf_keys)[0]
            if getattr(self, "_skip_nie_77", False) and nie_pick == 77:
                return self._pem_pure_energy_escape77_like_nieo(
                    current_map_id=current_map_id,
                    current_prefix=current_prefix,
                    use_foreground=use_foreground,
                    stop_event=stop_event,
                )
            return self._pem_pure_energy_nie_family_like_nieo(
                nie_id=nie_pick,
                current_map_id=current_map_id,
                current_prefix=current_prefix,
                use_foreground=use_foreground,
                stop_event=stop_event,
            )

        prof = getattr(self, "_configured_nieo_profile", None)
        rare_id = self._nieo_map_rare_capture_hit(
            current_map_id, unique_ids, profile=prof
        )
        if rare_id is not None:
            return self._run_nieo_map_rare_capture_battle(
                rare_pet_id=rare_id,
                current_map_id=current_map_id,
                current_prefix=current_prefix,
                use_foreground=use_foreground,
                stop_event=stop_event,
                pem=True,
            )

        self._is_in_battle = True
        self._is_scanning_steady_state = False
        self._reset_current_battle_skill_use_counters()

        fallback_action = self._resource_defeat_skill_action(unique_ids)

        def defeat_action(round_idx: int) -> str:
            action = self._resource_defeat_skill_action(unique_ids)
            self._note_current_battle_skill_use(action)
            self._emit(
                f"[资源战胜] round {round_idx}: use {action}",
                "INFO",
            )
            return action

        cycle_ov = self._capsule_cycle_tiers_for_current_battle()
        cfg = BattleConfig(
            mode=BattleMode.WILD,
            use_foreground=use_foreground,
            skill_key=(
                "对战.使用技能三"
                if fallback_action == "skill3"
                else "对战.使用技能四"
            ),
            action_callback=defeat_action,
            abort_check=lambda: stop_event.is_set() or getattr(self.bot, "stop_current", False),
            round_timeout_sec=60.0,
            capsule_cycle_tiers_override=cycle_ov,
        )

        def on_pi():
            if self._unified_framework and hasattr(self._unified_framework, "_petswf_to_petitem_durations"):
                durs = self._unified_framework._petswf_to_petitem_durations
                if durs:
                    cur = durs[-1]
                    self._petswf_to_petitem_current_duration = cur
                    if (
                        self._petswf_to_petitem_min_duration is None
                        or cur < self._petswf_to_petitem_min_duration
                    ):
                        self._petswf_to_petitem_min_duration = cur

        cfg.on_petitem_detected = on_pi

        self._emit("[纯净能量] 阶段2：等待 PetItem", "INFO")
        stage2_cursor = kernel_cursor()
        ok, calib_result = self._unified_framework.stage2_calibration_and_petitem(
            trigger_callback=None,
            use_foreground=use_foreground,
            timeout_s=15.0,
            skip_stage1=True,
            config=cfg,
            initial_cursor=stage2_cursor,
        )

        if calib_result == "reconnect_needed":
            self._emit("[纯净能量] 校准检测到非目标地图，请求重启当前模式", "WARN")
            prof = getattr(self, "_configured_nieo_profile", None)
            if prof is not None:
                self._current_mode = f"nieo:{prof.slug}"
            else:
                self._current_mode = "pure_energy"
            self._request_mode_restart(stop_event, "纯净能量-校准后地图不匹配")
            return None

        if not ok:
            self._emit("[纯净能量] 阶段2失败，切换地图", "WARN")
            self._is_in_battle = False
            self._is_scanning_steady_state = True
            return self._neighbor_switch_twomap_after_fail(
                pem=True,
                current_map_id=current_map_id,
                current_prefix=current_prefix,
                use_foreground=use_foreground,
                stop_event=stop_event,
            ) or current_map_id

        bs = self._unified_framework.stage3_battle_loop(cfg)
        if not bs:
            if self._handle_stage3_round_timeout_reconnect(DEFAULT_PROFILE_DUGULU, use_foreground, stop_event, is_nieo=False):
                return None
            self._is_in_battle = False
            self._is_scanning_steady_state = True
            return self._neighbor_switch_twomap_after_fail(
                pem=True,
                current_map_id=current_map_id,
                current_prefix=current_prefix,
                use_foreground=use_foreground,
                stop_event=stop_event,
            ) or current_map_id

        self._unified_framework.stage4_post_battle(cfg, is_training_room=False)
        self._battle_count += 1
        if self._note_resource_yellow_victory():
            self._is_in_battle = False
            self._is_scanning_steady_state = True
            return None
        recovery_triggered = self._commit_current_battle_skill_uses_and_maybe_recover(
            use_foreground,
            stop_event,
            log_tag="资源战胜",
        )
        self._csv_log_battle("defeat", sorted(unique_ids))

        self._pem_post_battle_reconnect_check(use_foreground, stop_event)

        self._is_in_battle = False
        self._is_scanning_steady_state = True

        maint_map = self._post_battle_external_maintenance_handoff(use_foreground, stop_event)
        if maint_map is not None:
            return maint_map

        if self._pem_pure_energy_maybe_rotation_then_exit(stop_event, "战胜"):
            return None

        if self._nieo_single_map_escape and not recovery_triggered:
            self._emit(
                f"🧭 [尼奥单图] 战胜后保留 map{current_map_id} 继续扫描",
                "DEBUG",
            )
            return current_map_id

        nxt = self._neighbor_switch_twomap_after_fail(
            pem=True,
            current_map_id=current_map_id,
            current_prefix=current_prefix,
            use_foreground=use_foreground,
            stop_event=stop_event,
        )
        return nxt if nxt is not None else current_map_id

    def _get_farthest_two_points(
        self,
        route_points: List[Tuple[str, Region]],
        reg_a: Region,
        map_id: int,
        prefix: str
    ) -> List[Tuple[str, Region]]:
        """Return the two farthest route points from reg_a."""
        reference_center = self._region_center(reg_a)

        def calc_distance(key_reg: Tuple[str, Region]) -> Tuple[float, str, Region]:
            key, reg = key_reg
            point_center = self._region_center(reg)
            dist = self._dist2(point_center, reference_center)
            return (dist, key, reg)

        point_distances = [calc_distance(p) for p in route_points]

        point_distances.sort(key=lambda x: x[0], reverse=True)

        if len(point_distances) >= 2:
            farthest_points = point_distances[:2]
            sorted_points = [(key, reg) for _, key, reg in farthest_points]
            excluded_points = [(key, reg) for _, key, reg in point_distances[2:]]
            excluded_keys = [k for k, _ in excluded_points]
            included_keys = [k for k, _ in sorted_points]
            self._emit(f"[稀有精灵模式] test farthest 2 points from A: {', '.join(included_keys)} | excluded={', '.join(excluded_keys)}", "INFO")
            return sorted_points
        else:
            self._emit("route points fewer than 2; return all points", "WARN")
            return route_points

    # ---------------------------
    # 智能追踪相关方法
    # ---------------------------
    def _click_region_twice(self, reg_or_key, use_foreground: bool, gap: float = 0.08):
        """Click a region twice."""
        self._click_region(reg_or_key, use_foreground)
        time.sleep(gap)
        self._click_region(reg_or_key, use_foreground)

    def _detect_self_movement(self, timeout: float = 0.8) -> bool:
        """Detect whether self movement triggered a PetItem signal."""
        try:
            if wait_kernel_contains(RE_PETITEM, timeout=timeout, poll=0.05):
                return True
        except Exception:
            pass
        return False

    def _scan_orange_around_point(
        self,
        center_reg: Region,
        scan_radius: int = 100
    ) -> Optional[Tuple[float, float]]:
        """
        以某个刷新点为中心，扫描附近区域的橙色像素，找到橙色精灵的中心位置

        Args:
            center_reg: 刷新点region（作为扫描中心）
            scan_radius: 扫描半径（像素）

        Returns:
            橙色精灵的中心坐标 (x, y)，如果没找到返回None
        """
        ORANGE_COLOR = (254, 103, 0)  # FE6700
        ORANGE_TOLERANCE = 15  # 橙色检测容差

        # 鑾峰彇刷新鐐逛腑蹇?
        cx, cy = self._region_center(center_reg)

        # 璁＄畻鎵弿鍖哄煙锛堜互刷新鐐逛负涓績鐨勬鏂瑰舰锛?
        x1 = max(0, int(cx - scan_radius))
        y1 = max(0, int(cy - scan_radius))
        x2 = int(cx + scan_radius)
        y2 = int(cy + scan_radius)

        try:
            # 鎴彇鎵弿鍖哄煙
            img = window_manager.grab_game_bbox(x1, y1, x2, y2)
            if img is None:
                return None

            # 杞崲涓篟GB鏁扮粍
            arr = np.asarray(img.convert("RGB"), dtype=np.uint8)
            h, w = arr.shape[:2]

            # 鏌ユ壘姗欒壊鍍忕礌
            orange_pixels = []
            tr, tg, tb = ORANGE_COLOR

            for y in range(h):
                for x in range(w):
                    r, g, b = arr[y, x]
                    if (abs(r - tr) <= ORANGE_TOLERANCE and
                        abs(g - tg) <= ORANGE_TOLERANCE and
                        abs(b - tb) <= ORANGE_TOLERANCE):
                        # 杞崲涓烘父鎴忓潗鏍?
                        gx = x1 + x
                        gy = y1 + y
                        orange_pixels.append((gx, gy))

            if not orange_pixels:
                return None

            # 璁＄畻姗欒壊鍍忕礌鐨勪腑蹇冿紙璐ㄥ績锛?
            if len(orange_pixels) == 1:
                return orange_pixels[0]

            # 使用平均
            avg_x = sum(p[0] for p in orange_pixels) / len(orange_pixels)
            avg_y = sum(p[1] for p in orange_pixels) / len(orange_pixels)

            return (avg_x, avg_y)

        except Exception as e:
            self._emit(f"橙色扫描异常：{e}", "WARN")
            return None

    def _track_orange_movement(
        self,
        initial_center: Tuple[float, float],
        center_reg: Region,
        scan_radius: int = 100,
        max_track_time: float = 2.0,
        poll_interval: float = 0.1,
        stop_event: threading.Event = None,
    ) -> Optional[Tuple[float, float]]:
        """Track orange target movement and return the latest center."""
        last_center = initial_center
        t0 = time.time()

        while (time.time() - t0) < max_track_time:
            if stop_event and stop_event.is_set():
                return None

            current_center = self._scan_orange_around_point(center_reg, scan_radius)

            if current_center is None:
                if time.time() - t0 < 0.3:
                    continue
                else:
                    self._emit("tracking lost orange target", "WARN")
                    return last_center

            dx = current_center[0] - last_center[0]
            dy = current_center[1] - last_center[1]
            dist = (dx**2 + dy**2)**0.5

            if dist > 5:
                last_center = current_center
                self._emit(f"tracked orange movement to ({current_center[0]:.0f}, {current_center[1]:.0f}), shift={dist:.1f}px", "DEBUG")

            time.sleep(poll_interval)

        return last_center

    def _find_safe_nearby_point(
        self,
        target_reg: Region,
        target_key: str,
        route_points: Sequence[Tuple[str, Region]],
        exclude_keys: List[str] = None,
    ) -> Optional[Tuple[str, Region]]:
        """Find a nearby safe route point for compensation clicks."""
        target_center = self._region_center(target_reg)
        exclude_keys = exclude_keys or []
        exclude_keys.append(target_key)

        candidates = []
        for key, reg in route_points:
            if key in exclude_keys:
                continue
            center = self._region_center(reg)
            dist = self._dist2(target_center, center)
            candidates.append((dist, key, reg))

        if not candidates:
            return None

        candidates.sort(key=lambda x: x[0])
        return candidates[0][1], candidates[0][2]

    def _smart_click_and_track_rare_pet(
        self,
        target_key: str,
        target_reg: Region,
        route_points: Sequence[Tuple[str, Region]],
        reg_a: Region,
        reg_b: Region,
        profile: WildCaptureProfile,
        use_foreground: bool,
        stop_event: threading.Event,
        max_retries: int = 2,
    ) -> Optional[Tuple[float, float]]:
        """Smart click and track a rare orange target."""
        self._emit(f"启动智能追踪：刷新点 {target_key}", "INFO")

        self._emit("阶段1：双击刷新点", "DEBUG")
        self._click_region_twice(target_reg, use_foreground, gap=0.08)

        moved = self._detect_self_movement(timeout=0.8)

        if moved:
            self._emit("已检测到移动，继续正常流程", "SUCCESS")
            return self._region_center(target_reg)

        self._emit("未检测到移动，开始补偿跟踪", "WARN")

        initial_orange = self._scan_orange_around_point(target_reg, scan_radius=100)

        if initial_orange is None:
            self._emit("cannot find orange target; give up", "ERROR")
            return None

        self._emit(f"initial orange position: ({initial_orange[0]:.0f}, {initial_orange[1]:.0f})", "INFO")

        nearby_point = self._find_safe_nearby_point(
            target_reg, target_key, route_points
        )

        if not nearby_point:
            self._emit("❌ 无法找到附近安全点，放弃", "ERROR")
            return None

        nearby_key, nearby_reg = nearby_point
        self._emit(f"📍 选择附近安全点: {nearby_key}", "DEBUG")

        # 点击闄勮繎瀹夊叏鐐?
        self._click_region(nearby_reg, use_foreground)
        self._current_pos = self._region_center(nearby_reg)

        # 等待移动到附近点
        self._sleep_abortable(stop_event, 1.0)

        # 鎸佺画杩借釜姗欒壊绉诲姩
        tracked_center = self._track_orange_movement(
            initial_orange,
            target_reg,  # 仍然以原始刷新点为扫描中心
            scan_radius=120,  # 绋嶅井鎵╁ぇ鎵弿鑼冨洿
            max_track_time=1.5,
            poll_interval=0.1,
            stop_event=stop_event,
        )

        if tracked_center is None:
            self._emit("tracking lost; give up", "ERROR")
            return None

        self._emit(f"tracked orange new position: ({tracked_center[0]:.0f}, {tracked_center[1]:.0f})", "INFO")

        best_point = None
        best_dist = float('inf')

        for key, reg in route_points:
            center = self._region_center(reg)
            dist = self._dist2(tracked_center, center)
            if dist < best_dist:
                best_dist = dist
                best_point = (key, reg)

        if best_point is None or best_dist > 50**2:
            self._emit(f"orange position is not near any route point (nearest {best_dist**0.5:.1f}px); click orange center directly", "WARN")
            if use_foreground:
                window_manager.click(tracked_center[0], tracked_center[1])
            else:
                window_manager.click_background(tracked_center[0], tracked_center[1])
            return tracked_center

        new_key, new_reg = best_point
        self._emit(f"橙点移动到刷新点附近：{new_key}；双击", "INFO")

        self._click_region_twice(new_reg, use_foreground, gap=0.08)

        battle_triggered = self._detect_self_movement(timeout=0.8)

        if battle_triggered:
            self._emit("战斗触发成功", "SUCCESS")
            return self._region_center(new_reg)

        self._emit("战斗仍未触发，移动到另一侧", "WARN")

        # 鎵惧埌精灵鍙︿竴渚х殑瀹夊叏鐐?
        opposite_point = self._find_safe_nearby_point(
            new_reg, new_key, route_points, exclude_keys=[target_key, nearby_key]
        )

        if opposite_point:
            opp_key, opp_reg = opposite_point
            self._emit(f"move to opposite safe point: {opp_key}", "DEBUG")
            self._click_region(opp_reg, use_foreground)
            self._current_pos = self._region_center(opp_reg)
            self._sleep_abortable(stop_event, 1.0)

            # 鍐嶆杩借釜姗欒壊位置
            latest_orange = self._scan_orange_around_point(new_reg, scan_radius=120)
            if latest_orange:
                # 鍐嶆点击姗欒壊位置闄勮繎鐨勫埛鏂扮偣
                final_point = None
                final_dist = float('inf')
                for key, reg in route_points:
                    center = self._region_center(reg)
                    dist = self._dist2(latest_orange, center)
                    if dist < final_dist:
                        final_dist = dist
                        final_point = (key, reg)

                if final_point and final_dist <= 50**2:
                    final_key, final_reg = final_point
                    self._emit(f"最后点击刷新点：{final_key}", "INFO")
                    self._click_region_twice(final_reg, use_foreground, gap=0.08)

                    if self._detect_self_movement(timeout=0.8):
                        return self._region_center(final_reg)

        self._emit("补偿追踪失败，放弃本场", "ERROR")
        return None

    @staticmethod
    def _hit_target_mp3(lines: List[str], mp3_id_or_ids) -> bool:
        """Return whether kernel lines contain target pet sound mp3 IDs."""
        return lines_have_target_pet_sound_id(lines, mp3_id_or_ids)

    def _sleep_abortable(self, stop_event: Optional[threading.Event], seconds: float, tick: float = 0.1):
        end = time.time() + float(max(0.0, seconds))
        while time.time() < end:
            if stop_event is not None and stop_event.is_set():
                return
            if getattr(self.bot, "stop_current", False):
                return
            if getattr(self.bot, "is_paused", False):
                time.sleep(0.05)
                continue
            time.sleep(tick)

    def _wait_if_paused(self, stop_event: threading.Event):
        if hasattr(self.bot, "wait_if_paused") and callable(getattr(self.bot, "wait_if_paused")):
            self.bot.wait_if_paused()
            return
        while getattr(self.bot, "is_paused", False) and (not stop_event.is_set()) and (not getattr(self.bot, "stop_current", False)):
            time.sleep(0.05)

    def _emit(self, text: str, level: str = "INFO"):
        if hasattr(self.bot, "emit_and_log") and callable(getattr(self.bot, "emit_and_log")):
            try:
                self.bot.emit_and_log(text, level)
                return
            except Exception:
                pass
        if level == "ERROR":
            log.error(text)
        elif level in ("WARN", "WARNING"):
            log.warning(text)
        else:
            log.info(text)

    # ------------------------------------------------------------------ #
    #  挂机对战模式（AFK Battle锛夆€?4 种子模式                              #
    # ------------------------------------------------------------------ #
    def run_afk_battle_mode(
        self,
        stop_event: threading.Event,
        use_foreground: bool,
        sub_mode: str = "normal",
    ) -> None:
        """Run AFK battle mode."""
        from core.logger import fetch_kernel_since, kernel_cursor
        from core.unified_battle_framework import BattleConfig, BattleMode, LastActionType

        MODE_LABELS = {
            "normal": "挂机普通",
            "defeat": "挂机击败",
            "rare": "挂机稀有",
            "nieo": "挂机尼奥",
        }
        label = MODE_LABELS.get(sub_mode, sub_mode)

        self._current_mode = f"afk_{sub_mode}"
        self._battle_count = 0
        self._emit(f"{label}模式已启动，等待入战信号...", "SYSTEM")

        NIE_FAMILY = {77, 310, 416}

        # ---- 鏋勫缓 action_callback ----
        def _make_action_callback_normal(round_idx: int) -> str:
            if round_idx == 1:
                return "skill"
            return "capsule"

        def _make_action_callback_defeat(round_idx: int) -> str:
            return "skill4"

        def _make_action_callback_nieo(round_idx: int) -> str:
            if round_idx == 1:
                return "skill"
            return "capsule"

        while not stop_event.is_set() and not getattr(self.bot, "stop_current", False):
            # ---------- 1. 等待入战信号 ----------
            cursor = kernel_cursor()
            petitem_already = False
            battle_found = False

            while not stop_event.is_set() and not getattr(self.bot, "stop_current", False):
                lines = fetch_kernel_since(cursor)
                cursor = kernel_cursor()
                if not lines:
                    time.sleep(0.1)
                    continue

                for idx, line in enumerate(lines):
                    s = str(line)
                    if line_matches(RE_PETITEM, s):
                        collected = self._collect_fight_pet_ids_immediate(
                            stop_event, current_lines=lines, start_index=idx,
                        )
                        if collected:
                            self._immediate_collected_pet_ids = collected
                        petitem_already = True
                        battle_found = True
                        break
                    elif line_matches(RE_FIGHT_PET, s):
                        collected = self._collect_fight_pet_ids_immediate(
                            stop_event, current_lines=lines, start_index=idx,
                        )
                        if collected:
                            self._immediate_collected_pet_ids = collected
                        battle_found = True
                        break

                if battle_found:
                    break

            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                break

            self._emit(f"检测到入战信号（第{self._battle_count + 1}场）", "INFO")

            # ---------- 2. 纭畾鏈鎴樻枟鐨?action_callback ----------
            collected_ids = set(getattr(self, "_immediate_collected_pet_ids", None) or [])
            nie_id: Optional[int] = None
            need_recover = False

            if sub_mode == "rare":
                nie_family_found = collected_ids & NIE_FAMILY
                if nie_family_found:
                    nie_id = list(nie_family_found)[0]
                    self._last_nie_family_id = nie_id
                    self._emit(f"检测到尼尔家族 {nie_id}，执行切换策略", "SYSTEM")

                    def action_cb_nie(round_idx: int, _nid=nie_id) -> str:
                        limit_action = self._nie_family_round_limit_action(
                            round_idx,
                            use_foreground,
                            allow_escape=True,
                        )
                        if limit_action is not None:
                            return limit_action
                        if round_idx == 1:
                            return "skill"
                        elif round_idx == 2:
                            if not self._switch_pet_for_nie_family(_nid, use_foreground, stop_event, test_mode=False):
                                self._emit("[配置尼奥] 尼尔家族切换失败，进入胶囊循环", "WARN")
                                return "capsule"
                            return "switch"
                        else:
                            return "capsule"

                    action_callback = action_cb_nie
                else:
                    self._emit("稀有精灵单捕策略（技能一 + 胶囊）", "SYSTEM")
                    action_callback = _make_action_callback_normal
            elif sub_mode == "defeat":
                action_callback = _make_action_callback_defeat
            elif sub_mode == "nieo":
                action_callback = _make_action_callback_nieo
            else:
                action_callback = _make_action_callback_normal

            skill_key = "对战.使用技能四" if sub_mode == "defeat" else "对战.使用技能一"

            # ---------- 3. 鏋勫缓 BattleConfig ----------
            config = BattleConfig(
                mode=BattleMode.WILD,
                use_foreground=use_foreground,
                skill_key=skill_key,
                action_callback=action_callback,
                abort_check=lambda: stop_event.is_set() or getattr(self.bot, "stop_current", False),
                round_timeout_sec=60.0,
                capsule_cycle_tiers_override=self._capsule_cycle_tiers_for_current_battle(),
            )

            # ---------- 4. Stage 2 ----------
            if petitem_already:
                self._emit("已检测到 PetItem，直接执行第1回合", "INFO")
                try:
                    act = action_callback(1)
                    self._unified_framework._execute_action(act, config, round_idx=1)
                except Exception as e:
                    self._emit(f"执行第1回合失败：{e}", "WARN")
                success = True
            else:
                stage2_cursor = kernel_cursor()
                success, calib_result = self._unified_framework.stage2_calibration_and_petitem(
                    trigger_callback=None,
                    use_foreground=use_foreground,
                    timeout_s=15.0,
                    skip_stage1=True,
                    config=config,
                    initial_cursor=stage2_cursor,
                )

            if not success:
                self._emit("阶段2失败，跳过本场并继续等待", "WARN")
                time.sleep(1.0)
                continue

            # ---------- 5. Stage 3 ----------
            battle_success = self._unified_framework.stage3_battle_loop(config)
            if not battle_success:
                self._emit("阶段3失败", "WARN")
                from core.dar_route_runner import DEFAULT_PROFILE_DUGULU
                if self._handle_stage3_round_timeout_reconnect(
                    DEFAULT_PROFILE_DUGULU, use_foreground, stop_event, is_nieo=False,
                ):
                    return
                time.sleep(1.0)
                continue

            # ---------- 6. Stage 4 ----------
            self._unified_framework.stage4_post_battle(config, is_training_room=False)
            self._battle_count += 1

            # ---------- 7. 缁撴灉鍒ゅ畾涓庢棩蹇?----------
            if sub_mode == "defeat":
                result_str = "defeat"
            elif sub_mode == "rare" and self._unified_framework._last_action == LastActionType.CAPSULE:
                result_str = "captured"
                need_recover = True
            else:
                result_str = "battled"

            self._emit(f"第 {self._battle_count} 场战斗结束（{result_str}），继续等待战斗信号", "SUCCESS")

            # ---------- 8. 绋€鏈夋ā寮忔崟鎹夋垚鍔熷悗鎭㈠精灵 ----------
            if need_recover:
                self._emit("捕捉成功，恢复精灵", "INFO")
                self._sleep_abortable(stop_event, 3.0)
                self._is_recovering = True
                recovery_ok = self._recover_pets(
                    use_foreground, stop_event,
                    skip_return_storage=False,
                    nie_family_id=nie_id,
                    profile=None,
                )
                self._is_recovering = False
                self._last_nie_family_id = None
                if not recovery_ok:
                    break

        self._emit(f"{label} 模式已停止；已完成 {self._battle_count} 场战斗", "SYSTEM")

    # ------------------------------------------------------------------ #
    #  娲诲姩精灵模式锛堝崟鍥?A锛涢亣鏁?鎴樻枟绛栫暐鐧界洅锛?                           #
    # ------------------------------------------------------------------ #

    def _event_pet_guard_map(
        self,
        profile: "EventPetModeProfile",
        use_foreground: bool,
        stop_event: threading.Event,
        *,
        tag: str = "活动精灵",
    ) -> bool:
        """Return True if map is correct; otherwise trigger reconnect and return False."""
        actual = self._get_last_map_id()
        if actual is None:
            return True
        if int(actual) == int(profile.map_a_id):
            return True
        self._emit(
            f"[{tag}] kernel map={actual}, expected map{profile.map_a_id}; refresh reconnect",
            "WARN",
        )
        self._event_pet_trigger_reconnect(profile, use_foreground, stop_event, reason="map突变")
        return False

    def _event_pet_verify_map_after_battle(
        self,
        profile: "EventPetModeProfile",
        use_foreground: bool,
        stop_event: threading.Event,
        *,
        battle_start_cursor: int,
    ) -> bool:
        """Verify a fresh post-battle map/NewNPC pair; reconnect if absent or wrong."""
        expected = int(profile.map_a_id)
        cursor = max(0, int(battle_start_cursor))
        fresh_lines: List[str] = []
        deadline = time.time() + 8.0
        last_map_id: Optional[int] = None

        self._emit(
            f"[活动精灵] 战后地图检查：只扫描本场入战后新日志（cursor={cursor}）",
            "INFO",
        )
        while time.time() < deadline:
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return False
            rows = fetch_kernel_since(cursor, return_rows=True)
            if isinstance(rows, list) and rows:
                for row in rows:
                    if isinstance(row, tuple) and len(row) >= 3:
                        cursor = max(cursor, int(row[0]))
                        fresh_lines.append(str(row[2]))

            newnpc_idx = -1
            for idx in range(len(fresh_lines) - 1, -1, -1):
                if line_matches(RE_NEWNPC_MULTI, fresh_lines[idx]):
                    newnpc_idx = idx
                    break
            if newnpc_idx >= 0:
                for idx in range(newnpc_idx - 1, -1, -1):
                    last_map_id = first_map_id_in_line(fresh_lines[idx])
                    if last_map_id is not None:
                        break
                if last_map_id == expected:
                    self._emit(
                        f"[活动精灵] 战后地图检查通过：新日志 map{expected} + NewNPC",
                        "SUCCESS",
                    )
                    return True
                if last_map_id is not None:
                    break
            time.sleep(0.1)

        actual = last_map_id if last_map_id is not None else self._get_last_map_id()
        self._emit(
            f"[活动精灵] 战后未发现本场的新 map{expected} + NewNPC "
            f"(fresh_map={last_map_id}, last_known_map={actual}); reconnect",
            "WARN",
        )
        self._event_pet_trigger_reconnect(
            profile, use_foreground, stop_event, reason="战后新地图信号缺失或错位"
        )
        return False

    def _apply_event_pet_pick_overrides(self, profile: "EventPetModeProfile") -> None:
        """Apply event-pet pick overrides."""
        rev = int(profile.pick_flight_reverse)
        pid = int(profile.pick_flight_pet_id)
        self._pickmode_flight_reverse_override = rev
        self._pickmode_flight_pet_id_override = pid
        _FLIGHT_LABEL = {164: "闪光皮皮(164)", 166: "闪光皮皮(166)"}
        label = _FLIGHT_LABEL.get(pid, f"飞行系({pid})")
        self._emit(
            f"[活动精灵-Pick] flight reverse {rev} -> {label}",
            "INFO",
        )

    def _clear_event_pet_pick_overrides(self) -> None:
        for attr in ("_pickmode_flight_reverse_override", "_pickmode_flight_pet_id_override"):
            if hasattr(self, attr):
                delattr(self, attr)

    def _event_pet_trigger_reconnect(
        self,
        profile: "EventPetModeProfile",
        use_foreground: bool,
        stop_event: threading.Event,
        *,
        reason: str,
    ) -> None:
        """Trigger reconnect for event-pet flows."""
        self._emit(
            f"[活动精灵-{profile.name}-{reason}] trigger reconnect to event map {profile.map_a_id}",
            "WARN",
        )
        if getattr(self, "_event_pet_active_rotation", False):
            self._event_pet_rotation_reconnect_requested = True
            self._should_restart_after_reconnect = False
            self._event_pet_restart_profile = None
            self._event_pet_restart_skip_pre = False
            self._emit(
                f"[活动精灵-{profile.name}-{reason}] rotation mode: hand reconnect back to rotation layer",
                "SYSTEM",
            )
            return
        self._should_restart_after_reconnect = True
        self._event_pet_restart_profile = profile
        self._event_pet_restart_skip_pre = False

    def _pickmode_expected_party_ids(self) -> frozenset:
        """Expected party IDs for current pick branch."""
        return PICKMODE_STANDARD_PARTY_IDS

    def _pickmode_target_party_id_list(
        self,
        target_pet_id: int,
        *,
        base_pet_id: int = PICKMODE_CYAN_BASE_PET_ID,
    ) -> Tuple[int, ...]:
        """普通六宠中用目标青色替换指定基准宠；目标已存在时避免重复。"""
        target = int(target_pet_id)
        base = int(base_pet_id)
        if target in PICKMODE_STANDARD_PARTY_IDS and target != base:
            return tuple(PICKMODE_STANDARD_PARTY_ID_LIST)
        result: List[int] = []
        for pet_id in PICKMODE_STANDARD_PARTY_ID_LIST:
            if int(pet_id) == base:
                if target not in result:
                    result.append(target)
                continue
            if int(pet_id) not in result:
                result.append(int(pet_id))
        return tuple(result)

    def _pickmode_recent_party_ids_for_pick(self) -> set[int]:
        found_ids: set[int] = set()
        first_map_cursor = getattr(self, "_refresh_pipeline_first_map_kernel_cursor", None)
        if first_map_cursor is not None:
            lines = fetch_kernel_since(int(first_map_cursor))
        else:
            lines = fetch_kernel_since(0)
        if not isinstance(lines, list):
            lines = []
        for line in lines:
            for pid in iter_party_pet_swf_ids_in_line(str(line)):
                found_ids.add(int(pid))

        all_lines = fetch_kernel_since(0)
        if isinstance(all_lines, list):
            between_ids, _bounds = collect_fight_pet_swf_ids_between_latest_two_maps(all_lines)
            for pid in between_ids:
                found_ids.add(int(pid))
        return found_ids

    def _pickmode_classify_target_cyan_party(
        self,
        target_pet_id: int,
        *,
        log_tag: str,
        base_pet_id: int = PICKMODE_CYAN_BASE_PET_ID,
    ) -> Tuple[str, set[int], Tuple[int, ...]]:
        target_list = self._pickmode_target_party_id_list(
            target_pet_id,
            base_pet_id=base_pet_id,
        )
        target_ids = set(target_list)
        ordinary_ids = set(PICKMODE_STANDARD_PARTY_IDS)
        found_ids = self._pickmode_recent_party_ids_for_pick()
        found_text = ",".join(str(x) for x in sorted(found_ids)) if found_ids else "无"
        target_text = ",".join(str(x) for x in target_list)
        ordinary_text = ",".join(str(x) for x in PICKMODE_STANDARD_PARTY_ID_LIST)

        if target_ids.issubset(found_ids):
            self._emit(
                f"[{log_tag}] SWF 命中目标组，保持当前六宠不重取：目标={target_text}，已见={found_text}",
                "SUCCESS",
            )
            return "target", found_ids, target_list
        if ordinary_ids.issubset(found_ids):
            self._emit(f"[{log_tag}] SWF 命中普通六宠：普通={ordinary_text}，已见={found_text}", "INFO")
            return "ordinary", found_ids, target_list
        self._emit(
            f"[{log_tag}] SWF 未命中目标组/普通六宠，准备清包重取：目标={target_text}，已见={found_text}",
            "WARN",
        )
        return "mismatch", found_ids, target_list

    def _event_pet_expected_party_ids(self, profile: "EventPetModeProfile") -> frozenset:
        """Expected party IDs for event-pet pick."""
        _ = profile
        return self._pickmode_expected_party_ids()

    def _rotation_expected_party_ids_for_segment(
        self, schedule_mode: str
    ) -> Optional[frozenset]:
        """Expected party IDs for a rotation/reconnect segment."""
        seg = (schedule_mode or "").strip()
        if seg == "eit":
            from core.event_pet_mode_registry import get_profile as get_event_profile

            root = getattr(self.bot, "project_root", None) or os.path.dirname(
                os.path.dirname(os.path.abspath(__file__))
            )
            pf = get_event_profile(root, "yite")
            if pf is None:
                return None
            return self._event_pet_expected_party_ids(pf)
        return self._pickmode_expected_party_ids()

    def _prepare_rotation_segment_pick_overrides(self, schedule_mode: str) -> None:
        """Prepare pick overrides for a rotation segment."""
        self._clear_event_pet_pick_overrides()
        if (schedule_mode or "").strip() != "eit":
            return
        from core.event_pet_mode_registry import get_profile as get_event_profile

        root = getattr(self.bot, "project_root", None) or os.path.dirname(
            os.path.dirname(os.path.abspath(__file__))
        )
        pf = get_event_profile(root, "yite")
        if pf is not None:
            self._apply_event_pet_pick_overrides(pf)

    def _execute_event_pet_pre_reconnect(
        self,
        profile: "EventPetModeProfile",
        use_foreground: bool,
        stop_event: threading.Event,
    ) -> bool:
        """Run event-pet pre-reconnect: pick, to-script, and map A gate."""
        prev_rev = getattr(self, "_pickmode_flight_reverse_override", None)
        prev_pid = getattr(self, "_pickmode_flight_pet_id_override", None)
        party_ids = self._event_pet_expected_party_ids(profile)
        try:
            self._apply_event_pet_pick_overrides(profile)
            return self._execute_nieo_pre_rotation_reconnect(
                use_foreground=use_foreground,
                stop_event=stop_event,
                pem_route=False,
                to_script=profile.to_script,
                expected_map_id=int(profile.map_a_id),
                expected_party_ids=party_ids,
                reason=f"{profile.name}-前置重连",
            )
        finally:
            if prev_rev is None:
                if hasattr(self, "_pickmode_flight_reverse_override"):
                    delattr(self, "_pickmode_flight_reverse_override")
            else:
                self._pickmode_flight_reverse_override = prev_rev
            if prev_pid is None:
                if hasattr(self, "_pickmode_flight_pet_id_override"):
                    delattr(self, "_pickmode_flight_pet_id_override")
            else:
                self._pickmode_flight_pet_id_override = prev_pid

    def _event_pet_run_screen_calibration(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
        log_tag: str,
        entry_guard_cursor: Optional[int] = None,
    ) -> bool:
        if not self._unified_framework:
            return False
        if entry_guard_cursor is not None:
            try:
                from core.logger import fetch_kernel_since

                fresh_lines = fetch_kernel_since(entry_guard_cursor)
                if isinstance(fresh_lines, list):
                    for line in fresh_lines:
                        s = str(line)
                        if line_matches(RE_PETITEM, s) or line_matches(RE_FIGHT_PET, s):
                            self._emit(f"[{log_tag}] 校准前已检测到入战信号，跳过校准清理", "INFO")
                            return False
            except Exception as e:
                self._emit(f"[{log_tag}] 校准前内核检查异常：{e}", "DEBUG")
        if not self._unified_framework._check_calibration_probes():
            return False
        self._emit(f"[{log_tag}] 检测到校准探针，开始清理校准", "WARN")
        x_values, _regions_dict = self._unified_framework._calculate_x_values()
        _distribution, target_idx = self._unified_framework._analyze_distribution(x_values)
        if target_idx is None:
            self._emit(f"[{log_tag}] 校准失败：无法判断目标组", "WARN")
            return False
        if entry_guard_cursor is not None:
            try:
                from core.logger import fetch_kernel_since

                fresh_lines = fetch_kernel_since(entry_guard_cursor)
                if isinstance(fresh_lines, list):
                    for line in fresh_lines:
                        s = str(line)
                        if line_matches(RE_PETITEM, s) or line_matches(RE_FIGHT_PET, s):
                            self._emit(f"[{log_tag}] 校准点击前已检测到入战信号，取消清理", "INFO")
                            return False
            except Exception as e:
                self._emit(f"[{log_tag}] 校准点击前内核检查异常：{e}", "DEBUG")
        self._unified_framework._calibrate_click_group(target_idx, use_foreground)
        self._sleep_abortable(stop_event, 0.35)
        self._emit(f"[{log_tag}] 校准已清理", "SUCCESS")
        return True

    def _event_pet_poll_entry_swf_since(
        self,
        profile: "EventPetModeProfile",
        cursor: int,
        stop_event: threading.Event,
    ) -> Tuple[bool, int]:
        lines = fetch_kernel_since(max(0, cursor))
        new_cursor = kernel_cursor()
        target_id = int(profile.entry_pet_id)
        for idx, line in enumerate(lines or []):
            line_str = str(line)
            if not line_matches(RE_FIGHT_PET, line_str):
                continue
            for m in finditer_kernel_line(RE_FIGHT_PET_ID, line_str):
                try:
                    pid = int(m.group(1))
                except (TypeError, ValueError):
                    continue
                if pid != target_id:
                    continue
                collected = self._collect_fight_pet_ids_immediate(
                    stop_event, current_lines=lines, start_index=idx
                )
                if collected:
                    self._immediate_collected_pet_ids = collected
                self._eit_battle_kernel_cursor = max(0, cursor)
                self._emit(
                    f"[活动精灵] detected pet/swf/{target_id}; "
                    f"IDs={sorted(collected) if collected else '[]'}",
                    "SUCCESS",
                )
                return True, new_cursor
        return False, new_cursor

    def _event_pet_peek_entry_since(
        self,
        profile: "EventPetModeProfile",
        stop_event: threading.Event,
        cursor: int,
    ) -> Tuple[str, int]:
        """Non-blocking entry snapshot: return battle, calibration, or none plus cursor."""
        if stop_event.is_set() or getattr(self.bot, "stop_current", False):
            return "none", cursor
        lines = fetch_kernel_since(cursor)
        new_cursor = kernel_cursor()
        target_id = int(profile.entry_pet_id)
        for idx, line in enumerate(lines or []):
            line_str = str(line)
            if line_matches(RE_PETITEM, line_str):
                self._eit_battle_kernel_cursor = max(0, cursor)
                self._emit("[活动精灵] 检测到 PetItem，已入战", "SUCCESS")
                return "battle", new_cursor
            if line_matches(RE_FIGHT_PET, line_str):
                for m in finditer_kernel_line(RE_FIGHT_PET_ID, line_str):
                    try:
                        pid = int(m.group(1))
                    except (TypeError, ValueError):
                        continue
                    if pid != target_id:
                        continue
                    collected = self._collect_fight_pet_ids_immediate(
                        stop_event, current_lines=lines, start_index=idx
                    )
                    if collected:
                        self._immediate_collected_pet_ids = collected
                    self._eit_battle_kernel_cursor = max(0, cursor)
                    self._emit(
                        f"[活动精灵] detected pet/swf/{target_id}; "
                        f"IDs={sorted(collected) if collected else '[]'}",
                        "SUCCESS",
                    )
                    return "battle", new_cursor
        if self._unified_framework:
            try:
                fresh_lines = fetch_kernel_since(cursor)
                if isinstance(fresh_lines, list):
                    for idx, line in enumerate(fresh_lines):
                        line_str = str(line)
                        if line_matches(RE_PETITEM, line_str):
                            collected = self._collect_fight_pet_ids_immediate(
                                stop_event, current_lines=fresh_lines, start_index=idx
                            )
                            if collected:
                                self._immediate_collected_pet_ids = collected
                            self._eit_battle_kernel_cursor = max(0, cursor)
                            self._emit("[活动精灵] 校准前已检测到 PetItem，跳过校准", "SUCCESS")
                            return "battle", kernel_cursor()
                        if line_matches(RE_FIGHT_PET, line_str):
                            collected = self._collect_fight_pet_ids_immediate(
                                stop_event, current_lines=fresh_lines, start_index=idx
                            )
                            if collected:
                                self._immediate_collected_pet_ids = collected
                            self._eit_battle_kernel_cursor = max(0, cursor)
                            self._emit("[活动精灵] 校准前已检测到 fightResource/pet/swf，跳过校准", "SUCCESS")
                            return "battle", kernel_cursor()
            except Exception as e:
                self._emit(f"[活动精灵] 校准前内核检查异常：{e}", "DEBUG")

        if self._unified_framework and self._unified_framework._check_calibration_probes():
            return "calibration", new_cursor
        return "none", new_cursor

    def _event_pet_hunt_dispatch(
        self,
        profile: "EventPetModeProfile",
        use_foreground: bool,
        stop_event: threading.Event,
    ) -> str:
        """Dispatch event-pet hunt strategy. Return entered, aborted, or reconnect."""
        strategy = (profile.hunt_strategy or "").strip().lower()
        if strategy == "eit_ui_v2":
            return self._event_pet_hunt_eit_ui_v2(profile, use_foreground, stop_event)
        self._emit(f"[活动精灵] unknown hunt_strategy={profile.hunt_strategy!r}", "ERROR")
        return "aborted"

    def _event_pet_hunt_eit_ui_v2(
        self,
        profile: "EventPetModeProfile",
        use_foreground: bool,
        stop_event: threading.Event,
    ) -> str:
        """Event pet EIT UI v2 hunt loop."""
        prefix = profile.region_prefix
        min_cycles = int(profile.min_cycles_before_entry)
        key0 = prefix
        key1 = f"{prefix}.1"
        key2 = f"{prefix}.2"
        key3 = f"{prefix}.3"

        self._emit(
            f"[活动精灵/{profile.name}] UI hunt: state machine; "
            f"detect target pet/swf/{profile.entry_pet_id} after cycle {min_cycles}",
            "INFO",
        )

        hunt_cursor = kernel_cursor()
        cycles_without_progress = 0
        cycle_idx = 0
        phase = "new_cycle"
        next_action_at = 0.0
        next_click1_at = 0.0
        click1_deadline = 0.0
        click1_count = 0

        def _handle_entry_probe(
            probe: str,
            *,
            cycle_idx: int,
            phase: str,
            entry_guard_cursor: Optional[int] = None,
        ) -> Optional[str]:
            nonlocal cycles_without_progress
            if probe == "battle":
                self._emit(
                    f"[活动精灵] cycle {cycle_idx} phase {phase}: battle detected",
                    "SUCCESS",
                )
                return "entered"
            if probe == "calibration":
                self._event_pet_run_screen_calibration(
                    use_foreground,
                    stop_event,
                    profile.name,
                    entry_guard_cursor=entry_guard_cursor,
                )
                cycles_without_progress = 0
                self._emit(
                    f"[活动精灵] 第 {cycle_idx} 轮 {phase} 阶段：校准已清理，继续点击循环",
                    "SYSTEM",
                )
            return None

        def _peek_if_active(cycle_idx: int, phase: str) -> Optional[str]:
            nonlocal hunt_cursor
            if cycle_idx < min_cycles:
                return None
            probe, new_cursor = self._event_pet_peek_entry_since(
                profile, stop_event, hunt_cursor
            )
            hunt_cursor = new_cursor
            return _handle_entry_probe(
                probe,
                cycle_idx=cycle_idx,
                phase=phase,
                entry_guard_cursor=new_cursor,
            )

        while not stop_event.is_set() and not getattr(self.bot, "stop_current", False):
            now = time.time()

            out = _peek_if_active(cycle_idx, phase)
            if out == "entered":
                return "entered"

            if now < next_action_at:
                time.sleep(EIT_HUNT_TICK_SEC)
                continue

            if phase == "new_cycle":
                cycle_idx += 1
                if not self._event_pet_guard_map(profile, use_foreground, stop_event):
                    return "reconnect"
                if cycle_idx == min_cycles:
                    hunt_cursor = kernel_cursor()
                    self._emit(
                        f"[活动精灵] cycle {cycle_idx}: enable battle detection; cursor reset to current kernel",
                        "INFO",
                    )
                self._emit(
                    f"[伊特] hunt cycle {cycle_idx}"
                    + (" (warmup, no detect)" if cycle_idx < min_cycles else " (nonblocking detect on)"),
                    "INFO" if cycle_idx <= min_cycles or cycle_idx % 3 == 0 else "DEBUG",
                )
                phase = "click0"
                next_action_at = now
                continue

            if phase == "click0":
                try:
                    self._click_region(key0, use_foreground)
                except KeyError:
                    self._emit(f"[活动精灵] 缺少区域：{key0}", "ERROR")
                    return "aborted"
                click1_count = 0
                next_click1_at = 0.0
                click1_deadline = now + EIT_CLICK1_WHITE_TIMEOUT_SEC
                phase = "click1_wait_white"
                next_action_at = now + EIT_HUNT_TICK_SEC
                continue

            if phase == "click1_wait_white":
                if click1_count > 0 and self._eit_is_white_probe_ready():
                    self._emit(
                        f"[伊特] white probe ready after {click1_count} clicks on {key1}",
                        "INFO",
                    )
                    phase = "click2"
                    next_action_at = now
                    continue
                if now >= click1_deadline:
                    self._emit(
                        f"[伊特] {key1} 白色探针等待超过 "
                        f"{EIT_CLICK1_WHITE_TIMEOUT_SEC:.0f}s，触发重连",
                        "WARN",
                    )
                    self._event_pet_trigger_reconnect(
                        profile,
                        use_foreground,
                        stop_event,
                        reason="伊特.1白色探针超时",
                    )
                    return "reconnect"
                if now >= next_click1_at:
                    if click1_count > 0:
                        self._emit(
                            f"[伊特] {key1} not white after {EIT_CLICK1_WHITE_RETRY_SEC:.0f}s; click again",
                            "DEBUG",
                        )
                    try:
                        self._click_region(key1, use_foreground)
                    except KeyError:
                        self._emit(f"[活动精灵] 缺少区域：{key1}", "ERROR")
                        return "aborted"
                    click1_count += 1
                    next_click1_at = now + EIT_CLICK1_WHITE_RETRY_SEC
                next_action_at = now + EIT_HUNT_TICK_SEC
                continue

            if phase == "click2":
                try:
                    self._click_region(key2, use_foreground)
                except KeyError:
                    self._emit(f"[活动精灵] 缺少区域：{key2}", "ERROR")
                    return "aborted"
                phase = "click3_first"
                next_action_at = now + 0.06
                continue

            if phase == "click3_first":
                try:
                    self._click_region(key3, use_foreground)
                except KeyError:
                    self._emit(f"[活动精灵] 缺少区域：{key3}", "ERROR")
                    return "aborted"
                phase = "click3_second"
                next_action_at = now + 0.06
                continue

            if phase == "click3_second":
                try:
                    self._click_region(key3, use_foreground)
                except KeyError:
                    self._emit(f"[活动精灵] 缺少区域：{key3}", "ERROR")
                    return "aborted"
                if cycle_idx >= min_cycles:
                    cycles_without_progress += 1
                    if cycles_without_progress >= EIT_HUNT_MAX_CYCLES_WITHOUT_PROGRESS:
                        self._emit(
                            f"[活动精灵] cycle {cycle_idx}: {cycles_without_progress} cycles without battle/calibration; reconnect",
                            "WARN",
                        )
                        self._event_pet_trigger_reconnect(
                            profile, use_foreground, stop_event, reason="hunt loop timeout"
                        )
                        return "reconnect"
                phase = "new_cycle"
                next_action_at = now + 0.08
                continue

            self._emit(f"[活动精灵] unknown EIT hunt phase: {phase}", "ERROR")
            return "aborted"

        return "aborted"

    def _event_pet_battle_dispatch(
        self,
        profile: "EventPetModeProfile",
        use_foreground: bool,
        stop_event: threading.Event,
    ) -> str:
        """Dispatch event-pet battle strategy."""
        strategy = (profile.battle_strategy or "").strip().lower()
        if strategy == "eit_hp_jita_capture":
            return self._eit_run_battle(use_foreground, stop_event)
        self._emit(
            f"[活动精灵] unknown battle_strategy={profile.battle_strategy!r}",
            "ERROR",
        )
        return "failed"

    def _event_pet_recover_after_capture(
        self,
        profile: "EventPetModeProfile",
        use_foreground: bool,
        stop_event: threading.Event,
    ) -> bool:
        """Recover pets after event-pet capture."""
        return self._recover_pets(
            use_foreground,
            stop_event,
            skip_return_storage=False,
            nie_family_id=None,
            profile=None,
        )

    def _event_pet_recover_slots_one_and_jita(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
        bag_open_key: str,
        bag_open_btn_key: str,
    ) -> bool:
        """Compatibility wrapper for event-pet post-battle recovery."""
        if not self._recover_and_identify_pickmode_bag_slots(
            use_foreground, stop_event, "伊特.战后"
        ):
            self._emit("[伊特] 战后恢复/识别失败", "ERROR")
            self._close_pet_bag_with_verify(
                use_foreground,
                stop_event,
                bag_open_key,
                bag_open_btn_key,
                log_tag="伊特",
            )
            return False
        self._sleep_abortable(stop_event, 0.3)
        self._close_pet_bag_with_verify(
            use_foreground, stop_event, bag_open_key, bag_open_btn_key, log_tag='伊特'
        )
        self._emit("[伊特] 战后恢复完成", "SUCCESS")
        return True

    def _event_pet_post_start_bag_scan(
        self, use_foreground: bool, stop_event: threading.Event, log_tag: str
    ) -> bool:
        """Open pet bag, recover, identify slots, then close it."""
        bag_open_btn = "精灵背包.打开精灵背包按钮"
        bag_open = "精灵背包.打开精灵背包"
        try:
            self._click_region(bag_open_btn, use_foreground)
        except KeyError:
            self._click_region(bag_open, use_foreground)
        if not self._wait_pet_bag_ui_ready_after_open(stop_event, log_tag=log_tag):
            self._emit(f"❌ [{log_tag}] 背包UI未就绪，请求重连并重启活动精灵", "ERROR")
            self._request_mode_restart(
                stop_event,
                f"{log_tag}-背包UI未就绪",
            )
            return False
        if not self._recover_and_identify_pickmode_bag_slots(
            use_foreground, stop_event, log_tag
        ):
            self._emit(f"❌ [{log_tag}] 恢复/识别背包槽位失败，请求重连", "ERROR")
            self._request_mode_restart(
                stop_event,
                f"{log_tag}-恢复识别背包失败",
            )
            return False
        self._pickmode_base_recovery_done = True
        self._close_pet_bag_with_verify(
            use_foreground, stop_event, bag_open, bag_open_btn, log_tag=log_tag
        )
        return True

    def run_event_pet_mode(
        self,
        profile: "EventPetModeProfile",
        stop_event: threading.Event,
        use_foreground: bool,
        *,
        skip_pre_rotation: bool = False,
        is_rotation_mode: bool = False,
        next_switch_time: Optional[datetime] = None,
    ) -> bool:
        """Run the event-pet main loop."""
        self._active_use_foreground = bool(use_foreground)
        if next_switch_time is None:
            next_switch_time = getattr(self, "_next_rotation_switch_time", None)
        active_rotation = bool(is_rotation_mode or getattr(self, "_is_rotation_mode", False))
        if active_rotation:
            self._is_rotation_mode = True
            if next_switch_time:
                self._next_rotation_switch_time = next_switch_time
                if self.ROTATION_TEST_MODE:
                    self._test_mode_start_time = time.time()
                self._emit(
                    f"⏰ [{profile.name}-轮换] 下次切换时间："
                    f"{next_switch_time.strftime('%Y-%m-%d %H:%M:%S')}",
                    "INFO",
                )

        self._current_mode = f"event_pet_{profile.slug}"
        self._event_pet_active_profile = profile
        self._event_pet_active_rotation = active_rotation
        self._event_pet_skip_pre_rotation = skip_pre_rotation
        self._apply_event_pet_pick_overrides(profile)
        self._event_pet_rotation_reconnect_requested = False
        self._battle_count = 0
        self._emit(
            f"[活动精灵] start {profile.name}: map A={profile.map_a_id}, "
            f"to={profile.to_script}, entry pet ID={profile.entry_pet_id}",
            "SYSTEM",
        )

        if active_rotation and self._check_rotation_switch_time():
            self._emit(
                f"[活动精灵] {profile.name}：开始前已到轮换时间",
                "SYSTEM",
            )
            self._event_pet_active_profile = None
            self._event_pet_active_rotation = False
            self._clear_event_pet_pick_overrides()
            return True

        if profile.delete_swf_ids:
            from core.dar_route_runner import WildCaptureProfile

            swf_prof = WildCaptureProfile(
                name=profile.name,
                route_hint=profile.route_hint,
                map_swf_id=profile.map_a_id,
                target_mp3_id=profile.entry_pet_id,
                target_pet_id=profile.entry_pet_id,
                delete_swf_ids=profile.delete_swf_ids,
            )
            self._check_and_delete_swf_files(swf_prof)

        run_ok = True
        try:
            if not skip_pre_rotation:
                while not stop_event.is_set() and not getattr(self.bot, "stop_current", False):
                    if self._execute_event_pet_pre_reconnect(
                        profile, use_foreground, stop_event
                    ):
                        break
                    self._emit(
                        "[活动精灵] 前置重连失败，重试完整流程",
                        "WARN",
                    )
                    self._sleep_abortable(stop_event, 2.0)

            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return False

            if not self._event_pet_post_start_bag_scan(
                use_foreground, stop_event, profile.name
            ):
                return False

            while not stop_event.is_set() and not getattr(self.bot, "stop_current", False):
                if self._is_rotation_mode and self._check_rotation_switch_time():
                    break
                if not self._event_pet_guard_map(profile, use_foreground, stop_event):
                    run_ok = False
                    break

                hunt_out = self._event_pet_hunt_dispatch(
                    profile, use_foreground, stop_event
                )
                if hunt_out == "reconnect":
                    run_ok = False
                    break
                if hunt_out != "entered":
                    run_ok = False
                    break

                battle_start_cursor = kernel_cursor()
                battle_out = self._event_pet_battle_dispatch(
                    profile, use_foreground, stop_event
                )
                self._battle_count += 1

                if battle_out == "capture":
                    self._sleep_abortable(stop_event, 2.0)
                    if not self._event_pet_recover_after_capture(
                        profile, use_foreground, stop_event
                    ):
                        run_ok = False
                        break
                elif battle_out == "defeat":
                    self._emit(
                        "[活动精灵] 战斗结束但未捕捉成功，执行重连",
                        "WARN",
                    )
                    self._event_pet_trigger_reconnect(
                        profile, use_foreground, stop_event, reason="战斗结束"
                    )
                    run_ok = False
                    break
                else:
                    self._emit(
                        f"[活动精灵] 战斗流程返回 {battle_out!r}，立即重连；"
                        "不再执行战后地图检查或重新扫点",
                        "WARN",
                    )
                    self._event_pet_trigger_reconnect(
                        profile,
                        use_foreground,
                        stop_event,
                        reason="战斗流程失败",
                    )
                    run_ok = False
                    break

                if not self._event_pet_verify_map_after_battle(
                    profile,
                    use_foreground,
                    stop_event,
                    battle_start_cursor=battle_start_cursor,
                ):
                    run_ok = False
                    break

                if self._pem_pure_energy_maybe_rotation_then_exit(stop_event, profile.name):
                    break

            self._emit(
                f"[活动精灵] {profile.name} stopped; battles={self._battle_count}",
                "SYSTEM",
            )
        finally:
            self._event_pet_active_profile = None
            self._event_pet_active_rotation = False
            self._clear_event_pet_pick_overrides()

        if active_rotation and getattr(self, "_event_pet_rotation_reconnect_requested", False):
            self._event_pet_rotation_reconnect_requested = False
            self._should_restart_after_reconnect = False
            self._event_pet_restart_profile = None
            self._emit(
                f"[活动精灵] {profile.name}：返回轮换层执行重连重试",
                "SYSTEM",
            )
            return False

        if getattr(self, "_should_restart_after_reconnect", False):
            prof = getattr(self, "_event_pet_restart_profile", None) or profile
            self._event_pet_restart_profile = None
            if active_rotation:
                self._emit(
                    f"[活动精灵] {profile.name}: rotation mode cancels internal restart",
                    "SYSTEM",
                )
                return False
            if prof is not None:
                self._request_mode_restart(
                    stop_event,
                    f"活动精灵-{prof.name}-重连",
                )
        return run_ok

    # ------------------------------------------------------------------ #
    #  浼婄壒模式锛堝唴缃椿鍔ㄧ簿鐏靛疄渚嬶級                                        #
    # ------------------------------------------------------------------ #

    def _eit_rgb_distance(self, rgb: Tuple[int, int, int], target: Tuple[int, int, int]) -> float:
        return float(np.sqrt(sum((a - b) ** 2 for a, b in zip(rgb, target))))

    def _eit_classify_hp_color(self, rgb: Optional[Tuple[int, int, int]]) -> Optional[str]:
        """Return orange, brown, or None."""
        if rgb is None:
            return None
        d_orange = self._eit_rgb_distance(rgb, EIT_HP_ORANGE_RGB)
        d_brown = self._eit_rgb_distance(rgb, EIT_HP_BROWN_RGB)
        if d_brown <= EIT_HP_COLOR_MAX_DIST and d_brown < d_orange:
            return "brown"
        if d_orange <= EIT_HP_COLOR_MAX_DIST:
            return "orange"
        return None

    def _eit_is_white_probe_ready(self) -> bool:
        try:
            reg = self.regions.get('伊特.白色')
            if reg:
                return self._check_white_probe_pure_white(reg)
        except KeyError:
            pass
        return False

    def _eit_open_bag(self, use_foreground: bool, stop_event: threading.Event) -> bool:
        self._emit("💼 [伊特] 打开精灵背包", "INFO")
        try:
            self._click_region("精灵背包.打开精灵背包按钮", use_foreground)
        except KeyError:
            self._click_region('精灵背包.打开精灵背包', use_foreground)
        return self._wait_pet_bag_ui_ready_after_open(stop_event, log_tag='伊特')

    def _eit_close_bag(
        self, use_foreground: bool, stop_event: Optional[threading.Event] = None
    ) -> None:
        self._close_pet_bag_with_verify(
            use_foreground,
            stop_event or threading.Event(),
            '精灵背包.打开精灵背包',
            "精灵背包.打开精灵背包按钮",
            log_tag='伊特',
        )

    def _eit_recover_pet_slot(
        self,
        pos_cn: str,
        use_foreground: bool,
        stop_event: threading.Event,
        tag: str = '伊特',
    ) -> None:
        from core.unified_battle_framework import BattleConfig, BattleMode

        self._emit(f"🔄 [{tag}] 恢复精灵{pos_cn}", "INFO")
        pet_key = f"精灵背包.精灵{pos_cn}"
        pet_btn_key = f"精灵背包.精灵{pos_cn}按钮"
        try:
            self._click_region_twice(pet_btn_key, use_foreground)
        except KeyError:
            self._click_region_twice(pet_key, use_foreground)
        self._sleep_abortable(stop_event, 0.5)
        self._emit(f"[{tag}] 点击精灵恢复（精灵{pos_cn}）", "INFO")
        try:
            self._click_region("精灵背包.精灵恢复按钮", use_foreground)
        except KeyError:
            self._click_region("精灵背包.精灵恢复", use_foreground)
        self._sleep_abortable(stop_event, 1.0)
        if self._unified_framework:
            temp_config = BattleConfig(
                mode=BattleMode.WILD,
                use_foreground=use_foreground,
                abort_check=lambda: stop_event.is_set() or getattr(self.bot, "stop_current", False),
            )
            self._unified_framework._wait_for_confirm_probes(temp_config, timeout_s=2.0)
        self._sleep_abortable(stop_event, 0.5)

    def _eit_mode_prepare_pets(
        self, use_foreground: bool, stop_event: threading.Event
    ) -> bool:
        """Prepare EIT pets and cache the detected switch slot."""
        if stop_event.is_set() or getattr(self.bot, "stop_current", False):
            return False
        if not self._eit_open_bag(use_foreground, stop_event):
            self._emit("[伊特] 精灵背包未就绪", "WARN")
            return False
        if not self._recover_and_identify_pickmode_bag_slots(
            use_foreground, stop_event, "伊特.准备"
        ):
            self._emit("[伊特] 恢复/识别背包槽位失败", "ERROR")
            self._eit_close_bag(use_foreground, stop_event)
            return False
        jita_pos = getattr(self, "_jita_pos", None)
        if jita_pos not in ("二", "三", "四", "五", "六"):
            self._emit("[伊特] 未在精灵2-6识别到机塔/亚梅丝槽", "ERROR")
            self._eit_close_bag(use_foreground, stop_event)
            return False
        self._eit_close_bag(use_foreground, stop_event)
        self._pickmode_base_recovery_done = True
        self._emit(f"[伊特] 准备完成：统一恢复识别，切换槽=精灵{jita_pos}", "SUCCESS")
        return True

    def _eit_click1_until_white(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
        timeout_s: float = EIT_CLICK1_WHITE_TIMEOUT_SEC,
    ) -> bool:
        """Click EIT.1 until the white probe is ready."""
        click_count = 0
        overall_deadline = time.time() + max(0.0, float(timeout_s))
        while (
            time.time() < overall_deadline
            and not stop_event.is_set()
            and not getattr(self.bot, "stop_current", False)
        ):
            click_count += 1
            try:
                self._click_region("伊特.1", use_foreground)
            except KeyError:
                self._emit("[伊特] 缺少区域：伊特.1", "ERROR")
                return False
            deadline = time.time() + EIT_CLICK1_WHITE_RETRY_SEC
            while time.time() < deadline:
                if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                    return False
                if self._eit_is_white_probe_ready():
                    self._emit(
                        f"[伊特] white probe ready after {click_count} clicks on 伊特.1",
                        "INFO",
                    )
                    return True
                time.sleep(0.05)
            self._emit(
                f"[伊特] 伊特.1 not white after {EIT_CLICK1_WHITE_RETRY_SEC:.0f}s; click again",
                "DEBUG",
            )
        if not stop_event.is_set() and not getattr(self.bot, "stop_current", False):
            self._emit(
                f"[伊特] 伊特.1 白色探针等待超过 {timeout_s:.0f}s",
                "WARN",
            )
        return False

    def _eit_wait_target_pet_swf(
        self, stop_event: threading.Event, timeout_s: float = EIT_BATTLE_ENTRY_WAIT_SEC
    ) -> bool:
        """Wait for the target fightResource pet swf and collect pet ids."""
        cursor = kernel_cursor()
        deadline = time.time() + timeout_s
        while time.time() < deadline:
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return False
            batch_start = cursor
            lines = fetch_kernel_since(cursor)
            cursor = kernel_cursor()
            for idx, line in enumerate(lines or []):
                line_str = str(line)
                if not line_matches(RE_FIGHT_PET, line_str):
                    continue
                for m in finditer_kernel_line(RE_FIGHT_PET_ID, line_str):
                    try:
                        pid = int(m.group(1))
                    except (TypeError, ValueError):
                        continue
                    if pid != EIT_TARGET_PET_ID:
                        continue
                    collected = self._collect_fight_pet_ids_immediate(
                        stop_event, current_lines=lines, start_index=idx,
                    )
                    if collected:
                        self._immediate_collected_pet_ids = collected
                    self._eit_battle_kernel_cursor = batch_start
                    self._emit(
                        f"[伊特] detected target pet/swf/{EIT_TARGET_PET_ID}; "
                        f"collected pet IDs: {sorted(collected) if collected else []}",
                        "SUCCESS",
                    )
                    return True
            time.sleep(0.05)
        return False

    def run_eit_mode(
        self,
        stop_event: threading.Event,
        use_foreground: bool,
        *,
        skip_pre_rotation: bool = False,
    ) -> None:
        """Run the built-in EIT event-pet mode."""
        import os
        from core.event_pet_mode_registry import get_profile, load_all_event_pet_modes

        root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
        profile = get_profile(root, "yite")
        if profile is None:
            for slug, pf in load_all_event_pet_modes(root).items():
                if pf.route_hint == "伊特" or pf.entry_pet_id == EIT_TARGET_PET_ID:
                    profile = pf
                    break
        if profile is None:
            self._emit("[伊特] 未找到活动精灵配置（assets/event_pet_modes）", "ERROR")
            return
        self.run_event_pet_mode(
            profile,
            stop_event,
            use_foreground,
            skip_pre_rotation=skip_pre_rotation,
        )

    def _enemy_pet_ids_for_battle_csv(self, profile: WildCaptureProfile) -> list:
        """Return enemy ids for the battle CSV row."""
        nie_id = getattr(self, "_current_battle_nie_family_id", None)
        if nie_id:
            return [nie_id]
        all_ids = set(getattr(self, "_immediate_collected_pet_ids", None) or [])
        target_set = self._rare_mode_target_pet_ids(profile)
        overlap = sorted(all_ids & target_set)
        if overlap:
            return overlap
        nie_overlap = sorted(all_ids & {77, 310, 416})
        if nie_overlap:
            return nie_overlap
        noise = {1100000}
        return sorted(x for x in all_ids if x not in noise)

    def _eit_run_battle(
        self, use_foreground: bool, stop_event: threading.Event
    ) -> str:
        """Run one EIT battle. Return capture, defeat, or failed."""
        from core.unified_battle_framework import BattleConfig, BattleMode, LastActionType

        if not self._unified_framework:
            self._emit("[伊特] 统一战斗框架未初始化", "ERROR")
            return "failed"

        state = {
            "on_jita": False,
            "jita_skill2_pending": False,
            "last_skill1_round": None,
            "next_round_use_skill1": False,
            "failed_capsule_only": False,
        }
        cycle_ov = self._capsule_cycle_tiers_for_current_battle()
        capsule_label_map = {"high": "高级", "super": "超级", "special": "特级"}
        capsule_label = "/".join(capsule_label_map.get(t, str(t)) for t in cycle_ov)

        def action_callback(round_idx: int) -> str:
            if round_idx <= 3:
                self._emit(f"[伊特] 第{round_idx}回合：使用二技能", "INFO")
                return "skill2"

            if state["failed_capsule_only"]:
                self._emit(f"[伊特] 第{round_idx}回合：切换失败，回退到胶囊", "WARN")
                return "capsule"

            if not state["on_jita"]:
                rgb = self._mean_rgb_for_region_key("伊特.血量")
                kind = self._eit_classify_hp_color(rgb)
                if rgb:
                    self._emit(f"[伊特] 第{round_idx}回合：血量RGB={rgb}，类型={kind or '未知'}", "INFO")
                if kind == "brown":
                    self._emit(f"[伊特] 第{round_idx}回合：棕色血量，切换机塔", "INFO")
                    if not self._switch_pet_for_rare_mode("jita", use_foreground, stop_event):
                        state["failed_capsule_only"] = True
                        self._emit("[伊特] 切换机塔失败，回退到胶囊", "WARN")
                        return "capsule"
                    state["on_jita"] = True
                    state["jita_skill2_pending"] = True
                    return "switch"
                return "skill"

            if state["jita_skill2_pending"]:
                state["jita_skill2_pending"] = False
                state["last_skill1_round"] = None
                state["next_round_use_skill1"] = False
                self._emit(f"[伊特] 第{round_idx}回合：机塔首回合使用二技能", "INFO")
                return "skill2"

            if state["next_round_use_skill1"]:
                state["last_skill1_round"] = round_idx
                state["next_round_use_skill1"] = False
                self._emit(f"[伊特] 第{round_idx}回合：上一回合害怕红色，使用一技能", "INFO")
                return "skill"

            if state["last_skill1_round"] is not None:
                rounds_since = round_idx - int(state["last_skill1_round"])
                if rounds_since == 1:
                    self._emit(f"[伊特] 第{round_idx}回合：一技能后使用 {capsule_label} 胶囊", "INFO")
                    return "capsule"
                if rounds_since == 2:
                    if self._unified_framework:
                        probe_model = self._unified_framework._load_probe_templates()
                        if probe_model:
                            probe_state, _, _ = self._unified_framework._detect_round_probe(probe_model)
                            if probe_state == "BLUE" and self._check_fear_probe_pure_red(use_foreground):
                                state["next_round_use_skill1"] = True
                                self._emit(f"[伊特] 第{round_idx}回合：害怕红色，当前胶囊，下回合一技能", "INFO")
                                return "capsule"
                    state["last_skill1_round"] = round_idx
                    self._emit(f"[伊特] 第{round_idx}回合：害怕非红，使用一技能", "INFO")
                    return "skill"

            state["last_skill1_round"] = round_idx
            self._emit(f"[伊特] 第{round_idx}回合：使用一技能", "INFO")
            return "skill"

        config = BattleConfig(
            mode=BattleMode.WILD,
            use_foreground=use_foreground,
            skill_key="对战.使用技能一",
            action_callback=action_callback,
            abort_check=lambda: stop_event.is_set() or getattr(self.bot, "stop_current", False),
            round_timeout_sec=90.0,
            capsule_cycle_tiers_override=cycle_ov,
            clear_kernel_on_stage3_start=True,
            min_rounds_before_kernel_end=4,
            skip_map10_white_end=True,
        )

        stage2_cursor = getattr(self, "_eit_battle_kernel_cursor", None) or kernel_cursor()
        self._emit("[伊特] 阶段2：等待 PetItem 后执行战斗", "INFO")
        success, _calib = self._unified_framework.stage2_calibration_and_petitem(
            trigger_callback=None,
            use_foreground=use_foreground,
            timeout_s=20.0,
            skip_stage1=True,
            config=config,
            initial_cursor=stage2_cursor,
        )
        if not success:
            self._emit("[伊特] 阶段2失败", "WARN")
            return "failed"

        if not self._unified_framework.stage3_battle_loop(config):
            self._emit("[伊特] 战斗循环失败", "WARN")
            return "failed"

        if not self._unified_framework.stage4_post_battle(config, is_training_room=False):
            self._emit("[伊特] 阶段4战后处理失败", "WARN")
            return "failed"

        if self._unified_framework._last_action == LastActionType.CAPSULE:
            self._emit("[伊特] 捕捉成功", "SUCCESS")
            return "capture"
        self._emit("[伊特] 战斗结束但未确认捕捉", "WARN")
        return "defeat"

    def _should_log_csv_battle_start(self, profile: WildCaptureProfile) -> bool:
        """Return whether this battle should be logged as start."""
        if getattr(self, "_current_battle_nie_family_id", None) is not None:
            return True
        all_ids = set(getattr(self, "_immediate_collected_pet_ids", None) or [])
        target_set = self._rare_mode_target_pet_ids(profile)
        return bool(all_ids & target_set)

    def _csv_log_battle(self, result: str, enemy_pet_ids=None):
        """Log one battle row to CSV (called from nieo / wild paths)."""
        try:
            ubf = self._unified_framework
            self._battle_logger.log_battle(
                enemy_pet_ids=sorted(enemy_pet_ids) if enemy_pet_ids else [],
                total_rounds=ubf._round_idx if ubf else 0,
                result=result,
                battle_duration_s=ubf._battle_duration if ubf else 0.0,
                capsule_counts=ubf._battle_capsule_counts if ubf else {},
            )
            # 鉁?双塔锛氳褰曗€滀笂娆℃垬鏂楃粨鏉熲€濈殑鏃堕棿鎴筹紝鐢ㄤ簬判断 30min 无遇敌时重连前清缓存/tmp
            if getattr(self, "_current_mode", None) == "shuangta":
                self._shuangta_last_battle_end_ts = time.time()
        except Exception:
            pass

    def run_rotation_chain_test(
        self,
        stop_event: threading.Event,
        use_foreground: bool,
        *,
        resource_slug: str = "pure_energy",
        rare_slot: str = "shuangta",
        follow_cyan: bool = False,
    ) -> None:
        """
        轮换链测试：验证白天模式、闪光皮皮、螳螂、尼奥、稀有等入口。
        按当前配置执行 step1、Pick/战斗准备(step2-4)、to重连+地图门控(step5 entry_check_only)。
        用于确认地图进入与模式切换是否成功；失败会按当前保护逻辑退出。
        """
        from datetime import timezone as _tz
        _FAR = datetime(2099, 1, 1, tzinfo=_tz.utc)

        segments = [
            f"resource:{resource_slug}",
            "eit",
            "mantis",
            "nieo",
            "rare",
        ]
        self._rotation_rare_slot = rare_slot
        self._rotation_nieo_follow_cyan = bool(follow_cyan)
        self._is_rotation_mode = True
        self._rotation_full_chain_switch_key = None
        self.reset_swf_sync_state()
        total = len(segments)

        for seg_idx, segment in enumerate(segments, 1):
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                break
            self._emit(
                f"[链路测试] segment {seg_idx}/{total}: {segment}",
                "SYSTEM",
            )
            self._sync_swf_for_rotation_segment(
                segment,
                log_tag=f"链路测试/{segment}",
                runtime_subset=seg_idx > 1,
            )
            attempt = 0
            while not stop_event.is_set() and not getattr(self.bot, "stop_current", False):
                attempt += 1
                self._emit(
                    f"[链路测试/{segment}] attempt {attempt}: login -> Pick -> entry check",
                    "INFO",
                )
                # step1 login
                if not self._rotation_step1_login(use_foreground, stop_event):
                    self._emit(f"[链路测试/{segment}] 登录失败，返回本段主循环重试", "WARN")
                    self._sleep_abortable(stop_event, 2.0)
                    continue
                if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                    break
                # step2-4 pick + companion
                self._prepare_rotation_segment_pick_overrides(segment)
                party_ids = self._rotation_expected_party_ids_for_segment(segment)
                if not self._rotation_clear_backpack_and_pick_or_skip(
                    self._rotation_pick_mode_for(segment),
                    use_foreground,
                    stop_event,
                    log_tag=f"链路测试/{segment}",
                    expected_party_ids=party_ids,
                ):
                    self._emit(f"[链路测试/{segment}] 清背包失败，重试", "WARN")
                    continue
                if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                    break
                if not self._rotation_step4_set_companion(
                    use_foreground,
                    stop_event,
                    follow_cyan=self._rotation_initial_follow_cyan_for_mode(segment),
                ):
                    self._emit(f"[链路测试/{segment}] 设置跟随失败，重试", "WARN")
                    continue
                if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                    break
                segment_stop = _RotationSegmentStopSignal(stop_event)
                ok = self._rotation_step5_execute_to_script_and_start_mode(
                    segment,
                    use_foreground,
                    segment_stop,
                    _FAR,
                    entry_check_only=True,
                )
                if ok:
                    self._emit(
                        f"[链路测试] 分段 {seg_idx}/{total} {segment} 通过",
                        "SUCCESS",
                    )
                    break
                else:
                    self._emit(f"[链路测试/{segment}] 入口检查失败，重试", "WARN")
                    self._sleep_abortable(stop_event, 3.0)

        if not stop_event.is_set() and not getattr(self.bot, "stop_current", False):
            self._emit(
                f"[链路测试] 全部 {total} 个分段执行完成",
                "SUCCESS",
            )

    def run_rotation_mode(
        self,
        stop_event: threading.Event,
        use_foreground: bool,
        is_test_mode: bool = False,
        rotation_rare_slot: str = "shuangta",
        *,
        rotation_resource_enabled: bool = False,
        rotation_resource_slug: str = "pure_energy",
        rotation_mantis_enabled: bool = False,
        rotation_eit_enabled: bool = False,
        rotation_nieo_single_map_escape: bool = False,
        rotation_nieo_follow_cyan: bool = False,
        rotation_full_daily_maintenance: bool = False,
        initial_swf_full: bool = True,
    ) -> None:
        """Run rotation mode using the configured schedule."""
        from core.rotation_schedule import RotationScheduleOptions

        self._active_use_foreground = bool(use_foreground)
        slot = (rotation_rare_slot or "shuangta").strip().lower()
        self._rotation_rare_slot = slot
        self._rotation_nieo_single_map_escape = bool(rotation_nieo_single_map_escape)
        self._rotation_nieo_follow_cyan = bool(rotation_nieo_follow_cyan)
        self._emit(
            "[轮换模式] 尼奥族跟随颜色="
            + ("青色" if self._rotation_nieo_follow_cyan else "紫色"),
            "INFO",
        )
        self._rotation_full_daily_maintenance = bool(rotation_full_daily_maintenance)
        self._pending_rotation_full_chain_maintenance = None
        self._rotation_yilu_lanlan_maintenance_key = None
        self._pending_rotation_yilu_lanlan_maintenance = None
        self._rotation_schedule_options = RotationScheduleOptions(
            resource_enabled=bool(rotation_resource_enabled),
            resource_slug=(rotation_resource_slug or "pure_energy").strip(),
            mantis_enabled=bool(rotation_mantis_enabled),
            eit_enabled=bool(rotation_eit_enabled),
        )
        prof = self._resolve_rotation_rare_profile(slot)
        self._emit(f"[轮换模式] 非尼奥稀有：{prof.name} (slug={slot})", "INFO")
        self._is_rotation_mode = True
        self.reset_swf_sync_state()
        self.ROTATION_TEST_MODE = bool(is_test_mode)
        self._rotation_total_stats = {
            "nieo": {"普通逃跑": 0, "稀有捕捉": 0, "尼尔家族": 0, "108捕捉": 0, "77捕捉": 0, "310捕捉": 0, "416捕捉": 0, "运行次数": 0},
            "shuangta": {"total": 0, "entry_success": 0, "escape": 0, "capture": 0, "defeat": 0, "abort": 0, "运行次数": 0},
            "切换次数": 0,
        }

        first_segment_sync = True
        try:
            while not stop_event.is_set() and not getattr(self.bot, "stop_current", False):
                if self._run_rotation_pre_entry_maintenance():
                    continue
                current_mode, next_switch_datetime = self._detect_rotation_mode()
                if not self._sync_swf_for_rotation_segment(
                    current_mode,
                    log_tag=f"轮换/{current_mode}",
                    runtime_subset=not (initial_swf_full and first_segment_sync),
                ):
                    self._emit("[轮换模式] 当前时段 SWF 同步失败，等待后重试", "WARN")
                    self._sleep_abortable(stop_event, 3.0)
                    continue
                first_segment_sync = False
                self._next_rotation_switch_time = next_switch_datetime
                self._emit(
                    f"[轮换模式] 当前={current_mode}，下次切换={next_switch_datetime.strftime('%Y-%m-%d %H:%M:%S')}",
                    "SYSTEM",
                )

                if not self._rotation_step1_login(
                    use_foreground,
                    stop_event,
                    force_molecule_converter=self._rotation_step1_force_molecule_converter(),
                ):
                    self._emit("[轮换模式] 登录失败，返回轮换主循环重新判断", "WARN")
                    self._sleep_abortable(stop_event, 2.0)
                    continue
                if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                    break

                self._prepare_rotation_segment_pick_overrides(current_mode)
                expected_party_ids = self._rotation_expected_party_ids_for_segment(current_mode)
                if not self._rotation_clear_backpack_and_pick_or_skip(
                    self._rotation_pick_mode_for(current_mode),
                    use_foreground,
                    stop_event,
                    log_tag="轮换模式",
                    expected_party_ids=expected_party_ids,
                ):
                    self._emit("[轮换模式] 清包/取宠失败，准备重试", "WARN")
                    self._sleep_abortable(stop_event, 3.0)
                    continue

                if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                    break
                if not self._rotation_step4_set_companion(
                    use_foreground,
                    stop_event,
                    follow_cyan=self._rotation_initial_follow_cyan_for_mode(
                        current_mode
                    ),
                ):
                    self._emit("[轮换模式] 设置跟随失败，准备重试", "WARN")
                    continue

                segment_stop = _RotationSegmentStopSignal(stop_event)
                step5_ok = self._rotation_step5_execute_to_script_and_start_mode(
                    current_mode,
                    use_foreground,
                    segment_stop,
                    next_switch_datetime,
                )
                if self._consume_rotation_child_restart(
                    stop_event, source="子模式"
                ):
                    continue
                if isinstance(
                    getattr(
                        self,
                        "_pending_rotation_yilu_lanlan_maintenance",
                        None,
                    ),
                    dict,
                ):
                    self._emit(
                        "[轮换模式] 子模式已返回，整点依卢/岚岚待办交给轮换外层",
                        "SYSTEM",
                    )
                    continue
                if isinstance(
                    getattr(
                        self,
                        "_pending_rotation_full_chain_maintenance",
                        None,
                    ),
                    dict,
                ):
                    self._emit(
                        "[轮换模式] 子模式已返回，整点完整日常链待办交给轮换外层",
                        "SYSTEM",
                    )
                    continue
                if not step5_ok and not self._pending_rotation_switch:
                    if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                        break
                    self._emit("[轮换模式] 步骤5失败，准备重试", "WARN")
                    self._sleep_abortable(stop_event, 3.0)
                    continue

                if self._pending_rotation_switch:
                    next_mode = self._target_mode_after_switch
                    self._pending_rotation_switch = False
                    self._target_mode_after_switch = None
                    if self._rotation_total_stats:
                        self._rotation_total_stats["切换次数"] += 1
                    if next_mode:
                        self._execute_rotation_reconnect(
                            use_foreground,
                            stop_event,
                            next_mode,
                            reason="轮换模式-到点切换",
                            run_scheduled_full_chain_scan=False,
                        )
                    if self._consume_rotation_child_restart(
                        stop_event, source="到点切换子模式"
                    ):
                        continue
                    if self._is_user_stop_requested(stop_event):
                        break
                    if self.bot is not None and getattr(self.bot, "stop_current", False):
                        self.bot.stop_current = False
                    if stop_event.is_set():
                        self._emit(
                            "[轮换模式] 任务级停止事件仍为置位状态，禁止吞掉停止并继续切换",
                            "ERROR",
                        )
                        break
                    continue

                if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                    break
        except Exception as e:
            self._emit(f"[轮换模式] 异常：{e}", "ERROR")
            import traceback
            self._emit(traceback.format_exc(), "ERROR")
        finally:
            self._rotation_total_stats = None
            self._is_rotation_mode = False
            self._next_rotation_switch_time = None
            self._pending_rotation_switch = False
            self._target_mode_after_switch = None
            self._test_mode_current_mode = None
            self._test_mode_start_time = 0.0
            self._rotation_time_check_window_active = False
            self._last_rotation_time_check = 0.0
            self._rotation_rare_slot = "shuangta"
            self._rotation_nieo_single_map_escape = False
            self._rotation_nieo_follow_cyan = False
            self._pending_rotation_full_chain_maintenance = None
            self._rotation_yilu_lanlan_maintenance_key = None
            self._pending_rotation_yilu_lanlan_maintenance = None
            self._rotation_schedule_options = None
            self._rotation_active_segment_mode = None

    def _run_rotation_pre_entry_maintenance(self) -> bool:
        """Run light scheduled maintenance before reconnecting the target segment."""
        if self._maybe_run_rotation_hourly_full_chain_scan():
            self._pending_rotation_switch = False
            self._target_mode_after_switch = None
            pending_full = getattr(
                self, "_pending_rotation_full_chain_maintenance", None
            )
            if isinstance(pending_full, dict):
                self._emit(
                    "[轮换模式] 整点完整日常链尚未完成，"
                    "保持在轮换外层等待重试",
                    "WARN",
                )
                self._sleep_abortable(
                    getattr(self.bot, "_stop_event", threading.Event()),
                    1.0,
                )
            return True
        if not self._maybe_run_hourly_yilu_lanlan_maintenance():
            return False
        self._pending_rotation_switch = False
        self._target_mode_after_switch = None
        pending = getattr(
            self, "_pending_rotation_yilu_lanlan_maintenance", None
        )
        if isinstance(pending, dict):
            self._emit(
                "[轮换模式] 整点补跑尚未完成，保持在轮换外层并重试",
                "WARN",
            )
            self._sleep_abortable(
                getattr(self.bot, "_stop_event", threading.Event()),
                1.0,
            )
            return True
        self._emit(
            "[轮换模式] 目标模式重连前已完成整点补跑；重新判断当前模式",
            "SYSTEM",
        )
        return True

    def _consume_rotation_child_restart(
        self,
        stop_event: threading.Event,
        *,
        source: str,
    ) -> bool:
        """Consume one child restart immediately at the rotation boundary."""
        restart_reason = self.consume_mode_restart_request(stop_event)
        if restart_reason is None:
            return False
        self._emit(
            f"[轮换模式] {source}请求重启：{restart_reason}；返回轮换主线重新判断",
            "SYSTEM",
        )
        return True

    def _detect_rotation_mode(self, quiet: bool = False) -> Tuple[str, datetime]:
        """Detect current rotation mode and next switch time."""
        now = self._get_beijing_time()
        if self.ROTATION_TEST_MODE:
            if self._test_mode_current_mode is None:
                self._test_mode_current_mode = "nieo"
            current_mode = self._test_mode_current_mode
            interval_minutes = (
                self.ROTATION_RECONNECT_INTERVAL_MINUTES_NIEO
                if current_mode == "nieo"
                else self.ROTATION_RECONNECT_INTERVAL_MINUTES_SHUANGTA
            )
            next_switch = now + timedelta(minutes=interval_minutes)
            if not quiet:
                next_mode = "nieo" if current_mode == "shuangta" else "shuangta"
                self._emit(
                    f"[轮换模式-测试] 当前={current_mode}，下次切换={next_switch.strftime('%Y-%m-%d %H:%M:%S')}，下个模式={next_mode}",
                    "INFO",
                )
            return current_mode, next_switch

        from core.rotation_schedule import RotationScheduleOptions, detect_rotation_mode_at, rotation_mode_label

        opts = self._rotation_schedule_options or RotationScheduleOptions()
        current_mode, next_switch = detect_rotation_mode_at(now, opts, quiet=quiet)
        if not quiet:
            rs = getattr(self, "_rotation_rare_slot", "shuangta") or "shuangta"
            self._emit(f"[轮换模式] 北京时间 {now.strftime('%Y-%m-%d %H:%M:%S')}", "INFO")
            self._emit(
                f"[轮换模式] 当前={rotation_mode_label(current_mode, rare_slot=rs)}，下次切换={next_switch.strftime('%Y-%m-%d %H:%M:%S')}",
                "INFO",
            )
        return current_mode, next_switch

    def _reset_petswf_time_variables(self, log_prefix: str = "轮换模式") -> None:
        """Reset petswf-to-PetItem timing variables."""
        self._petswf_to_petitem_min_duration = None
        self._petswf_to_petitem_current_duration = None
        self._petswf_to_petitem_consecutive_over_threshold = 0
        # 鉁?娓呯┖鏃堕棿缁熻鏁版嵁锛堢‘淇濆垏鎹㈠悗閲嶆柊寮€濮嬬粺璁★級
        if self._unified_framework and hasattr(self._unified_framework, '_petswf_to_petitem_durations'):
            self._unified_framework._petswf_to_petitem_durations.clear()
            self._emit(f"[{log_prefix}] timing samples cleared", "INFO")
        self._emit(f"[{log_prefix}] petswf timing variables reset", "INFO")

    def _handle_map_entry_timeout(
        self,
        profile: Optional[WildCaptureProfile],
        use_foreground: bool,
        stop_event: threading.Event,
        is_rotation_mode: bool,
        reason: str = "进入地图失败",
    ) -> bool:
        """Handle map entry timeout and return whether restart was prepared."""
        mode_name = profile.name if profile else "未知模式"
        self._emit(f"[{mode_name}-{reason}] 请求重启当前模式", "WARN")
        if profile:
            profile_name_lower = profile.name.lower()
            if "双塔" in profile_name_lower:
                self._current_mode = "shuangta"
            elif "尼奥" in profile.name:
                self._current_mode = "nieo"
            elif "嘟咕噜" in profile_name_lower:
                self._current_mode = "dugulu"
        else:
            self._current_mode = "nieo"
        return self._request_mode_restart(stop_event, f"{mode_name}-{reason}")

    def _handoff_after_active_rotation_reconnect(
        self,
        reason: str,
        stop_event: threading.Event,
    ) -> bool:
        """Return immediately to the outer controller when rotation reconnect is busy."""
        if self._is_user_stop_requested(stop_event):
            return False
        self._emit(f"[{reason}] 轮换重连已在执行；当前调用立即退出", "WARN")
        return self._request_mode_restart(stop_event, f"{reason}-轮换重连占用")

    def _mark_rotation_reconnect_active(self, reason: str) -> None:
        _ = reason
        self._rotation_reconnect_executing = True

    def _clear_rotation_reconnect_active(self, reason: str) -> None:
        _ = reason
        self._rotation_reconnect_executing = False

    def _execute_rotation_reconnect(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
        current_mode: str,
        reason: str = "轮换重连",
        *,
        run_scheduled_full_chain_scan: bool = False,
    ) -> None:
        """Run the rotation reconnect pipeline for the target segment."""
        if self._rotation_reconnect_executing:
            self._handoff_after_active_rotation_reconnect(reason, stop_event)
            return bool(getattr(self, "_should_restart_after_reconnect", False))
        self._mark_rotation_reconnect_active(reason)
        self._stop_normal_1and1_monitoring()
        self._reset_petswf_time_variables(f"{reason}-切换前")
        # 依卢/岚岚会临时改写 Pet254；回到轮换时即使日程桶未变，也必须重做目标模式 SWF。
        if not self._sync_swf_for_rotation_segment(
            current_mode,
            log_tag=f"{reason}/SWF",
            force=True,
        ):
            self._emit(f"❌ [{reason}] 当前时段 SWF 同步失败，取消本次轮换重连", "ERROR")
            self._clear_rotation_reconnect_active(reason)
            return
        try:
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                stop_event.set()
                return
            if run_scheduled_full_chain_scan:
                runner = getattr(self.bot, "run_rotation_startup_daily_precheck", None)
                if not callable(runner):
                    self._emit(f"❌ [{reason}] 缺少轮换完整日常检测入口", "ERROR")
                    return
                self._emit(
                    f"🧩 [{reason}] 目标模式={current_mode}；先执行完整日常检测链，再一次性重连、取宠并进入目标模式",
                    "SYSTEM",
                )
                if not bool(
                    runner(
                        use_foreground=use_foreground,
                        runtime_switch=True,
                    )
                ):
                    self._emit(f"⚠️ [{reason}] 完整日常检测链未完成，停止本次重接入", "WARN")
                    return
                if not self._sync_swf_for_rotation_segment(
                    current_mode,
                    log_tag=f"{reason}/日常后恢复SWF",
                    force=True,
                    runtime_subset=True,
                ):
                    self._emit(f"❌ [{reason}] 完整日常后恢复目标模式SWF失败", "ERROR")
                    return
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                stop_event.set()
                return
            if not self._rotation_step1_login(
                use_foreground,
                stop_event,
                force_molecule_converter=self._rotation_step1_force_molecule_converter(),
            ):
                self._emit(f"[{reason}] 登录失败，退出本次轮换重接入", "WARN")
                return
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                stop_event.set()
                return
            self._prepare_rotation_segment_pick_overrides(current_mode)
            if not self._rotation_clear_backpack_and_pick_or_skip(
                self._rotation_pick_mode_for(current_mode),
                use_foreground,
                stop_event,
                log_tag=reason,
                expected_party_ids=self._rotation_expected_party_ids_for_segment(current_mode),
            ):
                self._emit(f"[{reason}] 清背包或取宠失败", "WARN")
                return
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                stop_event.set()
                return
            if not self._rotation_step4_set_companion(
                use_foreground,
                stop_event,
                follow_cyan=self._rotation_initial_follow_cyan_for_mode(current_mode),
            ):
                self._emit(f"[{reason}] 设置跟随失败", "WARN")
                return
            _detected_mode, next_switch_datetime = self._detect_rotation_mode()
            self._next_rotation_switch_time = next_switch_datetime
            segment_stop = _RotationSegmentStopSignal(stop_event)
            if not self._rotation_step5_execute_to_script_and_start_mode(
                current_mode,
                use_foreground,
                segment_stop,
                next_switch_datetime,
            ):
                self._emit(f"[{reason}] 步骤5失败", "WARN")
                return
            if self._is_user_stop_requested(stop_event) or stop_event.is_set():
                self._emit(f"[{reason}] 任务已停止，不标记轮换重连完成", "SYSTEM")
                return
            if getattr(self, "_should_restart_after_reconnect", False):
                self._emit(
                    f"[{reason}] 子模式已请求重启；本次不标记为完成，返回轮换主线",
                    "SYSTEM",
                )
                return
            self._emit(f"[{reason}] 轮换重连完成", "SUCCESS")
        except Exception as e:
            self._emit(f"[{reason}] 轮换重连异常：{e}", "ERROR")
            import traceback
            self._emit(traceback.format_exc(), "ERROR")
        finally:
            self._clear_rotation_reconnect_active(reason)

    def _execute_flash_pipi_pre_rotation_reconnect(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
    ) -> bool:
        """Run flash-pipi pre-rotation reconnect and verify map11 + newNpc."""
        reason = "闪皮前置重连"
        if self._rotation_reconnect_executing:
            self._handoff_after_active_rotation_reconnect(reason, stop_event)
            return False
        self._mark_rotation_reconnect_active(reason)
        try:
            self._stop_normal_1and1_monitoring()
            self._reset_petswf_time_variables(f"{reason}-切换前")
            if not self._rotation_step1_login(
                use_foreground,
                stop_event,
                force_molecule_converter=self._rotation_step1_force_molecule_converter(),
            ):
                return False
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return False
            if not self._rotation_clear_backpack_and_pick_or_skip(
                "shuangta",
                use_foreground,
                stop_event,
                log_tag=reason,
                expected_party_ids=self._pickmode_expected_party_ids(),
            ):
                return False
            if not self._rotation_step4_set_companion(use_foreground, stop_event):
                return False
            if hasattr(self.bot, "daily_runner"):
                if not self.bot.daily_runner.run_single_script("to闪光皮皮", bg_mode=(not use_foreground)):
                    self._emit(f"[{reason}] to闪光皮皮 脚本执行失败", "WARN")
                    return False
            else:
                self._emit(f"[{reason}] 缺少 daily_runner，无法执行 to闪光皮皮", "ERROR")
                return False
            self._sleep_abortable(stop_event, 2.0)
            last_map_id, has_newNPC = self._check_last_map_and_newnpc(11, timeout_s=10.0)
            return bool(last_map_id == 11 and has_newNPC)
        except Exception as e:
            self._emit(f"[{reason}] 异常：{e}", "ERROR")
            return False
        finally:
            self._clear_rotation_reconnect_active(reason)

    def _execute_nieo_pre_rotation_reconnect(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
        *,
        pem_route: bool = False,
        to_script: Optional[str] = None,
        expected_map_id: Optional[int] = None,
        expected_party_ids: Optional[frozenset] = None,
        reason: str = "尼奥前置重连",
        follow_cyan: bool = False,
    ) -> bool:
        """Run Nieo/custom pre-rotation reconnect and verify target map + newNpc."""
        if self._rotation_reconnect_executing:
            self._handoff_after_active_rotation_reconnect(reason, stop_event)
            return False

        self._mark_rotation_reconnect_active(reason)
        try:
            self._stop_normal_1and1_monitoring()
            self._reset_petswf_time_variables(f"{reason}-切换前")
            if not self._rotation_step1_login(
                use_foreground,
                stop_event,
                force_molecule_converter=self._rotation_step1_force_molecule_converter(),
            ):
                return False
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return False

            party_ids = expected_party_ids or self._pickmode_expected_party_ids()
            if not self._rotation_clear_backpack_and_pick_or_skip(
                "nieo",
                use_foreground,
                stop_event,
                log_tag=reason,
                expected_party_ids=party_ids,
            ):
                self._emit(f"[{reason}] 清包取宠失败", "WARN")
                return False

            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return False
            initial_follow_cyan = bool(
                follow_cyan
                and not self._pre_nieo_should_defer_cyan_until_a(
                    pem_route=pem_route,
                    to_script=to_script,
                )
            )
            if follow_cyan and not initial_follow_cyan:
                self._emit(
                    f"[{reason}] 青色跟随延后到首次A图；前置步骤4保持紫色",
                    "INFO",
                )
            if not self._rotation_step4_set_companion(
                use_foreground,
                stop_event,
                follow_cyan=initial_follow_cyan,
            ):
                self._emit(f"[{reason}] 设置跟随失败", "WARN")
                return False

            script_name = (to_script or ("to纯净能量" if pem_route else "to尼奥")).strip()
            if script_name.endswith(".json"):
                script_name = script_name[:-5]
            target_map_id = int(
                expected_map_id if expected_map_id is not None else (26 if pem_route else 11)
            )

            daily_runner = getattr(self.bot, "daily_runner", None)
            if daily_runner is None:
                self._emit(f"[{reason}] 缺少 daily_runner，无法执行 {script_name}", "ERROR")
                return False
            to_start_cursor = kernel_cursor()
            if not daily_runner.run_single_script(script_name, bg_mode=(not use_foreground)):
                self._emit(f"[{reason}] {script_name} 脚本执行失败", "WARN")
                return False

            special_gate = self._special_essence_gate_after_to(
                script_name, to_start_cursor, stop_event, log_tag=reason
            )
            if special_gate is not None:
                return special_gate

            self._sleep_abortable(stop_event, 2.0)
            last_map_id, has_newNPC = self._check_last_map_and_newnpc(
                target_map_id, timeout_s=10.0
            )
            ok = bool(last_map_id == target_map_id and has_newNPC)
            if ok:
                self._emit(f"[{reason}] 前置重连完成：map{target_map_id} + newNpc", "SUCCESS")
            else:
                self._emit(
                    f"[{reason}] 地图门控失败：map={last_map_id}, newNpc={has_newNPC}, expected={target_map_id}",
                    "WARN",
                )
            return ok
        except Exception as e:
            self._emit(f"[{reason}] 异常：{e}", "ERROR")
            return False
        finally:
            self._clear_rotation_reconnect_active(reason)

