    def _rotation_step1_login(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
        *,
        force_molecule_converter: bool = False,
        skip_molecule_converter: bool = False,
        retry_count: int = 0,
    ) -> bool:
        """Rotation step1: refresh/login and run the common login pipeline."""
        lp = "轮换模式-步骤1"
        if self._consume_nono_fusion_connection_ready():
            self._mark_refresh_pipeline_map500001_gate_done()
            self._emit(
                f"[{lp}] Nono 融合开始已成功，复用当前基地连接；跳过重复刷新，直接清包取宠和 to 脚本",
                "SUCCESS",
            )
            return True
        self._emit(f"[{lp}] 启动登录流程", "SYSTEM")
        try:
            self._try_delete_game_tmp_dir(log_tag=lp)
        except Exception:
            pass

        try:
            import win32gui
            if window_manager.find_window() and window_manager.hwnd:
                win32gui.SetForegroundWindow(window_manager.hwnd)
        except Exception:
            pass

        step1_res = self._step1_trinity_clicks_and_wait_login_swf(
            use_foreground, lp, stop_event=stop_event
        )
        if step1_res == "stopped":
            return False
        if step1_res == "trinity_fail":
            self._emit(f"[{lp}] 刷新UI点击失败，返回轮换主线", "WARN")
            return False
        if step1_res == "no_login":
            self._emit(f"[{lp}] 未检测到 Login.swf，返回轮换主线", "WARN")
            return False

        if stop_event.is_set() or getattr(self.bot, "stop_current", False):
            return False

        ok = self._run_full_refresh_login_pipeline(
            use_foreground,
            stop_event,
            log_prefix=lp,
            force_molecule_converter=force_molecule_converter,
            skip_molecule_converter=skip_molecule_converter,
        )
        if ok:
            self._mark_refresh_pipeline_map500001_gate_done()
            if not self._run_nono_fusion_after_mode_reconnect(
                use_foreground,
                reconnect_reason=lp,
            ):
                self._emit(f"[{lp}] 融合重连检查失败", "WARN")
                return False
            self._emit(f"[{lp}] 登录流程完成", "SUCCESS")
            return True
        self._emit(f"[{lp}] 登录流程失败", "WARN")
        return False
    def _rotation_step2_clear_backpack(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
        *,
        log_tag: str = "轮换模式-步骤2",
        close_after: bool = True,
    ) -> bool:
        """清空精灵背包。"""
        self._emit(f"[{log_tag}] 开始清空背包", "SYSTEM")
        if stop_event.is_set() or getattr(self.bot, "stop_current", False):
            stop_event.set()
            return False
        self._aisifeige_pos = None
        self._jita_pos = None
        self._yameisi_pos = None
        self._emit(f"[{log_tag}] 清包前已作废 Pick 颜色槽位缓存", "DEBUG")
        bag_open_key = "精灵背包.打开精灵背包"
        bag_open_btn_key = "精灵背包.打开精灵背包按钮"
        put_back_key = "精灵背包.放回仓库"
        put_back_btn_key = "精灵背包.放回仓库按钮"
        self._last_pet_bag_count_scan = None
        try:
            self._click_region(bag_open_btn_key, use_foreground)
        except KeyError:
            self._click_region(bag_open_key, use_foreground)

        if not self._wait_pet_bag_ui_ready_after_open(
            stop_event,
            log_tag=log_tag,
            allow_empty_bag=True,
        ):
            self._emit(f"[{log_tag}] 背包UI未就绪，停止清包", "ERROR")
            return False
        count_scan = getattr(self, "_last_pet_bag_count_scan", None)
        if not isinstance(count_scan, dict) or not count_scan.get("ok"):
            reason = (
                count_scan.get("reason")
                if isinstance(count_scan, dict)
                else "未取得背包数量扫描结果"
            )
            self._emit(f"[{log_tag}] 背包数量未确认：{reason}", "ERROR")
            return False
        try:
            pet_count = int(count_scan.get("count"))
        except (TypeError, ValueError):
            self._emit(
                f"[{log_tag}] 背包数量无效：{count_scan.get('count')}",
                "ERROR",
            )
            return False
        if not 0 <= pet_count <= 6:
            self._emit(f"[{log_tag}] 背包数量超出范围：{pet_count}", "ERROR")
            return False

        count_to_cn = {
            1: "一",
            2: "二",
            3: "三",
            4: "四",
            5: "五",
            6: "六",
        }
        if pet_count == 0:
            self._emit(f"[{log_tag}] 背包已为空，无需放回", "SUCCESS")
        for current_count in range(pet_count, 0, -1):
            tail_cn = count_to_cn[current_count]
            self._emit(
                f"[{log_tag}] 当前{current_count}只：点击放回后验证精灵{tail_cn}变深蓝",
                "INFO",
            )
            try:
                self._click_region(put_back_btn_key, use_foreground)
            except KeyError:
                self._click_region(put_back_key, use_foreground)
            self._sleep_abortable(stop_event, 0.8)
            if not self.wait_bag_putback_slot_deep_blue(
                tail_cn,
                stop_event,
                f"{log_tag}·精灵{tail_cn}",
            ):
                return False
        if pet_count:
            self._emit(
                f"[{log_tag}] 已按六→一尾槽规则放回 {pet_count} 只精灵",
                "SUCCESS",
            )

        if close_after:
            self._close_pet_bag_with_verify(
                use_foreground,
                stop_event,
                bag_open_key,
                bag_open_btn_key,
                log_tag=log_tag,
            )
        return True

    def _rotation_clear_backpack_and_pick_or_skip(
        self,
        current_mode: str,
        use_foreground: bool,
        stop_event: threading.Event,
        *,
        log_tag: str = "轮换模式",
        expected_party_ids: Optional[frozenset] = None,
        verify_primary_166: bool = True,
    ) -> bool:
        """Ensure a wild-mode party; SWF hits must also confirm pet 166 in slot one."""
        self._rotation_step4_bag_already_open = False
        self._rotation_step4_verified_primary_selected = False
        if stop_event.is_set() or getattr(self.bot, "stop_current", False):
            stop_event.set()
            return False

        if expected_party_ids:
            expected_ids = {int(x) for x in expected_party_ids}
            ids_text = ",".join(str(x) for x in sorted(expected_ids))
            self._emit(f"[{log_tag}] 准备清包取宠，期望六宠={ids_text}", "INFO")
            try:
                found_ids: set[int] = set()
                first_map_cursor = getattr(self, "_refresh_pipeline_first_map_kernel_cursor", None)
                if first_map_cursor is not None:
                    lines = fetch_kernel_since(int(first_map_cursor))
                else:
                    lines = fetch_kernel_since(0)
                if not isinstance(lines, list):
                    lines = []
                for line in lines:
                    for pid in iter_party_pet_swf_ids_in_line(str(line)):
                        if pid in expected_ids:
                            found_ids.add(pid)

                if not expected_ids.issubset(found_ids):
                    all_lines = fetch_kernel_since(0)
                    if isinstance(all_lines, list):
                        between_ids, _bounds = collect_fight_pet_swf_ids_between_latest_two_maps(all_lines)
                        for pid in between_ids:
                            if pid in expected_ids:
                                found_ids.add(pid)

                if expected_ids.issubset(found_ids):
                    self._emit(
                        f"[{log_tag}] SWFCheck检测到通用六宠已满足（{ids_text}）",
                        "SUCCESS",
                    )
                    if not verify_primary_166:
                        self._emit(
                            f"[{log_tag}] 当前流程不要求166首发检查，跳过清包取宠",
                            "SUCCESS",
                        )
                        return True
                    if not self._pickmode_open_bag_ready_for_target(
                        use_foreground,
                        stop_event,
                        log_tag=f"{log_tag}·166首发检查·开包",
                    ):
                        return False
                    primary_ok = self._bag_slot_one_is_pet166_from_open_bag(
                        use_foreground,
                        stop_event,
                        log_tag=f"{log_tag}·166首发检查",
                    )
                    if primary_ok:
                        if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                            stop_event.set()
                            return False
                        self._rotation_step4_bag_already_open = True
                        self._rotation_step4_verified_primary_selected = True
                        self._emit(
                            f"[{log_tag}] SWFCheck与166首发均通过；保持背包打开及精灵一选中，交给步骤4直接恢复",
                            "SUCCESS",
                        )
                        return True
                    self._close_pet_bag_with_verify(
                        use_foreground,
                        stop_event,
                        "精灵背包.打开精灵背包",
                        "精灵背包.打开精灵背包按钮",
                        log_tag=f"{log_tag}·166首发检查",
                    )
                    if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                        stop_event.set()
                        return False
                    self._emit(
                        f"⚠️ [{log_tag}] SWFCheck虽通过但166不在精灵一，"
                        "升级为mismatch并清包重取；重取后跳过重复首发检查",
                        "WARN",
                    )
                if found_ids and not expected_ids.issubset(found_ids):
                    seen_text = ",".join(str(x) for x in sorted(found_ids))
                    missing_text = ",".join(str(x) for x in sorted(expected_ids - found_ids))
                    self._emit(
                        f"[{log_tag}] 通用六宠未齐，已见={seen_text}，缺={missing_text}，继续清包取宠",
                        "INFO",
                    )
            except Exception as exc:
                self._emit(f"[{log_tag}] 通用六宠跳过判断异常：{exc}，继续清包取宠", "WARN")
        else:
            self._emit(f"[{log_tag}] 准备清包取宠", "INFO")

        try:
            if not self._rotation_step2_clear_backpack(
                use_foreground,
                stop_event,
                log_tag=f"{log_tag}-清包",
            ):
                self._emit(f"[{log_tag}] 清空背包失败", "WARN")
                return False

            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                stop_event.set()
                return False

            if not self._rotation_step3_place_pets(
                current_mode, use_foreground, stop_event
            ):
                self._emit(f"[{log_tag}] 取六宠失败", "ERROR")
                return False

            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                stop_event.set()
                return False

            self._emit(f"[{log_tag}] 清包取宠完成", "SUCCESS")
            return True
        except Exception as e:
            self._emit(f"[{log_tag}] 清包取宠异常：{e}", "ERROR")
            import traceback

            self._emit(traceback.format_exc(), "ERROR")
            return False

    def _pickmode_recent_party_ids_satisfied(
        self,
        expected_party_ids: Optional[frozenset],
        *,
        log_tag: str,
    ) -> bool:
        """Return whether recent login/map logs already contain the expected six-pet party."""
        if not expected_party_ids:
            return False
        expected_ids = {int(x) for x in expected_party_ids}
        ids_text = ",".join(str(x) for x in sorted(expected_ids))
        try:
            found_ids: set[int] = set()
            first_map_cursor = getattr(self, "_refresh_pipeline_first_map_kernel_cursor", None)
            if first_map_cursor is not None:
                lines = fetch_kernel_since(int(first_map_cursor))
            else:
                lines = fetch_kernel_since(0)
            if not isinstance(lines, list):
                lines = []
            for line in lines:
                for pid in iter_party_pet_swf_ids_in_line(str(line)):
                    if pid in expected_ids:
                        found_ids.add(pid)

            if not expected_ids.issubset(found_ids):
                all_lines = fetch_kernel_since(0)
                if isinstance(all_lines, list):
                    between_ids, _bounds = collect_fight_pet_swf_ids_between_latest_two_maps(all_lines)
                    for pid in between_ids:
                        if pid in expected_ids:
                            found_ids.add(pid)

            if expected_ids.issubset(found_ids):
                self._emit(f"[{log_tag}] 检测到新六宠已满足（{ids_text}），跳过补取", "SUCCESS")
                return True
            seen_text = ",".join(str(x) for x in sorted(found_ids)) if found_ids else "无"
            missing_text = ",".join(str(x) for x in sorted(expected_ids - found_ids))
            self._emit(
                f"[{log_tag}] 新六宠未齐，已见={seen_text}，缺={missing_text}",
                "INFO",
            )
            return False
        except Exception as exc:
            self._emit(f"[{log_tag}] 新六宠检测异常：{exc}，继续补取", "WARN")
            return False

    def ensure_pick_party_from_bag_warehouse_or_skip(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
        *,
        log_tag: str = "背包内仓库补六宠",
        expected_party_ids: Optional[frozenset] = None,
        verify_primary_166: bool = False,
    ) -> bool:
        """Ensure the standard party and return with the pet bag kept open."""
        self._pick_party_verified_primary_selected = False
        if stop_event.is_set() or getattr(self.bot, "stop_current", False):
            stop_event.set()
            return False
        expected = expected_party_ids or self._pickmode_expected_party_ids()
        if self._pickmode_recent_party_ids_satisfied(expected, log_tag=log_tag):
            if not self._pickmode_open_bag_ready_for_target(
                use_foreground,
                stop_event,
                log_tag=f"{log_tag}·开包",
            ):
                return False
            if not verify_primary_166:
                return True
            if self._bag_slot_one_is_pet166_from_open_bag(
                use_foreground,
                stop_event,
                log_tag=f"{log_tag}·166首发检查",
            ):
                self._pick_party_verified_primary_selected = True
                return True
            self._close_pet_bag_with_verify(
                use_foreground,
                stop_event,
                "精灵背包.打开精灵背包",
                "精灵背包.打开精灵背包按钮",
                log_tag=f"{log_tag}·166首发检查",
            )
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                stop_event.set()
                return False
            self._emit(
                f"⚠️ [{log_tag}] SWFCheck虽通过但166不在精灵一，"
                "升级为mismatch并清包重取；重取后跳过重复首发检查",
                "WARN",
            )

        if not self._rotation_step2_clear_backpack(
            use_foreground,
            stop_event,
            log_tag=f"{log_tag}-清包",
            close_after=False,
        ):
            self._emit(f"[{log_tag}] 清空背包失败", "ERROR")
            return False
        if stop_event.is_set() or getattr(self.bot, "stop_current", False):
            stop_event.set()
            return False

        try:
            self._emit(f"[{log_tag}] 清包后保持背包打开，直接打开背包内精灵仓库", "SYSTEM")
            self._click_region("精灵背包.精灵仓库", use_foreground)
            self._sleep_abortable(stop_event, 0.8)
            if not self._pickmode_rotation_step3_place_pets_from_open_warehouse(
                use_foreground,
                stop_event,
                log_tag=log_tag,
            ):
                self._emit(f"[{log_tag}] 背包内仓库补六宠失败", "ERROR")
                return False
            self._click_pet_warehouse_close(use_foreground, log_tag=log_tag)
            self._sleep_abortable(stop_event, 0.5)
            self._emit(
                f"[{log_tag}] 背包内仓库补六宠完成；仅关闭仓库，精灵背包保持打开",
                "SUCCESS",
            )
            return True
        except Exception as exc:
            self._emit(f"[{log_tag}] 背包内仓库补六宠异常：{exc}", "ERROR")
            import traceback

            self._emit(traceback.format_exc(), "ERROR")
            return False

