    def ensure_target_cyan_pick_party_from_bag_warehouse_or_rebuild(
        self,
        target_pet_id: int,
        use_foreground: bool,
        stop_event: threading.Event,
        *,
        log_tag: str = "目标青色前置",
        set_cyan_primary: bool = True,
        base_pet_id: int = PICKMODE_CYAN_BASE_PET_ID,
        verify_primary_166: bool = False,
        skip_cyan_recovery_when_primary: bool = False,
    ) -> bool:
        """目标青色前置：目标组直接恢复；普通组换基准宠；mismatch 重建目标组。"""
        target_pet_id = int(target_pet_id)
        base_pet_id = int(base_pet_id)
        if stop_event.is_set() or getattr(self.bot, "stop_current", False):
            stop_event.set()
            return False

        state, _found_ids, target_list = self._pickmode_classify_target_cyan_party(
            target_pet_id,
            log_tag=log_tag,
            base_pet_id=base_pet_id,
        )

        bag_open_from_primary_check = False
        if verify_primary_166 and state != "mismatch":
            if not self._pickmode_open_bag_ready_for_target(
                use_foreground,
                stop_event,
                log_tag=f"{log_tag}·166首发检查·开包",
            ):
                return False
            if self._bag_slot_one_is_pet166_from_open_bag(
                use_foreground,
                stop_event,
                log_tag=f"{log_tag}·166首发检查",
            ):
                self._emit(
                    f"[{log_tag}] 166技能三通过，沿用当前选中状态直接恢复精灵一",
                    "SUCCESS",
                )
                self._recover_selected_bag_pet_once(
                    "一",
                    use_foreground,
                    stop_event,
                    f"{log_tag}·166首发检查",
                )
                bag_open_from_primary_check = True
            else:
                self._close_pet_bag_with_verify(
                    use_foreground,
                    stop_event,
                    "精灵背包.打开精灵背包",
                    "精灵背包.打开精灵背包按钮",
                    log_tag=f"{log_tag}·166首发检查",
                )
                if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                    stop_event.set()
                    return False
                self._emit(
                    f"⚠️ [{log_tag}] SWFCheck虽通过但166不在精灵一，"
                    "升级为mismatch并清包重取；重取后跳过重复首发检查",
                    "WARN",
                )
                state = "mismatch"

        if target_pet_id != PICKMODE_AIFEIDESI_PET_ID and state == "ordinary":
            if bag_open_from_primary_check:
                self._close_pet_bag_with_verify(
                    use_foreground,
                    stop_event,
                    "精灵背包.打开精灵背包",
                    "精灵背包.打开精灵背包按钮",
                    log_tag=f"{log_tag}·166首发检查",
                )
            self._emit(
                f"[{log_tag}] 目标青色={target_pet_id}（非1459），"
                f"严格单青放回基准宠{base_pet_id}后换青",
                "SYSTEM",
            )
            return self.replace_current_cyan_with_pick_pet_from_closed_bag(
                target_pet_id,
                use_foreground,
                stop_event,
                log_tag=f"{log_tag}·单青换{target_pet_id}",
                set_cyan_primary=set_cyan_primary,
                require_putback_confirmation=True,
            )

        if state == "mismatch":
            self._emit(
                f"[{log_tag}] mismatch 按稳定数量逐只确认清包后重取目标组",
                "SYSTEM",
            )
            if not self._rotation_step2_clear_backpack(
                use_foreground,
                stop_event,
                log_tag=f"{log_tag}·清包",
                close_after=False,
            ):
                return False

        if state != "mismatch" and not bag_open_from_primary_check:
            if not self._pickmode_open_bag_ready_for_target(
                use_foreground,
                stop_event,
                log_tag=f"{log_tag}·开包",
            ):
                return False

        if state == "target":
            return self.recover_cyan_and_follow_purple_from_open_bag(
                use_foreground,
                stop_event,
                f"{log_tag}·目标组恢复",
                set_cyan_primary=set_cyan_primary,
                recover_pet_one=False,
                recover_cyan=True,
                set_follow_purple=True,
                skip_cyan_recovery_when_primary=skip_cyan_recovery_when_primary,
            )

        if state == "ordinary":
            if target_pet_id == PICKMODE_AIFEIDESI_PET_ID:
                self._emit(f"[{log_tag}] 目标1459时普通六宠即为正确，直接恢复1459青色", "SUCCESS")
                return self.recover_cyan_and_follow_purple_from_open_bag(
                    use_foreground,
                    stop_event,
                    f"{log_tag}·普通组1459恢复",
                    set_cyan_primary=set_cyan_primary,
                    recover_pet_one=False,
                    recover_cyan=True,
                    set_follow_purple=True,
                )
            if not self.put_back_cyan_slots_from_open_bag(
                use_foreground,
                stop_event,
                f"{log_tag}·放回{base_pet_id}青色",
                require_cyan=True,
                max_slots=1,
            ):
                return False
            needs_take_target = target_pet_id not in PICKMODE_STANDARD_PARTY_IDS
            if needs_take_target:
                if not self._pickmode_open_warehouse_from_ready_bag(
                    use_foreground,
                    stop_event,
                    log_tag=f"{log_tag}·打开仓库",
                ):
                    return False
                if not self.take_pickmode_pets_from_open_bag_warehouse(
                    (target_pet_id,),
                    use_foreground,
                    stop_event,
                    log_tag=f"{log_tag}·取目标青色",
                ):
                    return False
                self._click_pet_warehouse_close(use_foreground, log_tag=log_tag)
                self._sleep_abortable(stop_event, 0.5)
            else:
                self._emit(
                    f"[{log_tag}] 目标 {target_pet_id} 已在普通组内，"
                    f"仅放回{base_pet_id}青色",
                    "INFO",
                )

            return self.recover_cyan_and_follow_purple_from_open_bag(
                use_foreground,
                stop_event,
                f"{log_tag}·换青后恢复",
                set_cyan_primary=set_cyan_primary,
                recover_pet_one=False,
                recover_cyan=True,
                set_follow_purple=True,
            )

        if not self._pickmode_open_warehouse_from_ready_bag(
            use_foreground,
            stop_event,
            log_tag=f"{log_tag}·打开仓库",
        ):
            return False
        if not self.take_pickmode_pets_from_open_bag_warehouse(
            target_list,
            use_foreground,
            stop_event,
            log_tag=f"{log_tag}·目标组重取",
            rebuild_mode=True,
        ):
            return False
        self._click_pet_warehouse_close(use_foreground, log_tag=log_tag)
        self._sleep_abortable(stop_event, 0.5)
        return self.recover_cyan_and_follow_purple_from_open_bag(
            use_foreground,
            stop_event,
            f"{log_tag}·重取后恢复",
            set_cyan_primary=set_cyan_primary,
            recover_pet_one=False,
            recover_cyan=True,
            set_follow_purple=True,
        )

    def replace_current_cyan_with_pick_pet_from_closed_bag(
        self,
        target_pet_id: int,
        use_foreground: bool,
        stop_event: threading.Event,
        *,
        log_tag: str = "青色换宠",
        set_cyan_primary: bool = False,
        require_putback_confirmation: bool = False,
        set_follow_purple: bool = True,
        recover_target_after_take: bool = True,
    ) -> bool:
        """从关闭背包状态把当前青色放回，取出指定目标并按需恢复、跟随。"""
        if not self._pickmode_open_bag_ready_for_target(
            use_foreground,
            stop_event,
            log_tag=f"{log_tag}·开包",
        ):
            return False
        if not self.put_back_cyan_slots_from_open_bag(
            use_foreground,
            stop_event,
            f"{log_tag}·放回当前青色",
            require_cyan=True,
            max_slots=1,
            require_all_six_tricolor=require_putback_confirmation,
            verify_slot_deep_blue=require_putback_confirmation,
        ):
            return False
        if not self._pickmode_open_warehouse_from_ready_bag(
            use_foreground,
            stop_event,
            log_tag=f"{log_tag}·打开仓库",
        ):
            return False
        if not self.take_pickmode_pets_from_open_bag_warehouse(
            (int(target_pet_id),),
            use_foreground,
            stop_event,
            log_tag=f"{log_tag}·取{int(target_pet_id)}",
        ):
            return False
        self._click_pet_warehouse_close(use_foreground, log_tag=log_tag)
        self._sleep_abortable(stop_event, 0.5)
        if recover_target_after_take:
            if not self.recover_cyan_and_follow_purple_from_open_bag(
                use_foreground,
                stop_event,
                f"{log_tag}·恢复{'跟随' if set_follow_purple else ''}",
                set_cyan_primary=set_cyan_primary,
                recover_pet_one=False,
                recover_cyan=True,
                set_follow_purple=set_follow_purple,
            ):
                return False
        else:
            self._emit(
                f"[{log_tag}] 一次性模式已完成，取出{int(target_pet_id)}后跳过恢复",
                "SUCCESS",
            )
        if not set_follow_purple or not recover_target_after_take:
            self._close_pet_bag_with_verify(
                use_foreground,
                stop_event,
                "精灵背包.打开精灵背包",
                "精灵背包.打开精灵背包按钮",
                log_tag=(
                    f"{log_tag}·恢复后关闭背包"
                    if recover_target_after_take
                    else f"{log_tag}·取宠后关闭背包"
                ),
            )
        return True

    def _hide_newnpc_multi_4_for_warehouse(self, log_tag: str = "") -> None:
        """Hide newNpc/multi/4 before opening pet warehouse."""
        from core.swf_resource_ops import rename_newnpc_multi_4_to_4_og
        ok, msg = rename_newnpc_multi_4_to_4_og()
        tag = f"[{log_tag}] " if log_tag else ""
        self._emit(f"{tag}newNpc/multi 4->4_og: {msg}", "DEBUG" if ok else "WARN")

    def _keep_newnpc_multi_4_hidden(self, log_tag: str = "") -> None:
        self._hide_newnpc_multi_4_for_warehouse(log_tag)

    def _click_pet_warehouse_open(self, use_foreground: bool, *, log_tag: str = ""):
        self._hide_newnpc_multi_4_for_warehouse(log_tag)
        return self._click_region("精灵仓库.打开", use_foreground)

    def _click_pet_warehouse_close(self, use_foreground: bool, *, log_tag: str = ""):
        ret = self._click_region("精灵仓库.关闭", use_foreground)
        self._keep_newnpc_multi_4_hidden(log_tag)
        return ret

    def _warehouse_probe_is_mostly_white(self, region_key: str) -> bool:
        """Return whether a warehouse slot probe is mostly white."""
        try:
            reg = self.regions.get(region_key)
            if not reg:
                return True
            x1, y1, x2, y2 = reg.outer_bbox()
            img = window_manager.grab_game_bbox(x1, y1, x2, y2, min_size_px=2)
            if not img:
                return True
            arr = np.asarray(img.convert("RGB"), dtype=np.uint8)
            r, g, b = [int(v) for v in arr.mean(axis=(0, 1))]
            return (r > 240) and (g > 240) and (b > 240)
        except Exception:
            return True

    @staticmethod
    def _warehouse_right_rgb_is_end(rgb: Optional[Tuple[int, int, int]]) -> bool:
        if rgb is None:
            return False
        r, g, b = rgb
        # 结束态必须是明显的蓝色高亮（例如约 119,192,235）。
        # 宁可多点一次，也不能把仍可点击的浅灰按钮误判为末页。
        return (
            b >= 190
            and g >= r + 30
            and b >= g + 25
            and b >= r + 70
        )

    @staticmethod
    def _warehouse_right_rgb_is_available(rgb: Optional[Tuple[int, int, int]]) -> bool:
        if rgb is None:
            return False
        r, g, b = rgb
        # 右翻按钮可点击时会在两种中性亮灰之间切换：
        # 点击瞬间约 (183, 183, 183)，静止时约 (223, 223, 223)。
        # 不能只用旧的 185 下限，否则会把前一种可点击状态误判为未就绪。
        return min(r, g, b) >= 150 and max(r, g, b) - min(r, g, b) <= 35

    def _warehouse_click_all_until_right_available(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
        *,
        log_tag: str,
        timeout_s: float = 8.0,
    ) -> bool:
        for key in ("精灵仓库.ALL", "精灵仓库.右"):
            if not self.regions.get(key):
                self._emit(f"[{log_tag}] 缺少区域：{key}", "ERROR")
                return False

        t0 = time.time()
        attempts = 0
        last_log = 0.0
        while time.time() - t0 < timeout_s:
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return False
            rgb = self._mean_rgb_for_region_key("精灵仓库.右")
            if self._warehouse_right_rgb_is_available(rgb):
                self._emit(f"[{log_tag}] 精灵仓库.ALL 已生效：精灵仓库.右已亮灰 RGB={rgb}", "SUCCESS")
                return True
            attempts += 1
            if time.time() - last_log >= 1.0:
                self._emit(
                    f"[{log_tag}] 点击 精灵仓库.ALL 等待 精灵仓库.右亮灰：RGB={rgb}，尝试 {attempts}",
                    "DEBUG",
                )
                last_log = time.time()
            self._click_region("精灵仓库.ALL", use_foreground)
            self._sleep_abortable(stop_event, 0.25, tick=0.05)

        rgb = self._mean_rgb_for_region_key("精灵仓库.右")
        self._emit(f"[{log_tag}] 点击 精灵仓库.ALL 超时：精灵仓库.右仍未亮灰 RGB={rgb}", "ERROR")
        return False

    def _warehouse_right_until_end(
        self,
        right_clicks: int,
        use_foreground: bool,
        stop_event: threading.Event,
        *,
        log_tag: str,
    ) -> bool:
        """Click warehouse right until the right button reaches end color."""
        right_key = "精灵仓库.右"
        # 所有仓库倒数取宠统一以右翻按钮的末端颜色为结束条件。
        # right_clicks 保留用于兼容旧配置；安全上限统一为 300 次。
        _ = right_clicks
        for click_count in range(WAREHOUSE_PAGE_TURN_MAX_COUNT):
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return False
            rgb = self._mean_rgb_for_region_key(right_key)
            if self._warehouse_right_rgb_is_end(rgb):
                self._emit(
                    f"[{log_tag}] warehouse right reached end after "
                    f"{click_count} clicks: RGB={rgb}",
                    "INFO",
                )
                return True
            self._click_region(right_key, use_foreground)
            time.sleep(0.15)
        rgb = self._mean_rgb_for_region_key(right_key)
        if self._warehouse_right_rgb_is_end(rgb):
            self._emit(
                f"[{log_tag}] warehouse right reached end after "
                f"{WAREHOUSE_PAGE_TURN_MAX_COUNT} clicks: RGB={rgb}",
                "INFO",
            )
            return True
        self._emit(
            f"[{log_tag}] 仓库右翻达到上限 "
            f"{WAREHOUSE_PAGE_TURN_MAX_COUNT} 次仍未到末页：RGB={rgb}",
            "ERROR",
        )
        return False

    def _click_warehouse_jita_subtab(
        self, use_foreground: bool, *, log_tag: str = "Pick-步骤3"
    ) -> None:
        """Click warehouse mechanical-dragon subtab for jita."""
        key = "精灵仓库.机械龙系"
        if not self.regions.get(key):
            raise KeyError(f"缺少区域：{key}")
        self._click_region(key, use_foreground)
        self._emit(f"[{log_tag}] 点击 {key}", "INFO")
    def _pickmode_place_jita_dual_mechanical(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
        *,
        log_tag: str = "Pick",
    ) -> bool:
        """Place jita from dual-attribute mechanical-dragon warehouse path."""
        jita_ok = False
        for attempt in range(40):
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return False
            try:
                self._click_region("精灵仓库.双属性", use_foreground)
            except Exception:
                self._emit(f"[{log_tag}] 缺少区域：精灵仓库.双属性", "WARN")
                break
            self._sleep_abortable(stop_event, PICKMODE_WAREHOUSE_DUAL_ATTR_TO_MECHANICAL_SEC)
            try:
                self._click_warehouse_jita_subtab(use_foreground, log_tag=log_tag)
            except Exception as e:
                self._emit(f"[{log_tag}] 点击机械龙系失败：{e}", "WARN")
                break
            self._sleep_abortable(stop_event, PICKMODE_WAREHOUSE_MECHANICAL_TO_SLOT1_PROBE_SEC)
            if not self._warehouse_probe_is_mostly_white("精灵仓库.1"):
                jita_ok = True
                break
            self._emit(f"[{log_tag}] 精灵仓库.1仍为白色，重试 {attempt + 1}/40", "INFO")

        if jita_ok:
            self._emit(f"[{log_tag}] 机塔就绪，放入背包", "INFO")
            self._click_region("精灵仓库.放入背包", use_foreground)
            self._sleep_abortable(stop_event, 1.5)
            self._click_region_twice("对话框.普通确认", use_foreground, gap=0.06)
            self._sleep_abortable(stop_event, 0.8)
        else:
            self._emit(f"[{log_tag}] 机塔位置仍为白色，跳过放入背包", "WARN")
        return jita_ok

    def _pickmode_rotation_step3_place_pets_yameisi(
        self, use_foreground: bool, stop_event: threading.Event
    ) -> bool:
        """Yameisi branch uses the same unified Pick Step3."""
        return self._pickmode_rotation_step3_place_pets(
            use_foreground, stop_event
        )

    def _pickmode_rotation_step3_place_pets(
        self, use_foreground: bool, stop_event: threading.Event
    ) -> bool:
        """Unified Pick Step3: place six pets into backpack."""
        self._emit("[Pick-步骤3] 打开精灵仓库并取六宠", "SYSTEM")
        self._click_pet_warehouse_open(use_foreground, log_tag="Pick-步骤3")
        self._sleep_abortable(stop_event, 0.8)
        if not self._warehouse_click_all_until_right_available(
            use_foreground,
            stop_event,
            log_tag="Pick-步骤3·仓库ALL",
        ):
            return False
        if not self._pickmode_rotation_step3_place_pets_from_open_warehouse(
            use_foreground, stop_event, log_tag="Pick-步骤3"
        ):
            self._emit("[Pick-步骤3] 六宠未全部取出，停止后续跟随", "ERROR")
            return False
        self._emit("[Pick-步骤3] 关闭精灵仓库", "INFO")
        self._click_pet_warehouse_close(use_foreground, log_tag="Pick-步骤3")
        self._sleep_abortable(stop_event, 0.5)
        return True

    def _pickmode_rotation_step3_place_pets_from_open_warehouse(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
        *,
        log_tag: str = "Pick-步骤3",
    ) -> bool:
        """Place the standard six pets while the pet warehouse is already open."""
        import config as _rot_cfg

        def _r(name: str, default: int) -> int:
            try:
                return int(getattr(_rot_cfg, name, default))
            except Exception:
                return default

        if not self._rotation_place_pets_same_category_by_reverse(
            "飞行系", (4,), _r("ROTATION_NIEO_RIGHT_CLICKS_FLIGHT", 25),
            use_foreground, stop_event, reverse_order=False, log_tag=log_tag
        ):
            return False
        if not self._rotation_place_pets_same_category_by_reverse(
            "超能系", (3, 20), _r("ROTATION_NIEO_RIGHT_CLICKS_PSYCHIC", 80),
            use_foreground, stop_event, reverse_order=False, log_tag=log_tag
        ):
            return False
        if not self._rotation_place_pets_same_category_by_reverse(
            "普通系", (18,), _r("ROTATION_NIEO_RIGHT_CLICKS_NORMAL", 80),
            use_foreground, stop_event, reverse_order=False, log_tag=log_tag
        ):
            return False
        if not self._rotation_place_pets_same_category_by_reverse(
            "冰系", (6,), _r("ROTATION_NIEO_RIGHT_CLICKS_ICE", 80),
            use_foreground, stop_event, reverse_order=False, log_tag=log_tag
        ):
            return False
        if not self._pickmode_place_jita_dual_mechanical(
            use_foreground, stop_event, log_tag=log_tag
        ):
            return False
        return True

    def _pickmode_rotation_step4_set_companion_yameisi(
        self, use_foreground: bool, stop_event: threading.Event
    ) -> bool:
        """Yameisi branch Step4: recover/identify and follow purple slot."""
        return self._pickmode_rotation_step4_set_companion(use_foreground, stop_event)

    def _pickmode_rotation_step4_set_companion(
        self,
        use_foreground: bool,
        stop_event: threading.Event,
        *,
        follow_cyan: bool = False,
    ) -> bool:
        """Pick Step4: open bag, recover/identify slots, then set the requested companion."""
        self._emit("[Pick-步骤4] set companion", "SYSTEM")
        bag_open_key = "精灵背包.打开精灵背包"
        bag_open_btn_key = "精灵背包.打开精灵背包按钮"
        bag_already_open = bool(
            getattr(self, "_rotation_step4_bag_already_open", False)
        )
        verified_primary_selected = bool(
            bag_already_open
            and getattr(self, "_rotation_step4_verified_primary_selected", False)
        )
        self._rotation_step4_bag_already_open = False
        self._rotation_step4_verified_primary_selected = False
        if bag_already_open:
            self._emit(
                "[Pick-步骤4] 沿用166技能三检查已打开的背包，不再关闭重开",
                "INFO",
            )
        else:
            try:
                self._click_region(bag_open_btn_key, use_foreground)
            except KeyError:
                self._click_region(bag_open_key, use_foreground)
        if not self._wait_pet_bag_ui_ready_after_open(
            stop_event, log_tag="Pick-步骤4"
        ):
            self._emit("[Pick-步骤4] 精灵背包未就绪", "ERROR")
            return False
        if verified_primary_selected:
            self._emit(
                "[Pick-步骤4] 166技能三已通过且精灵一仍为选中状态，直接恢复精灵一",
                "SUCCESS",
            )
            self._recover_selected_bag_pet_once(
                "一",
                use_foreground,
                stop_event,
                "Pick-步骤4",
            )
        if not self._recover_pick_party_after_bag_ready(
            use_foreground,
            stop_event,
            "Pick-步骤4",
            include_primary=False,
            set_follow_primary=True,
            follow_primary_color="cyan" if follow_cyan else "purple",
            primary_already_recovered=verified_primary_selected,
        ):
            follow_label = "青色" if follow_cyan else "紫色"
            self._emit(f"[Pick-步骤4] 恢复或{follow_label}跟随失败", "ERROR")
            return False
        self._pickmode_base_recovery_done = True
        follow_label = "青色" if follow_cyan else "紫色"
        follow_pos = getattr(
            self,
            "_aisifeige_pos" if follow_cyan else "_jita_pos",
            None,
        )
        slot = follow_pos if follow_pos in ("一", "二", "三", "四", "五", "六") else None
        if slot:
            self._emit(
                f"[Pick-步骤4] {follow_label}跟随槽位：精灵{slot}",
                "SUCCESS",
            )
        else:
            self._emit(
                f"[Pick-步骤4] {follow_label}跟随动作已完成，但槽位缓存不可用",
                "WARN",
            )
        return True

