    def _rotation_step5_execute_to_script_and_start_mode(
        self,
        current_mode: str,
        use_foreground: bool,
        stop_event: threading.Event,
        next_switch_datetime: datetime,
        *,
        entry_check_only: bool = False,
    ) -> bool:
        """Rotation Step5: run to-script, verify map, then start target mode."""
        self._emit(f"[轮换模式-步骤5] 启动：模式={current_mode}", "SYSTEM")
        self._rotation_active_segment_mode = current_mode
        exec_mode = self._normalize_rotation_schedule_mode(current_mode)

        profile: Optional[WildCaptureProfile] = None
        expected_map_id: Optional[int] = None
        script_name: Optional[str] = None
        if exec_mode in ("nieo", "nieo_resource"):
            expected_map_id = 11
            script_name = "to尼奥"
        elif exec_mode == "pure_energy":
            expected_map_id = 27
            script_name = "to纯净能量"
        elif current_mode.startswith("resource:"):
            slug = current_mode.split(":", 1)[1]
            from core.nieo_mode_registry import get_profile as get_nieo_profile
            root = getattr(self.bot, "project_root", None) or os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
            nieo_pf = get_nieo_profile(root, slug)
            expected_map_id = int(getattr(nieo_pf, "map_a_id", 11)) if nieo_pf else 11
            script_name = getattr(nieo_pf, "to_script", None) or f"to{getattr(nieo_pf, 'name', slug)}"
        elif exec_mode == "eit":
            from core.event_pet_mode_registry import get_profile as get_event_profile
            root = getattr(self.bot, "project_root", None) or os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
            ep = get_event_profile(root, "yite")
            expected_map_id = int(ep.map_a_id) if ep else 414
            script_name = ep.to_script if ep else "to伊特"
        elif exec_mode == "mantis":
            profile = self._resolve_rotation_rare_profile("mantis")
            expected_map_id = int(profile.map_swf_id)
            script_name = profile.to_script or "to螳螂"
        else:
            if current_mode.startswith("rare:"):
                rare_key = current_mode.split(":", 1)[1]
            elif exec_mode in ("shuangta", "flash_pipi", "eyeball", "dugulu", "xiaodouya"):
                rare_key = exec_mode
            else:
                rare_key = getattr(self, "_rotation_rare_slot", "shuangta")
            profile = self._resolve_rotation_rare_profile(rare_key)
            expected_map_id = int(profile.map_swf_id)
            script_name = self._get_to_script_name(profile)

        dr = getattr(self.bot, "daily_runner", None)
        if expected_map_id is not None and not script_name:
            profile_name = getattr(profile, "name", current_mode)
            self._emit(f"[轮换模式-步骤5] 缺少 {profile_name} 的to脚本，停止地图门控", "ERROR")
            return False
        if script_name and dr is None:
            self._emit(f"[轮换模式-步骤5] daily_runner 不可用，无法执行 {script_name}.json", "ERROR")
            return False
        to_start_cursor = kernel_cursor()
        if script_name and dr is not None:
            self._emit(f"[轮换模式-步骤5] 执行 {script_name}.json", "INFO")
            ok_script = bool(
                dr.run_single_script(
                    script_name,
                    bg_mode=(not use_foreground),
                    stop_event=stop_event,
                )
            )
            if not ok_script:
                self._emit(f"[轮换模式-步骤5] 脚本执行失败：{script_name}", "WARN")
                return False
        special_gate = self._special_essence_gate_after_to(
            script_name,
            to_start_cursor,
            stop_event,
            log_tag=f"轮换模式-{getattr(profile, 'name', script_name)}",
        )
        if special_gate is False:
            return False

        self._sleep_abortable(stop_event, 2.0)

        if expected_map_id is not None and special_gate is not True:
            if profile is not None and self._is_wusuo_profile(profile):
                if not self._wait_wusuo_map325_and_probe_after_to(
                    to_start_cursor,
                    stop_event,
                    timeout_s=8.0,
                ):
                    self._emit("[轮换模式-步骤5] 乌索to脚本后门控失败", "WARN")
                    return False
                self._emit("[轮换模式-步骤5] 乌索零位门控通过", "SUCCESS")
                self._on_map_zero_gate_passed()
            elif profile is not None:
                gate_zero = wild_rare_map_gate_zero_literal_swf_ids(profile)
                expected_zero = self._wild_rare_expected_map_zero_after_to(profile)
                anchor_map_id = int(expected_zero) if expected_zero is not None else int(expected_map_id)
                last_map_id, has_newNPC = self._wait_after_to_then_check_last_map_and_newnpc(
                    anchor_map_id,
                    stop_event,
                    timeout_s=15.0,
                    log_tag="轮换模式-步骤5",
                    start_cursor=to_start_cursor,
                    accepted_map_ids=gate_zero if gate_zero else None,
                )
                if not has_newNPC or not self._kernel_map_matches_profile_expectation(
                    profile, last_map_id, anchor_map_id
                ):
                    self._emit(
                        f"[轮换模式-步骤5] 地图校验失败：map={last_map_id}, 期望={anchor_map_id}, newNpc={has_newNPC}",
                        "WARN",
                    )
                    return False
            else:
                last_map_id, has_newNPC = self._check_last_map_and_newnpc(int(expected_map_id), timeout_s=15.0)
                if last_map_id == int(expected_map_id) and has_newNPC:
                    pass
                else:
                    self._emit(
                        f"[轮换模式-步骤5] 地图校验失败：map={last_map_id}, 期望={expected_map_id}, newNpc={has_newNPC}",
                        "WARN",
                    )
                    return False

        if entry_check_only:
            self._emit(f"[轮换模式-步骤5] 入口检查通过：{current_mode}", "SUCCESS")
            return True

        if exec_mode == "nieo":
            self.run_nieo_mode(
                stop_event=stop_event,
                use_foreground=use_foreground,
                is_rotation_mode=True,
                next_switch_time=next_switch_datetime,
                nieo_single_map_escape=bool(getattr(self, "_rotation_nieo_single_map_escape", False)),
                follow_cyan=self._rotation_follow_cyan_for_mode(current_mode),
            )
        elif exec_mode == "nieo_resource":
            self.run_nieo_mode(
                stop_event=stop_event,
                use_foreground=use_foreground,
                is_rotation_mode=True,
                next_switch_time=next_switch_datetime,
                nieo_resource_defeat=True,
                nieo_single_map_escape=bool(getattr(self, "_rotation_nieo_single_map_escape", False)),
                follow_cyan=self._rotation_follow_cyan_for_mode(current_mode),
            )
        elif exec_mode == "pure_energy":
            self.run_pure_energy_resource_mode(
                stop_event=stop_event,
                use_foreground=use_foreground,
                nieo_pre_rotation_first=False,
                is_rotation_mode=True,
                next_switch_time=next_switch_datetime,
                single_map=bool(getattr(self, "_rotation_nieo_single_map_escape", False)),
                follow_cyan=self._rotation_follow_cyan_for_mode(current_mode),
            )
        elif current_mode.startswith("resource:"):
            slug = current_mode.split(":", 1)[1]
            from core.nieo_mode_registry import get_profile as get_nieo_profile
            root = getattr(self.bot, "project_root", None) or os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
            nieo_pf = get_nieo_profile(root, slug)
            if nieo_pf is None:
                return False
            self.run_configured_nieo_mode(
                nieo_pf,
                stop_event,
                use_foreground,
                is_rotation_mode=True,
                next_switch_time=next_switch_datetime,
                skip_pre_entry=True,
                single_map=bool(getattr(self, "_rotation_nieo_single_map_escape", False)),
                follow_cyan=self._rotation_follow_cyan_for_mode(current_mode),
            )
        elif exec_mode == "eit":
            from core.event_pet_mode_registry import get_profile as get_event_profile
            root = getattr(self.bot, "project_root", None) or os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
            ep = get_event_profile(root, "yite")
            if ep is None:
                return False
            return bool(self.run_event_pet_mode(
                ep,
                stop_event,
                use_foreground,
                skip_pre_rotation=True,
                is_rotation_mode=True,
                next_switch_time=next_switch_datetime,
            ))
        else:
            if profile is None:
                profile = self._resolve_rotation_rare_profile(getattr(self, "_rotation_rare_slot", "shuangta"))
            self.run(
                stop_event=stop_event,
                use_foreground=use_foreground,
                profile=profile,
                is_rotation_mode=True,
                next_switch_time=next_switch_datetime,
            )
        return True
