    PINNACLE_MODE_RANK = "rank"
    PINNACLE_MODE_FUN = "fun"

    PINNACLE_TARGET_LOBBY_MAP_ID = 4
    PINNACLE_BATTLE_AREA_MAP_ID = 433

    PINNACLE_IP_TOKEN = "/ip.txt"
    PINNACLE_LOGIN_WAIT_SEC = REFRESH_LOGIN_WAIT_SEC
    PINNACLE_IP_WAIT_SEC = 15.0
    PINNACLE_MAP_WAIT_SEC = 20.0
    PINNACLE_1AND1_MANDATORY_WAIT_SEC = 20.0
    PINNACLE_PETITEM_WAIT_SEC = 45.0
    # 涓夐敭寰幆 / 鍙岄敭寰幆锛堜腑閫燂級
    PINNACLE_LOOP_CLICK_INTERVAL_SEC = 0.25
    PINNACLE_LOOP_SLEEP_SEC = 0.05

    def run_pinnacle_mode(
        self,
        stop_event: threading.Event,
        use_foreground: bool,
        mode: str = "rank",
        small_account_mode: bool = False,
    ) -> None:
        """Run pinnacle battle mode, one skill turn per refresh cycle."""
        if mode not in (self.PINNACLE_MODE_RANK, self.PINNACLE_MODE_FUN):
            self._emit(f"[巅峰对战] 未知模式={mode}，默认使用排位", "WARN")
            mode = self.PINNACLE_MODE_RANK
        mode_label = "排位" if mode == self.PINNACLE_MODE_RANK else "娱乐"
        behavior = "小号模式" if small_account_mode else "标准模式"
        self._emit(f"[巅峰对战] 启动：{mode_label}，{behavior}", "SYSTEM")
        try:
            import win32gui
            if window_manager.find_window() and window_manager.hwnd:
                try:
                    win32gui.SetForegroundWindow(window_manager.hwnd)
                except Exception:
                    pass
        except Exception:
            pass
        round_idx = 0
        try:
            while not stop_event.is_set() and not getattr(self.bot, "stop_current", False):
                round_idx += 1
                self._emit(f"[巅峰对战] 第 {round_idx} 轮开始（{mode_label}）", "SYSTEM")
                try:
                    ok = self._pinnacle_run_once(mode, use_foreground, stop_event, small_account_mode)
                    if not ok:
                        self._emit("[巅峰对战] 本轮未完成，刷新后重试", "WARN")
                except Exception as e:
                    self._emit(f"[巅峰对战] 本轮异常：{e}", "ERROR")
                    import traceback
                    self._emit(traceback.format_exc(), "ERROR")
        finally:
            self._emit(f"[巅峰对战] 已停止，共执行 {round_idx} 轮", "SYSTEM")

    def _pinnacle_run_once(
        self,
        mode: str,
        use_foreground: bool,
        stop_event: threading.Event,
        small_account_mode: bool = False,
    ) -> bool:
        """Run one pinnacle cycle from refresh to the first skill click."""
        if not self._pinnacle_refresh_and_wait_login(use_foreground, stop_event):
            return False
        if stop_event.is_set() or getattr(self.bot, "stop_current", False):
            return False
        if not self._post_login_swf_programmatic_clicks(use_foreground, stop_event, "巅峰对战"):
            return False
        if not self._shield_schedule_after_map_signal(use_foreground, stop_event, "巅峰对战"):
            return False
        self._sleep_abortable(stop_event, 0.35)
        if not self._pinnacle_ensure_lobby_map4(use_foreground, stop_event):
            return False
        self._emit("[巅峰对战] 执行脚本 fix_script/巅峰对战.json", "SYSTEM")
        if hasattr(self.bot, "daily_runner"):
            try:
                if not self.bot.daily_runner.run_single_script("巅峰对战", bg_mode=(not use_foreground)):
                    self._emit("[巅峰对战] 脚本执行失败", "WARN")
                    return False
            except Exception as e:
                self._emit(f"[巅峰对战] 脚本异常：{e}", "ERROR")
                return False
        else:
            self._emit("[巅峰对战] 缺少 daily_runner", "ERROR")
            return False
        self._sleep_abortable(stop_event, 1.0)
        if not self._pinnacle_wait_for_map(self.PINNACLE_BATTLE_AREA_MAP_ID, self.PINNACLE_MAP_WAIT_SEC, stop_event):
            return False
        if not self._pinnacle_click_entry_and_start_until_petitem(mode, use_foreground, stop_event):
            return False
        if small_account_mode:
            self._emit("[巅峰对战] 小号模式：已入战，跳过技能点击", "INFO")
            return True
        self._emit("[巅峰对战] 点击 对战.使用技能一", "INFO")
        try:
            self._click_region("对战.使用技能一", use_foreground)
        except KeyError:
            self._emit("[巅峰对战] 缺少区域：对战.使用技能一", "ERROR")
            return False
        self._sleep_abortable(stop_event, 0.3)
        return True

    def _pinnacle_refresh_and_wait_login(
        self, use_foreground: bool, stop_event: threading.Event
    ) -> bool:
        """Refresh and wait for Login.swf."""
        from core.logger import fetch_kernel_since, kernel_cursor
        while not stop_event.is_set() and not getattr(self.bot, "stop_current", False):
            self._pinnacle_round_refresh_start = time.perf_counter()
            self._mark_refresh_pipeline_start()
            if not self._refresh_trinity_clicks(use_foreground, log_prefix="巅峰对战", stop_event=stop_event):
                self._sleep_abortable(stop_event, 0.8)
                continue
            self._sleep_abortable(stop_event, 0.45)
            cursor = kernel_cursor()
            t0 = time.time()
            while (time.time() - t0) < self.PINNACLE_LOGIN_WAIT_SEC:
                if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                    return False
                lines = fetch_kernel_since(cursor)
                if isinstance(lines, list) and any(self._kernel_line_indicates_login_swf(line) for line in lines):
                    self._emit("[巅峰对战] 检测到 Login.swf", "SUCCESS")
                    self._sleep_abortable(stop_event, 0.8)
                    return True
                cursor = kernel_cursor()
                time.sleep(0.2)
            self._emit("[巅峰对战] 未检测到 Login.swf，重试刷新登录", "WARN")
        return False

    def _pinnacle_wait_ip_signal(self, stop_event: threading.Event) -> bool:
        from core.logger import fetch_kernel_since, kernel_cursor
        cursor = kernel_cursor()
        t0 = time.time()
        while (time.time() - t0) < self.PINNACLE_IP_WAIT_SEC:
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return False
            lines = fetch_kernel_since(cursor)
            if isinstance(lines, list) and any(line_matches(RE_IP_TXT, str(line)) for line in lines):
                return True
            cursor = kernel_cursor()
            time.sleep(0.15)
        return False

    def _pinnacle_click_server_until_map(
        self, use_foreground: bool, stop_event: threading.Event
    ) -> bool:
        return self._click_three_keys_until_map_refresh(
            use_foreground=use_foreground,
            stop_event=stop_event,
            log_tag="巅峰对战",
        )

    def _pinnacle_handle_1and1_by_time(
        self, use_foreground: bool, stop_event: threading.Event
    ) -> bool:
        now_bj = self._get_beijing_time()
        if 0 <= int(now_bj.hour) < 6:
            return self._pinnacle_measure_and_handle_1and1_mandatory(use_foreground, stop_event)
        return self._pinnacle_wait_1and1_window_and_handle(use_foreground, stop_event, timeout_s=0.8)

    def _pinnacle_measure_and_handle_1and1_mandatory(
        self, use_foreground: bool, stop_event: threading.Event
    ) -> bool:
        start_t = time.time()
        timeout_s = float(self.PINNACLE_1AND1_MANDATORY_WAIT_SEC)
        while time.time() - start_t < timeout_s:
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return False
            if self._check_1and1_probes():
                elapsed = time.time() - start_t
                self._pinnacle_last_map_to_1and1_elapsed = elapsed
                return self._dismiss_1and1_until_disappear(use_foreground, stop_event, timeout_s=8.0, log_tag="巅峰对战", require_seen=True, require_click=True)
            time.sleep(0.05)
        self._emit(f"[巅峰对战] 强制1AND1等待超时({timeout_s:.0f}s)", "WARN")
        return False

    def _pinnacle_wait_1and1_window_and_handle(
        self, use_foreground: bool, stop_event: threading.Event, timeout_s: float
    ) -> bool:
        deadline = time.time() + max(0.0, float(timeout_s))
        while time.time() < deadline:
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return False
            if self._check_1and1_probes():
                return self._dismiss_1and1_until_disappear(use_foreground, stop_event, timeout_s=8.0, log_tag="巅峰对战", require_seen=True, require_click=True)
            time.sleep(0.05)
        return True

    def _pinnacle_latest_map_id(self) -> Optional[int]:
        return self._get_last_map_id()

    def _pinnacle_wait_for_map(
        self, target_map_id: int, timeout_s: float, stop_event: threading.Event
    ) -> bool:
        t0 = time.time()
        while (time.time() - t0) < timeout_s:
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return False
            if self._pinnacle_latest_map_id() == int(target_map_id):
                return True
            time.sleep(0.2)
        return False

    def _pinnacle_ensure_lobby_map4(
        self, use_foreground: bool, stop_event: threading.Event
    ) -> bool:
        last_id = self._pinnacle_latest_map_id()
        if last_id == self.PINNACLE_TARGET_LOBBY_MAP_ID:
            return True
        try:
            self._click_region("巅峰对战.地图", use_foreground)
            self._sleep_abortable(stop_event, 0.3)
            self._click_region("巅峰对战.船长室", use_foreground)
        except KeyError as e:
            self._emit(f"[巅峰对战] 缺少区域：{e}", "ERROR")
            return False
        return self._pinnacle_wait_for_map(self.PINNACLE_TARGET_LOBBY_MAP_ID, self.PINNACLE_MAP_WAIT_SEC, stop_event)

    def _pinnacle_wait_petitem(
        self,
        stop_event: threading.Event,
        timeout_s: Optional[float] = None,
    ) -> bool:
        from core.logger import fetch_kernel_since, kernel_cursor
        cursor = kernel_cursor()
        max_wait = float(timeout_s if timeout_s is not None else self.PINNACLE_PETITEM_WAIT_SEC)
        t0 = time.time()
        while time.time() - t0 < max_wait:
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return False
            lines = fetch_kernel_since(cursor)
            if isinstance(lines, list) and any(line_matches(RE_PETITEM, str(line)) for line in lines):
                return True
            cursor = kernel_cursor()
            time.sleep(0.1)
        self._emit(f"[巅峰对战] 等待PetItem超时({max_wait:.0f}s)", "WARN")
        return False

    def _pinnacle_click_entry_and_start_until_petitem(
        self, mode: str, use_foreground: bool, stop_event: threading.Event
    ) -> bool:
        enter_key = "巅峰对战.进入排位" if mode == self.PINNACLE_MODE_RANK else "巅峰对战.进入娱乐"
        start_key = "巅峰对战.开始对战"
        from core.logger import fetch_kernel_since, kernel_cursor
        cursor = kernel_cursor()
        last_click = 0.0
        seq = [enter_key, start_key]
        seq_idx = 0
        timeout_s = float(self.PINNACLE_PETITEM_WAIT_SEC)
        t0 = time.time()
        while time.time() - t0 < timeout_s:
            if stop_event.is_set() or getattr(self.bot, "stop_current", False):
                return False
            lines = fetch_kernel_since(cursor)
            if isinstance(lines, list) and any(line_matches(RE_PETITEM, str(line)) for line in lines):
                return True
            cursor = kernel_cursor()
            now = time.time()
            if now - last_click >= self.PINNACLE_LOOP_CLICK_INTERVAL_SEC:
                key = seq[seq_idx]
                try:
                    self._click_region(key, use_foreground)
                except KeyError:
                    self._emit(f"[巅峰对战] 缺少区域：{key}", "ERROR")
                    return False
                seq_idx = (seq_idx + 1) % len(seq)
                last_click = now
            time.sleep(self.PINNACLE_LOOP_SLEEP_SEC)
        self._emit(f"[巅峰对战] 点击进入/开始后等待PetItem超时({timeout_s:.0f}s)", "WARN")
        return False
